custom_fields.progress:
[[[
  const PROP_ID = 'casora-progress-property-v2';
  if (!document.getElementById(PROP_ID)) {
    const s = document.createElement('style');
    s.id = PROP_ID;
    s.textContent = '@property --casora-progress-pct { syntax: "<number>"; inherits: true; initial-value: 0; }';
    document.head.appendChild(s);
  }

  const dom = (entity?.entity_id || '').split('.')[0];
  const st = (entity?.state || '').toLowerCase();
  const feats = Number(entity?.attributes?.supported_features || 0);

  let glyph = '', svc = '', svcTarget = entity?.entity_id;
  if (variables.progress_transport) {
    if (dom === 'media_player' && (feats & 16385)) {
      glyph = st === 'paused' ? 'play' : 'pause';
      svc = 'media_player.media_play_pause';
    } else if (dom === 'vacuum' && (feats & 4)) {
      glyph = st === 'paused' ? 'play' : 'pause';
      svc = st === 'paused' ? 'vacuum.start' : 'vacuum.pause';
    } else if (variables.entity_pause) {
      /* 3D-Drucker: Pause/Fortsetzen sind button.*-Entitäten (23.09.2026). */
      const paused = st.includes('pause');
      const target = paused ? variables.entity_resume : variables.entity_pause;
      if (target && states[target]?.state !== 'unavailable') {
        glyph = paused ? 'play' : 'pause';
        svc = 'button.press';
        svcTarget = target;
      }
    }
  }

  const GLYPHS = {
    pause: '<rect class="casora-progress-glyph" x="14" y="13" width="2.6" height="10" rx="1.3"/>'
         + '<rect class="casora-progress-glyph" x="19.4" y="13" width="2.6" height="10" rx="1.3"/>',
    play:  '<path class="casora-progress-glyph" d="M15.4 12.9 L23.8 18 L15.4 23.1 Z"'
         + ' stroke-width="1.6" stroke-linejoin="round" stroke-linecap="round"/>',
  };

  let inner = '';
  if (glyph && svc) {
    const [d, sv] = svc.split('.');
    const stop = 'event.stopPropagation();event.stopImmediatePropagation();';
    const act = stop + "document.querySelector('home-assistant').hass.callService('"
              + d + "','" + sv + "',{entity_id:'" + svcTarget + "'});";
    inner = `<g style="cursor:pointer;pointer-events:auto;" onpointerdown="${stop}" onpointerup="${stop}" ontouchstart="${stop}" ontouchend="${stop}" onclick="${act}">`
          + `<circle cx="18" cy="18" r="12" fill="transparent"/>${GLYPHS[glyph]}</g>`;
  }

  return `<svg viewBox="0 0 36 36" xmlns="http://www.w3.org/2000/svg" style="display:block;width:100%;height:100%;overflow:visible;">
    <g transform="rotate(-90 18 18)">
      <circle class="casora-progress-track" cx="18" cy="18" r="14" fill="none" stroke="rgba(255,255,255,0.2)" stroke-width="4" stroke-linecap="round"/>
      <circle class="casora-progress-arc" cx="18" cy="18" r="14" fill="none" stroke="var(--casora-color-teal, #00c3d0)" stroke-width="4" stroke-linecap="round" stroke-dasharray="87.965"/>
    </g>
    ${inner}
  </svg>`;
]]]

card.--casora-icon-color-current:
[[[
  /* Fehler oder abgebrochener Druck: rot wie im Popup. */
  const bad = states[variables.entity_error]?.state === 'on'
    || (entity?.state || '').toLowerCase() === 'failed';
  return bad ? 'var(--casora-color-red, #FF4245)' : 'var(--casora-color-teal, #00c3d0)';
]]]

state.color:
[[[
  const bad = states[variables.entity_error]?.state === 'on'
    || (entity?.state || '').toLowerCase() === 'failed';
  return bad ? 'var(--casora-color-red, #FF4245)'
    : 'var(--casora-entity-state-active-color, var(--casora-entity-state-active, var(--secondary-text-color)))';
]]]

state.value:
[[[
  const error = states[variables.entity_error]?.state === 'on';
  const s = (entity?.state || "").toLowerCase();
  return error || (s && s !== 'idle' && s !== 'offline' && s !== 'unavailable' && s !== 'unknown');
]]]

casora_3d_printer.state_display:
[[[
  const fit = (t) => window.casoraStateFit?.(t) ?? t;

  const errorEntity = states[variables.entity_error];
  if (errorEntity && errorEntity.state === 'on') return fit("Problem");

  const key = (entity?.state || "").toLowerCase();

  /* Bambu-Druckstatus (print_status): eigene Wörter, nicht über die Stufen-Heuristik. */
  const BAMBU = { failed: "Fehlgeschlagen", finish: "Fertig", finished: "Fertig", running: "Druckt",
    prepare: "Vorbereitung", slicing: "Vorbereitung", init: "Vorbereitung", pause: "Pausiert", paused: "Pausiert" };
  if (BAMBU[key]) return fit(BAMBU[key]);

  if (key === "idle") return fit("Bereit");
  if (key === "offline") return fit("Offline");
  if (key === "unavailable") return fit("Nicht verfügbar");
  if (key === "unknown" || key === "") return fit("Unbekannt");

  if (key.includes("pause")) return fit("Pausiert");

  if (
    key.includes("print") ||
    key.includes("first_layer")
  ) return fit("Druckt");

  if (
    key.includes("heat") ||
    key.includes("cool") ||
    key.includes("temperature") ||
    key.includes("preconditioning")
  ) return fit("Heizt");

  if (
    key.includes("level") ||
    key.includes("bed_level")
  ) return fit("Nivellieren");

  if (
    key.includes("calibr") ||
    key.includes("scan") ||
    key.includes("accuracy") ||
    key.includes("lidar") ||
    key.includes("camera")
  ) return fit("Kalibrierung");

  if (
    key.includes("clean") ||
    key.includes("purify")
  ) return fit("Reinigung");

  if (
    key.includes("filament") ||
    key.includes("ams") ||
    key.includes("material")
  ) return fit("Filament");

  if (
    key.includes("check") ||
    key.includes("home") ||
    key.includes("prepare") ||
    key.includes("inspect") ||
    key.includes("identify")
  ) return fit("Vorbereitung");

  return fit("Aktiv");
]]]

casora_air_purifier.state_display:
[[[
  const fit = (t) => window.casoraStateFit?.(t) ?? t;
  const stateMap = { off: 'Aus', unavailable: 'Nicht verfügbar', unknown: 'Unbekannt', idle: 'Bereit', standby: 'Bereitschaft' };
  if (entity?.state === 'on') {
    const preset = entity?.attributes.preset_mode;
    const pct = entity?.attributes.percentage;
    /* Wie Home Assistant den Modus anzeigt (Übersetzung der Integration), keine eigenen Namen. */
    const fa = (k, v) => { try { return hass?.formatEntityAttributeValue ? hass.formatEntityAttributeValue(entity, k, v) : String(v); } catch (e) { return String(v); } };
    if (preset) return fit(fa('preset_mode', preset));
    if (pct != null) return fit(fa('percentage', pct));
    return fit('An');
  }
  if (stateMap[entity?.state]) return fit(stateMap[entity.state]);
  /* Sonst übersetzt, wie HA den Zustand anzeigt (statt Rohwert). */
  try { if (entity && hass?.formatEntityState) return fit(hass.formatEntityState(entity)); } catch (e) {}
  return fit(entity?.state ?? '');
]]]

