      '
:host { --ha-card-backdrop-filter: none !important; --ha-card-background: transparent !important; --card-background-color: transparent !important; --ha-card-box-shadow: none !important; --ha-card-border-width: 0px !important; }'
      + '
ha-card::before, ha-card::after, #card::before, #card::after, #container::before, #container::after { display: none !important; }'
      + '
ha-card { will-change: auto !important; }'
      + '
@media (max-width: 600px) { ha-card { padding-left: 14px !important; padding-right: 14px !important; } }'
    },
    tap_action: { action: 'none' },
    hold_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    styles: {
      card: [
        { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
        { padding: 'var(--casora-soft-card-top, 6px) 26px 22px 26px' },
      ],
      grid: [
        { 'grid-template-areas': '"body"' },
        { 'grid-template-columns': '1fr' },
      ],
      custom_fields: { body: [{ 'justify-self': 'stretch' }] },
    },
    custom_fields: { body: "[[[
  const UI = window._casoraUI;
  if (!UI || !entity) return '';
  const id  = entity?.entity_id;
  const sib = variables.sib || {};
  const a   = entity?.attributes || {};
  const st  = entity?.state;

  const sOf = (eid) => { if (!eid) return null; const s = states[eid]?.state; return (s == null || s === 'unknown' || s === 'unavailable') ? null : s; };
  const nOf = (eid) => { const s = sOf(eid); if (s == null) return null; const n = parseFloat(s); return isNaN(n) ? null : n; };
  const fmt = (n, d) => n.toLocaleString((window.casoraLocale ? window.casoraLocale() : 'de-DE'), { maximumFractionDigits: d, minimumFractionDigits: d });

  const on      = st === 'on';
  const preset  = on ? (a.preset_mode || null) : null;
  const pct     = on && a.percentage != null ? Math.round(a.percentage) : null;
  const level   = pct == null ? null : (pct <= 33 ? 1 : pct <= 66 ? 2 : 3);
  const presets = Array.isArray(a.preset_modes) ? a.preset_modes : [];
  /* Modus-Namen wie in Home Assistant (Übersetzung der Integration); liefert sie nur den Rohwert
     (auto, sleep), dann die gängigen Namen auf Deutsch, sonst groß geschrieben (Audit M8). */
  const presetLabel = (p) => {
    let t = p;
    try { if (hass && hass.formatEntityAttributeValue) t = hass.formatEntityAttributeValue(entity, 'preset_mode', p) || p; } catch (e) { t = p; }
    if (String(t) !== String(p)) return t;
    const de = { auto: 'Auto', sleep: 'Schlaf', silent: 'Leise', quiet: 'Leise', night: 'Nacht', eco: 'Eco', smart: 'Smart', turbo: 'Turbo', boost: 'Boost', normal: 'Normal', nature: 'Natur', manual: 'Manuell', favorite: 'Favorit', low: 'Niedrig', medium: 'Mittel', high: 'Hoch' };
    const s = String(p || '');
    return de[s.toLowerCase()] || (s.charAt(0).toUpperCase() + s.slice(1));
  };

  let mode;
  if (st === 'unavailable') mode = 'Nicht verfügbar';
  else if (!on)             mode = 'Aus';
  else if (preset)             mode = presetLabel(preset);
  else if (pct != null)        mode = (hass && hass.formatEntityAttributeValue) ? (() => { try { return hass.formatEntityAttributeValue(entity, 'percentage', pct); } catch (e) { return pct + ' %'; } })() : pct + ' %';
  else                         mode = 'An';

  const aqMap = { excellent: 'Ausgezeichnet', good: 'Gut', moderate: 'Mäßig', poor: 'Schlecht', very_poor: 'Sehr schlecht', inferior: 'Schlecht' };
  const aqRaw = sOf(sib.aq);
  const aqTxt = aqRaw ? (aqMap[String(aqRaw).toLowerCase()] || aqRaw) : null;
  const aqTone = !aqRaw ? null : (['excellent', 'good'].includes(String(aqRaw).toLowerCase()) ? 'good' : String(aqRaw).toLowerCase() === 'moderate' ? 'warn' : 'bad');
  const pm = nOf(sib.pm25);

  const parts = [];
  if (aqTxt) parts.push('Luft ' + aqTxt.toLowerCase());
