  let out = '';
  if (variables.part !== 'settings') {
  out = ['status', 'seg'].includes(variables.part) ? '' : UI.hero({ label: variables.room_name || 'Luftreiniger', value: mode, sub: parts.join(' · ') || null, center: true });

  if (st !== 'unavailable' && !['status', 'hero'].includes(variables.part)) {
