  }

  const info = [];
  const filt = nOf(sib.filter);
  if (filt != null) {
    const ft = filt < 10 ? 'bad' : filt < 25 ? 'warn' : 'good';
    info.push({ icon: 'mdi:air-filter', iconTone: 'accent', label: 'Filter', value: fmt(filt, 0) + ' %', bar: filt / 100, barTone: ft, entity: sib.filter });
  }
  if (aqTxt) info.push({ icon: 'mdi:weather-windy', iconTone: 'accent', label: 'Luftqualität', value: aqTxt, valueTone: aqTone, entity: sib.aq });
  if (pm != null) info.push({ icon: 'mdi:blur', iconTone: 'accent', label: 'Feinstaub PM2,5', value: fmt(pm, 0) + ' µg/m³', entity: sib.pm25 });
  const pw = nOf(sib.power);
  if (pw != null) info.push({ icon: 'mdi:flash', iconTone: 'good', label: 'Leistung', value: fmt(pw, pw < 10 ? 1 : 0) + ' W', entity: sib.power });
  if (info.length && !['ctrl', 'hero', 'seg'].includes(variables.part)) {
    /* Werte mit Verlauf (Filter, PM2,5, Leistung) schalten das Diagramm unten um */
    let grp = UI.group(info, 'Status');
    if (typeof window._hpChartCfg === 'function') {
      [sib.filter, sib.aq, sib.pm25, sib.power].filter(Boolean).forEach((e) => {
        grp = grp.split('data-casora-mi="' + e + '"').join('data-hp-metric="' + e + '"');
      });
      grp = '<style>.hui-row.hp-sel{background:var(--casora-popup-row-hover, rgba(255,255,255,0.08));}</style>'
        + '<div ontouchstart="window._hpPlantTap&&window._hpPlantTap(event,\'s\')" ontouchend="window._hpPlantTap&&window._hpPlantTap(event,\'t\')" onclick="window._hpPlantTap&&window._hpPlantTap(event,\'c\')">' + grp + '</div>';
    }
    out += (out ? '<div style="height:18px"></div>' : '') + grp;
  }

  }
