        styles: Object.assign({}, uiCard.styles, { card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '18px 26px 0' }] }),
        /* Diagramm in der Sand-Karte wie Pflanze/Energie (1.2), Etikett innen. */
        custom_fields: { body: '<div style="background:var(--casora-popup-row-fill, rgba(255,255,255,0.10));border-radius:var(--casora-popup-row-radius, 20px);box-shadow:var(--casora-popup-plate-shadow, none);backdrop-filter:var(--casora-popup-plate-backdrop, none);-webkit-backdrop-filter:var(--casora-popup-plate-backdrop, none);padding:14px 10px 6px;"><div class="hp-ct" style="font-family:var(--primary-font-family,system-ui);font-size:var(--casora-h15-fs,15px);font-weight:var(--casora-h15-fw,600);letter-spacing:var(--casora-h15-ls,-0.01em);text-transform:var(--casora-h15-tt,none);color:var(--casora-h15-c, var(--casora-popup-tiles-text-primary,#fff));padding:0 6px;text-align:left;">' + window._hpChartTitle(first) + '</div><div class="hp-chart-slot" style="min-height:150px;margin:6px 0 0;"></div></div>' },
