casora_aquarium.state_display:
[[[
  const fwId = variables.entity_freshwater;
  const swId = variables.entity_saltwater;
  const ttId = variables.entity_turtle;
  const fwSt = fwId ? fwId.replace('_temperatur_temperature','_temperaturstatus') : null;
  const swSt = swId ? swId.replace('_temperatur_temperature','_temperaturstatus') : null;
  const ttSt = ttId ? ttId.replace('_temperatur_temperature','_temperaturstatus') : null;
  const lvl = (id) => { const s=(states[id]?.state||'').toLowerCase(); return s.includes('kritisch')?2:s.includes('warnung')?1:0; };
  const worst = Math.max(fwSt?lvl(fwSt):0, swSt?lvl(swSt):0, ttSt?lvl(ttSt):0);
  if (worst >= 2) return 'Kritisch';
  if (worst >= 1) return 'Warnung';
  const ids = [fwId, swId, ttId].filter(Boolean);
  const nums = ids.map(id => parseFloat(states[id]?.state)).filter(n => !isNaN(n));
  if (nums.length === 0) return '—';
  const min = (window.casoraNum || ((x, a, b) => Number(x).toLocaleString(window.casoraLocale ? window.casoraLocale() : 'de-DE', { minimumFractionDigits: a, maximumFractionDigits: b == null ? a : b })))(Math.min(...nums), 1);
  const max = (window.casoraNum || ((x, a, b) => Number(x).toLocaleString(window.casoraLocale ? window.casoraLocale() : 'de-DE', { minimumFractionDigits: a, maximumFractionDigits: b == null ? a : b })))(Math.max(...nums), 1);
  const fit = (t) => window.casoraStateFit?.(t) ?? t;
  return fit(min === max ? min + ' °C' : min + ' – ' + max + ' °C');
]]]

casora_popup.content:
[[[
  /* Aquarien-Übersicht (alt, bis 01.10.2026 casora_popup_aquarium): öffnet das Becken-Popup
     des ersten eingetragenen Beckens. Neue Dashboards nutzen je Becken casora_aquarium_tank. */
  const _t = [variables.entity_saltwater, variables.entity_freshwater, variables.entity_turtle, entity?.entity_id]
    .find((id) => id && states[id] && String(states[id].attributes?.device_class || '') === 'temperature')
    || variables.entity_saltwater || variables.entity_freshwater || variables.entity_turtle || entity?.entity_id;
  const _st = _t ? String(_t).replace('_temperatur_temperature', '_temperaturstatus') : null;
  const _v = Object.assign({}, variables, { status_entity: variables.status_entity || (_st && _st !== _t && states[_st] ? _st : null) });
  return (window._casoraAqPopup && states[_t]) ? window._casoraAqPopup(states[_t], _v, states, hass) : { type: 'vertical-stack', cards: [] };
]]]

casora_aquarium_light.state_display:
[[[
  const fit = (t) => window.casoraStateFit?.(t) ?? t;
  if (!entity?.state || entity?.state === 'unavailable') return fit('Nicht verfügbar');
  return fit(entity?.state === 'on' ? 'An' : 'Aus');
]]]

casora_popup.content:
[[[
  /* Aquarium-Licht (alt, bis 01.10.2026 casora_popup_aquarium_light): öffnet das Becken-Popup
     mit dieser Leuchte. Wassertemperatur: variables.temp_entity, sonst ein Temperatursensor im
     selben Bereich (Aquarium-Name bevorzugt), sonst nur die Leuchte. */
  const _l = entity?.entity_id;
  const _ar = (id) => { const e = hass?.entities?.[id]; return e ? (e.area_id || hass?.devices?.[e.device_id]?.area_id || null) : null; };
  const _a = _ar(_l);
  const _temps = Object.keys(hass?.entities || {}).filter((id) => id.indexOf('sensor.') === 0 && states[id]
    && states[id].attributes?.device_class === 'temperature' && _a && _ar(id) === _a);
  const _t = variables.temp_entity || _temps.find((id) => /aquari|becken|tank|reef|fluval|trigon|chihiros|juwel|terrari|schildkr/i.test(id + ' ' + (states[id].attributes?.friendly_name || ''))) || _temps[0] || _l;
  const _v = Object.assign({}, variables, { light_entity: _l,
    light_reachable: variables.light_reachable || (variables.warn_entity && variables.warn_equals === 'off' ? variables.warn_entity : null) });
  return (window._casoraAqPopup && states[_t]) ? window._casoraAqPopup(states[_t], _v, states, hass) : { type: 'vertical-stack', cards: [] };
]]]

casora_aquarium_tank.state_display:
[[[
  const fit = (t) => window.casoraStateFit?.(t) ?? t;
  const ev = (variables.aq_eval && variables.aq_eval.text ? variables.aq_eval : (window._casoraAqEval ? window._casoraAqEval(entity, variables, states, hass) : {})) || {};
  /* 1.1.2: Wassertemperatur vorn („25,4° · Alles ok“). */
  return fit(window._casoraAqTileText ? window._casoraAqTileText(entity, ev) : (ev.text || ''));
]]]

aq_eval.value:
[[[
  return window._casoraAqEval ? window._casoraAqEval(entity, variables, states, hass) : { level: 0, text: '' };
]]]

custom_fields.glyph:
[[[
  const card = this;
  if (!card._casoraAssistBound) {
    card._casoraAssistBound = true;
    const openIt = (e) => {
      if (card._casoraAssistGuardUntil && Date.now() < card._casoraAssistGuardUntil) return;
      card._casoraAssistGuardUntil = Date.now() + 600;
      if (e.type === 'touchend' && e.cancelable) e.preventDefault();
      if (window._casoraAssist && window._casoraAssist.open()) return;
      const root = document.querySelector('home-assistant') || card;
      root.dispatchEvent(new CustomEvent('hass-action', {
        bubbles: true, composed: true,
        detail: { config: { tap_action: { action: 'assist' } }, action: 'tap' },
      }));
    };
    card.addEventListener('touchend', openIt, { passive: false });
    card.addEventListener('click', openIt);
  }
  return `<img class="casora-assist" src="${window.casoraIconUrl('assist-fill')}"
    alt="" aria-hidden="true">`;
]]]

