card_mod.style:
[[[
  const v = variables?.enabled;
  const isEnabled = () => {
    if (v === undefined || v === null) return true;
    if (typeof v === 'boolean') return v;
    if (typeof v === 'number') return v !== 0;
    const s = String(v).trim().toLowerCase();
    return !['false','0','no','off','disabled'].includes(s);
  };
  if (!isEnabled()) return ':host { display: none !important; }';
  return ':host { display: block; }';
]]]

casora_badge_activity.entity_picture:
[[[
  const a = entity?.attributes || {};
  const raw = a.entity_picture_local || a.entity_picture || a.media_image_url;
  if (raw) return String(raw).startsWith('/') ? `${location.origin}${raw}` : raw;

  const appName = String(a.app_name || a.source || '').toLowerCase();
  const appId   = String(a.app_id || '').toLowerCase();
  if (appName.includes('youtube') || appId.includes('youtube'))
    return '/casora_assets/icons/youtube.png';
  if (appName.includes('netflix') || appId.includes('netflix'))
    return '/casora_assets/icons/netflix.png?v=4';
  if (appName.includes('dazn') || appId.includes('dazn'))
    return '/casora_assets/icons/dazn.png?v=1';

  return null;
]]]

