casora_badge_activity.name:
[[[
  // Mirrors casora_now_playing's derivation exactly, so the same source
  // reads identically on mobile and on desktop:
  //   top    what is playing   (the game)
  //   bottom device - person   ("PS5 - username")
  const a = entity?.attributes || {};
  const norm = (x) => String(x ?? '').trim();

  const title = norm(a.full_title) || norm(a.media_title) || norm(a.title)
    || norm(a.friendly_name) || 'Aktivität';

  // friendly_name ("PS5"), not a.source — that is the verbose
  // "PlayStation Network", which says nothing the console name doesn't.
  const device = norm(a.friendly_name) || norm(a.source);
  const who    = norm(a.user);
  const sub    = [device, who].filter(Boolean).join(' · ');

  const esc = (s) => String(s ?? '')
    .replace(/&/g,'&amp;')
    .replace(/</g,'&lt;')
    .replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;')
    .replace(/'/g,'&#39;');

  return `
    <div class="badge-wrap">
      <div class="badge-title">${esc(title)}</div>
      <div class="badge-sub">${esc(sub)}</div>
    </div>
  `;
]]]

card.--casora-badge-opacity:
[[[
  // Mirror onto the host as well as ha-card. styles.card writes only
  // to ha-card, but :host rules — and the media rim, which reads its
  // vars from :host — need this value too, or the rim animates on a
  // different gate from the card it outlines.
  const P = (v) => { try { this.style.setProperty('--casora-badge-opacity', v); } catch (e) {} return v; };
  return P((() => {
  const cacheKey = '_casoraBadgeActivityOpacity';
  const v = variables?.enabled;
  const isEnabled = () => {
    if (v === undefined || v === null) return true;
    if (typeof v === 'boolean') return v;
    if (typeof v === 'number')  return v !== 0;
    const s = String(v).trim().toLowerCase();
    if (['false','0','no','off','disabled'].includes(s)) return false;
    if (['true','1','yes','on','enabled'].includes(s))   return true;
    return !!s;
  };
  if (!isEnabled()) return '0';

  if (entity === undefined || entity === null) return this[cacheKey] || '0';

  const s = String(entity?.state || '').toLowerCase();
  const a = entity?.attributes || {};

  if (['unavailable','unknown','off','standby'].includes(s)) { this[cacheKey] = '0'; return '0'; }
  if (['playing','buffering','paused'].includes(s)) { this[cacheKey] = '1'; return '1'; }

  const norm = (x) => String(x ?? '').trim();
  const title  = norm(a.media_title || a.title);
  const artist = norm(a.media_artist || a.artist || a.media_album_artist);
  const app    = norm(a.app_name || a.source);

  const r = (title || artist || app) ? '1' : '0';
  this[cacheKey] = r;
  return r;
  })());
]]]

card.--casora-badge-ptr:
[[[
  const v = variables?.enabled;
  const isEnabled = () => {
    if (v === undefined || v === null) return true;
    if (typeof v === 'boolean') return v;
    if (typeof v === 'number')  return v !== 0;
    const s = String(v).trim().toLowerCase();
    if (['false','0','no','off','disabled'].includes(s)) return false;
    if (['true','1','yes','on','enabled'].includes(s))   return true;
    return !!s;
  };
  if (!isEnabled()) return 'none';

  const s = String(entity?.state || '').toLowerCase();
  const a = entity?.attributes || {};

  if (['unavailable','unknown','off','standby'].includes(s)) return 'none';
  if (['playing','buffering','paused'].includes(s)) return 'auto';

  const norm = (x) => String(x ?? '').trim();
  const title  = norm(a.media_title || a.title);
  const artist = norm(a.media_artist || a.artist || a.media_album_artist);
  const app    = norm(a.app_name || a.source);

  return (title || artist || app) ? 'auto' : 'none';
]]]

card.--bg-url:
[[[
  const cacheKey = '_casoraMediaBgUrl';
  const a = entity?.attributes || {};
  const pref = a.entity_picture_local || a.entity_picture || a.media_image_url;

  if (pref) {
    const url = String(pref).startsWith('/') ? `${location.origin}${pref}` : pref;
    if (this._casoraBgRawUrl !== url) {
      this._casoraBgRawUrl = url;
      const img = new Image();
      img.onload = () => {
        if (this._casoraBgRawUrl !== url) return;
        const wrapped = `url("${url}")`;
        this[cacheKey] = wrapped;
        const card = this.shadowRoot?.querySelector('ha-card');
        if (card) { card.style.setProperty('--bg-url', wrapped);
                     card.style.setProperty('--casora-badge-has-art', '1'); }
        this.requestUpdate?.();
      };
      img.src = url;
    }
  }
  return this[cacheKey] || 'none';
]]]

casora_badge_air_quality.extra_styles:
[[[
  const ev = variables?.enabled;
  const enabled = (ev === undefined || ev === null) ? true :
    (typeof ev === 'boolean') ? ev :
    (typeof ev === 'number') ? ev !== 0 :
    !['false','0','no','off','disabled'].includes(String(ev).trim().toLowerCase());

  const hasEnt  = !!entity?.entity_id;
  const stRaw   = String(entity?.state ?? '').trim();
  const st      = stRaw.toLowerCase();
  const hide    = !enabled || !hasEnt || !stRaw || ['unknown','unavailable','none'].includes(st);

  /* Gemeinsames Level wie im Klima-Popup (Hemma 2.2.0, MIT): Text, Farbe und Symbol folgen ihm. */
  const aq = (() => { const st0 = String(entity?.state ?? '').trim().toLowerCase().replace(/_/g, ' '); const base = { excellent: 0, ausgezeichnet: 0, good: 0.5, gut: 0.5, moderate: 1, fair: 1, 'mäßig': 1, poor: 2, schlecht: 2, bad: 3, 'very bad': 3, 'very poor': 3, 'extremely poor': 3, 'sehr schlecht': 3 }[st0]; const sns = Array.isArray(variables?.sensors) ? variables.sensors.filter(Boolean) : []; let worst = -1; sns.forEach((eid) => { const n = parseFloat(states[eid]?.state); if (isNaN(n)) return; const id = eid.toLowerCase(); const a = states[eid]?.attributes || {}; const dc = String(a.device_class || '').toLowerCase(); const idx = id.endsWith('_index') || String(a.unit_of_measurement || '').toLowerCase() === 'index'; const t = (id.includes('pm25') || id.includes('pm2_5') || dc === 'pm25') ? [12, 35.4, 55.4] : (id.includes('pm10') || dc === 'pm10') ? [54, 154, 254] : (id.includes('voc') || id.includes('volatile_organic') || dc.includes('volatile_organic')) ? (idx ? [6, 8, 9] : [100, 200, 300]) : (id.includes('no2') || id.includes('nitrogen_dioxide') || dc === 'nitrogen_dioxide') ? (idx ? [6, 8, 9] : [53, 100, 360]) : (id.includes('co2') || id.includes('carbon') || dc === 'carbon_dioxide') ? [1000, 1500, 2000] : null; if (!t) { worst = Math.max(worst, 0); return; } worst = Math.max(worst, n <= t[0] ? 0 : n <= t[1] ? 1 : n <= t[2] ? 2 : 3); }); return worst >= 0 ? { level: worst, fromSensors: true } : { level: base, fromSensors: false }; })();
  let svgUrl = aq.level >= 2
    ? window.casoraIconUrl('aqi-high')
    : aq.level != null && aq.level <= 0.5
      ? window.casoraIconUrl('aqi-low')
      : window.casoraIconUrl('aqi-medium');
  /* Casora-Look (05.10.2026): Die SF-Grafik aus ~20 winzigen Punkten war im Badge-Kreis kaum zu
     lesen. Stattdessen ein kräftiges Wind-Symbol (zwei Luftströme) – so groß und stark wie Tropfen
     und Thermometer der Nachbar-Badges. Die Stufe zeigt neben der Farbe die Zahl der Partikel:
     gut keine, mäßig zwei, schlecht vier. */
  let aqSoftCSS = '';
  if (window._casoraSoft && window._casoraSoft()) {
    const ln = (dd) => `<path d="${dd}" fill="none" stroke="#000" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/>`;
    const n = aq.level >= 2 ? 4 : aq.level != null && aq.level <= 0.5 ? 0 : 2;
    const pts = [[5.2, 4.6], [5, 19.6], [21, 7.6], [9.8, 20.2]].slice(0, n);
    const wind = ln('M2.8 9.2h11a3.1 3.1 0 1 0-3.1-3.1') + ln('M2.8 14h15.2a3.1 3.1 0 1 1-3.1 3.1')
      + pts.map(([x, y]) => `<circle cx="${x}" cy="${y}" r="1.55"/>`).join('');
    svgUrl = 'data:image/svg+xml,' + encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24">${wind}</svg>`);
    aqSoftCSS = `
      #img-cell::before, .img-cell::before { scale: 0.56 !important; }`;
  }

  let gaugeCSS = '';
  if (variables?.gauge && !hide) {
    const gf  = { 0: 1, 0.5: 0.8, 1: 0.55, 2: 0.3, 3: 0.15 }[aq.level] ?? 0.5;
    const arc = Math.round(gf * 270);
    const rr = 13.5, C = 16, W = 3;
    const pt = (deg) => {
      const a = deg * Math.PI / 180;
      return `${(C + rr * Math.sin(a)).toFixed(3)} ${(C - rr * Math.cos(a)).toFixed(3)}`;
    };
    const arcPath = (a0, a1) =>
      `M ${pt(a0)} A ${rr} ${rr} 0 ${(a1 - a0) > 180 ? 1 : 0} 1 ${pt(a1)}`;
    let paths = '';
    if (arc < 269) paths += `<path d='${arcPath(225 + arc, 495)}' stroke='white' stroke-opacity='0.30' stroke-width='${W}' stroke-linecap='round' fill='none'/>`;
    paths += `<path d='${arcPath(225, 225 + arc)}' stroke='white' stroke-width='${W}' stroke-linecap='round' fill='none'/>`;

    const svg = `<svg xmlns='http://www.w3.org/2000/svg' width='32' height='32' viewBox='0 0 32 32'>${paths}</svg>`;
    const maskUrl = `url("data:image/svg+xml,${encodeURIComponent(svg)}")`;
    gaugeCSS = `
      #img-cell::before, .img-cell::before {
        background-color: color-mix(in srgb, var(--casora-badge-glyph, #fff) var(--casora-badge-circle-mix, 0%), var(--casora-badge-icon-fg, var(--casora-icon-color, var(--primary-text-color)))) !important;
        scale: var(--casora-badge-glyph-scale, none);
      }

      #img-cell::after, .img-cell::after {
        content: '';
        position: absolute;
        inset: 0;
        border-radius: 9999px;
        background: var(--casora-icon-color, #fff);
        opacity: calc(1 - var(--casora-badge-circle-on, 0));
        -webkit-mask: ${maskUrl} no-repeat center / 100% 100%;
        mask: ${maskUrl} no-repeat center / 100% 100%;
        transform: translateZ(0);
        -webkit-transform: translateZ(0);
      }

${variables?.gauge_keep_bg ? '#img-cell, .img-cell { --casora-badge-icon-scale: calc(54% + 31% * var(--casora-badge-circle-on, 0)); }' : `
      ha-card.button-card-main, ha-card.button-card-main:hover, ha-card.button-card-main:active,
      :host(:hover) ha-card, :host(:active) ha-card {
        /* Weich: Pille wie die Haupt-Badges (Ring ist dort aus) – sonst stand weiße Schrift
           direkt auf dem hellen Foto. Andere Designs: durchsichtig wie bisher. */
        background: color-mix(in srgb, var(--badge-background, transparent) calc(var(--casora-badge-circle-on, 0) * 100%), transparent) !important;
        box-shadow: var(--casora-badge-gauge-shadow, none) !important;
        filter: none !important;
        -webkit-filter: none !important;
        -webkit-tap-highlight-color: transparent !important;
      }
      ha-ripple, mwc-ripple { display: none !important; }
`}
    `;
  }

  return `${aqSoftCSS}
    :host{display:${hide ? 'none' : 'inline-block'} !important;order:var(--casora-badge-order-climate,2);}
    #img-cell, .img-cell { position: relative; }
    /* Weich (--casora-badge-circle-on: 1): volles Symbol (ha-state-icon) wie bei den Haupt-Badges –
       die feine Strichgrafik im ::before wirkte im Kreis winzig und dünn. Andere Designs: wie bisher. */
    #img-cell #icon, .img-cell #icon {
      color: color-mix(in srgb, var(--casora-badge-glyph, #fff) var(--casora-badge-circle-mix, 0%), transparent) !important;
      --icon-primary-color: color-mix(in srgb, var(--casora-badge-glyph, #fff) var(--casora-badge-circle-mix, 0%), transparent) !important;
      --state-icon-color: color-mix(in srgb, var(--casora-badge-glyph, #fff) var(--casora-badge-circle-mix, 0%), transparent) !important;
      opacity: 0 !important;
    }
    /* Luftqualität: auch im Kreis die AQI-Punkte (aqi-low/-medium/-high) wie in Hemma, nicht das Luftreiniger-Symbol. */
    #img-cell::before, .img-cell::before {
      content: '';
      opacity: 1;
      position: absolute;
      inset: 0;
      background-color: color-mix(in srgb, var(--casora-badge-glyph, #fff) calc(var(--casora-badge-circle-on, 0) * 100%), var(--casora-icon-color, var(--primary-text-color)));
      scale: var(--casora-badge-glyph-scale, none);
      /* Im Weich-Kreis größer: die feinen AQI-Punkte wirken sonst blass. Am Handy verkleinern die
         Reihen das Symbol (--casora-badge-icon-scale 54 %), dann waren die Punkte neben Tropfen und
         Thermometer winzig – im Kreis darum mindestens 96 % (Desktop bleibt bei 85 % × 1,15) (04.10.2026). */
      -webkit-mask: url('${svgUrl}') no-repeat center / max(calc(var(--casora-badge-icon-scale, 85%) * (1 + 0.15 * var(--casora-badge-circle-on, 0))), calc(96% * var(--casora-badge-circle-on, 0))) max(calc(var(--casora-badge-icon-scale, 85%) * (1 + 0.15 * var(--casora-badge-circle-on, 0))), calc(96% * var(--casora-badge-circle-on, 0)));
      mask: url('${svgUrl}') no-repeat center / max(calc(var(--casora-badge-icon-scale, 85%) * (1 + 0.15 * var(--casora-badge-circle-on, 0))), calc(96% * var(--casora-badge-circle-on, 0))) max(calc(var(--casora-badge-icon-scale, 85%) * (1 + 0.15 * var(--casora-badge-circle-on, 0))), calc(96% * var(--casora-badge-circle-on, 0)));
      transform: translateZ(0);
    }
  ` + gaugeCSS;
]]]

casora_badge_air_quality.name:
[[[
  /* Gemeinsames Level wie im Klima-Popup (Hemma 2.2.0, MIT): Text, Farbe und Symbol folgen ihm. */
  const aq = (() => { const st0 = String(entity?.state ?? '').trim().toLowerCase().replace(/_/g, ' '); const base = { excellent: 0, ausgezeichnet: 0, good: 0.5, gut: 0.5, moderate: 1, fair: 1, 'mäßig': 1, poor: 2, schlecht: 2, bad: 3, 'very bad': 3, 'very poor': 3, 'extremely poor': 3, 'sehr schlecht': 3 }[st0]; const sns = Array.isArray(variables?.sensors) ? variables.sensors.filter(Boolean) : []; let worst = -1; sns.forEach((eid) => { const n = parseFloat(states[eid]?.state); if (isNaN(n)) return; const id = eid.toLowerCase(); const a = states[eid]?.attributes || {}; const dc = String(a.device_class || '').toLowerCase(); const idx = id.endsWith('_index') || String(a.unit_of_measurement || '').toLowerCase() === 'index'; const t = (id.includes('pm25') || id.includes('pm2_5') || dc === 'pm25') ? [12, 35.4, 55.4] : (id.includes('pm10') || dc === 'pm10') ? [54, 154, 254] : (id.includes('voc') || id.includes('volatile_organic') || dc.includes('volatile_organic')) ? (idx ? [6, 8, 9] : [100, 200, 300]) : (id.includes('no2') || id.includes('nitrogen_dioxide') || dc === 'nitrogen_dioxide') ? (idx ? [6, 8, 9] : [53, 100, 360]) : (id.includes('co2') || id.includes('carbon') || dc === 'carbon_dioxide') ? [1000, 1500, 2000] : null; if (!t) { worst = Math.max(worst, 0); return; } worst = Math.max(worst, n <= t[0] ? 0 : n <= t[1] ? 1 : n <= t[2] ? 2 : 3); }); return worst >= 0 ? { level: worst, fromSensors: true } : { level: base, fromSensors: false }; })();
  /* Messsensoren bestimmen das Level: dann dieselben Worte wie das Popup. Sonst HAs Zustandstext. */
  const word = aq.fromSensors ? ['Ausgezeichnet', 'Mäßig', 'Schlecht', 'Sehr schlecht'][aq.level] : null;
  // entity is undefined during HA startup — formatEntityState(undefined) throws (auch beim Sprachwechsel).
  let fmt = '';
  try { fmt = entity ? hass.formatEntityState(entity) : ''; } catch (e) { fmt = ''; }
  const raw = word || fmt || entity?.state || 'Unbekannt';
  const nice = raw.charAt(0).toUpperCase() + raw.slice(1);
  const esc = (t) => String(t || '').replaceAll('"','&quot;');
  return `
    <div class="badge-wrap">
      <div class="badge-title">Luftqualität</div>
      <div class="badge-sub">${esc(nice)}</div>
    </div>
  `;
]]]

