card.--casora-fan-animation:
[[[
  if (window.location.pathname.endsWith('/home') || (window._casoraSoft && window._casoraSoft())) return 'none';
  const entities = [
    variables.climate_entity,
    variables.climate_entity_2,
    variables.climate_entity_3
  ].filter(e => !!e);
  const hvacActive = entities.some(eid => {
    const s = hass.states[eid];
    if (!s) return false;
    const action = s.attributes?.hvac_action;
    if (['heating','cooling','fan_only','fan','drying'].includes(action)) return true;
    return !['off','unavailable','unknown'].includes(s.state);
  });

  const prev = this._casoraPrevHvac;
  this._casoraPrevHvac = hvacActive;
  const justOn  = hvacActive  && prev === false;
  const justOff = !hvacActive && prev === true;

  if (hvacActive) {
    return justOn
      ? 'casora-fan-spin 1.5s ease-in 1, casora-fan-spin 0.9s linear 1.5s infinite'
      : 'casora-fan-spin 0.9s linear infinite';
  }
  if (justOff) return 'casora-fan-coast 1.5s ease-out 1 forwards';
  return 'none';
]]]

