card.--casora-badge-icon-color:
[[[
  const pid = variables?.entity_power || entity?.entity_id;
  const w = parseFloat(states[pid]?.state);
  /* Eingestellte iOS-Farben (energy_color_N, z. B. #ffd600 Solar) laufen über
     --casora-energy-sub-<ton>: Weich setzt dort die gedämpften Töne, Standard/Glas
     setzen nichts und behalten die eingestellte Farbe (03.10.2026). */
  if (variables?.color) {
    const HUE = { '#ffd600': 'yellow', '#ffd60a': 'yellow', '#ffcc00': 'yellow',
      '#0a84ff': 'blue', '#007aff': 'blue', '#64d2ff': 'blue', '#5ac8fa': 'blue',
      '#bf5af2': 'purple', '#af52de': 'purple', '#5e5ce6': 'purple',
      '#ff453a': 'red', '#ff3b30': 'red', '#ff4245': 'red',
      '#30d158': 'green', '#34c759': 'green', '#32d74b': 'green',
      '#ff9f0a': 'orange', '#ff9500': 'orange', '#ff9230': 'orange', '#00c3d0': 'teal' };
    const c = String(variables.color).trim();
    const h = HUE[c.toLowerCase()];
    return h ? 'var(--casora-energy-sub-' + h + ', ' + c + ')' : c;
  }
  if (!Number.isFinite(w)) return 'var(--casora-badge-energy-color, #30D158)';
  if (w >= Number(variables?.extreme_threshold ?? 3000)) return 'var(--casora-badge-energy-very-high-color, #FF4245)';
  if (w >= Number(variables?.heavy_threshold   ?? 1000)) return 'var(--casora-badge-energy-high-color, #FF9230)';
  if (w >= Number(variables?.normal_threshold  ?? 200))  return 'var(--casora-badge-energy-medium-color, #FFD600)';
  return 'var(--casora-badge-energy-low-color, #30D158)';
]]]

