casora_badge_energy_group.name:
[[[
  /* Ohne eigenen Sensor (Handy-Reihe, Räume nur mit Verbrauch/Kosten): Energie-Kachel bzw. Hausverbrauch. */
  /* Raum ohne eigenen Sensor, aber mit mehreren Geräten (power_entities): ihre Summe, in W. */
  const _list = Array.isArray(variables.power_entities) ? variables.power_entities.filter(Boolean) : [];
  const _toW = (id) => { const s = states[id]; const n = s ? parseFloat(s.state) : NaN; if (!Number.isFinite(n)) return null;
    const u = String((s.attributes || {}).unit_of_measurement || 'W'); return u === 'kW' ? n * 1000 : u === 'MW' ? n * 1e6 : u === 'mW' ? n / 1000 : n; };
  const _vals = _list.map(_toW).filter((n) => n != null);
  /* 06.10.2026: nur Leistung, unknown/unavailable übersprungen, Messsteckdose nicht doppelt (energy_parent). */
  const _ps = typeof window !== 'undefined' ? window._casoraPowerSum : null;
  const _sum = _ps && _list.length ? _ps({ energy_entities: _list, energy_parent: variables.power_parent }, states).sum
    : (_vals.length ? _vals.reduce((a, b) => a + b, 0) : NaN);
  const eid = _list.length ? null : (variables.home_power_entity || variables.power_entity || variables.entity_power
    || (window._casoraHousePower ? window._casoraHousePower() : null));
  const power = eid ? _toW(eid) : _sum; /* auch ein einzelner Sensor in kW/MW → W (B-TPL-04) */
  const sub = Number.isFinite(power)
    ? (power >= 1000 ? (power / 1000).toLocaleString((hass&&hass.locale&&hass.locale.language)||'de', { minimumFractionDigits: 1, maximumFractionDigits: 1 }) + ' kW' : Math.round(power) + ' W')
    : '';
  /* Immer zweizeilig wie die anderen Badges – ohne Wert ein Strich statt einer niedrigeren Badge. */
  return `
    <div class="badge-wrap">
      ${variables.title ? `<div class="badge-title" data-no-i18n>${String(variables.title).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]))}</div>` : `<div class="badge-title">Energie</div>`}
      <div class="badge-sub">${sub || '–'}</div>
    </div>
  `;
]]]

