casora_badge_scene.name:
[[[

  const rel = (iso) => {
    const t = Date.parse(iso);
    if (!isFinite(t)) return 'Noch nie';
    const m = Math.round((Date.now() - t) / 60000);
    if (m < 1) return 'Gerade eben';
    if (m < 60) return 'Vor ' + m + ' Min.';
    const h = Math.round(m / 60);
    // Calendar days, not 24-hour blocks: 36 hours ago is still yesterday.
    const day = (x) => { const o = new Date(x); return new Date(o.getFullYear(), o.getMonth(), o.getDate()); };
    const d = Math.round((day(Date.now()) - day(t)) / 86400000);
    if (h < 24 || d < 1) return 'Vor ' + h + ' Std.';
    return d === 1 ? 'Gestern' : 'Vor ' + d + ' Tagen';
  };

  const esc = (t) => String(t || '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  const name = entity?.attributes?.friendly_name || entity?.entity_id || '';
  // Aktive Szene: „Aktiv“ statt der Zeit (1.2, wie im Szenen-Blatt am Handy).
  const SC = window._casoraSC;
  const on = !!(SC && SC.isActive && entity && SC.isActive(entity.entity_id, states));
  return '<div class="badge-wrap"><div class="badge-title">' + esc(name) + '</div><div class="badge-sub">' + esc(on ? 'Aktiv' : rel(entity?.state)) + '</div></div>';
]]]

card.display:
[[[
  const v = variables?.enabled;
  const on = !(v === false || ['false','0','no','off'].includes(String(v).trim().toLowerCase()));
  return on && entity && entity?.state !== 'unavailable' ? 'inline-grid' : 'none';
]]]

