  };

  const ids = (variables.scene_entities || []).filter((id) => states[id]);
  let last = null;
  ids.forEach((id) => { const t = Date.parse(states[id].state); if (isFinite(t) && (!last || t > last.t)) last = { id: id, t: t }; });
  const SC = window._casoraSC;
  if (SC) SC.prefetch(ids, states);
  const act = SC ? ids.filter((id) => SC.isActive(id, states)).length : 0;
  const sub = act === 0 ? 'Keine aktiv' : act + ' Aktiv';
  const esc = (t) => String(t || '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  // Eigener Name aus dem Studio („Name auf dem Badge“, scenes_title); sonst „Szenen“.
  const title = variables.title ? '<div class="badge-title" data-no-i18n>' + esc(variables.title) + '</div>' : '<div class="badge-title">Szenen</div>';
  return '<div class="badge-wrap">' + title + '<div class="badge-sub">' + esc(sub) + '</div></div>';
]]]

casora_badge_security.extra_styles:
[[[
  const v = variables?.enabled;
  const enabled = (v === undefined || v === null) ? true :
    (typeof v === 'boolean') ? v :
    (typeof v === 'number') ? v !== 0 :
    !['false','0','no','off','disabled'].includes(String(v).trim().toLowerCase());
  const st = String(entity?.state ?? '').trim().toLowerCase();
  const noEntity = !entity?.entity_id || (window.casoraSeesEntity && !window.casoraSeesEntity(entity.entity_id, user));
  const isUnavailable = !st || ['unknown','unavailable'].includes(st);

  const dom = String(entity?.entity_id || '').split('.')[0];
  const dc = String(entity?.attributes?.device_class || '').toLowerCase();
  const nameRaw = String(entity?.attributes?.friendly_name || '').toLowerCase();
  const isWindow = dc === 'window' || nameRaw.includes('fenster') || nameRaw.includes('window');

  let name = 'lock';
  if (isUnavailable) name = 'default';
  else if (dom === 'camera') name = 'doorbell';
  else if (dom === 'lock') name = st === 'locked' ? 'lock-fill' : 'lock-open-fill';
  else if (dom === 'alarm_control_panel') name = ((window._casoraSoft && window._casoraSoft()) && window.casoraSecurityIcon)
    /* Weich: Modus-Symbol wie Alarm-Kachel, Popup und Mitteilungen. */
    ? window.casoraSecurityIcon(entity.entity_id, st, entity.attributes)
    : (st === 'disarmed' || st === 'triggered') ? 'shield_alarm' : 'shield_check';
  else if (dom === 'binary_sensor' || dom === 'cover') {
    const isOpen = st === 'on' || st === 'open';
    name = isWindow ? (isOpen ? 'window-open' : 'window-closed') : (isOpen ? 'door-open' : 'door-closed');
  }
  const URL = window.casoraIconUrl(name);
  // One size for every security glyph so the group badge and its
  // sub-badges are visually identical. Every glyph here now carries 6% of
  // transparent viewBox padding, so they all take the same 6% bump.
  const SIZE = variables?.icon_size || '88%';

  return `:host{display:${(!enabled || noEntity) ? 'none' : 'inline-block'} !important;${variables?.inline ? 'order:var(--casora-badge-order-security,1);' : ''}}
    #img-cell, .img-cell{ position: relative; }

    #img-cell #icon, .img-cell #icon{
      color: transparent !important;
      opacity: 0 !important;
    }

    #img-cell::before,
    .img-cell::before{
      content: '';
      position: absolute;
      inset: 0;
      background-color: color-mix(in srgb, var(--casora-badge-glyph, #fff) var(--casora-badge-circle-mix, 0%), var(--casora-badge-icon-color, var(--casora-badge-security-color, #00c3d0))) !important;
      scale: var(--casora-badge-glyph-scale, none);
      -webkit-mask: url('${URL}') no-repeat center / auto ${SIZE};
      mask: url('${URL}') no-repeat center / auto ${SIZE};
      transform: translateZ(0);
    }`;
]]]

