casora_badge_security.name:
[[[
  const esc = (t) => String(t ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

  const id  = String(entity?.entity_id || '');
  const dom = id.split('.')[0];
  const s   = String(entity?.state || '').toLowerCase();
  const dc  = String(entity?.attributes?.device_class || '').toLowerCase();
  const tilt = entity?.attributes?.tilt === true || entity?.attributes?.tilt === 'true'
    || (s === 'on' && !('tilt' in (entity?.attributes || {})) && !/kombi|combined/i.test(id + ' ' + (entity?.attributes?.friendly_name || ''))
      && /kipp|tilt/i.test(id + ' ' + (entity?.attributes?.friendly_name || '')));

  const title = variables?.label || entity?.attributes?.friendly_name || 'Sicherheit';

  let sub = '';
  if (['unknown','unavailable',''].includes(s)) {
    sub = 'Nicht verfügbar';
  } else if (dom === 'lock') {
    /* Nur jammed ist „Blockiert“; open/opening (Falle gezogen) und die Übergänge eigens (Nuki & Co.). */
    sub = s === 'locked' ? 'Verriegelt' : s === 'unlocked' ? 'Entriegelt' : s === 'jammed' ? 'Blockiert'
        : s === 'open' || s === 'opening' ? 'Offen' : s === 'locking' ? 'Wird verriegelt…' : s === 'unlocking' ? 'Wird entriegelt…'
        : ((() => { try { return hass.formatEntityState(entity); } catch (e) { return ''; } })() || s);
  } else if (dom === 'alarm_control_panel') {
    sub = s === 'disarmed' ? 'Deaktiviert'
        : s === 'triggered' ? 'Ausgelöst'
        : s === 'armed_home' ? 'Aktiviert (Zuhause)'
        : s === 'armed_away' ? 'Aktiviert (Abwesend)'
        : s === 'armed_custom_bypass' ? 'Aktiviert (Bypass)'
        : 'Aktiviert';
  } else if (dom === 'camera') {
    /* "Idle" is every camera, all day, so it says nothing. Fall through to the
       same alert wording the aggregated camera badge uses. */
    const alert = window.casoraCameraAlert
      ? window.casoraCameraAlert(hass, states, [id], variables?.alert_window_minutes) : '';
    sub = s === 'recording' ? 'Aufnahme'
        : s === 'streaming' ? 'Live'
        : (alert || 'Sicher');
  } else if (dom === 'cover') {
    sub = s === 'closed' ? 'Geschlossen' : 'Geöffnet';
  } else if (dc === 'motion') {
    sub = s === 'on' ? 'Bewegung' : 'Frei';
  } else if (tilt) {
    sub = 'Gekippt';
  } else {
    sub = s === 'on' ? 'Geöffnet' : 'Geschlossen';
  }

  /* Weich: dasselbe Wort wie Popup und Mitteilungen (casoraSecurityWord, 00-finden.js). */
  if ((dom === 'lock' || dom === 'alarm_control_panel') && (window._casoraSoft && window._casoraSoft()) && window.casoraSecurityWord)
    sub = window.casoraSecurityWord(id, s) || sub;

  return `
    <div class="badge-wrap">
      <div class="badge-title">${esc(title)}</div>
      <div class="badge-sub">${esc(sub)}</div>
    </div>
  `;
]]]

