    add('toggle', '[[[ return window._casoraAlarmSoftToggle ? window._casoraAlarmSoftToggle(' + JSON.stringify(ent) + ', states) : ""; ]]]');
  } else
  add('toggle', toggleHtml);

  const armService = (id) => 'alarm_' + id.replace('armed_', 'arm_');
  const rows = MODES.map((m) => {
    const active = st === m.id;
    const words = { state: {} };
    MODES.forEach((mm) => { words.state[mm.id] = mm.id === m.id ? 'Aktiv' : ' '; });
    ['disarmed', 'triggered', 'arming', 'pending', 'disarming'].forEach((s) => { words.state[s] = ' '; });
