  };
  return { type: 'vertical-stack', cards: [window._casoraStd ? window._casoraStd(uiCard, { top: ['hero', 'toggle'], center: ['toggle'], left: ['modes'] }) : uiCard] };
};
  return (entity?.entity_id || '').startsWith('binary_sensor.') ? _contacts() : _alarm();
