casora_badge_security_group.extra_styles:
[[[
  const ev = variables?.enabled;
  const enabled = (ev === undefined || ev === null) ? true :
    (typeof ev === 'boolean') ? ev :
    (typeof ev === 'number') ? ev !== 0 :
    !['false','0','no','off','disabled'].includes(String(ev).trim().toLowerCase());

  const _sec = (() => {
    const arr = (v) => Array.isArray(v) ? v : (v ? [v] : []);
    const st = (id) => String(states[id]?.state ?? '').toLowerCase();
    const cams = arr(variables.cameras);
    /* Gruppen-Helfer (z. B. „Fenster“ ohne Geräteklasse) zählen über ihre Mitglieder. */
    const flat = (id) => (id.startsWith('binary_sensor.') && Array.isArray(states[id]?.attributes?.entity_id))
      ? states[id].attributes.entity_id : [id];
    const ids = [...new Set([variables.alarm_entity, variables.doors_entity, variables.windows_entity,
      variables.lock_entity, variables.lock_entity_2, ...arr(variables.locks), ...arr(variables.entities), ...cams]
      .filter((x) => typeof x === 'string' && x.includes('.')).flatMap(flat))]
      /* „Wer sieht das?“ der Kacheln (casora-core.js): Ausgeblendetes zählt nicht mit. */
      .filter((x) => !window.casoraSeesEntity || window.casoraSeesEntity(x, user));
    const r = { triggered: false, disarmed: false, locks: 0, lockDead: 0, doors: 0, windows: 0, doorsTilted: 0, windowsTilted: 0, gates: 0, camDead: 0 };
    for (const id of ids) {
      const dom = id.split('.')[0], s = st(id), a = states[id]?.attributes || {};
      const dc = String(a.device_class || '').toLowerCase();
      const dead = !s || s === 'unavailable' || s === 'unknown';
      if (dom === 'alarm_control_panel') { if (s === 'triggered') r.triggered = true; else if (s === 'disarmed') r.disarmed = true; }
      else if (dom === 'lock') { if (dead) r.lockDead++; else if (s !== 'locked' && s !== 'locking') r.locks++; }
      else if (dom === 'camera') { if (dead || window._casoraCamDead?.[id] || window.casoraCamOffline?.(id, states)) r.camDead++; }
      else if (dom === 'cover') { if (['garage', 'gate', 'door'].includes(dc) && (s === 'open' || s === 'opening')) r.gates++; }
    }
    /* Türen/Fenster: Kontakt + Kippsensor (+ Kombi-Sensor) sind eine Öffnung (window.casoraOpenings). */
    const bs = ids.filter((id) => id.startsWith('binary_sensor.'));
    const units = window.casoraOpenings ? window.casoraOpenings(hass, bs) : bs.map((id) => {
      const a = states[id]?.attributes || {}, dc = String(a.device_class || '').toLowerCase(), s = st(id);
      if (!['door', 'window', 'garage_door', 'opening', ''].includes(dc)) return null;
      const nm = id + ' ' + (a.friendly_name || '');
      const on = s === 'on' || s === 'open';
      return { state: !on ? 'closed' : (a.tilt === true || a.tilt === 'true' || /kipp|tilt/i.test(nm)) ? 'tilted' : 'open',
        kind: dc === 'window' || (dc !== 'door' && dc !== 'garage_door' && /fenster|window/i.test(nm)) ? 'window' : 'door' };
    }).filter(Boolean);
    for (const u of units) {
      const win = u.kind === 'window' || (u.main && u.main === variables.windows_entity);
      if (u.state === 'tilted') { if (win) r.windowsTilted++; else r.doorsTilted++; }
      else if (u.state === 'open') { if (win) r.windows++; else r.doors++; }
    }
    r.insecure = r.triggered || r.disarmed || !!(r.locks || r.doors || r.windows || r.doorsTilted || r.windowsTilted || r.gates);
    r.problem = !!(r.camDead || r.lockDead);
    return r;
  })();
  const URL = window.casoraIconUrl(_sec.triggered ? 'shield_alarm' : (_sec.insecure || _sec.problem) ? 'shield_marked' : 'shield_check');

  return `:host{display:${enabled ? 'inline-block' : 'none'} !important;order:var(--casora-badge-order-security,1);}
    #img-cell, .img-cell{ position: relative; }

    #img-cell #icon, .img-cell #icon{
      color: transparent !important;
      opacity: 0 !important;
    }

    #img-cell::before,
    .img-cell::before{
      content: '';
      position: absolute;
      inset: 0;
      background-color: color-mix(in srgb, var(--casora-badge-glyph, #fff) var(--casora-badge-circle-mix, 0%), var(--casora-badge-icon-color, var(--casora-badge-security-color, #00c3d0))) !important;
      scale: var(--casora-badge-glyph-scale, none);
      -webkit-mask: url('${URL}') no-repeat center / auto 88%;
      mask: url('${URL}') no-repeat center / auto 88%;
      transform: translateZ(0);
    }`;
]]]

