    r.problem = !!(r.camDead || r.lockDead);
    return r;
  })();
  /* Weich/Nebel: window.casoraSecuritySummary (00-finden.js) – Variable summary: auto (Standard,
     Startseite kurz, Räume ausgeschrieben) | short (Symbole mit Zahl) | detailed (Liste in Worten); Zustandswörter „Alles sicher“, „Aktiv · Modus“, „Alarm!“.
     Hemma 2/1: Liste wie bisher, alles zu = „Alles sicher“ (Schlösser, Alarm, Türen, Fenster), Kipp-Stellung und offline. */
  const n = (c, one, many) => c === 1 ? one : c + ' ' + many;
  let sub = 'Alles sicher', subHtml = null;
  if ((window._casoraSoft && window._casoraSoft()) && window.casoraSecuritySummary) {
    const arr = (v) => Array.isArray(v) ? v : (v ? [v] : []);
    const alId = [variables.alarm_entity, ...arr(variables.entities)].find((x) => typeof x === 'string' && x.startsWith('alarm_control_panel.'));
    /* Kurz oder ausführlich (07.10.2026): summary auto (Standard) = Startseite kurz, Räume ausgeschrieben;
       place sagt die Handy-Vorlage (home/room), am Desktop erkennt die Karte ihre Ansicht selbst. */
    const place = variables.place || (window.casoraOnHomeView && window.casoraOnHomeView(this) ? 'home' : 'room');
    const mode = window.casoraSecurityMode ? window.casoraSecurityMode(variables.summary, place) : 'short';
