card.--casora-badge-icon-color:
[[[
  const _sec = (() => {
    const arr = (v) => Array.isArray(v) ? v : (v ? [v] : []);
    const st = (id) => String(states[id]?.state ?? '').toLowerCase();
    const cams = arr(variables.cameras);
    /* Gruppen-Helfer (z. B. „Fenster“ ohne Geräteklasse) zählen über ihre Mitglieder. */
    const flat = (id) => (id.startsWith('binary_sensor.') && Array.isArray(states[id]?.attributes?.entity_id))
      ? states[id].attributes.entity_id : [id];
    const ids = [...new Set([variables.alarm_entity, variables.doors_entity, variables.windows_entity,
      variables.lock_entity, variables.lock_entity_2, ...arr(variables.locks), ...arr(variables.entities), ...cams]
      .filter((x) => typeof x === 'string' && x.includes('.')).flatMap(flat))]
      /* „Wer sieht das?“ der Kacheln (casora-core.js): Ausgeblendetes zählt nicht mit. */
      .filter((x) => !window.casoraSeesEntity || window.casoraSeesEntity(x, user));
    const r = { triggered: false, disarmed: false, locks: 0, lockDead: 0, doors: 0, windows: 0, doorsTilted: 0, windowsTilted: 0, gates: 0, camDead: 0 };
    for (const id of ids) {
      const dom = id.split('.')[0], s = st(id), a = states[id]?.attributes || {};
      const dc = String(a.device_class || '').toLowerCase();
      const dead = !s || s === 'unavailable' || s === 'unknown';
      if (dom === 'alarm_control_panel') { if (s === 'triggered') r.triggered = true; else if (s === 'disarmed') r.disarmed = true; }
      else if (dom === 'lock') { if (dead) r.lockDead++; else if (s !== 'locked' && s !== 'locking') r.locks++; }
      else if (dom === 'camera') { if (dead || window._casoraCamDead?.[id] || window.casoraCamOffline?.(id, states)) r.camDead++; }
      else if (dom === 'cover') { if (['garage', 'gate', 'door'].includes(dc) && (s === 'open' || s === 'opening')) r.gates++; }
    }
    /* Türen/Fenster: Kontakt + Kippsensor (+ Kombi-Sensor) sind eine Öffnung (window.casoraOpenings). */
    const bs = ids.filter((id) => id.startsWith('binary_sensor.'));
    const units = window.casoraOpenings ? window.casoraOpenings(hass, bs) : bs.map((id) => {
      const a = states[id]?.attributes || {}, dc = String(a.device_class || '').toLowerCase(), s = st(id);
      if (!['door', 'window', 'garage_door', 'opening', ''].includes(dc)) return null;
      const nm = id + ' ' + (a.friendly_name || '');
      const on = s === 'on' || s === 'open';
      return { state: !on ? 'closed' : (a.tilt === true || a.tilt === 'true' || /kipp|tilt/i.test(nm)) ? 'tilted' : 'open',
        kind: dc === 'window' || (dc !== 'door' && dc !== 'garage_door' && /fenster|window/i.test(nm)) ? 'window' : 'door' };
    }).filter(Boolean);
    for (const u of units) {
      const win = u.kind === 'window' || (u.main && u.main === variables.windows_entity);
      if (u.state === 'tilted') { if (win) r.windowsTilted++; else r.doorsTilted++; }
      else if (u.state === 'open') { if (win) r.windows++; else r.doors++; }
    }
    r.insecure = r.triggered || r.disarmed || !!(r.locks || r.doors || r.windows || r.doorsTilted || r.windowsTilted || r.gates);
    r.problem = !!(r.camDead || r.lockDead);
    /* Stufe = schlimmster Zustand: ausgelöst = Gefahr, sonst Hinweis bei allem, was der Text
       nennt; Gefahr auch bei klemmendem Schloss oder Offenem bei Abwesenheit (00-finden.js). */
    const h = window.casoraSecurityLevel ? window.casoraSecurityLevel(hass, ids) : 'ok';
    r.level = r.triggered ? 'alarm' : (r.insecure || r.problem) ? (h === 'alarm' ? 'alarm' : 'warn') : 'ok';
    return r;
  })();
  const legacy = _sec.triggered ? 'var(--casora-badge-red-color, #ff453a)'
    : (_sec.insecure || _sec.problem) ? 'var(--casora-badge-alert-color, #ff9800)'
    : 'var(--casora-badge-security-color, #00c3d0)';
  return `var(--casora-security-${_sec.level}-color, ${legacy})`;
]]]

casora_badge_temp.extra_styles:
[[[
  const ev = variables?.enabled;
  const enabled = (ev === undefined || ev === null) ? true :
    (typeof ev === 'boolean') ? ev :
    (typeof ev === 'number') ? ev !== 0 :
    !['false','0','no','off','disabled'].includes(String(ev).trim().toLowerCase());

  const hasEnt = !!entity?.entity_id;
  const stRaw  = String(entity?.state ?? '').trim();
  const st     = stRaw.toLowerCase();
  const v      = parseFloat(stRaw);
  const hide   = !enabled || !hasEnt || !stRaw || ['unknown','unavailable','none'].includes(st) || Number.isNaN(v);

  const unit = String(variables?.temp_unit || (hass.config?.unit_system?.temperature === '°F' ? 'F' : 'C')).toUpperCase();
  const t = (unit === 'F')
    ? { cool: 70, warm: 81 }
    : { cool: 21, warm: 27 };

  let svgUrl;
  if      (v <= t.cool) svgUrl = window.casoraIconUrl('temp-low');
  else if (v <= t.warm) svgUrl = window.casoraIconUrl('temp-medium');
  else                  svgUrl = window.casoraIconUrl('temp-high');

  let gaugeCSS = '';
  if (variables?.gauge && !hide) {
    const gf  = Math.max(0.05, Math.min(1,
      unit === 'F' ? (v - 45) / 50 : (v - 7) / 28));
    const arc = Math.round(gf * 270);
    const rr = 13.5, C = 16, W = 3;
    const pt = (deg) => {
      const a = deg * Math.PI / 180;
      return `${(C + rr * Math.sin(a)).toFixed(3)} ${(C - rr * Math.cos(a)).toFixed(3)}`;
    };
    const arcPath = (a0, a1) =>
      `M ${pt(a0)} A ${rr} ${rr} 0 ${(a1 - a0) > 180 ? 1 : 0} 1 ${pt(a1)}`;
    let paths = '';
    if (arc < 269) paths += `<path d='${arcPath(225 + arc, 495)}' stroke='white' stroke-opacity='0.30' stroke-width='${W}' stroke-linecap='round' fill='none'/>`;
    paths += `<path d='${arcPath(225, 225 + arc)}' stroke='white' stroke-width='${W}' stroke-linecap='round' fill='none'/>`;

    const svg = `<svg xmlns='http://www.w3.org/2000/svg' width='32' height='32' viewBox='0 0 32 32'>${paths}</svg>`;
    const maskUrl = `url("data:image/svg+xml,${encodeURIComponent(svg)}")`;
    gaugeCSS = `
      #img-cell::before, .img-cell::before {
        background-color: color-mix(in srgb, var(--casora-badge-glyph, #fff) var(--casora-badge-circle-mix, 0%), var(--casora-badge-icon-fg, var(--casora-icon-color, var(--primary-text-color)))) !important;
        scale: var(--casora-badge-glyph-scale, none);
      }

      #img-cell::after, .img-cell::after {
        content: '';
        position: absolute;
        inset: 0;
        border-radius: 9999px;
        background: var(--casora-icon-color, #fff);
        opacity: calc(1 - var(--casora-badge-circle-on, 0));
        -webkit-mask: ${maskUrl} no-repeat center / 100% 100%;
        mask: ${maskUrl} no-repeat center / 100% 100%;
        transform: translateZ(0);
        -webkit-transform: translateZ(0);
      }

${variables?.gauge_keep_bg ? '#img-cell, .img-cell { --casora-badge-icon-scale: calc(54% + 31% * var(--casora-badge-circle-on, 0)); }' : `
      ha-card.button-card-main, ha-card.button-card-main:hover, ha-card.button-card-main:active,
      :host(:hover) ha-card, :host(:active) ha-card {
        /* Weich: Pille wie die Haupt-Badges (Ring ist dort aus) – sonst stand weiße Schrift
           direkt auf dem hellen Foto. Andere Designs: durchsichtig wie bisher. */
        background: color-mix(in srgb, var(--badge-background, transparent) calc(var(--casora-badge-circle-on, 0) * 100%), transparent) !important;
        box-shadow: var(--casora-badge-gauge-shadow, none) !important;
        filter: none !important;
        -webkit-filter: none !important;
        -webkit-tap-highlight-color: transparent !important;
      }
      ha-ripple, mwc-ripple { display: none !important; }
`}
    `;
  }

  return `
    :host{display:${hide ? 'none' : 'inline-block'} !important;order:var(--casora-badge-order-climate,2);}
    #img-cell, .img-cell { position: relative; }
    /* Weich (--casora-badge-circle-on: 1): volles Symbol (ha-state-icon) wie bei den Haupt-Badges –
       die feine Strichgrafik im ::before wirkte im Kreis winzig und dünn. Andere Designs: wie bisher. */
    #img-cell #icon, .img-cell #icon {
      color: color-mix(in srgb, var(--casora-badge-glyph, #fff) var(--casora-badge-circle-mix, 0%), transparent) !important;
      --icon-primary-color: color-mix(in srgb, var(--casora-badge-glyph, #fff) var(--casora-badge-circle-mix, 0%), transparent) !important;
      --state-icon-color: color-mix(in srgb, var(--casora-badge-glyph, #fff) var(--casora-badge-circle-mix, 0%), transparent) !important;
      opacity: var(--casora-badge-circle-on, 0) !important;
    }
    #img-cell::before, .img-cell::before {
      content: '';
      opacity: calc(1 - var(--casora-badge-circle-on, 0));
      position: absolute;
      inset: 0;
      background-color: color-mix(in srgb, var(--casora-badge-glyph, #fff) var(--casora-badge-circle-mix, 0%), var(--casora-icon-color, var(--primary-text-color)));
      scale: var(--casora-badge-glyph-scale, none);
      -webkit-mask: url('${svgUrl}') no-repeat center / var(--casora-badge-icon-scale, 85%) var(--casora-badge-icon-scale, 85%);
      mask: url('${svgUrl}') no-repeat center / var(--casora-badge-icon-scale, 85%) var(--casora-badge-icon-scale, 85%);
      transform: translateZ(0);
    }
  ` + gaugeCSS;
]]]

