casora_camera.entity_picture:
[[[
  /* Kamera aus: Kamerasymbol auf der normalen Kachelfläche wie jede ausgeschaltete Kachel. */
  if (String(entity?.state || '').toLowerCase() === 'off') return window.casoraIconUrl('camera');
  // Weich (Runde 2): ohne Bild (keine Entität, offline) wenigstens das Kamerasymbol wie jede Kachel.
  /* Offline (Kamera liefert kein Bild, _casoraCamDead) zählt wie ohne Bild – sonst lag ein schwarzes
     Standbild auf der Kachel und der dunkle Weich-Name darauf war unlesbar (03.10.2026). */
  const s0 = String(entity?.state || '').toLowerCase();
  const dead = s0 !== 'recording' && s0 !== 'off' && (!!window._casoraCamDead?.[entity?.entity_id] || !!window.casoraCamOffline?.(entity?.entity_id, states, variables));
  /* D-05: Weich auch ohne geladenes Standbild (lädt nicht, nur Schwarz) – this._hcPic setzt background-image. */
  const plain = !entity?.attributes?.entity_picture || entity?.state === 'unavailable' || dead || this._hcPic !== true;
  return plain && (() => { try { return getComputedStyle(document.documentElement).getPropertyValue('--casora-tile-fallback-name').trim() === '1'; } catch (e) { return false; } })() ? window.casoraIconUrl('camera') : null;
]]]

