card.background-image:
[[[
  const host = this;
  const setBg = (u) => { host.style.setProperty('--casora-cam-img', u ? `url("${u}")` : 'none'); };
  const weich = (() => { try { return getComputedStyle(document.documentElement).getPropertyValue('--casora-tile-fallback-name').trim() === '1'; } catch (e) { return false; } })();
  /* D-05: ob gerade ein echtes Bild liegt – Name, Zustand und Symbol der Kachel richten sich in Weich danach. */
  const picNow = (on) => { if (host._hcPic !== on) { host._hcPic = on; if (host.requestUpdate) host.requestUpdate(); } };
  const pic = entity?.attributes?.entity_picture;
  /* Weich: offline (kein Bild, _casoraCamDead) wie ohne Bild – normale Kachelfläche statt Schwarz. */
  const s0 = String(entity?.state || '').toLowerCase();
  const dead = s0 !== 'recording' && s0 !== 'off' && (!!window._casoraCamDead?.[entity?.entity_id] || !!window.casoraCamOffline?.(entity?.entity_id, states, variables))
    && (() => { try { return getComputedStyle(document.documentElement).getPropertyValue('--casora-tile-fallback-name').trim() === '1'; } catch (e) { return false; } })();
  if (s0 === 'off' || !pic || entity?.state === 'unavailable' || dead) {
    host._hcWant = null;
    clearTimeout(host._hcRetry);
    if (host._hcBlob) { URL.revokeObjectURL(host._hcBlob); host._hcBlob = null; }
    setBg(null);
    host._hcPic = false;
    return "none";
  }
  const url = pic.startsWith("/") ? `${window.location.origin}${pic}` : pic;
  if (host._hcWant !== url) {
    host._hcWant = url;
    clearTimeout(host._hcRetry);
    const load = (attempt) => {
      if (host._hcWant !== url) return;
      fetch(attempt ? `${url}&_r=${Date.now()}` : url, { cache: 'no-store' })
        .then((r) => r.ok ? r.blob() : Promise.reject(r.status))
        .then((b) => {
          if (host._hcWant !== url || !b.size) return;
          /* D-05 (Weich): ein ganz schwarzes oder einfarbiges Standbild (Platzhalter ohne Bild) zählt als
             „kein Bild“ – sonst tiefschwarze Kachel mit „Live“. */
          return (weich && window.createImageBitmap ? createImageBitmap(b).then((bm) => {
            const c = document.createElement('canvas'); c.width = 8; c.height = 8;
            const x = c.getContext('2d'); x.drawImage(bm, 0, 0, 8, 8);
            const px = x.getImageData(0, 0, 8, 8).data; const hi = [0, 0, 0], lo = [255, 255, 255];
            for (let i = 0; i < px.length; i += 4) for (let k = 0; k < 3; k++) { hi[k] = Math.max(hi[k], px[i + k]); lo[k] = Math.min(lo[k], px[i + k]); }
            return Math.max(hi[0], hi[1], hi[2]) < 14 || Math.max(hi[0] - lo[0], hi[1] - lo[1], hi[2] - lo[2]) < 6;
          }).catch(() => false) : Promise.resolve(false)).then((black) => {
            if (host._hcWant !== url) return;
            const old = host._hcBlob;
            host._hcBlob = black ? null : URL.createObjectURL(b);
            setBg(host._hcBlob);
            if (old) setTimeout(() => URL.revokeObjectURL(old), 1000);
            picNow(!black);
          });
        })
        .catch(() => {
          picNow(false);
          if (host._hcWant === url && attempt < 8) host._hcRetry = setTimeout(() => load(attempt + 1), Math.min(2000 * 2 ** attempt, 30000));
        });
    };
    load(0);
  }
  /* D-05 (Weich): Abdunklung nur, wenn wirklich ein Bild liegt – sonst die normale Kachelfläche. */
  if (weich && host._hcPic !== true) return "none";
  return "linear-gradient(rgba(20,20,20,0.4), rgba(20,20,20,0.6)), var(--casora-cam-img, none)";
]]]

card.--casora-entity-name:
[[[
  /* Weich: liegt ein Standbild (abgedunkelt) auf der Kachel, steht der Name hell wie der Zustand –
     der dunkle Weich-Name war darauf unlesbar. Ohne Bild bleibt die Theme-Farbe (inherit). */
  const s0 = String(entity?.state || '').toLowerCase();
  const dead = s0 !== 'recording' && s0 !== 'off' && (!!window._casoraCamDead?.[entity?.entity_id] || !!window.casoraCamOffline?.(entity?.entity_id, states, variables));
  const plain = s0 === 'off' || !entity?.attributes?.entity_picture || entity?.state === 'unavailable' || dead || this._hcPic !== true;
  return !plain && (() => { try { return getComputedStyle(document.documentElement).getPropertyValue('--casora-tile-fallback-name').trim() === '1'; } catch (e) { return false; } })() ? 'rgba(255,255,255,0.92)' : 'inherit';
