[[[
  /* Ohne Standbild liegt die Schrift auf der normalen Kachelfläche – helle Themes brauchen dort dunkle Schrift. */
  const s0 = String(entity?.state || '').toLowerCase();
  const dead = s0 !== 'recording' && s0 !== 'off' && (!!window._casoraCamDead?.[entity?.entity_id] || !!window.casoraCamOffline?.(entity?.entity_id, states, variables))
    && (() => { try { return getComputedStyle(document.documentElement).getPropertyValue('--casora-tile-fallback-name').trim() === '1'; } catch (e) { return false; } })();
  const plain = s0 === 'off' || !entity?.attributes?.entity_picture || entity?.state === 'unavailable' || dead
    || (this._hcPic !== true && (() => { try { return getComputedStyle(document.documentElement).getPropertyValue('--casora-tile-fallback-name').trim() === '1'; } catch (e) { return false; } })());
  return plain ? 'var(--casora-camera-plain-text, rgba(255,255,255,0.85))' : 'rgba(255,255,255,0.85)';
]]]

casora_cameras.state_display:
[[[
  const fit = (t) => window.casoraStateFit?.(t) ?? t;
  const cams = Array.isArray((window._casoraCams ? window._casoraCams(variables, entity, hass) : variables.cameras)) ? (window._casoraCams ? window._casoraCams(variables, entity, hass) : variables.cameras).filter(Boolean) : [];
  if (!cams.length) return fit('Keine Kameras');
  const dead = cams.filter(id => ['unavailable','unknown',''].includes(String(states[id]?.state ?? '').toLowerCase()) || !!window.casoraCamOffline?.(id, states)).length;
  if (dead === cams.length) return fit(cams.length === 1 ? 'Offline' : 'Alle offline');
  if (dead > 0) return fit(dead + ' offline');
  const alert = window.casoraCameraAlert ? window.casoraCameraAlert(hass, states, cams, variables.alert_window_minutes) : '';
  return fit(alert || 'Sicher');
]]]

casora_car.state_display:
[[[
  const fit = (t) => window.casoraStateFit?.(t) ?? t;
  return fit(window._casoraCar ? window._casoraCar.tile(variables.car || entity?.entity_id, states) : (entity?.state || ''));
]]]

