variables.active_override:
[[[
  /* Schiebedach offen → Kachel aktiv (Wunsch 24.09.2026), sonst normale Logik */
  const p = variables.car || entity?.entity_id || null;
  const sd = window._casoraCar && window._casoraCar.id ? window._casoraCar.id(p, 'schiebedach', 'binary_sensor') : (p && 'binary_sensor.' + p + '_schiebedach'); return sd && states[sd]?.state === 'on' ? true : null;
]]]

casora_popup.content:
[[[
  const sensors  = Array.isArray(variables.sensors) ? variables.sensors.filter(Boolean) : [];
  /* Die Kachel-Entität zählt nur dort, wo sie hingehört: ein Temperatur-Badge
     ist kein Luftqualitätssensor. */
  const ownId    = entity?.entity_id;
  const ownDc    = String(entity?.attributes?.device_class || '');
  const tempId   = variables.entity_temp || (ownDc === 'temperature' ? ownId : null);
  const humidId  = variables.entity_humidity || (ownDc === 'humidity' ? ownId : null);
  const qualId   = variables.entity_quality || sensors[0]
    || (ownId && !['temperature', 'humidity'].includes(ownDc) && !String(ownId).startsWith('climate.') ? ownId : null);
  const roomName = variables.room_name || 'Klima';

  const safeNum = (id) => {
    if (!id) return null;
    const s = states[id]?.state;
    if (!s || s === 'unavailable' || s === 'unknown') return null;
    const n = parseFloat(s);
    return isNaN(n) ? null : n;
  };

  const sensorThresh = (eid) => {
    const id   = (eid || '').toLowerCase();
    const unit = states[eid]?.attributes?.unit_of_measurement || '';
    const dc   = (states[eid]?.attributes?.device_class || '').toLowerCase();
    const isIndex = id.endsWith('_index') || unit.toLowerCase() === 'index';
    if (id.includes('pm25') || id.includes('pm2_5') || dc === 'pm25')
      return { good: 12,   moderate: 35.4, high: 55.4, unit: unit || 'µg/m³' };
    if (id.includes('pm10') || dc === 'pm10')
      return { good: 54,   moderate: 154,  high: 254,  unit: unit || 'µg/m³' };
    if (id.includes('voc') || id.includes('volatile_organic') || dc.includes('volatile_organic'))
      return isIndex
        ? { good: 6,   moderate: 8,   high: 9,   unit: unit || 'index' }
        : { good: 100, moderate: 200, high: 300, unit: unit || 'ppb' };
    if (id.includes('no2') || id.includes('nitrogen_dioxide') || dc === 'nitrogen_dioxide')
      return isIndex
        ? { good: 6,  moderate: 8,   high: 9,   unit: unit || 'index' }
        : { good: 53, moderate: 100, high: 360, unit: unit || 'ppb' };
    if (id.includes('co2') || id.includes('carbon') || dc === 'carbon_dioxide')
      return { good: 1000, moderate: 1500, high: 2000, unit: unit || 'ppm' };
    return { good: null, moderate: null, high: null, unit };
  };

  const _qid  = JSON.stringify(qualId  || '');
  const _tid  = JSON.stringify(tempId  || '');
  const _hid  = JSON.stringify(humidId || '');
  const _sns  = JSON.stringify(sensors);
  const _room = JSON.stringify(roomName);

  const allEntities = [qualId, tempId, humidId, ...sensors].filter(Boolean);

  const temp      = safeNum(tempId);
  const tempUnit  = states[tempId]?.attributes?.unit_of_measurement || '°';
  const isFahrenheit = tempUnit === '°F';
  const graphTempColor =
    temp == null ? '#67F5A0' :
    isFahrenheit ? (
      temp < 76 ? '#67F5A0' :
      temp < 82 ? '#FF9230' : '#FF4245'
    ) : (
      temp < 24 ? '#67F5A0' :
      temp < 28 ? '#FF9230' : '#FF4245'
    );


  /* Styles */

  const noHoverStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; }',
    'ha-card { background: transparent !important; border: none !important; border-radius: 0 !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; cursor: default !important; }',
    'ha-card:hover { box-shadow: none !important; border-color: transparent !important; }',
    'ha-ripple { display: none !important; }',
  ].join('\n');

  const wrapperStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; }',
    'ha-card { background: transparent !important; border: none !important; border-radius: 0 !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; overflow: visible !important; cursor: default !important; }',
    'ha-card:hover { box-shadow: none !important; }',
    '#container { overflow: visible !important; }',
    'ha-ripple { display: none !important; }',
  ].join('\n');

  const contentCardStyle = wrapperStyle + '\n@media (max-width: 600px) { ha-card { padding-left: 14px !important; padding-right: 14px !important; } }';

  const tapStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; pointer-events: auto !important; }',
    'ha-card { background: transparent !important; border: none !important; border-radius: 0 !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; overflow: visible !important; }',
    'ha-card #container { transition: opacity 0.18s ease, filter 0.18s ease !important; }',
    'ha-card:hover #container { filter: brightness(1.12) saturate(1.08) drop-shadow(0 0 10px rgba(255,255,255,0.05)); }',
    'ha-ripple { display: none !important; }',
  ].join('\n');

  const tileTapStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: inset 0 1px 0.5px -0.5px rgba(255,255,255,calc(var(--casora-popup-tiles-glow-top-tight,0.20) * 1.5)), inset 0 -1px 0.5px -0.5px rgba(255,255,255,calc(var(--casora-popup-tiles-glow-bottom-tight,0.15) * 1.5)), inset 0 3px 6px -3px rgba(255,255,255,calc(var(--casora-popup-tiles-glow-top-soft,0.08) * 1.5)), inset 0 -3px 6px -3px rgba(255,255,255,calc(var(--casora-popup-tiles-glow-bottom-soft,0.05) * 1.5)) !important; }',
    'ha-card { background: var(--casora-popup-tiles-fill, rgba(255,255,255,0.08)) !important; border: none !important; border-radius: 24px !important; box-shadow: inset 0 1px 0.5px -0.5px rgba(255,255,255,var(--casora-popup-tiles-glow-top-tight,0.20)), inset 0 -1px 0.5px -0.5px rgba(255,255,255,var(--casora-popup-tiles-glow-bottom-tight,0.15)), inset 0 3px 6px -3px rgba(255,255,255,var(--casora-popup-tiles-glow-top-soft,0.08)), inset 0 -3px 6px -3px rgba(255,255,255,var(--casora-popup-tiles-glow-bottom-soft,0.05)) !important; backdrop-filter: var(--casora-popup-tiles-backdrop, blur(10px) saturate(1.1)) !important; -webkit-backdrop-filter: var(--casora-popup-tiles-backdrop, blur(10px) saturate(1.1)) !important; cursor: pointer !important; transform: scale(1) !important; transition: background-color var(--casora-popup-tile-hover-duration, 0.2s) ease, transform var(--casora-popup-tile-hover-duration, 0.2s) ease, box-shadow 0.2s ease !important; }',
    'ha-card:hover { background: var(--casora-popup-tile-hover, rgba(255,255,255,0.09)) !important; transform: scale(var(--casora-popup-tile-hover-scale, 1.01)) !important; }',
    'ha-ripple { display: none !important; }',
  ].join('\n');

  const _thresh = "const sensorThresh=(eid)=>{const id=(eid||'').toLowerCase();const dc=(states[eid]?.attributes?.device_class||'').toLowerCase();const isIdx=id.endsWith('_index')||(states[eid]?.attributes?.unit_of_measurement||'').toLowerCase()==='index';if(id.includes('pm25')||id.includes('pm2_5')||dc==='pm25')return{good:12,moderate:35.4,high:55.4};if(id.includes('pm10')||dc==='pm10')return{good:54,moderate:154,high:254};if(id.includes('voc')||id.includes('volatile_organic')||dc.includes('volatile_organic'))return isIdx?{good:6,moderate:8,high:9}:{good:100,moderate:200,high:300};if(id.includes('no2')||id.includes('nitrogen_dioxide')||dc==='nitrogen_dioxide')return isIdx?{good:6,moderate:8,high:9}:{good:53,moderate:100,high:360};if(id.includes('co2')||id.includes('carbon')||dc==='carbon_dioxide')return{good:1000,moderate:1500,high:2000};return{good:null,moderate:null,high:null};};";
  const _safe = "const safeNum=(id)=>{if(!id)return null;const s=states[id]?.state;if(!s||s==='unavailable'||s==='unknown')return null;const n=parseFloat(s);return isNaN(n)?null:n;};";
  const _scoreBlock = `
    const aqState = (qualId ? states[qualId]?.state : '').toLowerCase().replace(/_/g, ' ') || '';
    let scoreLabel = 'Unbekannt', scoreColor = 'var(--primary-text-color)', advice = 'Luftqualität nicht verfügbar', score = 3;
    switch (aqState) {
      case 'excellent': scoreLabel='Ausgezeichnet'; scoreColor='var(--casora-badge-air-quality-excellent-color)'; advice='Luftqualität ist hervorragend';    score=5; break;
      case 'good':      scoreLabel='Gut';      scoreColor='var(--casora-badge-air-quality-good-color)';     advice='Luftqualität ist gut';       score=4; break;
      case 'moderate':  scoreLabel='Mäßig';  scoreColor='var(--casora-badge-air-quality-moderate-color)'; advice='Luftqualität ist mäßig';   score=3; break;
      case 'fair':      scoreLabel='Mäßig';      scoreColor='var(--casora-badge-air-quality-moderate-color)'; advice='Luftqualität ist mäßig';   score=3; break;
      case 'poor':      scoreLabel='Schlecht';      scoreColor='var(--casora-badge-air-quality-poor-color)';     advice='Lüften empfohlen';      score=2; break;
      case 'bad': case 'very bad': case 'very poor': case 'extremely poor':
        scoreLabel='Sehr schlecht'; scoreColor='var(--casora-badge-air-quality-bad-color)'; advice='Jetzt lüften'; score=1; break;
    }
    const activeSensors = sensors.filter(eid => safeNum(eid) != null);
    if (activeSensors.length > 0) {
      const levels = activeSensors.map(eid => { const v=safeNum(eid); const t=sensorThresh(eid); if(t.good==null)return 0; if(v<=t.good)return 0; if(v<=t.moderate)return 1; if(v<=t.high)return 2; return 3; });
      const worstLevel = Math.max(...levels);
      switch (worstLevel) {
        case 0: scoreLabel='Ausgezeichnet'; scoreColor='var(--casora-badge-air-quality-excellent-color)'; advice='Luftqualität ist hervorragend'; break;
        case 1: scoreLabel='Mäßig';  scoreColor='var(--casora-badge-air-quality-moderate-color)'; advice='Luftqualität ist mäßig'; break;
        case 2: scoreLabel='Schlecht';       scoreColor='var(--casora-badge-air-quality-poor-color)';    advice='Lüften empfohlen'; break;
        default: scoreLabel='Sehr schlecht';       scoreColor='var(--casora-badge-air-quality-bad-color)';     advice='Jetzt lüften'; break;
      }
      activeSensors.forEach(eid => {
        const id=eid.toLowerCase(); const v=safeNum(eid); const t=sensorThresh(eid);
        if (v==null||t.good==null||v<=t.good) return;
        if (id.includes('pm25')||id.includes('pm2_5')) advice='Erhöhte Partikelbelastung';
        if (id.includes('voc')) advice='VOCs erkannt – lüften';
        if (id.includes('no2')||id.includes('nitrogen_dioxide')) advice='NO₂ erkannt – lüften';
        if (id.includes('co2')||id.includes('carbon')) advice = v > t.high ? 'CO₂ hoch – Fenster öffnen' : 'CO₂ erhöht – lüften';
      });
    }
  `;

  /* AQI Gauge */
  const gaugeCard = {
    type: 'custom:button-card',
    entity: qualId,
    tap_action: qualId ? { action: 'more-info' } : { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: tapStyle },
    styles: {
      card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '0' }],
      grid: [{ 'grid-template-areas': '"c"' }, { 'grid-template-columns': '1fr' }],
      custom_fields: { c: [{ 'justify-self': 'end' }] },
    },
    custom_fields: {
      c: `[[[
        const qualId = ${_qid};
        const sensors = ${_sns};
        const radius = 42;
        const circ = 2 * Math.PI * radius;
        ${_safe}
        ${_thresh}
        ${_scoreBlock}
        const activeSensors2 = sensors.filter(eid => safeNum(eid) != null);
        let aqiNum, aqiDen, aqiRatio;
        if (activeSensors2.length > 0) {
          const levels2 = activeSensors2.map(eid => { const v=safeNum(eid); const t=sensorThresh(eid); if(t.good==null)return 0; if(v<=t.good)return 0; if(v<=t.moderate)return 1; if(v<=t.high)return 2; return 3; });
          const goodCount = levels2.filter(l => l === 0).length;
          aqiNum = goodCount; aqiDen = activeSensors2.length; aqiRatio = goodCount / activeSensors2.length;
        } else {
          aqiNum = score; aqiDen = 5; aqiRatio = score / 5;
        }
        const dashOffset = circ - aqiRatio * circ;
        return '<div style="position:relative;width:120px;height:120px;">'
          + '<svg viewBox="0 0 100 100" style="transform:rotate(-90deg);width:100%;height:100%;">'
            + '<circle cx="50" cy="50" r="42" fill="none" stroke="rgba(255,255,255,0.07)" stroke-width="7"/>'
            + '<circle cx="50" cy="50" r="42" fill="none" stroke="' + scoreColor + '" stroke-width="7" stroke-linecap="round" stroke-dasharray="' + circ.toFixed(2) + '" stroke-dashoffset="' + dashOffset.toFixed(2) + '"/>'
          + '</svg>'
          + '<div style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;">'
            + '<div style="position:relative;display:flex;align-items:center;justify-content:center;margin-top:6px;">'
              + '<div style="position:absolute;bottom:100%;left:0;right:0;text-align:center;font-size:11px;color:var(--casora-popup-tiles-text-muted);letter-spacing:.06em;font-weight:500;padding-bottom:2px;">AQI</div>'
              + '<div style="font-size:24px;color:' + scoreColor + ';font-weight:600;line-height:1;">' + aqiNum + '/' + aqiDen + '</div>'
            + '</div>'
          + '</div>'
        + '</div>';
      ]]]`,
    },
  };

  /* Right Column */
  const rightColCard = {
    type: 'custom:button-card',
    entity: qualId,
    tap_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: wrapperStyle },
    styles: {
      card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '0' }],
      grid: [
        { display: 'flex' }, { 'flex-direction': 'column' }, { 'align-items': 'flex-end' }, { gap: '28px' },
      ],
      custom_fields: {
        ring: [{ flex: '0 0 auto' }, { 'margin-top': '66px' }],
      },
    },
    custom_fields: {
      ring: { card: gaugeCard },
    },
  };

  /* Temp Stat Card */
  const tempStatCard = {
    type: 'custom:button-card',
    entity: tempId || qualId,
    tap_action: tempId ? { action: 'more-info' } : { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: tempId ? tapStyle : noHoverStyle },
    styles: {
      card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '0' }],
      grid: [{ 'grid-template-areas': '"c"' }, { 'grid-template-columns': '1fr' }],
      custom_fields: { c: [{ 'justify-self': 'start' }] },
    },
    custom_fields: {
      c: `[[[
        const tempId = ${_tid};
        const s = tempId ? states[tempId] : null;
        const raw = parseFloat(s?.state);
        const v = isNaN(raw) ? null : raw;
        const tempUnit = s?.attributes?.unit_of_measurement || '°';
        const isFahrenheit = tempUnit === '°F';
        const tempStr = v != null ? (isFahrenheit ? Math.round(v).toString() : (window.casoraNum || ((x, a, b) => Number(x).toLocaleString(window.casoraLocale ? window.casoraLocale() : 'de-DE', { minimumFractionDigits: a, maximumFractionDigits: b == null ? a : b })))(v, 1)) : '—';
        const graphTempColor =
          v == null ? 'var(--casora-badge-temp-comfortable-color, #67F5A0)' :
          isFahrenheit ? (
            v < 76 ? 'var(--casora-badge-temp-comfortable-color, #67F5A0)' :
            v < 82 ? '#FF9230' : '#FF4245'
          ) : (
            v < 24 ? 'var(--casora-badge-temp-comfortable-color, #67F5A0)' :
            v < 28 ? '#FF9230' : '#FF4245'
          );
        return '<div>'
          + '<div style="display:flex;align-items:baseline;gap:3px;padding-right:6px;">'
            + '<span style="font-size:26px;font-weight:400;color:var(--casora-popup-tiles-text-primary);">' + tempStr + '</span>'
            + '<span style="font-size:13px;color:var(--casora-popup-tiles-text-secondary);">' + tempUnit + '</span>'
          + '</div>'
          + '<div style="display:flex;align-items:center;gap:6px;margin-top:7px;">'
            + '<span style="width:8px;height:8px;background:' + graphTempColor + ';border-radius:50%;display:inline-block;flex-shrink:0;"></span>'
            + '<span style="font-size:14px;color:var(--casora-popup-tiles-text-secondary);">Temp</span>'
          + '</div>'
        + '</div>';
      ]]]`,
    },
  };

  /* Humid Stat Card */
  const humidStatCard = {
    type: 'custom:button-card',
    entity: humidId || qualId,
    tap_action: humidId ? { action: 'more-info' } : { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: humidId ? tapStyle : noHoverStyle },
    styles: {
      card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '0' }],
      grid: [{ 'grid-template-areas': '"c"' }, { 'grid-template-columns': '1fr' }],
      custom_fields: { c: [{ 'justify-self': 'start' }] },
    },
    custom_fields: {
      c: `[[[
        const humidId = ${_hid};
        const s = humidId ? states[humidId] : null;
        const raw = parseFloat(s?.state);
        const v = isNaN(raw) ? null : raw;
        const humidStr = v != null ? v.toFixed(0) : '—';
        const humidColor =
          v == null        ? 'rgba(255,255,255,0.7)' :
          v < 20 || v > 75 ? 'var(--casora-popup-red-color, #ff4245)'    :
          v < 30 || v > 65 ? 'var(--casora-popup-orange-color, #ff9230)' :
          v < 35 || v > 60 ? 'var(--casora-popup-yellow-color, #ffd600)' :
          'var(--casora-badge-climate-color, #C7CED6)';
        return '<div>'
          + '<div style="display:flex;align-items:baseline;gap:3px;padding-left:6px;">'
            + '<span style="font-size:26px;font-weight:400;color:var(--casora-popup-tiles-text-primary);">' + humidStr + '</span>'
            + '<span style="font-size:13px;color:var(--casora-popup-tiles-text-secondary);">%</span>'
          + '</div>'
          + '<div style="display:flex;align-items:center;gap:6px;margin-top:7px;margin-left:6px;">'
            + '<span style="width:8px;height:8px;background:' + humidColor + ';border-radius:50%;display:inline-block;flex-shrink:0;transition:background .4s ease;"></span>'
            + '<span style="font-size:14px;color:var(--casora-popup-tiles-text-secondary);">Luftfeuchtigkeit</span>'
          + '</div>'
        + '</div>';
      ]]]`,
    },
  };

  /* Stats Row */
  const statsRowCard = {
    type: 'custom:button-card',
    entity: tempId || qualId,
    tap_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: wrapperStyle },
    styles: {
      card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '0' }],
      grid: [
        { display: 'flex' }, { 'flex-direction': 'row' }, { 'align-items': 'flex-start' },
        { 'justify-content': 'flex-start' }, { gap: '0' },
      ],
      custom_fields: {
        temp_s:  [{ flex: '0 0 auto' }, { order: '1' }],
        div:     [{ flex: '0 0 auto' }, { 'align-self': 'stretch' }, { order: '2' }],
        humid_s: [{ flex: '0 0 auto' }, { order: '3' }],
      },
    },
    custom_fields: {
      temp_s:  { card: tempStatCard },
      div:     '<div style="width:2px;height:100%;background:rgba(255,255,255,0.09);margin:0 12px;"></div>',
      humid_s: { card: humidStatCard },
    },
  };

  /* Header Card */
  const headerCard = {
    type: 'custom:button-card',
    entity: qualId,
    tap_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: contentCardStyle },
    styles: {
      card: [
        { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
        { padding: '28px 28px 44px 28px' },
      ],
      grid: [
        { 'grid-template-areas': '"title right" "stats right"' },
        { 'grid-template-columns': '1fr auto' },
        { 'align-items': 'flex-start' },
        { gap: '16px 28px' },
      ],
      custom_fields: {
        title: [{ 'justify-self': 'start' }, { 'text-align': 'left' }],
        stats: [{ 'justify-self': 'start' }, { 'text-align': 'left' }],
        right: [{ 'justify-self': 'end' }, { 'align-self': 'flex-start' }],
      },
    },
    custom_fields: {
      title: `[[[
        const qualId = ${_qid};
        const sensors = ${_sns};
        const roomName = ${_room};
        ${_safe}
        ${_thresh}
        ${_scoreBlock}
        return '<div style="font-family:var(--primary-font-family,system-ui);color:var(--casora-popup-tiles-text-primary);text-align:left;">'
          + '<div style="font-size:22px;font-weight:400;letter-spacing:-.5px;margin-top:20px;margin-bottom:16px;line-height:1.4;overflow:visible;">' + advice + '</div>'
        + '</div>';
      ]]]`,
      stats: { card: statsRowCard },
      right: { card: rightColCard },
    },
  };

  /* Graph Card */
  const humidV = safeNum(humidId);
  const humidGraphColor =
    humidV == null ? '#00c3d0' :
    (humidV < 20 || humidV > 75) ? '#FF4245' :
    (humidV < 30 || humidV > 65) ? '#FF9230' :
    (humidV < 35 || humidV > 60) ? '#FFD600' :
    '#00c3d0';

  const climateSeries = [];
  if (tempId) climateSeries.push({ entity: tempId, name: 'Temperatur', color: 'c2', decimals: 1 });
  if (humidId) climateSeries.push({ entity: humidId, name: 'Luftfeuchtigkeit', color: 'c1', decimals: 0 });

  /* Diagramm (casora-chart, 1.2): Temperatur und Luftfeuchtigkeit per Umschalter statt zweiter
     y-Achse; beim Ablesen zeigt die Hero-Zeile Wert und Zeit. */
  const graphCard = {
    type: 'custom:casora-chart', kind: 'line', span: '6h', bucket: '15min', height: 104,
    series: climateSeries, readout: 'hero',
  };

  /* Sensor Tile Helpers */
  const cleanSensorName = (eid) => {
    /* Messgrößen kurz wie Temperatur/Luftfeuchtigkeit (Issue #2): nach Entität bzw. Geräteklasse,
       in derselben Reihenfolge wie Schwellen und Symbol (eCO2 mit VOC-Klasse bleibt CO₂). */
    const id = String(eid || '').toLowerCase();
    const dc = String(states[eid]?.attributes?.device_class || '').toLowerCase();
    if (id.includes('pm25') || id.includes('pm2_5') || dc === 'pm25') return 'PM2.5';
    if (id.includes('pm10') || dc === 'pm10') return 'PM10';
    if (dc === 'pm1') return 'PM1';
    if (dc === 'pm4') return 'PM4';
    if (id.includes('carbon_monoxide') || id.includes('kohlenmonoxid') || dc === 'carbon_monoxide') return 'CO';
    if (id.includes('co2') || id.includes('carbon_dioxide') || id.includes('kohlendioxid') || dc === 'carbon_dioxide') return 'CO₂';
    if (id.includes('voc') || id.includes('volatile_organic') || dc.includes('volatile_organic')) return 'VOC';
    if (id.includes('no2') || id.includes('nitrogen_dioxide') || id.includes('stickstoffdioxid') || dc === 'nitrogen_dioxide') return 'NO₂';
    if (dc === 'ozone') return 'O₃';
    if (dc === 'sulphur_dioxide') return 'SO₂';
    /* Sonst der Name ohne Raum- und Gerätenamen davor (has_entity_name: „Gerät Messwert“). */
    const fn = states[eid]?.attributes?.friendly_name || eid.split('.').pop() || eid;
    const dev = hass?.devices?.[hass?.entities?.[eid]?.device_id];
    const strip = (s, p) => {
      p = String(p || '').trim();
      if (!p) return s;
      const esc = p.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const out = s.replace(new RegExp('^' + esc + '\\s*', 'i'), '');
      return out.trim() ? out : s;
    };
    let name = strip(fn, variables.room_name);
    if (dev) name = strip(strip(name, dev.name_by_user), dev.name);
    /* Großschreibung umlautfest: \b\w hielt „ä“ für ein Wortende („LuftqualitäTsmonitor“). */
    return name.replace(/_/g, ' ').trim().replace(/(^|[^\p{L}\p{N}])(\p{L})/gu, (m, a, c) => a + c.toUpperCase());
  };

  const makeSensorCard = (eid) => {
    const name = cleanSensorName(eid);
    const info = sensorThresh(eid);

    return {
      type: 'custom:button-card',
      entity: eid,
      tap_action: { action: 'more-info' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      card_mod: { style: tileTapStyle },
      styles: {
        card: [
          { background: 'rgba(255,255,255,0.045)' }, { border: 'none' }, { borderRadius: '24px' },
          { boxShadow: 'none' }, { backdropFilter: 'none' }, { WebkitBackdropFilter: 'none' },
          { padding: '18px 18px 16px 18px' },
        ],
        grid: [{ 'grid-template-areas': '"c"' }, { 'grid-template-columns': '1fr' }],
        custom_fields: { c: [{ 'justify-self': 'stretch' }, { overflow: 'visible' }] },
      },
      custom_fields: {
        c: `[[[
          const s = states['${eid}'];
          const raw = parseFloat(s?.state);
          const v = (s?.state === 'unavailable' || s?.state === 'unknown' || isNaN(raw)) ? null : raw;
          const name = ${JSON.stringify(name)};
          const good     = ${info.good};
          const moderate = ${info.moderate};
          const high     = ${info.high};
          const unit     = ${JSON.stringify(info.unit)};

          let label, color;
          if (v == null || good == null) {
            label = v == null ? '—' : 'Wert';
            color = 'rgba(255,255,255,0.4)';
          } else if (v <= good)     { label='Gut';     color='var(--casora-badge-air-quality-good-color)'; }
          else if (v <= moderate)   { label='Mäßig'; color='var(--casora-badge-air-quality-moderate-color)'; }
          else if (v <= high)       { label='Schlecht';     color='var(--casora-badge-air-quality-poor-color)'; }
          else                      { label='Sehr schlecht';      color='var(--casora-badge-air-quality-bad-color)'; }

          let pct = 0;
          if (v != null && good != null) {
            if (v <= good)     pct = (v / good) * 50;
            else if (v <= moderate) pct = 50 + ((v - good)     / (moderate - good))     * 25;
            else if (v <= high)     pct = 75 + ((v - moderate) / (high - moderate))     * 15;
            else                    pct = Math.min(100, 90 + ((v - high) / Math.max(high, 1)) * 10);
          }

          const gradient = color;

          const valStr = v != null ? v.toLocaleString() : '—';

          return '<div style="margin-top:1px;min-width:0;overflow:hidden;">'
            + '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;gap:8px;">'
              + '<span style="font-size:13px;color:var(--casora-popup-tiles-text-primary);font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;letter-spacing:.01em;">' + name + '</span>'
              + '<span style="font-size:13px;color:' + color + ';white-space:nowrap;font-weight:600;letter-spacing:.01em;flex-shrink:0;">' + label + '</span>'
            + '</div>'
            + '<div style="display:flex;align-items:baseline;gap:3px;">'
              + '<span style="font-size:20px;font-weight:400;color:var(--casora-popup-tiles-text-primary);line-height:1;white-space:nowrap;">' + valStr + '</span>'
              + '<span style="font-size:12px;color:var(--casora-popup-tiles-text-muted);white-space:nowrap;">' + unit + '</span>'
            + '</div>'
            + '<div style="position:relative;height:8px;width:100%;background:var(--casora-popup-progress-track, rgba(255,255,255,0.09));border-radius:999px;overflow:hidden;margin-top:10px;">'
              + '<div style="position:absolute;inset:0 auto 0 0;width:' + pct.toFixed(1) + '%;border-radius:999px;background:' + gradient + ';transition:width .35s ease;"></div>'
            + '</div>'
          + '</div>';
        ]]]`,
      },
    };
  };

  /* Sensor Tiles Grid */
  const cnt    = sensors.length;
  const cols   = 2;
  const sKeys  = sensors.map((_, i) => 's' + i);
  const gcd    = (a, b) => b === 0 ? a : gcd(b, a % b);
  const rem    = cnt % cols;
  let tileAreas, tileCols;
  if (rem === 0) {
    tileCols = 'repeat(' + cols + ', 1fr)';
    const rows = [];
    for (let i = 0; i < cnt; i += cols) rows.push('"' + sKeys.slice(i, i + cols).join(' ') + '"');
    tileAreas = rows.join(' ');
  } else {
    const lcm      = cols * rem / gcd(cols, rem);
    const fullSpan = lcm / cols;
    const lastSpan = lcm / rem;
    tileCols       = 'repeat(' + lcm + ', 1fr)';
    const rows     = [];
    const fullRows = Math.floor(cnt / cols);
    for (let r = 0; r < fullRows; r++) {
      const row = sKeys.slice(r * cols, (r + 1) * cols).map(k => Array(fullSpan).fill(k).join(' ')).join(' ');
      rows.push('"' + row + '"');
    }
    const lastRow = sKeys.slice(fullRows * cols).map(k => Array(lastSpan).fill(k).join(' ')).join(' ');
    rows.push('"' + lastRow + '"');
    tileAreas = rows.join(' ');
  }

  const tileCustomFields = {};
  const tileFieldStyles  = {};
  sensors.forEach((eid, i) => {
    tileCustomFields['s' + i] = { card: makeSensorCard(eid) };
    tileFieldStyles['s' + i]  = [{ 'justify-self': 'stretch' }, { overflow: 'visible' }];
  });

  const tilesCard = cnt === 0 ? null : {
    type: 'custom:button-card',
    entity: qualId,
    tap_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: contentCardStyle },
    styles: {
      card: [
        { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
        { padding: '0px 28px 20px 28px' },
      ],
      grid: [
        { 'grid-template-areas': tileAreas },
        { 'grid-template-columns': tileCols },
        { gap: '8px' },
        { 'align-items': 'start' },
      ],
      custom_fields: tileFieldStyles,
    },
    custom_fields: tileCustomFields,
  };

  /* Shared popup anatomy: hero, chart, grouped rows. The four tiles
     become readings, carrying range on the number itself - a "Good"
     repeated down the column is noise. */
  const UI = window._casoraUI;
  if (UI) {
    /* _scoreBlock is a source string injected into nested cards, so its
       score/label/advice never exist out here. Same rules, evaluated in
       this scope. */
    const _aq = (qualId ? states[qualId]?.state : '' || '').toLowerCase().replace(/_/g, ' ') || '';
    let scoreLabel = 'Unbekannt', advice = 'Luftqualität nicht verfügbar', score = 3;
    switch (_aq) {
      case 'excellent': scoreLabel='Ausgezeichnet'; advice='Luftqualität ist hervorragend';  score=5; break;
      case 'good':      scoreLabel='Gut';      advice='Luftqualität ist gut';    score=4; break;
      case 'moderate':  scoreLabel='Mäßig';  advice='Luftqualität ist mäßig'; score=3; break;
      case 'fair':      scoreLabel='Mäßig';      advice='Luftqualität ist mäßig'; score=3; break;
      case 'poor':      scoreLabel='Schlecht';      advice='Lüften empfohlen';   score=2; break;
      case 'bad': case 'very bad': case 'very poor': case 'extremely poor':
        scoreLabel='Sehr schlecht'; advice='Jetzt lüften'; score=1; break;
    }
    const _active = sensors.filter(eid => safeNum(eid) != null);
    if (_active.length) {
      const _levels = _active.map(eid => {
        const v = safeNum(eid), t = sensorThresh(eid);
        if (t.good == null) return 0;
        if (v <= t.good) return 0;
        if (v <= t.moderate) return 1;
        if (v <= t.high) return 2;
        return 3;
      });
      switch (Math.max(..._levels)) {
        case 0: scoreLabel='Ausgezeichnet'; advice='Luftqualität ist hervorragend';  score=5; break;
        case 1: scoreLabel='Mäßig';  advice='Luftqualität ist mäßig'; score=3; break;
        case 2: scoreLabel='Schlecht';      advice='Lüften empfohlen';   score=2; break;
        default: scoreLabel='Sehr schlecht';      advice='Jetzt lüften';          score=1; break;
      }
      _active.forEach(eid => {
        const id = eid.toLowerCase(), v = safeNum(eid), t = sensorThresh(eid);
        if (v == null || t.good == null || v <= t.good) return;
        if (id.includes('pm25') || id.includes('pm2_5')) advice = 'Erhöhte Partikelbelastung';
        if (id.includes('voc')) advice = 'VOCs erkannt \u2013 l\u00fcften';
        if (id.includes('no2') || id.includes('nitrogen_dioxide')) advice = 'NO\u2082 erkannt \u2013 l\u00fcften';
        if (id.includes('co2') || id.includes('carbon')) {
          advice = v > t.high ? 'CO\u2082 hoch \u2013 Fenster \u00f6ffnen' : 'CO\u2082 erh\u00f6ht \u2013 l\u00fcften';
        }
      });
    }

    const areas = [], fields = {}, fstyle = {};
    const add = (name, html) => {
      areas.push('"' + name + '"');
      fields[name] = html;
      fstyle[name] = [{ 'justify-self': 'stretch' }, { overflow: 'visible' }];
    };

    const heroTone = score >= 4 ? 'good' : score === 3 ? null : score === 2 ? 'warn' : 'bad';
    const t = safeNum(tempId);
    const h = safeNum(humidId);
    const tUnit = states[tempId]?.attributes?.unit_of_measurement || '\u00b0';
    const _LANG = hass?.locale?.language || hass?.language || 'de';
    const _nf = (v) => (Math.round(v * 10) / 10).toLocaleString(_LANG);
    const _tU = tUnit === '\u00b0' ? '\u00b0C' : tUnit;
    const bits = [];
    if (t != null) bits.push(_nf(t) + ' ' + _tU);
    if (h != null) bits.push(Math.round(h) + ' % Luftfeuchtigkeit');

    const metricAreas = [], metricFields = {}, metricStyle = {};
    const addMetric = (n2, html) => {
      metricAreas.push('"' + n2 + '"');
      metricFields[n2] = html;
      metricStyle[n2] = [{ 'justify-self': 'stretch' }, { overflow: 'visible' }];
    };

    /* "Excellent" already says it - "Air quality is great" underneath is
       the same sentence twice, and the room name is context you had from
       the card you tapped. The bar carries the name now. */
    /* Ohne Luftqualitätssensor kein „Luftqualität: Unbekannt“ – dann führt die Temperatur. */
    const _noAq = !qualId && !sensors.length;
    const _hum = safeNum(humidId);
    addMetric('head', UI.hero(_noAq ? {
      compact: true,
      read: '*',
      label: temp != null ? 'Temperatur' : 'Luftfeuchtigkeit',
      value: temp != null ? temp.toLocaleString(window.casoraLocale ? window.casoraLocale() : 'de-DE', { maximumFractionDigits: 1 }) + ' ' + tempUnit
        : (_hum != null ? Math.round(_hum) + ' %' : '—'),
    } : {
      compact: true,
      label: 'Luftqualität',
      read: '*',
      value: scoreLabel,
    }));

    /* The chart goes under the number it explains, not at the foot of
       the sheet. Health, Battery and Stocks all do this: headline,
       chart, then the lists. It was last only because that is where the
       pre-redesign layout left it. As a field inside the content card
       rather than a sibling in the stack, so it can sit between the
       hero and the first group - and the side gutter comes from the
       card, so the chart drops its own. */
    addMetric('chart', { card: graphCard });

    const legendSeries = [];
    if (t != null) legendSeries.push({
      color: 'var(--casora-chart-c2, #C8743A)', value: _nf(t) + ' ' + _tU, label: 'Temperatur' });
    if (h != null) legendSeries.push({
      color: 'var(--casora-chart-c1, #4A7DBA)', value: Math.round(h) + ' %', label: 'Luftfeuchtigkeit' });
    if (legendSeries.length) {
      addMetric('legend', UI.legend(legendSeries));
    }

    const sensorGlyph = (eid) => {
      const id = (eid || '').toLowerCase();
      const dc = (states[eid]?.attributes?.device_class || '').toLowerCase();
      if (id.includes('co2') || id.includes('carbon') || dc === 'carbon_dioxide') {
        return { icon: 'co2-fill', tone: 'var(--casora-color-teal, #00C3D0)' };
      }
      if (id.includes('pm25') || id.includes('pm2_5') || id.includes('pm10')
          || dc === 'pm25' || dc === 'pm10') {
        return { icon: 'allergens-fill', tone: 'var(--casora-color-amber, #ffb254)' };
      }
      if (id.includes('voc') || id.includes('volatile_organic')
          || dc.includes('volatile_organic')) {
        return { icon: 'mdi:air-filter', tone: 'var(--casora-color-purple, #9333ea)' };
      }
      return { icon: 'mdi:air-filter', tone: 'var(--casora-color-blue, #0A84FF)' };
    };

    const readings = sensors.map((eid) => {
      const v = safeNum(eid);
      const th = sensorThresh(eid);
      let tone = null;
      if (v != null && th && th.good != null) {
        tone = v <= th.good ? 'good' : v <= th.moderate ? null : v <= th.high ? 'warn' : 'bad';
      }
      const unit = states[eid]?.attributes?.unit_of_measurement || th?.unit || '';
      const glyph = sensorGlyph(eid);
      return {
        entity: eid,
        icon: glyph.icon,
        iconTone: glyph.tone,
        label: cleanSensorName(eid),
        value: v == null ? '\u2014' : _nf(v) + (unit ? ' ' + unit : ''),
        valueTone: tone,
      };
    });
    /* Gleiche Messgröße zweimal (z. B. zwei PM2.5-Sensoren): Gerätename darunter (Issue #2). */
    readings.forEach((r) => {
      if (readings.filter((x) => x.label === r.label).length < 2) return;
      const d = hass?.devices?.[hass?.entities?.[r.entity]?.device_id];
      r.sub = (d && (d.name_by_user || d.name)) || states[r.entity]?.attributes?.friendly_name || null;
    });
    /* 24.09.2026: Temperatur und Luftfeuchtigkeit als erste Zeilen der Messwerte. */
    /* Wohlfühlbereiche wie bei CO2/PM/VOC in vier Stufen: grün, neutral, orange, rot. */
    const _band = (v, ok, fair, warn) => v >= ok[0] && v <= ok[1] ? 'good' : v >= fair[0] && v <= fair[1] ? null : v >= warn[0] && v <= warn[1] ? 'warn' : 'bad';
    const _climRows = [];
    if (tempId && t != null) _climRows.push({ entity: tempId, icon: 'mdi:thermometer', iconTone: graphTempColor,
      label: 'Temperatur', value: _nf(t) + ' ' + _tU, valueTone: _band(t, [20, 23], [18, 25], [16, 27]) });
    if (humidId && h != null) _climRows.push({ entity: humidId, icon: 'mdi:water-percent', iconTone: humidGraphColor,
      label: 'Luftfeuchtigkeit', value: Math.round(h) + ' %', valueTone: _band(h, [40, 60], [30, 65], [25, 70]) });
    readings.unshift(..._climRows);
    /* Weich: Messwert außerhalb des Wohlfühlbereichs (Orange/Rot) als aktive Zeile wie im Pflanzen-Popup. */
    readings.forEach((r) => { r.active = r.valueTone === 'warn' || r.valueTone === 'bad'; });
    if (readings.length) add('read', UI.group(readings, 'Messwerte'));

    /* One object: the number, its status and the curve it describes, on
       a single plate. They were two stacked blocks - a floating stat
       with a graph under it - which is the part that never read as
       Apple. Health, Battery and Stocks all bind the headline to the
       chart. The plate moved here from the chart card, which is
       transparent inside it now. */
    /* Weich (E3, 01.10.2026): der Kopf steht als Ring-Unterzeile über dem Diagramm, die
       Legende entfällt (die Werte stehen in den Messwerten), der Lüftungs-Coach unter „Mehr“. */
    const _softK = !!(UI.soft && UI.soft());
    if (_softK) {
      ['head', 'legend'].forEach((k) => {
        delete metricFields[k]; delete metricStyle[k];
        const i = metricAreas.indexOf('"' + k + '"'); if (i > -1) metricAreas.splice(i, 1);
      });
    }
    const metricCard = {
      type: 'custom:button-card',
      tap_action: { action: 'none' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      extra_styles: '@keyframes casora-plate-hold { from, to { opacity: 0; } }'
        + ' @keyframes casora-plate-in {'
        + ' from { opacity: 0; transform: perspective(900px) translateZ(-70px); }'
        + ' to { opacity: 1; transform: perspective(900px) translateZ(0); } }'
        + ' ha-card { animation: var(--casora-popup-plate-enter, none);'
        + ' animation-delay: var(--casora-popup-plate-delay, 0ms); }',
      card_mod: { style: [
        ':host { --ha-card-box-shadow: none !important;'
          + ' --button-card-box-shadow: none !important;'
          + ' --button-card-box-shadow-hover: var(--casora-popup-plate-shadow, none) !important;'
          + ' --casora-card-hover-shadow: var(--casora-popup-plate-shadow, none) !important;'
          + ' --casora-card-hover-filter: none !important;'
          + ' --casora-hover-filter: none !important;'
          + ' --ha-card-backdrop-filter: none !important; }',
        'ha-card { background: var(--casora-popup-chart-fill, rgba(0,0,0,0.26)) !important;'
          + ' border: none !important;'
          + ' border-radius: var(--casora-popup-row-radius, 20px) !important;'
          + ' box-shadow: var(--casora-popup-plate-shadow, none) !important;'
          + ' backdrop-filter: var(--casora-popup-plate-backdrop, none) !important;'
          + ' -webkit-backdrop-filter: var(--casora-popup-plate-backdrop, none) !important;'
          + ' overflow: visible !important;'
          + ' will-change: auto !important; cursor: default !important; }',
        '#container > * { --casora-card-hover-shadow: none !important;'
          + ' --button-card-box-shadow-hover: none !important; }',
        'ha-card::before, ha-card::after { display: none !important; }',
        'ha-card:hover { box-shadow: var(--casora-popup-plate-shadow, none) !important;'
          + ' background: var(--casora-popup-chart-fill, rgba(0,0,0,0.26)) !important;'
          + ' border-color: transparent !important; filter: none !important; }',
        'ha-ripple { display: none !important; }',
      ].join('\n') },
      styles: {
        card: [
          { background: 'var(--casora-popup-chart-fill, rgba(0,0,0,0.26))' },
          { 'border-radius': 'var(--casora-popup-row-radius, 20px)' },
          { 'backdrop-filter': 'var(--casora-popup-plate-backdrop, none)' },
          { '-webkit-backdrop-filter': 'var(--casora-popup-plate-backdrop, none)' },
          { 'box-shadow': 'var(--casora-popup-plate-shadow, none)' },
          { border: 'none' }, { padding: '30px 28px 26px 28px' },
        ],
        grid: [{ 'grid-template-areas': metricAreas.join(' ') },
               { 'grid-template-columns': 'minmax(0, 1fr)' },
               { 'row-gap': '0' }],
        custom_fields: metricStyle,
      },
      custom_fields: metricFields,
    };
    areas.unshift('"metric"');
    fields.metric = { card: metricCard };
    fstyle.metric = [{ 'justify-self': 'stretch' }, { overflow: 'visible' }];
    if (_softK) {
      areas.unshift('"hero"');
      fields.hero = UI.hero(_noAq ? {
        center: true, line: true, read: '*',
        value: temp != null ? temp.toLocaleString(window.casoraLocale ? window.casoraLocale() : 'de-DE', { maximumFractionDigits: 1 }) + ' ' + tempUnit
          : (_hum != null ? Math.round(_hum) + ' %' : '—'),
        sub: temp != null && _hum != null ? Math.round(_hum) + ' % Luftfeuchtigkeit' : null,
      } : { center: true, line: true, read: '*', value: scoreLabel, valueTone: heroTone, sub: bits.join(' · ') || null });
      fstyle.hero = [{ 'justify-self': 'stretch' }];
    }

    areas.forEach((a, i) => {
      const key = a.replace(/"/g, '');
      if (fstyle[key]) {
        fstyle[key].push({ '--casora-popup-plate-delay': (i * 55) + 'ms' });
      }
    });


    /* Casora lokal (24.09.2026): Lüftungs-Coach im Zuhause-Klima-Popup, nicht in Räumen (window._casoraVent.climateSlot). */
    { const _vc = window._casoraVent ? window._casoraVent.climateSlot(roomName, states) : ''; if (_vc) add('vcoach', (_softK && UI.more) ? UI.more('climate-coach', _vc) : _vc); }

    const uiCard = {
      type: 'custom:button-card',
      card_mod: { style: contentCardStyle
        + '\nha-card { will-change: auto !important; }' },
      entity: qualId,
      tap_action: { action: 'none' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      styles: {
        card: [
          { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
          { padding: 'var(--casora-soft-card-top, 6px) 26px 22px 26px' },
        ],
        grid: [
          { 'grid-template-areas': areas.join(' ') },
          { 'grid-template-columns': 'minmax(0, 1fr)' },
          { 'row-gap': '28px' },
        ],
        custom_fields: fstyle,
      },
      custom_fields: fields,
    };

    /* Popup-Standard (24.09.2026): ab 761 px Verlauf oben über volle Breite, darunter links Messwerte, rechts Lüftungs-Coach (Weich: „Mehr“ unter den Messwerten, volle Breite). */
    return { type: 'vertical-stack', cards: [window._casoraStd ? window._casoraStd(uiCard, _softK ? { top: ['hero'], full: ['metric'], left: ['read', 'vcoach'], single: true } : { top: [], full: ['metric'], left: ['read'], right: ['vcoach'] }) : uiCard] };
  }

  const cards = [headerCard, graphCard];
  if (tilesCard) cards.push(tilesCard);
  return { type: 'vertical-stack', cards };
]]]

popup_styles.styles:
--casora-popup-plate-enter:
  casora-plate-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
@media (prefers-reduced-motion: reduce) {
  --casora-popup-plate-enter: none;
}

/* Popup-Standard (24.09.2026): breit wie alle Popups. */
--popup-min-width: 900px;
--popup-max-width: 920px;

/* Eine Popup-Familie (01.10.2026): dieselbe Sheet-Fläche wie die Bedien-Popups –
   Fläche, Blur, Schatten und Abdunklung aus dem Standard, Höhe folgt dem Inhalt,
   Schließen-Kreuz mit demselben Abstand zur Sheet-Kante. */
.header { padding-top: var(--casora-popup-header-gap, 10px); }
--casora-popup-header-gap: 14px;
--casora-popup-gutter-wide: 34px;
--casora-popup-gutter-phone: 22px;

/* Held. A chart has to fetch its history, so revealing the widgets
   first only meant watching the graph arrive late. casora-popup
   stamps data-casora-charts-ready once every chart in the popup has
   drawn, or gives up on one that never will, and the entry below
   swaps the hold for the entrance. Read by each widget for itself,
   never by a wrapper. */
--casora-popup-plate-enter: casora-plate-hold 10s linear both;

/* The chart is the widget here, so it settles in rather than
   snapping on once its history lands. */
--casora-popup-chart-enter: 420ms;
--casora-popup-chart-enter-ease: cubic-bezier(0.22, 0.75, 0.28, 1);

--casora-popup-hero-label-size: 15px;
--casora-popup-row-radius: 26px;
/* Frosted, not opaque. The pane's blur used to sit under these, and
   .content still nulls --ha-card-backdrop-filter for every card in
   the popup, so the frost has to be asked for here. The fills drop
   to let it read. */
/* The theme lifts every ha-card with filter: brightness(1.01) on
   hover. A filter on an ancestor makes every descendant's
   backdrop-filter inert, so hovering the empty space around a
   widget - the wrapper card - knocked the frost out of both of
   them. Killed popup-wide; the plate re-declares its own shadow. */
--casora-card-hover-filter: none;
--casora-hover-filter: none;
--casora-card-hover-shadow: none;

--casora-popup-row-pad-x: 26px;
--casora-popup-row-pad-y: 15px;
--casora-popup-plate-backdrop: blur(24px) saturate(180%);
--casora-popup-chart-fill: var(--casora-sheet-chart-fill, rgba(10, 12, 16, 0.68));
--casora-popup-row-fill: var(--casora-sheet-row-fill, rgba(12, 14, 19, 0.62));
/* Lifted, not slabbed: one wide soft pass carries the height, one
   short contact pass keeps the edge from dissolving into the room. */
--casora-popup-plate-shadow: var(--casora-sheet-plate-shadow,
  0 18px 40px -22px rgba(0, 0, 0, 0.50),
  0 2px 8px -5px rgba(0, 0, 0, 0.28));

/* visionOS puts nothing bare on the room: the only chrome outside a
   window is its close control, and that control is itself a glass
   object. The title was printed twice - here and in the widget
   eight pixels below - so it goes, clipped rather than removed so a
   screen reader still gets it. */

/* The chrome arrives with the first plate instead of being there
   on frame one while everything under it fades in. */
--casora-popup-chrome-enter:
  casora-popup-chrome-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
.content { animation: none; }
/* The title lives in the bar now, centered and level with the
   close control, so it is no longer hidden. */
.header-title { font-size: 20px; font-weight: 600; letter-spacing: -0.01em; }
/* 48px is left alone: the base sizes it so the glyph's ink lands on
   the same left margin as the widgets below. */
.header-close {
  border-radius: 50%;
  background: var(--casora-popup-row-fill, rgba(255, 255, 255, 0.10));
  backdrop-filter: var(--casora-popup-plate-backdrop, none);
  -webkit-backdrop-filter: var(--casora-popup-plate-backdrop, none);
  box-shadow: var(--casora-popup-plate-shadow, none);
}

ha-adaptive-dialog, ha-dialog, wa-drawer {
  --ha-card-backdrop-filter: none;
  --ha-card-background: transparent;
  --card-background-color: transparent;
  --ha-card-box-shadow: none;
  --ha-card-border-width: 0px;
}

/* Popup-Standard (24.09.2026): Info-Popup - Abschnittsüberschriften in der Karte. */
--casora-lbl-in: block;
--casora-lbl-out: none;

casora_cover.entity_picture:
[[[
  const st = (entity?.state || '').toLowerCase();
  const pos = Number(entity?.attributes?.current_position);
  if (st === 'opening') return window.casoraIconUrl('cover_open');
  if (st === 'closing') return window.casoraIconUrl('cover_60');
  if (Number.isFinite(pos)) {
    return pos <= 0
      ? window.casoraIconUrl('cover_closed1')
      : window.casoraIconUrl('cover_open1');
  }
  if (st === 'closed') return window.casoraIconUrl('cover_closed');
  if (st === 'open') return window.casoraIconUrl('cover_open');
  return window.casoraIconUrl('cover_closed');
]]]

card.--casora-icon-svg-url:
[[[
  const st = (entity?.state || '').toLowerCase();
  const pos = Number(entity?.attributes?.current_position);
  if (st === 'opening') return `url('${window.casoraIconUrl('cover_open')}')`;
  if (st === 'closing') return `url('${window.casoraIconUrl('cover_60')}')`;
  if (Number.isFinite(pos)) {
    return pos <= 0
      ? `url('${window.casoraIconUrl('cover_closed1')}')`
