  /* Curtain SVGs */
  const CURTAIN_OPEN_URI = 'data:image/svg+xml;base64,';
  const CURTAIN_CLOSED_URI = 'data:image/svg+xml;base64,';

  /* Palette matches casora_popup_light's makeLightCard, teal instead of yellow. */
  const _cc = {
