state.value:
[[[
  const w = parseFloat(entity?.state);
  if (!Number.isFinite(w)) { this._casoraEnergyActive = false; return false; }
  const on  = Number(variables.high_threshold ?? 500);
  const off = Number(variables.release_threshold ?? on * 0.8);
  const now = this._casoraEnergyActive === true ? (w >= off) : (w >= on);
  this._casoraEnergyActive = now;
  return now;
]]]

casora_energy.state_display:
[[[
  const _c = variables.entity_power || entity?.entity_id;
  const id = ((id) => { const s = id && states[id]; const a = (s && s.attributes) || {}; return !!s && (a.device_class === 'power' || /^[kMG]?W$/.test(String(a.unit_of_measurement || ''))); })(_c) ? _c : null;
  // K4 (Weich-Audit): kurz, die Handy-Kachel kürzte „Kein Sensor ge…“.
  if (!id) return 'Kein Sensor';
  const _u = String(states[id]?.attributes?.unit_of_measurement || 'W');
  const w = parseFloat(states[id]?.state) * (_u === 'kW' ? 1000 : _u === 'MW' ? 1e6 : _u === 'GW' ? 1e9 : 1);
  if (!Number.isFinite(w)) return 'Nicht verfügbar';
  /* Kleine negative Werte sind Messrauschen am Zähler (Popup: „Inaktiv“), echte sind Einspeisung. */
  const _f = (x) => x >= 1000 ? (x / 1000).toLocaleString(window.casoraLocale ? window.casoraLocale() : 'de', { minimumFractionDigits: 1, maximumFractionDigits: 1 }) + ' kW' : Math.round(x) + ' W';
  if (w < 0) return w > -20 ? '0 W' : 'Einspeisung ' + _f(-w);
  return _f(w);
]]]

