custom_fields.svg:
[[[
  const KF_ID = 'casora-toggle-kf-v8';
  if (!document.getElementById(KF_ID)) {
    const s = document.createElement('style');
    s.id = KF_ID;
    s.textContent = [
      '@keyframes casora-thumb-on-d{from{transform:translateX(0)}to{transform:translateX(18px)}}',
      '@keyframes casora-thumb-off-d{from{transform:translateX(18px)}to{transform:translateX(0)}}',
      '@keyframes casora-thumb-on-m{from{transform:translateX(0)}to{transform:translateX(12px)}}',
      '@keyframes casora-thumb-off-m{from{transform:translateX(12px)}to{transform:translateX(0)}}'
    ].join('');
    document.head.appendChild(s);
  }
  const toggleTarget = variables.toggle_entity || entity?.entity_id || '';
  const toggleState = (states[toggleTarget]?.state || entity?.state || "").toLowerCase();
  const activeStates = ["on","open","opening","playing","unlocked","unlocking","cleaning","returning","cool","heat"];
  const extraStates = Array.isArray(variables.active_states) ? variables.active_states.map(v => String(v).toLowerCase()) : [];
  const isOn = [...activeStates, ...extraStates].includes(toggleState);
  const mob = window.matchMedia('(max-width: 767px), (max-height: 600px)').matches;
  const W = mob ? 38 : 44, H = mob ? 26 : 26, r = mob ? 8 : 9, cx0 = mob ? 14 : 14;
  const SW = W + 2;
  const travel = mob ? 12 : 18;
  const stateKey = '_casora_toggle_' + (entity?.entity_id || '');
  const shouldAnimate = window[stateKey] !== undefined && window[stateKey] !== isOn;
  window[stateKey] = isOn;
  const anim = isOn ? (mob ? 'casora-thumb-on-m' : 'casora-thumb-on-d') : (mob ? 'casora-thumb-off-m' : 'casora-thumb-off-d');
  const animStyle = shouldAnimate ? `animation:${anim} 0.2s ease forwards;` : '';
  const circleCx = (!shouldAnimate && isOn) ? cx0 + travel : cx0;
  const mid = 'htm-' + (entity?.entity_id || '').replace(/[^a-z0-9]/gi, '-');
  const trackFillVar = getComputedStyle(document.documentElement).getPropertyValue('--casora-toggle-track-fill').trim();
  const trackFill = trackFillVar || 'rgba(255,255,255,0.85)';
  const offColor = 'var(--casora-toggle-off-color, rgba(255,255,255,0.8))';
  /* Fix-Runde 1 (A-03): Design mit --casora-toggle-style: solid (Weich) zeichnet den Schalter
     wie im Licht-Popup – gefüllte Spur (an: Ton, aus: Taupe), weißer Knopf mit Schatten. */
  if (getComputedStyle(document.documentElement).getPropertyValue('--casora-toggle-style').trim() === 'solid') {
    const kr = 10, k0 = 13, kx = (!shouldAnimate && isOn) ? k0 + travel : k0;
    const track = isOn ? 'var(--casora-toggle-on-fill, var(--casora-lps-switch-on, #B67A50))' : 'var(--casora-toggle-off-fill, var(--casora-lps-switch-off, rgba(58,50,43,0.38)))';
    return `<svg viewBox="0 0 ${SW} ${H}" style="display:block;width:100%;height:100%;overflow:visible;"><rect x="2" y="1" width="${W-2}" height="${H-2}" rx="${(H-2)/2}" style="fill:${track};transition:fill .2s ease;"/><circle cx="${kx}" cy="${H/2}" r="${kr}" style="${animStyle}fill:var(--casora-lps-knob, #fff);filter:drop-shadow(0 1px 1.5px rgba(0,0,0,0.2));"/></svg>`;
  }
  if (isOn) {
    return `<svg viewBox="0 0 ${SW} ${H}" style="display:block;width:100%;height:100%;overflow:visible;"><defs><mask id="${mid}"><rect x="2" y="1" width="${W-2}" height="${H-2}" rx="${(H-2)/2}" fill="white"/><circle cx="${circleCx}" cy="${H/2}" r="${r}" fill="black" style="${animStyle}"/></mask></defs><rect x="2" y="1" width="${W-2}" height="${H-2}" rx="${(H-2)/2}" fill="${trackFill}" mask="url(#${mid})"/></svg>`;
  } else {
    return `<svg viewBox="0 0 ${SW} ${H}" style="display:block;width:100%;height:100%;overflow:visible;"><rect x="2" y="1" width="${W-2}" height="${H-2}" rx="${(H-2)/2}" fill="none" stroke-width="2" style="stroke:${offColor};"/><circle cx="${circleCx}" cy="${H/2}" r="${r}" style="${animStyle}fill:${offColor};"/></svg>`;
  }
]]]

