tap_action.service:
[[[
  if (variables.toggle_service) return variables.toggle_service;

  const target = variables.toggle_entity || entity?.entity_id || '';
  const state = (states[target]?.state || entity?.state || '').toLowerCase();
  if (state === 'unavailable' || state === 'unknown') return 'none';

  if (target.startsWith('lock.')) {
    if (state === 'locked') return 'lock.unlock';
    if (state === 'unlocked') return 'lock.lock';
    return 'none';
  }

  if (target.startsWith('media_player.')) {
    const feats = Number(states[target]?.attributes?.supported_features || 0);
    if (state === 'off') return (feats & 128) ? 'media_player.turn_on' : 'none';
    return (feats & 256) ? 'media_player.turn_off' : 'none';
  }

  return 'homeassistant.toggle';
]]]

tap_action.service_data:
[[[
  if (variables.toggle_service_data) return variables.toggle_service_data;

  return {
    entity_id: variables.toggle_entity || entity?.entity_id
  };
]]]

custom_fields.battery:
[[[
  const batt = variables.battery_entity;
  if (!batt) return "";
  const st = states[batt];
  if (!st) return "";
  // Akku-Stufen (05.10.2026, window.casoraBattery): nur Schwach/Fast leer zeigen ein Symbol,
  // in der Farbe der Stufe (orange/rot). battery_low_threshold der Karte gilt weiter.
  const B = window.casoraBattery;
  const raw = (st.state ?? "").toString().toLowerCase();
  const lv = B ? B.level(st, { low: variables.battery_low_threshold ?? undefined })
    : (["low", "critical"].includes(raw) || parseFloat(raw) <= Number(variables.battery_low_threshold ?? 20)) ? 'low' : 'ok';
  if (lv !== 'low' && lv !== 'crit') return "";
  const size = (window.innerWidth < 768) ? 20 : 24;
  return `
    <ha-icon
      icon="${B ? B.icon(lv) : 'mdi:battery-alert'}"
      style="
        --mdc-icon-size:${size}px;
        color: ${B ? B.color(lv) : 'var(--casora-entity-state, var(--secondary-text-color))'};
      "
    ></ha-icon>
  `;
]]]

custom_fields.progress:
[[[
  const PROP_ID = 'casora-progress-property-v2';
  if (!document.getElementById(PROP_ID)) {
    const s = document.createElement('style');
    s.id = PROP_ID;
    s.textContent = '@property --casora-progress-pct { syntax: "<number>"; inherits: true; initial-value: 0; }';
    document.head.appendChild(s);
  }

  const dom = (entity?.entity_id || '').split('.')[0];
  const st = (entity?.state || '').toLowerCase();
  const feats = Number(entity?.attributes?.supported_features || 0);

  let glyph = '', svc = '';
  if (variables.progress_transport) {
    if (dom === 'media_player' && (feats & 16385)) {
      glyph = st === 'paused' ? 'play' : 'pause';
      svc = 'media_player.media_play_pause';
    } else if (dom === 'vacuum' && (feats & 4)) {
      glyph = st === 'paused' ? 'play' : 'pause';
      svc = st === 'paused' ? 'vacuum.start' : 'vacuum.pause';
    }
  }

  const GLYPHS = {
    pause: '<rect class="casora-progress-glyph" x="14" y="13" width="2.6" height="10" rx="1.3"/>'
         + '<rect class="casora-progress-glyph" x="19.4" y="13" width="2.6" height="10" rx="1.3"/>',
    play:  '<path class="casora-progress-glyph" d="M15.4 12.9 L23.8 18 L15.4 23.1 Z"'
         + ' stroke-width="1.6" stroke-linejoin="round" stroke-linecap="round"/>',
  };

  let inner = '';
  if (glyph && svc) {
    const [d, sv] = svc.split('.');
    const stop = 'event.stopPropagation();event.stopImmediatePropagation();';
    const act = stop + "document.querySelector('home-assistant').hass.callService('"
              + d + "','" + sv + "',{entity_id:'" + entity?.entity_id + "'});";
    inner = `<g style="cursor:pointer;pointer-events:auto;" onpointerdown="${stop}" ontouchstart="${stop}" onclick="${act}">`
          + `<circle cx="18" cy="18" r="12" fill="transparent"/>${GLYPHS[glyph]}</g>`;
  }

  return `<svg viewBox="0 0 36 36" xmlns="http://www.w3.org/2000/svg" style="display:block;width:100%;height:100%;overflow:visible;">
    <g transform="rotate(-90 18 18)">
      <circle class="casora-progress-track" cx="18" cy="18" r="14" fill="none" stroke="rgba(255,255,255,0.2)" stroke-width="4" stroke-linecap="round"/>
      <circle class="casora-progress-arc" cx="18" cy="18" r="14" fill="none" stroke="var(--casora-color-teal, #00c3d0)" stroke-width="4" stroke-linecap="round" stroke-dasharray="87.965"/>
    </g>
    ${inner}
  </svg>`;
]]]

casora_entity.extra_styles:
/* Diagonal specular hairline */
ha-card::before{
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  padding: 1px;
  box-sizing: border-box;
  opacity: var(--casora-active-overlay-opacity, 0);
  background: linear-gradient(
    to bottom right,
    var(--casora-card-specular-start, transparent) 0%,
    var(--casora-card-specular-mid, transparent) 45%,
    var(--casora-card-specular-mid, transparent) 55%,
    var(--casora-card-specular-end, transparent) 100%
  );
  -webkit-mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  mask-composite: exclude;
}

#battery{
  opacity: 0;
  transform: scale(.92);
  transition: opacity .8s ease, transform .3s ease;
  will-change: opacity, transform;
}

@media (hover: hover) and (pointer: fine){
  :host(:hover) #battery,
  :host(:focus-within) #battery{
    opacity: .6;
    transform: scale(1);
  }
}

@media (hover: none) and (pointer: coarse){
  #battery{ opacity: 0; }
}

/* ── Page load animation ── */
/* No filter here on purpose: one non-compositable property forces the whole
   animation onto the main thread, where the cold-load template compile
   stalls it. transform+opacity only keeps it on the compositor. */
@keyframes casoraFadeIn {
  from { opacity: 0; transform: translateY(100px) scale(0.95); }
  to   { opacity: 1; transform: translateY(0)     scale(1);    }
}

@keyframes casoraFadeInRight {
  from { opacity: 0; transform: translateX(80px); }
  to   { opacity: 1; transform: translateX(0);    }
}

/* Desktop + tablet: slide in from right */
ha-card {
  animation: var(--casora-anim-name, casoraFadeInRight) var(--casora-anim-duration, 0.4s) cubic-bezier(0.16, 1, 0.3, 1) both;
  animation-delay: var(--casora-anim-delay, var(--delay-d, 0s));
  animation-play-state: var(--casora-init-play, running);
  will-change: opacity, transform;
}

/* Mobile portrait: slide up from bottom */
@media (max-width: 767px) and (orientation: portrait) {
  ha-card {
    animation: var(--casora-anim-name, casoraFadeIn) var(--casora-anim-duration, 0.45s) cubic-bezier(0.16, 1, 0.3, 1) both;
    animation-delay: var(--casora-anim-delay, var(--delay, 0s));
    animation-play-state: var(--casora-init-play, running);
  }
}

/* Progress */
#progress {
  background: none !important;
  mask: none !important;
  -webkit-mask: none !important;
  overflow: visible;
}

#progress svg {
  position: relative;
  z-index: 1;
}

#progress svg .casora-progress-glyph {
  fill: var(--casora-progress-arc-color, var(--casora-color-teal, #00c3d0));
  stroke: var(--casora-progress-arc-color, var(--casora-color-teal, #00c3d0));
}

#progress svg .casora-progress-track {
  stroke: var(--casora-progress-track-color, rgba(0,0,0,0.12));
}

#progress svg .casora-progress-arc {
  stroke: var(--casora-progress-arc-color, rgba(255,255,255,0.5));
  stroke-opacity: var(--casora-progress-arc-opacity, 1);
  stroke-dashoffset: calc(87.965px - var(--casora-progress-pct, 0) * 0.87965px);
  transition: stroke-dashoffset 0.8s linear;
}

/* Toggle tracks the tile unit, like the icon circle, so it stays proportional to the
   card. A fraction of the height, never height/200px: dividing a length by a length
   is CSS Values 4 and Firefox drops the whole declaration. On :host so it also
   reaches cards whose root element the ha-card selector does not match. */
:host {
  --casora-toggle-width: calc(var(--casora-entity-height-current, 200px) * 0.23);
  --casora-toggle-height: calc(var(--casora-entity-height-current, 200px) * 0.13);
}

ha-card {
  --casora-height-mq: var(--casora-entity-height-current, var(--casora-entity-height-desktop, 200px));
  --casora-box-shadow-mq: var(--casora-tile-rest-shadow-desktop, var(--casora-tile-glass-rim-desktop, var(--casora-tile-glass-rim, inset 0 1px 0 -0.5px rgba(255,255,255,0.10), 0 2px 8px rgba(0,0,0,0.10))));
  /* Sized off the icon circle: two balanced circles in opposite corners. Ratio, not a
     literal, so it tracks the card automatically. Visible ring is 32/36 of this (r14 +
     stroke 4 in a 36 viewBox), i.e. ~0.8x the icon circle. */
  --casora-progress-size-mq: calc(var(--casora-icon-circle-size, 44px) * var(--casora-progress-icon-ratio, 0.9));
  --casora-icon-circle-size: calc(var(--casora-entity-height-current, 200px) * var(--casora-icon-circle-ratio, 0.22));  /* casora_thermostat's temp puck reads this too */
  /* Every top-corner extra centers on this, so the toggle, the progress ring and
     the thermostat's rail stay in line with the icon circle at every tile size. */
  --casora-icon-center-y: calc(
    var(--casora-entity-inner-pad-current, var(--casora-entity-inner-pad-desktop, 20px))
    + var(--casora-tile-icon-mt, -2px)
    + var(--casora-icon-circle-size, 44px) / 2);
  --casora-entity-active-tint-current: var(--casora-entity-active-tint, rgba(255,255,255,0.94));
  --casora-icon-fallback-color: rgba(50,50,50,0.85);
  --casora-toggle-off-color-active: var(--casora-toggle-off-fill-active, rgba(0,0,0,0.55));
  --casora-progress-arc-color: var(--casora-progress-color, var(--casora-color-teal, #00c3d0));
  --casora-progress-arc-opacity: 1;

  /* Tile geometry. Only -mq is rewritten by the breakpoint; -lg never is.
     styles.card picks between them off variables.size. */
  --casora-tile-areas-mq: "i" "n" "s";
  --casora-tile-cols-mq: 1fr;
  --casora-tile-rows-mq: 1fr min-content min-content;
  --casora-tile-gap-mq: 4px 0;
  --casora-tile-name-mb-mq: -2px;
  --casora-tile-align-content-mq: start;
  --casora-tile-icon-align-mq: start;
  --casora-tile-icon-mt-mq: -2px;
  --casora-tile-extras-mq: block;
  --casora-tile-radius-mq: var(--ha-card-border-radius, 28px);
  --casora-tile-state-inset-mq: 0px;

  --casora-tile-areas-lg: "i" "n" "s";
  --casora-tile-cols-lg: 1fr;
  --casora-tile-rows-lg: 1fr min-content min-content;
  --casora-tile-gap-lg: 4px 0;
  --casora-tile-name-mb-lg: -2px;
  --casora-tile-align-content-lg: start;
  --casora-tile-icon-align-lg: start;
  --casora-tile-icon-mt-lg: -2px;
  --casora-tile-extras-lg: block;
  --casora-tile-radius-lg: var(--ha-card-border-radius, 28px);
  --casora-tile-state-inset-lg: 0px;

  /* Defaults, so first paint is correct before styles.card stamps these
     inline a frame later. */
  --casora-tile-areas: var(--casora-tile-areas-mq);
  --casora-tile-cols: var(--casora-tile-cols-mq);
  --casora-tile-rows: var(--casora-tile-rows-mq);
  --casora-tile-gap: var(--casora-tile-gap-mq);
  --casora-tile-name-mb: var(--casora-tile-name-mb-mq);
  --casora-tile-align-content: var(--casora-tile-align-content-mq);
  --casora-tile-icon-align: var(--casora-tile-icon-align-mq);
  --casora-tile-icon-mt: var(--casora-tile-icon-mt-mq);
  --casora-tile-extras: var(--casora-tile-extras-mq);
  --casora-tile-radius: var(--casora-tile-radius-mq);
  --casora-tile-state-inset: var(--casora-tile-state-inset-mq);
}

/* 100cqi for the auto-fitting state text = the card's content box. */
ha-card { container-type: inline-size; }

/* Media list must match the one casora-smart-row switches its grid on. */
@media (max-width: 767px) and (orientation: portrait),
       (max-height: 500px) and (orientation: portrait),
       (max-height: 600px) and (orientation: landscape) {
  ha-card {
    --casora-height-mq: 100%;  /* the grid track owns the height */
    --casora-icon-circle-size: 42px;
    --casora-toggle-width: 46px;   /* height-current is not this tier's tile height */
    --casora-toggle-height: 26px;
    --casora-tile-areas-mq: "i n" "i s";
    --casora-tile-cols-mq: auto minmax(0, 1fr);
    --casora-tile-rows-mq: auto auto;
    --casora-tile-gap-mq: 1px 10px;
    --casora-tile-name-mb-mq: 0px;  /* -2px is tuned for the 4px stacked gap */
    --casora-tile-align-content-mq: center;
    --casora-tile-icon-align-mq: center;
    --casora-tile-icon-mt-mq: 0px;
    --casora-tile-icon-mt-lg: 0px;  /* or a large tile's icon sits 2px above its small neighbor */
    --casora-tile-extras-mq: none;  /* no corners; icon_tap_action toggles instead */
    --casora-tile-radius-mq: var(--casora-tile-radius-phone, 26px);
    --casora-tile-radius-lg: var(--casora-tile-radius-phone, 26px);
    --casora-tile-state-inset-mq: calc(42px + 10px);
  }

  /* Keeps nested custom-field cards on the tile radius too. */
  :host {
    --ha-card-border-radius: var(--casora-tile-radius-phone, 26px);
  }
}

@media (max-width: 767px), (max-height: 600px) {
  ha-card {
    /* Phone tiles stay flat: drop the desktop rim, not just dim it. */
    --casora-box-shadow-mq: var(--casora-tile-rest-shadow, var(--casora-tile-glass-rim, inset 0 1px 0 -0.5px rgba(255,255,255,0.10), 0 2px 8px rgba(0,0,0,0.10)));
    --casora-toggle-width: 40px;
    /* Schalter oben am Kachelrand statt auf die Symbolmitte zentriert (27.09.2026). */
    --casora-toggle-top: calc(var(--casora-entity-inner-pad-current, var(--casora-entity-inner-pad-desktop, 20px)) + (var(--casora-entity-icon-size-current, var(--casora-entity-icon-size-desktop, 34px)) - 20px) / 2);
    --casora-progress-icon-ratio: 0.8;
    --casora-entity-active-tint-current: var(--casora-entity-active-tint-mobile, var(--casora-entity-active-tint, rgba(255,255,255,1)));
  }
}

#toggle {
  opacity: var(--casora-toggle-opacity, 0.65);
  transition: opacity 0.18s ease;
  /* Default until the JS-templated inline display lands, or it flashes in. */
  display: var(--casora-tile-extras, block);
  /* button-card gives every custom field class="ellipsis" (overflow:hidden) on the
     same div it stamps the inline style onto; !important here beats both. */
  overflow: visible !important;
}

#progress {
  display: var(--casora-progress-display, none);
}

#state {
  opacity: var(--casora-state-opacity, 0.75);
}

/* button-card's .no-icon rules set end/start here, which closes the gap on
   casora_thermostat only. */
#name, #state {
  align-self: center !important;
  /* .ellipsis clips at the padding box, so 1.15 line-height cuts descenders
     off; the negative margin keeps the layout where it was. */
  padding-block: 0.16em;
  margin-block: -0.16em;
}

@keyframes casoraEntityFanSpin {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}

/* Icon circles */
#img-cell, .casora-icon-circle {
  position: relative;
  border-radius: 50% !important;
  background: var(--casora-icon-circle-bg, rgba(0,0,0,0.20)) !important;
  width: var(--casora-icon-circle-size, 44px) !important;
  height: var(--casora-icon-circle-size, 44px) !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  overflow: hidden !important;
  box-shadow: var(--casora-icon-circle-shadow, 0 2px 6px rgba(0,0,0,0.04)) !important;
  transition: background-color 0.3s ease;
}
/* Inactive-icon tint */
#img-cell::before {
  content: "";
  position: absolute;
  inset: 0;
  margin: auto;
  width: var(--casora-icon-mask-scale, 60%);
  height: var(--casora-icon-mask-scale, 60%);
  /* Weich (A-12): Aus-Zustand in Aus-Grau statt Gerätefarbe – nur mit --casora-icon-off-mix. */
  background-color: color-mix(in srgb, var(--casora-icon-off-ink, transparent) var(--casora-icon-off-mix, 0%), var(--casora-icon-inactive-color, rgba(255,255,255,0.95)));
  -webkit-mask-image: var(--casora-icon-mask-image, none);
  mask-image: var(--casora-icon-mask-image, none);
  -webkit-mask-size: contain;
  mask-size: contain;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-position: center;
  mask-position: center;
  opacity: var(--casora-icon-mask-active, 0);
  pointer-events: none;
  transition: background-color 0.3s ease, opacity 0.3s ease;
}
#img-cell img {
  width: var(--casora-icon-mask-scale, 60%) !important;
  height: var(--casora-icon-mask-scale, 60%) !important;
  max-width: var(--casora-icon-mask-scale, 60%) !important;
  max-height: var(--casora-icon-mask-scale, 60%) !important;
  object-fit: contain !important;
  flex: none !important;
  opacity: calc(1 - var(--casora-icon-mask-active, 1)) !important;
  transition: opacity 0.3s ease !important;
}
#img-cell ha-icon {
  --mdc-icon-size: 25px !important;
  flex: none !important;
  color: rgba(255,255,255,1.0) !important;
}
#icon { color: rgba(255,255,255,1.0) !important; }

@media (max-width: 767px) and (orientation: portrait),
       (max-height: 500px) and (orientation: portrait),
       (max-height: 600px) and (orientation: landscape) {
  #img-cell ha-icon { --mdc-icon-size: 24px !important; }
}
@media (hover: hover) {
  #img-cell:hover, .casora-icon-circle:hover { transform: scale(1.03); transition: transform 0.15s ease; }
}
@media (hover: none) {
  #img-cell:active, .casora-icon-circle:active { filter: brightness(1.15); transform: scale(1.03); }
}

ha-card { isolation: isolate; }

ha-card::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  z-index: -1;
  background: var(--casora-entity-overlay-tint, var(--casora-entity-active-tint-current, rgba(255,255,255,0.94)));
  opacity: var(--casora-active-overlay-opacity, 0);
  transition: opacity var(--casora-active-overlay-dur, .5s) ease, background-color .35s ease;
}

/* Steady top/bottom glow (active state) */
#container::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: var(--casora-tile-radius, var(--ha-card-border-radius, 28px));
  pointer-events: none;
  z-index: -1;
  opacity: var(--casora-entity-glow-opacity, 0);
  transition: opacity var(--casora-active-overlay-dur, .5s) ease;
  background:
    radial-gradient(60% 24px at 50% 0%,   rgba(255,255,255,0.20) 0%, transparent 100%),
    radial-gradient(60% 24px at 50% 100%, rgba(255,255,255,0.15) 0%, transparent 100%);
}

:host { scroll-snap-align: start; }

casora_entity.hidden:
[[[
  const off = (v) => v === false || v === 'false' || v === 0 || v === '0';
  if (off(variables?.enabled)) return true;
  if (String(variables?.show_when ?? 'always') !== 'active') return false;
  const idle = variables?.idle;
  return idle === true || idle === 'true' || idle === 1 || idle === '1';
]]]

icon_tap_action.service:
[[[
  if (variables.toggle_service) return variables.toggle_service;

  const target = variables.toggle_entity || entity?.entity_id || '';
  const state = (states[target]?.state || entity?.state || '').toLowerCase();
  if (state === 'unavailable' || state === 'unknown') return 'none';

  if (target.startsWith('lock.')) {
    if (state === 'locked') return 'lock.unlock';
    if (state === 'unlocked') return 'lock.lock';
    return 'none';
  }

  if (target.startsWith('media_player.')) {
    const feats = Number(states[target]?.attributes?.supported_features || 0);
    if (state === 'off') return (feats & 128) ? 'media_player.turn_on' : 'none';
    return (feats & 256) ? 'media_player.turn_off' : 'none';
  }

  if (target.startsWith('vacuum.')) {
    return (state === 'cleaning' || state === 'returning' || state === 'paused') ? 'vacuum.return_to_base' : 'vacuum.start';
  }

  return 'homeassistant.toggle';
]]]

icon_tap_action.service_data:
[[[
  if (variables.toggle_service_data) return variables.toggle_service_data;

  return {
    entity_id: variables.toggle_entity || entity?.entity_id
  };
]]]

state.value:
[[[
  /* Gerät fehlt (03.10.2026): Die Kachel nennt eine feste Entität, die es in HA nicht (mehr) gibt –
     z. B. nach einem Umzug mit umbenannten Geräten. Steht als erster Zustand vor allen anderen
     (auch denen der Kachelvorlagen): Zustandstext „Gerät fehlt“, ruhig wie „Aus“, kein Schalter.
     Ohne geladene Zustände nichts melden; Kacheln ohne Entität bleiben Platzhalter. */
  const id = this._config && this._config.entity;
  if (typeof id !== 'string' || !/^[a-z_]+\.[a-z0-9_]+$/.test(id) || !states || states[id]) return false;
  for (const k in states) return true;
  return false;
]]]

state.state_display:
[[[
  const t = window.casoraTr ? window.casoraTr('Gerät fehlt') : 'Gerät fehlt';
  return window.casoraStateFit ? window.casoraStateFit(t) : t;
]]]

card.--casora-icon-color-current:
[[[
  const icon   = variables.icon || '';
  const domain = (entity?.entity_id || '').split('.')[0];
  if (icon === 'energy' || icon === 'power') {
    const pid = variables.entity_power || entity?.entity_id;
    const w = parseFloat(states[pid]?.state);
    if (!Number.isFinite(w)) return 'var(--casora-badge-energy-color, #30D158)';
    if (w >= Number(variables.extreme_threshold ?? 3000)) return 'var(--casora-badge-energy-very-high-color, #FF4245)';
    if (w >= Number(variables.heavy_threshold   ?? 1000)) return 'var(--casora-badge-energy-high-color, #FF9230)';
    if (w >= Number(variables.normal_threshold  ?? 200))  return 'var(--casora-badge-energy-medium-color, #FFD600)';
    return 'var(--casora-badge-energy-low-color, #30D158)';
  }
  const byIcon = {
    plant:    'var(--casora-tile-plant-color, var(--casora-color-yellow, #FFCC00))',
    updates:  'var(--casora-tile-media-color, var(--casora-color-teal, #00c3d0))',
    'updates-restart': 'var(--casora-tile-media-color, var(--casora-color-teal, #00c3d0))',
    wifi:     'var(--casora-tile-media-color, var(--casora-popup-primary-color, #00c3d0))',
    doorbell: 'var(--casora-color-teal, #00c3d0)',
  };
  const byDomain = {
    light:        'var(--casora-color-yellow, #FFCC00)',
    fan:          'var(--casora-color-teal, #00C3D0)',
    humidifier:   'var(--casora-color-teal, #00C3D0)',
    climate:      'var(--casora-color-teal, #00C3D0)',
    vacuum:       'var(--casora-color-teal, #00C3D0)',
    cover:        'var(--casora-color-teal, #00c3d0)',
    media_player: 'var(--casora-tile-media-color, var(--casora-color-teal, #00c3d0))',
    lock:         entity?.state === 'unlocking' ? 'var(--casora-color-yellow, #FFCC00)' : 'var(--casora-lock-unlocked-color, var(--casora-color-teal, #00c3d0))',
    plant:        'var(--casora-tile-plant-color, var(--casora-color-yellow, #FFCC00))',
  };
  return byIcon[icon] || byDomain[domain] || 'var(--casora-icon-fallback-color, rgba(255,255,255,0.95))';
]]]

card.--casora-icon-svg-url:
[[[
  const pic = entity?.attributes?.entity_picture || '';
  if (pic && pic.startsWith('/local/')) return `url('${pic}')`;
  const icon = variables.icon || 'default';
  return `url('${window.casoraIconUrl(icon)}')`;
]]]

card.--casora-icon-use-mask:
[[[
  const pic = entity?.attributes?.entity_picture || '';
  if (pic && (pic.startsWith('/api/') || pic.startsWith('http'))) return '0';
  return '1';
]]]

state.value:
[[[
  if (variables.active_override !== null && variables.active_override !== undefined) {
    return !!variables.active_override;
  }

  const defaults = ["on","open","opening","unlocked","unlocking","playing","cleaning","returning","cool","heat","washing","rinsing","spinning","drying","running","active","problem"];
  const extra = Array.isArray(variables.active_states) ? variables.active_states.map(v => String(v).toLowerCase()) : [];
  const activeStates = [...defaults, ...extra];

  if (activeStates.includes((entity?.state || "").toLowerCase())) return true;

  const list = Array.isArray(variables.active_entities)
    ? variables.active_entities.filter(Boolean)
    : (variables.active_entities ? [variables.active_entities] : []);
  if (!list.length) return false;

  const isOn = (eid) => activeStates.includes(String(states[eid]?.state || "").toLowerCase());

  return String(variables.active_entities_mode || "any").toLowerCase() === "all"
    ? list.every(isOn)
    : list.some(isOn);
]]]

casora_entity.state_display:
[[[
  if (!entity?.state) return "";
  if (entity?.state === "ok") return "Gesund";
  return (() => { try { return hass.formatEntityState(entity); } catch (e) { return ''; } })() || entity?.state;
]]]

card.--casora-entity-anim-name:
[[[
  if (!window._casoraAnimSetup) {
    window._casoraAnimSetup = true;
    window._casoraFromBg = false;
    window._casoraLastPath = window.location.pathname;
    document.addEventListener('visibilitychange', () => {
      if (document.hidden) window._casoraFromBg = true;
    });
    window.addEventListener('location-changed', () => {
      const newPath = window.location.pathname;
      if (newPath !== window._casoraLastPath) {
        window._casoraFromBg = false;
      }
      window._casoraLastPath = newPath;
    });
  }
  return window._casoraFromBg ? 'none' : 'casoraFadeIn';
]]]

card.--casora-icon-inactive-color:
[[[
  const icon   = variables.icon || '';
  const domain = (entity?.entity_id || '').split('.')[0];
  if (domain === 'media_player') return 'var(--casora-icon-inactive-fallback-color, rgba(255,255,255,0.95))';
  if (icon === 'energy' || icon === 'power') {
    const pid = variables.entity_power || entity?.entity_id;
    const w = parseFloat(states[pid]?.state);
    if (!Number.isFinite(w)) return 'var(--casora-badge-energy-color, #30D158)';
    if (w >= Number(variables.extreme_threshold ?? 3000)) return 'var(--casora-badge-energy-very-high-color, #FF4245)';
    if (w >= Number(variables.heavy_threshold   ?? 1000)) return 'var(--casora-badge-energy-high-color, #FF9230)';
    if (w >= Number(variables.normal_threshold  ?? 200))  return 'var(--casora-badge-energy-medium-color, #FFD600)';
    return 'var(--casora-badge-energy-low-color, #30D158)';
  }
  const byIcon = {
    plant:    'var(--casora-color-green, #30D158)',
    wifi:     'var(--casora-popup-primary-color, #00c3d0)',
    doorbell: 'var(--casora-color-teal, #00c3d0)',
  };
  const byDomain = {
    light:        'var(--casora-color-yellow, #FFCC00)',
    fan:          'var(--casora-color-teal, #00C3D0)',
    humidifier:   'var(--casora-color-teal, #00C3D0)',
    climate:      'var(--casora-color-teal, #00C3D0)',
    vacuum:       'var(--casora-color-teal, #00C3D0)',
    cover:        'var(--casora-color-teal, #00c3d0)',
    lock:         'var(--casora-color-teal, #00c3d0)',
    plant:        'var(--casora-color-green, #30D158)',
  };
  return byIcon[icon] || byDomain[domain] || 'var(--casora-icon-inactive-fallback-color, rgba(255,255,255,0.95))';
]]]

card.display:
[[[
  return (states['input_boolean.casora_mobile_navigation']?.state === 'on') ? 'none' : 'block';
]]]

card.--casora-progress-pct:
[[[
  if (!variables.show_progress) return 0;

  let v = variables.progress_value;

  if (v === null || v === undefined) {
    const target = variables.progress_entity || entity?.entity_id;
    const st = states[target];

    if (!st) return 0;

    const rawState = st.state;
    const attrs = st.attributes || {};

    const stateNum = parseFloat(rawState);
    if (Number.isFinite(stateNum)) {
      v = stateNum;
    }

    else if (Number.isFinite(Number(attrs.percentage))) {
      v = Number(attrs.percentage);
    } else if (Number.isFinite(Number(attrs.progress))) {
      v = Number(attrs.progress);
    }

    else if (
      Number.isFinite(Number(attrs.media_position)) &&
      Number.isFinite(Number(attrs.media_duration)) &&
      Number(attrs.media_duration) > 0
    ) {
      const position = Number(attrs.media_position);
      const duration = Number(attrs.media_duration);
      const stateNow = (st.state || '').toLowerCase();

      let effectivePosition = position;

      if (
        stateNow === 'playing' &&
        attrs.media_position_updated_at
      ) {
        const updatedAt = new Date(attrs.media_position_updated_at).getTime();
        if (Number.isFinite(updatedAt)) {
          const elapsed = Math.max(0, (Date.now() - updatedAt) / 1000);
          effectivePosition += elapsed;
        }
      }

      effectivePosition = Math.max(0, Math.min(duration, effectivePosition));
      v = (effectivePosition / duration) * 100;
    }

    else {
      v = 0;
    }
  }

  const n = Number(v);
  return Number.isFinite(n) ? Math.max(0, Math.min(100, n)) : 0;
]]]

card.--casora-progress-display:
[[[
  if (!variables.show_progress) return 'none';
  const activeStates = variables.progress_active_states || [];
  const s = (entity?.state || '').toLowerCase();
  return activeStates.includes(s) ? 'var(--casora-tile-extras, block)' : 'none';
]]]

card.--casora-name-fit:
[[[
  /* Einheitliche Schriftgröße (01.10.2026): Namen schrumpfen auf dem Handy nicht mehr je
     Kachel; passt ein Name nicht, kürzt #name ihn mit „…“ (styles.name: nowrap/ellipsis).
     Vorher (27.09.) wurde hier ein Fit-Span mit verkleinerter Schrift eingesetzt. */
  return 0;
]]]

toggle.display:
[[[
  if (!variables.show_toggle) return 'none';
  const target = variables.toggle_entity || entity?.entity_id || '';
  const tState = (states[target]?.state || entity?.state || '').toLowerCase();
  if (tState === 'unavailable' || tState === 'unknown') return 'none';
  if (target.startsWith('media_player.')) {
    const feats = states[target]?.attributes?.supported_features;
    if (typeof feats === 'number' && !(feats & 384)) return 'none';
  }
  if (variables.show_progress) {
    const activeStates = variables.progress_active_states || [];
    const s = (entity?.state || '').toLowerCase();
    if (activeStates.includes(s)) return 'none';
  }
  return 'var(--casora-tile-extras, block)';
]]]

casora_entity.name:
[[[
  /* Wie button-cards eigener Standard (Anzeigename, sonst Objekt-ID). Ohne Entität: Ersatzname der
     Vorlage (variables.casora_default_name), nur wenn das Design --casora-tile-fallback-name: 1 setzt
     (Weich, Fix-Runde 1 A-15) – sonst wie bisher ohne Namen. */
  if (entity) {
    const a = entity.attributes || {};
    return a.friendly_name ? a.friendly_name : entity.entity_id.substr(entity.entity_id.indexOf('.') + 1);
  }
  let on = false;
  try { on = getComputedStyle(document.documentElement).getPropertyValue('--casora-tile-fallback-name').trim() === '1'; } catch (e) {}
  return on ? (variables.casora_default_name || '') : '';
]]]

custom_fields.more:
[[[
  void states[variables.actions_toggle_helper];
  void states[variables.actions_active_helper];
  const A = window._casoraActions;
  if (!A) {
    if (window._casoraCoreWaiters !== null) {
      (window._casoraCoreWaiters = window._casoraCoreWaiters || new Set()).add(this);
    }
    return '';
  }
  A.bind(this, variables, hass);
  return A.moreMarkup(variables, entity?.entity_id);
]]]

custom_fields.pill_1:
[[[
