casora_entity_actions.extra_styles:
:host {
  --casora-actions-pad: var(--casora-entity-inner-pad-current, var(--casora-entity-inner-pad-desktop, 20px));
  --casora-actions-btn-radius: 13px;
  --casora-actions-icon-size: 23px;
  --casora-actions-svg-size: 20px;
  --casora-actions-corner-gap: 4px;
  --casora-actions-more-size: 21px;
  --casora-actions-more-offset: 16px;
  --casora-actions-more-fill-r: 18px;
  --casora-actions-corner-shift: 0.26s;
  --casora-actions-pill-h: 40px;
  --casora-actions-pill-gap: 8px;
  --casora-actions-pill-bottom: var(--casora-actions-pad);
  --casora-actions-label-size: 15px;
  /* FIT_REF_PX in casora-core must equal this floor. */
  --casora-actions-label-min: 12px;
  --casora-actions-glyph-gap: 10px;
  --casora-actions-label-gap: 12px;

  --casora-actions-dur-in: 0.30s;
  --casora-actions-dur-out: 0.14s;
  --casora-actions-ease-in: cubic-bezier(0.32, 0.72, 0, 1);
  --casora-actions-ease-out: cubic-bezier(0.4, 0, 0.7, 1);
  --casora-actions-pill-scale: 0.94;
  --casora-actions-pill-rise: 6px;

  --casora-actions-press-more: 0.86;
  --casora-actions-press-pill: 0.97;
  --casora-actions-press-down: 0.12s;
  --casora-actions-press-up: 0.28s;
  --casora-actions-ease-press-down: cubic-bezier(0.2, 0, 0.4, 1);
  --casora-actions-ease-press-up: cubic-bezier(0.32, 0.72, 0, 1);
}

/* On ha-card, not :host: --casora-icon-circle-size lives here and a :host
   var cannot read one from a descendant. */
ha-card {
  --casora-actions-hit: var(--casora-icon-circle-size, 40px);
  /* The button is one fixed size everywhere; only its distance from the
     corner follows the tile's own padding. --more-offset is half the dots
     plus the gap that keeps the fill off the edge. */
  --casora-actions-more-inset: calc(
    var(--casora-actions-hit) / 2 - var(--casora-actions-more-offset));
  --casora-actions-more-fill: radial-gradient(circle closest-side,
    var(--casora-actions-pill-bg) var(--casora-actions-more-fill-r),
    transparent calc(var(--casora-actions-more-fill-r) + 0.5px));
  --casora-actions-pill-pad-start: calc(
    (var(--casora-actions-hit) - var(--casora-actions-icon-size)) / 2);
  --casora-side-lit: var(--casora-active-overlay-opacity, 0);
  --casora-actions-ink: color-mix(in srgb, #000 calc(var(--casora-side-lit) * 100%), #fff);
  /* Matches the tile toggle, whose track is rgba(0,0,0,0.75) under
     --casora-toggle-opacity. That 0.75 is the theme's track-fill alpha. */
  --casora-actions-dots-opacity: calc(0.75 * var(--casora-toggle-opacity, 0.8));
  --casora-actions-pill-bg-on: color-mix(in srgb,
    rgba(0, 0, 0, 0.20) calc(var(--casora-side-lit) * 100%),
    rgba(255, 255, 255, 0.26));
  --casora-actions-pill-bg: color-mix(in srgb,
    rgba(0, 0, 0, 0.10) calc(var(--casora-side-lit) * 100%),
    rgba(255, 255, 255, 0.13));
  --casora-actions-pill-bg-hover: color-mix(in srgb,
    rgba(0, 0, 0, 0.16) calc(var(--casora-side-lit) * 100%),
    rgba(255, 255, 255, 0.19));
}

@media (max-width: 767px), (max-height: 600px) {
  .casora-act-pill .casora-act-glyphbox { display: none; }
  .casora-act-pill {
    gap: 0;
    --casora-actions-label-inset: 0px;
    --casora-actions-pill-pad-start: 14px;
  }

  :host {
    --casora-actions-btn-radius: 12px;
    --casora-actions-icon-size: 22px;
    --casora-actions-svg-size: 19px;
    --casora-actions-corner-gap: 2px;
    --casora-actions-pill-h: 30px;
    --casora-actions-pill-gap: 6px;
    --casora-actions-pill-bottom: 10px;
    --casora-actions-label-size: 14px;
  }
}

/* The press lives one level in: the pill wrapper's transform belongs to
   the cross-fade. */
.casora-act-hit {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  gap: var(--casora-actions-glyph-gap, 10px);
  box-sizing: border-box;
  border-radius: inherit;
  overflow: hidden;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;

  transform: scale(1);
  transition:
    transform var(--casora-actions-press-up, 0.28s)
      var(--casora-actions-ease-press-up, cubic-bezier(0.32, 0.72, 0, 1)),
    background-color 0.18s ease;
}

.casora-act-hit.pressed {
  transform: scale(var(--casora-act-press, 0.96));
  background: var(--casora-actions-pill-bg-hover);
  transition:
    transform var(--casora-actions-press-down, 0.12s)
      var(--casora-actions-ease-press-down, cubic-bezier(0.2, 0, 0.4, 1)),
    background-color var(--casora-actions-press-down, 0.12s) ease;
}

@media (prefers-reduced-motion: reduce) {
  .casora-act-hit, .casora-act-hit.pressed { transform: none; }
}

.casora-act-more {
  justify-content: center;
  background: transparent;
  --casora-act-press: var(--casora-actions-press-more, 0.86);
}

.casora-act-more.pressed {
  background: radial-gradient(circle closest-side,
    var(--casora-actions-pill-bg-hover) var(--casora-actions-more-fill-r),
    transparent calc(var(--casora-actions-more-fill-r) + 0.5px));
}

.casora-act-dots {
  display: block;
  flex: none;
  width: var(--casora-actions-more-size);
  height: var(--casora-actions-more-size);
  fill: var(--casora-actions-ink);
  opacity: var(--casora-actions-dots-opacity);
  pointer-events: none;
}

.casora-act-pill {
  background: var(--casora-actions-pill-bg);
  --casora-act-press: var(--casora-actions-press-pill, 0.97);
  padding-inline-start: var(--casora-actions-pill-pad-start);
  padding-inline-end: var(--casora-actions-label-gap, 12px);
  /* The label sizes off 100cqi, which is the CONTENT box. */
  container-type: inline-size;
  --casora-actions-label-inset: calc(
    var(--casora-actions-icon-size)
    + var(--casora-actions-glyph-gap, 10px));
}

.casora-act-glyphbox {
  flex: none;
  display: grid;
  place-items: center;
  width: var(--casora-actions-icon-size);
  height: var(--casora-actions-icon-size);
}

.casora-act-label {
  flex: 0 1 auto;
  /* Without it the label refuses to shrink and clips mid-word. */
  min-width: 0;
  display: block;
  line-height: 1.25;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: var(--casora-actions-label-size);
  font-weight: 500;
  letter-spacing: -0.01em;
  color: var(--casora-actions-ink);
  opacity: 0.9;
}

.casora-act-icon {
  display: block;
  object-fit: contain;

  background: transparent !important;
  background-color: transparent !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  filter: none;

  color: var(--casora-actions-ink);
  opacity: 0.52;

  transition: color 0.18s ease, opacity 0.18s ease;
}

/* HA's own hook; without it mdi glyphs ride a text baseline and sit low. */
.casora-act-ha-icon {
  --mdc-icon-size: var(--casora-actions-icon-size);
  --ha-icon-display: block;
  width: var(--casora-actions-icon-size);
  height: var(--casora-actions-icon-size);
  line-height: 0;
}

.casora-act-svg {
  filter: brightness(0) invert(calc(1 - var(--casora-side-lit)));
  width: var(--casora-actions-svg-size);
  height: var(--casora-actions-svg-size);
  object-fit: contain;
}

.casora-act-hit.active .casora-act-icon {
  opacity: 1;
}

.casora-act-pill.active {
  background: var(--casora-actions-pill-bg-on);
}

.casora-act-hit.unavailable .casora-act-icon {
  opacity: 0.35;
  color: var(--disabled-text-color);
}

.casora-act-hit.unavailable .casora-act-label {
  opacity: 0.5;
}

#glyph_1, #glyph_2, #pill_1, #pill_2 {
  overflow: hidden !important;
}

/* Hover only. Press is a pointerdown class: :active on touch lands late
   and can stick. */
@media (hover: hover) and (pointer: fine) {
  .casora-act-more:hover { background: var(--casora-actions-more-fill); }
  .casora-act-pill:hover { background: var(--casora-actions-pill-bg-hover); }
}

