[[[
  const dom = String(entity?.entity_id || '').split('.')[0];
  return ({
    light: 'light', switch: 'plug', input_boolean: 'plug',
    fan: 'fan', climate: 'thermostat', humidifier: 'humidifier',
    media_player: 'speaker', lock: 'lock-fill', cover: 'curtain-open',
    vacuum: 'vacuum', script: 'scenes', scene: 'scenes',
    automation: 'scenes', button: 'power_on', input_button: 'power_on',
    binary_sensor: 'motion', remote: 'tv', water_heater: 'hot_water',
    valve: 'curtain-open', siren: 'motion',
  })[dom] || 'default';
]]]

casora_fan.extra_styles:
#img-cell img {
  transform-origin: 50% 50% !important;
  animation: var(--casora-fan-animation, none) !important;
  animation-play-state: var(--hsr-anim-paused, running) !important;
}

@keyframes casora-fan-spin {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}
@keyframes casora-fan-coast {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}

card.--casora-fan-animation:
[[[
  const s = String(entity?.state || '').toLowerCase();
  const isOn = s === 'on';
  const prev = this._casoraPrevFan;
  this._casoraPrevFan = isOn;
  const justOn  = isOn  && prev === false;
  const justOff = !isOn && prev === true;
  if (isOn) {
    return justOn
      ? 'casora-fan-spin 1.5s ease-in 1, casora-fan-spin 0.9s linear 1.5s infinite'
      : 'casora-fan-spin 0.9s linear infinite';
  }
  if (justOff) return 'casora-fan-coast 1.5s ease-out 1 forwards';
  return 'none';
]]]

casora_popup.content:
[[[
  const UI = window._casoraUI;
  if (!UI || !entity) return { type: 'vertical-stack', cards: [] };
  const id = entity?.entity_id;

  /* Geschwister-Entitäten desselben Geräts (Filter, PM2,5, Display, ...) */
  const reg = hass.entities || {};
  const devId = reg[id]?.device_id;
  const sib = {};
  if (devId) {
    Object.values(reg).forEach((e) => {
      if (e.device_id !== devId || e.entity_id === id) return;
      const eid = e.entity_id;
      const dom = eid.split('.')[0];
      const unit = states[eid]?.attributes?.unit_of_measurement;
      const dc = states[eid]?.attributes?.device_class;
      if (dom === 'sensor') {
        if (/filter/.test(eid)) sib.filter = sib.filter || eid;
        else if (dc === 'pm25' || /pm25|pm2_5/.test(eid)) sib.pm25 = sib.pm25 || eid;
        else if (/luftqualitat|air_quality/.test(eid)) sib.aq = sib.aq || eid;
        else if (unit === 'W') sib.power = sib.power || eid;
      } else if (dom === 'switch') {
        if (/display/.test(eid)) sib.display = sib.display || eid;
        else if (/kindersicherung|child_lock/.test(eid)) sib.child_lock = sib.child_lock || eid;
      } else if (dom === 'select' && /nachtlicht|night_light/.test(eid)) {
        sib.night_light = sib.night_light || eid;
      }
    });
  }
  const areaId = reg[id]?.area_id || (devId ? hass.devices?.[devId]?.area_id : null);
  const roomName = variables.room_name || (areaId ? hass.areas?.[areaId]?.name : null) || 'Luftreiniger';

  const uiCard = {
    type: 'custom:button-card',
    entity: id,
    triggers_update: [id].concat(Object.values(sib)),
    variables: { sib: sib, room_name: roomName },
    card_mod: { style:
      '\n:host { --ha-card-backdrop-filter: none !important; --ha-card-background: transparent !important; --card-background-color: transparent !important; --ha-card-box-shadow: none !important; --ha-card-border-width: 0px !important; }'
      + '\nha-card::before, ha-card::after, #card::before, #card::after, #container::before, #container::after { display: none !important; }'
      + '\nha-card { will-change: auto !important; }'
      + '\n@media (max-width: 600px) { ha-card { padding-left: 14px !important; padding-right: 14px !important; } }'
    },
    tap_action: { action: 'none' },
    hold_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    styles: {
      card: [
        { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
        { padding: 'var(--casora-soft-card-top, 6px) 26px 22px 26px' },
      ],
      grid: [
        { 'grid-template-areas': '"body"' },
        { 'grid-template-columns': '1fr' },
      ],
      custom_fields: { body: [{ 'justify-self': 'stretch' }] },
    },
