casora_football.extra_styles:
/* Wappen in Farbe auf weißem Kreis; der Gegner sitzt klein unten rechts am Kreis. */
#img-cell {
  position: relative !important;
  overflow: visible !important;
  background: var(--casora-football-crest-bg, #fff) !important;
  width: var(--casora-icon-circle-size, 44px) !important;
  height: var(--casora-icon-circle-size, 44px) !important;
  aspect-ratio: 1 / 1 !important;
  box-shadow: 0 0 0 1px var(--casora-football-crest-ring, rgba(58,50,43,0.06)) !important;
}
:host #img-cell img {
  /* Wappen 64 %, runde Flagge 73 % mit Haarlinie (Variablen aus styles.card). */
  width: var(--casora-football-img, 64%) !important;
  height: var(--casora-football-img, 64%) !important;
  max-width: var(--casora-football-img, 64%) !important;
  max-height: var(--casora-football-img, 64%) !important;
  border-radius: var(--casora-football-img-radius, 0) !important;
  object-fit: contain !important;
  -webkit-mask: none !important;
  mask: none !important;
}
#img-cell::after {
  content: '';
  display: var(--casora-football-opp-show, none);
  position: absolute;
  right: -10px;
  bottom: -6px;
  width: 54%;
  height: 54%;
  border-radius: 50%;
  background: var(--casora-football-crest-bg, #fff) var(--casora-football-opp) center / var(--casora-football-opp-size, 74%) no-repeat;
  box-shadow: 0 0 0 2.5px var(--casora-football-ring, var(--ha-card-background, var(--card-background-color, #fff)));
}
.cfb-pill {
  /* Ecke als reiner Statustext (Variante F, 07.10.2026): keine Fläche – eine Kapsel rechts oben
     hieße „antippen/schalten“ wie der Schalter der Nachbarkacheln. Höhe = Schalter-Linie. */
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 26px;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: -0.1px;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  white-space: nowrap;
  color: var(--casora-football-ink, var(--casora-entity-state, var(--secondary-text-color)));
}
.cfb-pill.live { color: var(--casora-football-live, var(--casora-color-red, #D35A4E)); }
.cfb-pill.live i { width: 7px; height: 7px; border-radius: 50%; background: currentColor; animation: cfb-blink 2s ease-in-out infinite; }
.cfb-pill.on {
  /* Aktiv (Spieltag, Wahl 08.10.2026): der weiße Wappenkreis verschwindet auf der hellen Fläche – die
     Ecke wird eine gefüllte Pille, live rot, sonst Akzent. Farbe 22 % dunkler: weiße Schrift ≥ 4,5:1. */
  padding: 0 10px;
  border-radius: 13px;
  color: #fff;
  background: color-mix(in srgb, var(--casora-color-teal, #4E9E95) 78%, #000);
}
.cfb-pill.on.live { color: #fff; background: color-mix(in srgb, var(--casora-color-red, #D35A4E) 78%, #000); }
@keyframes cfb-blink { 50% { opacity: 0.35; } }
@media (prefers-reduced-motion: reduce) { .cfb-pill.live i { animation: none; } }
/* Handy groß: gleich breit wie klein – Pille kompakter, damit sie neben Wappen und Gegner passt. */
@media (max-width: 767px), (max-height: 600px) {
  .cfb-pill { font-size: 12px; gap: 5px; }
  .cfb-pill.on { padding: 0 9px; }
  .cfb-pill.live i { width: 6px; height: 6px; }
  /* Kleine Kachel (Zeile): der Text beginnt 10 px neben dem Kreis – Gegnerwappen enger anlegen. */
  #img-cell::after { right: -5px; bottom: -4px; width: 48%; height: 48%; }
}

casora_football.hidden:
[[[
  const off = (v) => v === false || v === 'false' || v === 0 || v === '0';
  if (off(variables?.enabled)) return true;
  return !!window._casoraFootball?.hidden(entity, variables);
]]]

casora_football.state_display:
[[[
  /* Handy: Gegner als Kürzel (auch „groß“ ist nicht breiter, nur doppelt so hoch);
     klein ohne Ecke – dort stehen Spielminute bzw. Endstand im Text. */
  const phone = !!window.matchMedia?.('(max-width: 767px), (max-height: 600px)').matches;
  const small = phone && !variables.size_large;
  return window._casoraFootball ? window._casoraFootball.state(entity, small, phone) : '';
]]]

card.--casora-football-ink:
