      .replaceAll("&","&amp;")
      .replaceAll("<","&lt;")
      .replaceAll(">","&gt;")
      .replaceAll('"',"&quot;")
      .trim();
    return `<span class="casora-media-state">${esc(variables.game)}</span>`;
  }
  if (!entity?.state) return "";
  return (() => { try { return hass.formatEntityState(entity); } catch (e) { return ''; } })() || entity?.state;
]]]

variables.art_url:
[[[
  const a = entity?.attributes || {};
  const pick = [a.game_image_main, a.game_image_header, a.game_icon]
    .find(x => x && String(x).trim());
  if (!pick) return '';
  const u = String(pick).trim();
  return u.startsWith('/') ? window.location.origin + u : u;
]]]

variables.game:
[[[
  const a = entity?.attributes || {};
  const dead = ['none','unknown','unavailable',''];
  const named = String(a.game ?? '').trim();
  if (named && !dead.includes(named.toLowerCase())) return named;
  const st = String(entity?.state ?? '').trim();
  const isTitle = typeof window.casoraPsnStateTitle === 'function'
    ? window.casoraPsnStateTitle(st)
    : !['playing','paused','idle','on','off','home','away','online','offline',
        'standby','unavailable','unknown','none','null',''].includes(st.toLowerCase());
  return isTitle ? st : '';
]]]

variables.is_active:
[[[
  if (!variables.game) return false;
  const st = String(entity?.state ?? '').toLowerCase();
  return !['offline','off','none','unavailable','unknown',''].includes(st);
]]]

tap_action.action:
[[[
  /* Ohne zugeordnetes Gerät nichts; fehlt das Gerät in HA: Popup mit „Gerät fehlt“ (03.10.2026). */
  if (!entity && !this._config?.entity) return 'none';
  return window.casoraPopupAction ? window.casoraPopupAction() : 'more-info';
]]]

casora_geschirrspueler.state_display:
[[[
  const fit = (t) => window.casoraStateFit?.(t) ?? t;
  return fit(window._casoraDish ? window._casoraDish.tile(entity, variables, states, hass) : (entity?.state || ''));
]]]

variables.progress_entity:
[[[
  /* Fortschritt über den Geräte-Finder (Casora) – feste Variable hat Vorrang. */
  if (variables.appliance_progress) return variables.appliance_progress;
  const M = window._casoraDish;
  try { return (M && M.resolve && entity) ? M.resolve(entity, {}, states, hass).progress : null; }
  catch (e) { return null; }
]]]

casora_humidifier.state_display:
[[[
  /* Ohne Gerät nicht leer bleiben (30.09.2026). */
  if (!entity) return 'Gerät fehlt';
  if (!entity.state) return '';
  return (() => { try { return hass.formatEntityState(entity); } catch (e) { return ''; } })() || entity.state;
]]]

tap_action.action:
[[[
  /* Ohne Gerät: Casora-Popup mit dem Hinweis „Gerät fehlt“ statt gar nichts (03.10.2026). */
  if (entity) return 'more-info';
  return window.casoraPopupAction ? window.casoraPopupAction() : 'none';
]]]

casora_popup.title:
[[[
  const n = String(this._config?.name || '').trim();
  return (n.startsWith('[[[') ? '' : n) || 'Luftbefeuchter';
]]]

casora_light.state_display:
[[[
  const memsOf = (eid) => {
    const m = states[eid]?.attributes?.entity_id;
    return Array.isArray(m) ? m.filter(x => typeof x === "string" && x.startsWith("light.")) : [];
  };
  const units = (eid, seen) => {
    if (!eid || seen.has(eid)) return [];
    const mems = memsOf(eid);
    if (!mems.length || !mems.some(m => memsOf(m).length)) return [eid];
    seen.add(eid);
    return mems.flatMap(m => units(m, seen));
  };

  const seen = new Set();
  // Gruppe ohne HA-Gruppe: variables.lights zählt mit (z. B. vom Standardraum).
  const base = Array.isArray(variables?.lights) && variables.lights.length ? variables.lights : [entity?.entity_id];
  let all = [...new Set(base.flatMap((id) => units(id, seen)))];
  /* Eine flache HA-Gruppe ist trotzdem eine Gruppe: ihre Lampen zählen, damit es
     überall gleich heißt – einzelne Lampe „Aus“, Gruppe „Alle aus“. */
  if (all.length === 1 && memsOf(all[0]).length > 1) {
    const ex = memsOf(all[0]).filter((m) => states[m]);
    // Gibt es die Mitglieder nicht, zählt die Gruppe selbst (sonst „Alle aus“ trotz An).
    if (ex.length) all = ex;
  }
  all = all.filter((id) => states[id]);
  const onCount = all.filter(eid => states[eid]?.state === "on").length;

  return onCount === 0 ? (all.length === 1 ? "Aus" : "Alle aus")
       : onCount === all.length ? (all.length === 1 ? "An" : "Alle An")
       : `${onCount} An`;
]]]

casora_popup.content:
[[[
  const _st1 = states[entity?.entity_id];
  const _single = !!_st1 && !Array.isArray(_st1.attributes?.entity_id) && !(Array.isArray(variables.lights) && variables.lights.length) && !variables.popup_group && !variables.group_entity;
  if (_single) {
  const UI = window._casoraUI;
  if (!UI) return { type: 'vertical-stack', cards: [] };
  const id = entity?.entity_id, a = entity?.attributes || {};
  const reg = hass.entities || {};
  const devId = reg[id]?.device_id;
  const areaId = reg[id]?.area_id || (devId ? hass.devices?.[devId]?.area_id : null);
  const roomName = areaId ? hass.areas?.[areaId]?.name : null;
  const esc = UI.esc, T = UI.tokens;
  const modes = a.supported_color_modes || [];
  const base = {
    type: 'custom:button-card', entity: id, triggers_update: [id], variables: { room_name: roomName },
    card_mod: { style:
      '\n:host { --ha-card-backdrop-filter: none !important; --ha-card-background: transparent !important; --card-background-color: transparent !important; --ha-card-box-shadow: none !important; --ha-card-border-width: 0px !important; }'
      + '\nha-card::before, ha-card::after, #card::before, #card::after, #container::before, #container::after { display: none !important; }'
      + '\nha-card { will-change: auto !important; }'
      + '\n@media (max-width: 600px) { ha-card { padding-left: 14px !important; padding-right: 14px !important; } }' },
    tap_action: { action: 'none' }, hold_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    styles: {
      card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: 'var(--casora-soft-card-top, 6px) 26px 0 26px' }],
      grid: [{ 'grid-template-areas': '"body"' }, { 'grid-template-columns': '1fr' }],
      custom_fields: { body: [{ 'justify-self': 'stretch' }, { 'min-width': '0' }] },
    },
    custom_fields: { body: "[[[\n  const UI = window._casoraUI;\n  if (!UI || !entity) return '';\n  const T = UI.tokens, esc = UI.esc;\n  const id = entity?.entity_id, a = entity?.attributes || {};\n  const on = entity?.state === 'on';\n  const pct = on && a.brightness != null ? Math.max(1, Math.round(a.brightness / 2.55)) : 0;\n  const dimmable = (a.supported_color_modes || []).some((m) => m !== 'onoff');\n  const ago = (iso) => {\n    if (!iso) return null;\n    const m = (Date.now() - new Date(iso).getTime()) / 60000;\n    if (isNaN(m) || m < 0) return null;\n    if (m < 1) return 'gerade eben';\n    if (m < 60) return 'vor ' + Math.floor(m) + (Math.floor(m) === 1 ? ' Minute' : ' Minuten');\n    const h = m / 60; if (h < 24) return 'vor ' + Math.floor(h) + (Math.floor(h) === 1 ? ' Stunde' : ' Stunden');\n    const d = h / 24; return 'vor ' + Math.floor(d) + (Math.floor(d) === 1 ? ' Tag' : ' Tagen');\n  };\n  const value = entity?.state === 'unavailable' ? 'Nicht verf\u00fcgbar' : on ? (dimmable ? pct + ' %' : 'An') : 'Aus';\n  let out = '<style>ha-card.disabled{pointer-events:auto!important;}'\n    + '.hl-pw{display:flex;justify-content:center;margin-top:16px;}'\n    + '.hl-b{width:56px;height:56px;border-radius:999px;display:grid;place-items:center;cursor:pointer;line-height:0;'\n    +   'background:' + (on ? T.ink : 'var(--casora-popup-seg-fill, rgba(255,255,255,0.16))') + ';color:' + (on ? '#000' : T.ink) + ';'\n    +   'transition:transform .12s ease;user-select:none;-webkit-user-select:none;}'\n    + '.hl-b > *{pointer-events:none;}.hl-b:active{transform:scale(.92);}'\n    + '</style>';\n  out += UI.hero({ label: variables.room_name || null, value: value, sub: on && a.effect && a.effect !== 'None' && a.effect !== 'off' ? ((() => { try { return (hass && hass.formatEntityAttributeValue && hass.formatEntityAttributeValue(entity, 'effect', a.effect)) || a.effect; } catch (x) { return a.effect; } })()) : ago(entity.last_changed), center: true });\n  /* Reglerfarbe = aktuelle Lampenfarbe (RGB, sonst Wei\u00dftemperatur, sonst Lichtgelb) */\n  const k2rgb = (k) => {\n    const t = Math.max(1000, Math.min(40000, k)) / 100;\n    let r, g, b;\n    if (t <= 66) { r = 255; g = 99.4708025861 * Math.log(t) - 161.1195681661; b = t <= 19 ? 0 : 138.5177312231 * Math.log(t - 10) - 305.0447927307; }\n    else { r = 329.698727446 * Math.pow(t - 60, -0.1332047592); g = 288.1221695283 * Math.pow(t - 60, -0.0755148492); b = 255; }\n    const c = (v) => Math.round(Math.max(0, Math.min(255, v)));\n    return [c(r), c(g), c(b)];\n  };\n  let rgb = null;\n  if (Array.isArray(a.rgb_color) && a.color_mode !== 'color_temp') rgb = a.rgb_color;\n  else if (a.color_temp_kelvin) rgb = k2rgb(a.color_temp_kelvin);\n  else if (Array.isArray(a.rgb_color)) rgb = a.rgb_color;\n  const fill = rgb ? 'rgb(' + rgb.join(',') + ')' : 'var(--casora-color-yellow, #FFCC00)';\n  if (dimmable) {\n    out += '<div style=\"height:10px\"></div><div style=\"--casora-popup-slider-fill:' + fill + ';--casora-popup-slider-icon:' + (on ? 'rgba(0,0,0,0.55)' : '#ffffff') + ';\">'\n      + UI.slider({ value: pct, icon: 'light',\n      svc: { domain: 'light', service: 'turn_on', field: 'brightness_pct', target: { entity_id: id } } }) + '</div>';\n  }\n  out += '<div class=\"hl-pw\"><div class=\"hl-b\" data-casora-svc=\"' + esc(JSON.stringify({ domain: 'light', service: 'toggle', target: { entity_id: id } })) + '\">'\n    + '<ha-icon icon=\"mdi:power\" style=\"--mdc-icon-size:26px;width:26px;height:26px;display:block;\"></ha-icon></div></div>';\n  return out;\n]]]" },
  };
  const svc = (data) => esc(JSON.stringify({ domain: 'light', service: 'turn_on', data: data, target: { entity_id: id } }));
  const staticCard = (html) => Object.assign({}, base, {
    entity: undefined, triggers_update: [], variables: {},
    styles: Object.assign({}, base.styles, { card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '0 26px' }] }),
    custom_fields: { body: html },
  });
  const CSS = '<style>ha-card.disabled{pointer-events:auto!important;}'
    + '.hl-l{font-family:' + T.font + ';font-size:var(--casora-h15-fs,15px);font-weight:var(--casora-h15-fw,600);letter-spacing:var(--casora-h15-ls,-0.01em);text-transform:var(--casora-h15-tt,none);color:var(--casora-h15-c, ' + T.ink + ');margin:22px 4px 8px;text-align:left;}'
    + '.hl-sw{display:flex;flex-wrap:nowrap;gap:8px;justify-content:space-between;}'
    + '.hl-c{position:relative;flex:1 1 0;max-width:40px;aspect-ratio:1/1;border-radius:999px;cursor:pointer;box-shadow:inset 0 0 0 1px rgba(255,255,255,.18);transition:transform .12s ease;}'
    + '.hl-c:active{transform:scale(.9);}'
    /* Trefferfläche 44 px (sichtbar 38–40 px), Abstand 8 px bleibt frei. */
    + '.hl-c::before{content:"";position:absolute;inset:-4px;border-radius:999px;}'
    + '.hl-src{display:flex;gap:7px;overflow-x:auto;overflow-y:hidden;-webkit-overflow-scrolling:touch;overscroll-behavior-x:contain;width:100%;scrollbar-width:none;padding-bottom:2px;}'
    + '.hl-src::-webkit-scrollbar{display:none;}'
    + '.hl-src .hui-sg,.hl-seg .hui-sg{flex:none;font-family:' + T.font + ';font-size:14px;font-weight:500;padding:10px 14px;border-radius:999px;white-space:nowrap;cursor:pointer;'
    +   'background:var(--casora-popup-seg-fill, rgba(255,255,255,0.16));color:' + T.ink + ';}'
    + '.hl-src .hui-sg.on,.hl-seg .hui-sg.on{background:' + T.ink + ';color:var(--casora-popup-ui-on-ink, #000);}'
    + '.hl-seg{display:flex;gap:7px;}.hl-seg .hui-sg{flex:1 1 0;text-align:center;}'
    /* Handy: Trefferfläche 44 px (sichtbar 37 px): unsichtbarer Rand oben/unten, Fläche nur im Innern; die
       Quellen-Leiste bekommt dafür Innenabstand (sie schneidet senkrecht ab), Lage unverändert. Nur am
       Handy – am Desktop schnitt der Kartenrand den unsichtbaren Rand unter der letzten Reihe ab. */
    + '@media (max-width: 600px){.hl-src .hui-sg,.hl-seg .hui-sg{border-block:3.5px solid transparent;background-clip:padding-box;margin-block:-3.5px;}'
    +   '.hl-src{padding-top:3.5px;padding-bottom:5.5px;margin-block:-3.5px;}}'
    + '</style>';
  const cards = [base];
  if (modes.includes('color_temp')) {
    const lo = a.min_color_temp_kelvin || 2700, hi = a.max_color_temp_kelvin || 6500;
    const k = (v) => Math.max(lo, Math.min(hi, v));
    const temps = [['Warm', k(2700)], ['Neutral', k(4000)], ['Kalt', k(6000)]];
    /* Gewählter Weißton hinterlegt (wie bei den Effekten): eigene Karte mit der Entität, damit sie
       nach dem Tippen neu zeichnet – vorher statisch, „Warm“ blieb ohne Markierung. */
    const _tw = temps.map((x) => [x[0], x[1], svc({ color_temp_kelvin: x[1] })]);
    cards.push(Object.assign(staticCard(''), { entity: id, triggers_update: [id], custom_fields: { body:
      '[[[\n  const a = entity?.attributes || {};\n'
      + '  const k = entity?.state === \'on\' && (!a.color_mode || a.color_mode === \'color_temp\') ? Number(a.color_temp_kelvin) || null : null;\n'
      + '  const T = ' + JSON.stringify(_tw) + ';\n'
      + '  let best = -1;\n'
      + '  if (k) T.forEach((x, i) => { if (best < 0 || Math.abs(x[1] - k) < Math.abs(T[best][1] - k)) best = i; });\n'
      + '  return ' + JSON.stringify(CSS + '<div class="hl-l">Weißton</div><div class="hl-seg">')
      + ' + T.map((x, i) => \'<div class="hui-sg\' + (i === best ? \' on\' : \'\') + \'" data-casora-svc="\' + x[2] + \'">\' + x[0] + \'</div>\').join(\'\') + \'</div>\';\n]]]' } }));
  }
  if (modes.some((m) => ['hs', 'rgb', 'rgbw', 'rgbww', 'xy'].includes(m))) {
    const cols = [['#FF3B30', 0], ['#FF9500', 30], ['#FFCC00', 50], ['#34C759', 120], ['#00C7BE', 175], ['#007AFF', 215], ['#AF52DE', 280], ['#FF2D55', 340]];
    cards.push(staticCard(CSS + '<div class="hl-l">Farbe</div><div class="hl-sw">'
      + cols.map((c) => '<div class="hl-c" style="background:' + c[0] + '" data-casora-svc="' + svc({ hs_color: [c[1], 100] }) + '"></div>').join('') + '</div>'));
  }
  const fx = (Array.isArray(a.effect_list) ? a.effect_list : []).filter((e) => e && !/^(none|off)$/i.test(e));
  /* Effektnamen übersetzt, wie HA sie anzeigt (Rainbow -> Regenbogen …) */
  const fxName = (e) => { try { if (hass && hass.formatEntityAttributeValue) return hass.formatEntityAttributeValue(entity, 'effect', e) || e; } catch (x) {} return e; };
  if (fx.length) {
    const cur = a.effect;
    const list = cur && fx.includes(cur) ? [cur].concat(fx.filter((x) => x !== cur)) : fx;
    cards.push(staticCard(CSS + '<div class="hl-l">Effekte</div><div class="hl-src" ontouchstart="event.stopPropagation();var w=this;cancelAnimationFrame(w._raf);var t=event.touches[0];w._sx=t.clientX;w._sy=t.clientY;w._sl=w.scrollLeft;w._h=null;w._js=false;w._lx=t.clientX;w._lt=event.timeStamp;w._v=0;w._m=w.scrollWidth-w.clientWidth;" ontouchmove="event.stopPropagation();var w=this,t=event.touches[0];var dx=t.clientX-w._sx,dy=t.clientY-w._sy;if(w._h===null&&(Math.abs(dx)>6||Math.abs(dy)>6))w._h=Math.abs(dx)>Math.abs(dy);if(!w._h)return;if(!w._js&&Math.abs(dx)>40&&w.scrollLeft===w._sl&&w._m>0&&!((dx>0&&w._sl<=0)||(dx<0&&w._sl>=w._m))){w._js=true;w._sx=t.clientX;w._sl=w.scrollLeft;dx=0;}if(!w._js)return;if(event.cancelable)event.preventDefault();w.scrollLeft=w._sl-dx;var dt=Math.max(1,event.timeStamp-w._lt);w._v=0.8*((w._lx-t.clientX)/dt)+0.2*w._v;w._lx=t.clientX;w._lt=event.timeStamp;" ontouchend="event.stopPropagation();var w=this;if(!w._js)return;var v=w._v*16,last=performance.now();var step=function(now){var f=Math.min(3,(now-last)/16);last=now;w.scrollLeft+=v*f;v*=Math.pow(0.95,f);if(Math.abs(v)>0.2)w._raf=requestAnimationFrame(step);};w._raf=requestAnimationFrame(step);" ontouchcancel="event.stopPropagation()">'
      + list.map((e) => '<div class="hui-sg' + (e === cur ? ' on' : '') + '" data-casora-svc="' + svc({ effect: e }) + '">' + esc(fxName(e)) + '</div>').join('') + '</div>'));
  }
  cards.push(Object.assign({}, base, {
    styles: Object.assign({}, base.styles, { card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '0 26px 22px 26px' }] }),
    custom_fields: { body: "[[[\n  const UI = window._casoraUI;\n  if (!UI || !entity) return '';\n  return '<div style=\"margin-top:22px\">' + UI.group([{ icon: 'mdi:tune-variant', label: 'Weitere Einstellungen', entity: entity?.entity_id }]) + '</div>';\n]]]" },
  }));
  return { type: 'vertical-stack', cards: cards };
  }

  return typeof window._casoraLPC === 'function'
    ? window._casoraLPC(entity, states, typeof hass !== 'undefined' ? hass : null, variables)
    : null;

]]]

casora_popup.header_actions:
[[[
  const _st1 = states[entity?.entity_id];
  const _single = !!_st1 && !Array.isArray(_st1.attributes?.entity_id) && !(Array.isArray(variables.lights) && variables.lights.length) && !variables.popup_group && !variables.group_entity;
  if (_single) return null;

  const _hdr = typeof window._casoraLPC === 'function' ? window._casoraLPC(entity, states, typeof hass !== 'undefined' ? hass : null, variables, 'header') : null;
  return (_hdr && _hdr.actions) || null;

]]]

popup_styles.styles:
/* Eine Popup-Familie (01.10.2026): dieselbe Sheet-Fläche wie die Bedien-Popups –
   Fläche, Blur, Schatten und Abdunklung aus dem Standard, Höhe folgt dem Inhalt,
   Schließen-Kreuz mit demselben Abstand zur Sheet-Kante. */
.header { padding-top: var(--casora-popup-header-gap, 10px); }
--casora-popup-header-gap: 14px;
--casora-popup-gutter-wide: 22px;

/* No chart to wait for, so the plates arrive as soon as they build. */
--casora-popup-plate-enter:
  casora-plate-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
@media (prefers-reduced-motion: reduce) {
  --casora-popup-plate-enter: none;
}

--casora-popup-hero-label-size: 15px;
--casora-popup-row-radius: 26px;
--casora-popup-plate-backdrop: blur(24px) saturate(180%);
/* The tiles and the room pills do blur - they are small, and an
   inactive tile with no blur reads as a hole rather than a control.
   Separate from the plate knob so this can go on its own. */
--casora-popup-tile-backdrop: blur(24px) saturate(180%);
--casora-popup-row-fill: var(--casora-sheet-row-fill, rgba(12, 14, 19, 0.62));
--casora-popup-chart-fill: var(--casora-sheet-chart-fill, rgba(10, 12, 16, 0.68));
/* The theme lifts every ha-card with filter: brightness(1.01) on
   hover, and a filter on an ancestor makes every backdrop-filter
   inside it inert - hovering the space around a plate knocked the
   frost out of it. Killed popup-wide; each plate re-declares its
   own shadow. */
--casora-card-hover-filter: none;
--casora-hover-filter: none;
--casora-card-hover-shadow: none;
/* Lifted, not slabbed: one wide soft pass carries the height, one
   short contact pass keeps the edge off the room. */
--casora-popup-plate-shadow: var(--casora-sheet-plate-shadow,
  0 18px 40px -22px rgba(0, 0, 0, 0.50),
  0 2px 8px -5px rgba(0, 0, 0, 0.28));

/* Nothing bare on the room but the close control, and that control
   is itself a glass object. The title is clipped rather than
   removed so a screen reader still gets it - the header widget
   below carries it on screen. */

/* The chrome arrives with the first plate instead of being there
   on frame one while everything under it fades in. */
--casora-popup-chrome-enter:
  casora-popup-chrome-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
.content { animation: none; }
/* The title lives in the bar now, centered and level with the
   close control, so it is no longer hidden. */
.header-title { font-size: 20px; font-weight: 600; letter-spacing: -0.01em; }
/* The toggle sits with the close rather than opposite it: two
   controls that belong to the same popup read as a pair, and the
   state reads left-to-right off the button it describes. The title
   is absolutely centered on the bar either way. */
.header-actions {
  order: 0;
  margin-left: 10px;
  margin-right: auto;
  padding-right: 0;
}
.header-close {
  border-radius: 50%;
  background: var(--casora-lp-close-bg, var(--casora-popup-row-fill, rgba(255, 255, 255, 0.10)));
  backdrop-filter: var(--casora-lp-close-backdrop, var(--casora-popup-plate-backdrop, none));
  -webkit-backdrop-filter: var(--casora-lp-close-backdrop, var(--casora-popup-plate-backdrop, none));
  box-shadow: var(--casora-lp-close-shadow, var(--casora-popup-plate-shadow, none));
  width: var(--casora-lp-close-size, 48px);
  height: var(--casora-lp-close-size, 48px);
  color: var(--casora-lp-close-ink, var(--casora-popup-header-title-color, var(--primary-text-color, #fff)));
}
/* Weich (soft) setzt diese Werte im Popup-Stil (style); ohne sie bleibt alles wie oben. */
.header {
  position: var(--casora-lp-head-pos, relative);
  top: 0; left: 0; right: 0;
  pointer-events: var(--casora-lp-head-pe, auto);
}
.header-nav {
  order: var(--casora-lp-close-order, 0);
  margin-left: var(--casora-lp-close-ml, 0px);
  translate: 0 var(--casora-lp-close-dy, 0px);
  pointer-events: auto;
}
