  const _hdr = typeof window._casoraLPC === 'function' ? window._casoraLPC(entity, states, typeof hass !== 'undefined' ? hass : null, variables, 'header') : null;
  return (_hdr && _hdr.title) || 'Lichtsteuerung';

]]]

casora_lock.entity_picture:
[[[
  /* open (Falle gezogen) zeigt das offene Schloss wie unlocked, opening wie unlocking. */
  if (['unlocked', 'open'].includes(variables.lock_state || entity?.state)) return window.casoraIconUrl('lock-open-fill');
  if (['unlocking', 'opening'].includes(variables.lock_state || entity?.state)) return window.casoraIconUrl('lock-unlocking-fill');
  return window.casoraIconUrl('lock-fill');
]]]

icon_tap_action.service:
[[[
  if (variables.toggle_service) return variables.toggle_service;

  const target = variables.toggle_entity || entity?.entity_id || '';
  const state = (states[target]?.state || entity?.state || '').toLowerCase();
  if (state === 'unavailable' || state === 'unknown') return 'none';

  if (target.startsWith('lock.')) {
    if (state === 'locked') return 'lock.unlock';
    if (state === 'unlocked') return 'lock.lock';
    return 'none';
  }

  if (target.startsWith('media_player.')) {
    const feats = Number(states[target]?.attributes?.supported_features || 0);
    if (state === 'off') return (feats & 128) ? 'media_player.turn_on' : 'none';
    return (feats & 256) ? 'media_player.turn_off' : 'none';
  }

  if (target.startsWith('vacuum.')) {
    return (state === 'cleaning' || state === 'returning' || state === 'paused') ? 'vacuum.return_to_base' : 'vacuum.start';
  }

  return 'homeassistant.toggle';
]]]

icon_tap_action.service_data:
[[[
  if (variables.toggle_service_data) return variables.toggle_service_data;

  return {
    entity_id: variables.toggle_entity || entity?.entity_id
  };
]]]

casora_lock.state_display:
[[[
  const fit = (t) => window.casoraStateFit?.(t) ?? t;
  if (!entity) return "";
  const ids = (Array.isArray(variables.locks) ? variables.locks : []).filter((id) => typeof id === 'string' && states[id]);
  if (ids.length > 1) {
    const open = ids.filter((id) => ['unlocked', 'open', 'opening', 'unlocking'].includes(states[id].state));
    if (open.length === ids.length) return fit('Alle entriegelt');
    if (open.length) return fit(open.length + ' entriegelt');
    const odd = ids.find((id) => states[id].state !== 'locked');
    if (odd) return fit((() => { try { return hass.formatEntityState(states[odd]); } catch (e) { return ''; } })() || states[odd].state);
  }
  /* Ein Wort je Zustand wie Badge und Popup (HA sagt auf Deutsch „Aufgeschlossen“). */
  const word = { locked: 'Verriegelt', unlocked: 'Entriegelt' }[variables.lock_state || entity?.state];
  if (word) return fit(word);
  return fit((() => { try { return hass.formatEntityState(entity); } catch (e) { return ''; } })() || entity?.state);
]]]

card.--casora-icon-mask-image:
[[[
  if (['unlocked', 'open'].includes(variables.lock_state || entity?.state)) return `url('${window.casoraIconUrl('lock-open-fill')}')`;
  if (['unlocking', 'opening'].includes(variables.lock_state || entity?.state)) return `url('${window.casoraIconUrl('lock-unlocking-fill')}')`;
  return `url('${window.casoraIconUrl('lock-fill')}')`;
]]]

variables.lock_state:
[[[
  /* A tile over several locks (variables.locks) is only "locked" when every
     one of them is; one open door makes the whole tile read unlocked. */
  const ids = (Array.isArray(variables.locks) ? variables.locks : []).filter((id) => typeof id === 'string' && states[id]);
  if (ids.length < 2) return entity?.state;
  const st = ids.map((id) => states[id].state);
  for (const s of ['jammed', 'unlocking', 'opening', 'open', 'unlocked', 'locking']) if (st.includes(s)) return s === 'open' || s === 'opening' ? 'unlocked' : s;
  if (st.every((s) => s === 'locked')) return 'locked';
  return entity?.state;
]]]

casora_media.entity_picture:
[[[
  if (variables.has_artwork && variables.art_url) return variables.art_url;
  const icon = variables?.icon;
  if (icon === 'ps5') {
    if (variables.is_active) {
      return `${window.casoraIconUrl('ps5')}#s=${encodeURIComponent(entity.last_changed || '')}`;
    }
    return window.casoraIconUrl('ps5_off');
  }
  if (icon) return window.casoraIconUrl(icon);
  return window.casoraIconUrl('speaker');
]]]

