card.--casora-mobile-hero-src:
[[[
  /* Foto der Startseite wie im Studio (Übersicht, auch nach dem Umzug): image/image_night
     überstimmen das Theme-Bild. Ohne Foto gilt das Theme (--casora-mobile-hero-img-day/-night). */
  const ID = 'casora-mobile-hero-src';
  let el = document.getElementById(ID);
  /* Ältere Handy-Layouts ohne image: die Vorlade-Liste beginnt mit dem Foto der Übersicht
     (beim Anlegen und beim Umzug so geschrieben); das nächste Speichern im Studio setzt image. */
  const pre = Array.isArray(variables.preload_rooms) ? variables.preload_rooms[0] : null;
  const base = variables.image || (typeof pre === 'string' && /^[a-z0-9][a-z0-9_-]*$/i.test(pre) ? pre : null);
  if (!base) {
    if (el) { el.remove(); if (window.casoraWallpaperRefresh) window.casoraWallpaperRefresh(); }
    return '0';
  }
  const dir = '/casora_assets/rooms/';
  const night = variables.image_night || (base + '-night');
  const css = ':root{--casora-mobile-hero-img-day:url("' + dir + encodeURI(String(base)) + '.jpg") !important;'
    + '--casora-mobile-hero-img-night:url("' + dir + encodeURI(String(night)) + '.jpg") !important;}';
  if (!el) { el = document.createElement('style'); el.id = ID; document.head.appendChild(el); }
  if (el.textContent !== css) {
    el.textContent = css;
    if (window.casoraWallpaperRefresh) window.casoraWallpaperRefresh();
  }
  return '0';
]]]

card.--casora-room-photo-blur-src:
[[[
  /* #8: Unschärfe des Raumfotos hinter einem geöffneten Raum (Studio: Design & Bedienung → Mobil).
     filter-overlay.js liest --casora-room-photo-blur; leer = 28 px wie bisher. */
  const ID = 'casora-room-photo-blur';
  const el = document.getElementById(ID);
  const v = variables.room_photo_blur;
  const n = Number(v);
  if (v === null || v === undefined || v === '' || !isFinite(n) || n < 0) {
    if (el) el.remove();
    return '0';
  }
  const css = ':root{--casora-room-photo-blur:' + Math.min(n, 80) + 'px !important;}';
  const s = el || document.head.appendChild(Object.assign(document.createElement('style'), { id: ID }));
  if (s.textContent !== css) s.textContent = css;
  return '0';
]]]

card.--casora-room-groups-src:
[[[
  /* Raumseite am Handy nach Kategorien gliedern (Studio: Design & Bedienung → Handy).
     filter-overlay.js liest --casora-room-groups; leer = an. */
  const ID = 'casora-room-groups';
  const el = document.getElementById(ID);
  const v = variables.room_groups;
  if (v !== false && v !== 'false') {
    if (el) el.remove();
    return '0';
  }
  const css = ':root{--casora-room-groups:off !important;}';
  const s = el || document.head.appendChild(Object.assign(document.createElement('style'), { id: ID }));
  if (s.textContent !== css) s.textContent = css;
  return '0';
]]]

card.--casora-font-set:
[[[
  const STACKS = {
    inter:   '"Inter", -apple-system, BlinkMacSystemFont, system-ui, sans-serif',
    hanken:  '"Hanken Grotesk", -apple-system, BlinkMacSystemFont, system-ui, sans-serif',
    jakarta: '"Inter", -apple-system, BlinkMacSystemFont, system-ui, sans-serif',
    system:  '-apple-system, BlinkMacSystemFont, system-ui, "Segoe UI", Roboto, sans-serif'
  };
  const link = (id, href) => {
    let l = document.getElementById(id);
    if (l && l.getAttribute('href') === href) return;
    if (!l) { l = document.createElement('link'); l.id = id; l.rel = 'stylesheet'; document.head.appendChild(l); }
    l.href = href;
  };
  const key = String(variables.font || '').trim().toLowerCase();
  let want = STACKS[key] || '';
  if (key === 'custom') {
    /* Eigene Schrift (z. B. gekaufte Gilroy), im Studio hochgeladen – CSS schreibt fonts.py. */
    const fam = String(variables.font_family || '').replace(/["'<>;{}\\]/g, '').trim();
    link('casora-font-custom', '/local/casora/fonts/casora-fonts.css');
    want = fam ? '"' + fam + '", ' + STACKS.inter : '';
  }
  /* Casoras Schriften immer bereitstellen – auch die Designs setzen sie (Inter, Hanken Grotesk). */
  link('casora-font-faces', '/casora_assets/fonts/hanken-grotesk.css');
  const ID = 'casora-font-v1';
  let el = document.getElementById(ID);
  if (!want) { if (el) el.remove(); return '0'; }
  if (!el) {
    el = document.createElement('style');
    el.id = ID;
    document.head.appendChild(el);
  }
  const css = 'html{--primary-font-family:' + want + ' !important;}';
  if (el.textContent !== css) el.textContent = css;
  return '1';
]]]

casora_mobile_chrome.extra_styles:
/* ha-card is overflow:visible so the count can sit proud of the circle,
   which also stopped it clipping button-card's ripple - a square layer
   filling the card's box, so the hover read as a box behind the disc. */
:host{
  --button-card-ripple-color: transparent !important;
  --button-card-ripple-hover-color: transparent !important;
  --ha-ripple-color: transparent !important;
  --ha-ripple-hover-color: transparent !important;
  --mdc-ripple-press-opacity: 0 !important;
}
:host ha-ripple,
:host mwc-ripple{ display: none !important; }
:host{
  display: block !important;
  pointer-events: auto !important;
}

/* Measured off iOS's own capsule. Three layers, none on ha-card, which HA and
   the theme restyle: the glass, the content, then the edge light, which
   brightens the glass behind it rather than painting white over it. */
:host{
  --casora-card-hover-filter: none;
  --casora-hover-filter: none;
}
:host ha-card{
  position: relative !important;
  border-radius: calc(var(--casora-mchrome-h, 44px) / 2) !important;
  background: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-shadow: none !important;
  filter: none !important;
  border: none !important;
  overflow: visible !important;
  isolation: isolate;
}
:host ha-card::before{
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  background-color: var(--casora-pill-fill, rgba(255,255,255,0.10));
  backdrop-filter: var(--casora-pill-backdrop, blur(12px) saturate(1.4));
  -webkit-backdrop-filter: var(--casora-pill-backdrop, blur(12px) saturate(1.4));
  box-shadow: var(--casora-pill-rim, inset 0 0.5px 0 rgba(255,255,255,0.10), inset 0 -0.5px 0 rgba(255,255,255,0.10)),
    -0.5px 0 0 var(--casora-pill-edge, rgba(0,0,0,0.50)), 0.5px 0 0 var(--casora-pill-edge, rgba(0,0,0,0.50));
  pointer-events: none;
}
:host ha-card::after{
  content: "";
  position: absolute;
  inset: 0;
  z-index: 2;
  border-radius: inherit;
  backdrop-filter: var(--casora-pill-highlight, brightness(1.45));
  -webkit-backdrop-filter: var(--casora-pill-highlight, brightness(1.45));
  padding: 1px;
  box-sizing: border-box;
  -webkit-mask: linear-gradient(to bottom, #000 0, rgba(0,0,0,.45) 13%, transparent 31%, transparent 69%, rgba(0,0,0,.45) 87%, #000 100%), linear-gradient(#000 0 0), linear-gradient(#000 0 0) content-box;
  -webkit-mask-composite: source-in, source-out;
  mask: linear-gradient(to bottom, #000 0, rgba(0,0,0,.45) 13%, transparent 31%, transparent 69%, rgba(0,0,0,.45) 87%, #000 100%), linear-gradient(#000 0 0), linear-gradient(#000 0 0) content-box;
  mask-composite: intersect, subtract;
  pointer-events: none;
}

/* A filled button is flat. The capsule carries the glass; a button lit
   white on top of it should read as one solid shape, not as a disc with
   the capsule's sheen and blur showing through its edge. */
:host ha-card > .custom-field ha-card,
:host ha-card button-card{
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  background-image: none !important;
}

:host #edit::before{
  content: "";
  display: var(--casora-chrome-sep, none);
  position: absolute;
  left: -2.5px;
  top: var(--casora-chrome-sep-top, 13px);
  width: 1px;
  height: var(--casora-chrome-sep-h, 18px);
  background: var(--casora-pill-divider, rgba(60,60,67,0.36));
  pointer-events: none;
}

/* The badge hangs outside the capsule, so nothing on the way may clip. */
:host #container,
:host .button-card-content,
:host #customfields,
:host .custom-field,
:host .vertical,
:host .ellipsis{ overflow: visible !important; }

