  // Kameras und Kontakte von hier, solange sie selbst keine eingetragen hat.
  const K = ["security_cameras", "security_cameras_label", "security_door_sensors", "security_lock_batteries", "security_lock_entity", "security_lock_entity_2", "security_locks", "security_locks_label", "security_entity_1", "security_entity_2", "security_entity_3", "security_entity_4", "security_entity_5", "security_entity_6", "security_entity_7", "security_entity_8", "security_label_1", "security_label_2", "security_label_3", "security_label_4", "security_label_5", "security_label_6", "security_label_7", "security_label_8"];
  const o = {};
  K.forEach((k) => { if (variables[k] != null) o[k] = variables[k]; });
  window._casoraMobileSec = o;
  return '';
