      width: 100% !important;
      min-width: 100% !important;
      max-width: 100% !important;
      flex: 1 1 auto !important;
    }
  `;
  for (let i = 1; i <= 8; i++) {
    const on = list[i] ? 1 : 0;
    css += `
      #c${i} {
        --np-c${i}: ${on};
        max-height: calc(var(--np-c${i}, 0) * 210px);
        opacity: var(--np-c${i}, 0);
        margin-top: calc(var(--np-c${i}, 0) * 8px);
        overflow: hidden;
        pointer-events: ${on ? 'auto' : 'none'};
        transition:
          max-height .42s cubic-bezier(0.32, 0.72, 0, 1),
          margin-top .42s cubic-bezier(0.32, 0.72, 0, 1),
          opacity .3s ease;
      }
    `;
  }
  return css;
]]]

casora_mobile_now_playing.extra_styles:
[[[
  const staticCSS = `:host(.casora-navbar-card.casora-navbar-card):active{filter:none!important;-webkit-filter:none!important}:host{position:sticky!important;top:-9999px!important;filter:none!important;-webkit-filter:none!important}#aspect-ratio{display:block!important;min-width:0!important;min-height:0!important}ha-card.button-card-main{background:transparent!important;backdrop-filter:none!important;-webkit-backdrop-filter:none!important;box-shadow:none!important;border:none!important;overflow:visible!important;padding:0!important;contain:none!important;isolation:auto!important;will-change:auto!important;transition:none!important}.button-card-main,.button-card-content,#customfields{overflow:visible!important;contain:none!important;isolation:auto!important}#media_row::-webkit-scrollbar{display:none!important}`;
  const npCSS = `
    #media_row > * {
      width: 100% !important;
      min-width: 100% !important;
      max-width: 100% !important;
      flex: 0 0 100% !important;
      scroll-snap-align: start;
      scroll-snap-stop: always;
      box-sizing: border-box !important;
      --np-bloom-strength: 0.62;
    }

    #np_rail > * {
      width: 100% !important;
      max-width: 100% !important;
      flex: 1 1 auto !important;
      --np-bloom-strength: 0.62;
    }

    @media (hover: none) and (pointer: coarse) and (orientation: landscape) and (max-height: 600px) {
      #np_rail > * {
        width: calc((100vw
          - (max(var(--casora-measured-safe-left, 0px), var(--casora-rail-left, 16px))
             + max(env(safe-area-inset-right), var(--casora-rail-left, 16px)))
          - 60px - var(--np-gap, 10px)) / 2) !important;
        max-width: calc((100vw
          - (max(var(--casora-measured-safe-left, 0px), var(--casora-rail-left, 16px))
             + max(env(safe-area-inset-right), var(--casora-rail-left, 16px)))
          - 60px - var(--np-gap, 10px)) / 2) !important;
      }
    }


  `;

  const npList = (typeof window._casoraNPView === 'function')
    ? (typeof window._casoraNPView === "function" ? window._casoraNPView(states, variables.cfg) : [])
    : [];
  const anyActive = npList.length > 0;
  const shown = anyActive;
  const ov = shown ? 'visible' : 'hidden';
  this.setAttribute('data-casora-np', '');
  this.toggleAttribute('data-casora-np-empty', !shown);
  /* Weich (1.0.7): das Karussell wird zur ruhigen Liste (09-weich-wiedergabe.js). */
  if (window._casoraNPSoft) window._casoraNPSoft.mount(this, variables.cfg, 'phone');

  return staticCSS + npCSS +
    `:host{display:grid!important;overflow:${ov}!important;grid-template-rows:${shown?'1fr':'0fr'}!important;grid-template-columns:minmax(0,1fr)!important;opacity:${shown?'1':'0'};pointer-events:${shown?'auto':'none'};transition:grid-template-rows .5s cubic-bezier(0.32,0.72,0,1),opacity ${shown?'.35s ease .12s':'.25s ease'}}` +
    `#aspect-ratio{overflow:${ov}!important}` +
    `ha-card.button-card-main{min-height:0!important;overflow:${ov}!important}`;
]]]

media_row.display:
[[[
  /* Casora-Look: die Liste aus 09-weich-wiedergabe.js ersetzt die Medien-Zeile – schon beim ersten
     Zeichnen ausblenden, sonst blitzt bis zum Nachladen der Skripte der alte Player auf (05.10.2026). */
  if (getComputedStyle(document.documentElement).getPropertyValue('--casora-popup-layout').trim() === 'soft') return 'none';
  const filter = states['input_select.casora_mobile_filter']?.state ?? 'all';
  if (filter === 'media') return 'block';
  if (filter !== 'all') return 'none';
  const npList = (typeof window._casoraNPView === 'function')
    ? (typeof window._casoraNPView === "function" ? window._casoraNPView(states, variables.cfg) : [])
    : [];
  return npList.length ? 'block' : 'none';
]]]

