card.extra_styles:
[[[ const _rv = variables.casora_rv || {}; 
  /* Weich (1.0.7): die Medien-Pillen werden zur ruhigen Liste (09-weich-wiedergabe.js). */
  if (window._casoraNPSoft) window._casoraNPSoft.mount(this, window._casoraNPSoft.roomCfg(_rv), 'room');
  const step = 22;

  const PC = window._casoraPCSources?.(states, _rv) || {};

  const fields = [
    ['mp1',  !!_rv.media_player_1  && _rv.media_player_1],
    ['mp2',  !!_rv.media_player_2  && _rv.media_player_2],
    ['mp3',  !!_rv.media_player_3  && _rv.media_player_3],
    ['mp4',  !!_rv.media_player_4  && _rv.media_player_4],
    ['mp5',  !!_rv.media_player_5  && _rv.media_player_5],
    ['mp6',  !!_rv.media_player_6  && _rv.media_player_6],
    ['mp7',  !!_rv.media_player_7  && _rv.media_player_7],
    ['mp8',  !!_rv.media_player_8  && _rv.media_player_8],
    ['mp9',  !!_rv.media_player_9  && _rv.media_player_9],
    ['mp10', !!_rv.media_player_10 && _rv.media_player_10],
    ['activity1', !!_rv.psn_1],
    ['activity2', !!_rv.psn_2],
    ['activity_discord', !!PC.discord],
    ['activity_steam', !!PC.steam]
  ];

  let i = 0;
  let stagger = '';
  for (const [id, shown] of fields) {
    if (!shown) continue;
    stagger += '#' + id + '{--casora-badge-enter-delay:' + (i * step) + 'ms;}';
    i++;
  }

  return (
    'ha-card{' +
      'will-change: auto !important;' +
      'isolation: auto !important;' +
      'contain: none !important;' +
    '}' +
    '#container{' +
      'will-change: auto !important;' +
      'isolation: auto !important;' +
    '}' +
    stagger +
    '#mp1, #mp2, #mp3, #mp4, #mp5, #mp6, #mp7, #mp8, #mp9, #mp10,' +
    '#activity1, #activity2, #activity_discord, #activity_steam{' +
      'overflow: var(--casora-field-ovf, visible) !important;' +
    '}'
  );
]]]

