/* Handy: zu breite Badge-Reihen blättern seitwärts (30.09.2026). Die innere Karte ist so breit
   wie ihre Badges (mindestens die Reihe), damit die Reihe selbst scrollt und nicht das Raster
   darin über den Rand ragt. Der rechte Abstand sitzt an der inneren Karte, sonst fehlt er
   am Ende des Scrollbereichs. Weiche Ränder setzt window._casoraBadgeRows (01-basis.js). */
#climate_row > *,#security_row > *,#energy_row > *,#rooms_row > *,#room_sub_climate > *,#room_sub_security > *,#room_sub_lights > *,#room_sub_presence > *,#room_sub_energy > *,#room_sub_media > *{width:max-content!important;min-width:100%!important;display:block!important;box-sizing:border-box!important;padding-right:var(--casora-rail-left, 16px)!important}
#climate_row::-webkit-scrollbar,#security_row::-webkit-scrollbar,#energy_row::-webkit-scrollbar,#rooms_row::-webkit-scrollbar,#room_sub_climate::-webkit-scrollbar,#room_sub_security::-webkit-scrollbar,#room_sub_lights::-webkit-scrollbar,#room_sub_presence::-webkit-scrollbar,#room_sub_energy::-webkit-scrollbar,#room_sub_media::-webkit-scrollbar{display:none!important}
#climate_row,#security_row,#energy_row,#rooms_row,#room_sub_climate,#room_sub_security,#room_sub_lights,#room_sub_presence,#room_sub_energy,#room_sub_media{touch-action:pan-x pan-y;-webkit-overflow-scrolling:touch}
#climate_row[data-cs-fade="r"],#security_row[data-cs-fade="r"],#energy_row[data-cs-fade="r"],#rooms_row[data-cs-fade="r"],#room_sub_climate[data-cs-fade="r"],#room_sub_security[data-cs-fade="r"],#room_sub_lights[data-cs-fade="r"],#room_sub_presence[data-cs-fade="r"],#room_sub_energy[data-cs-fade="r"],#room_sub_media[data-cs-fade="r"]{-webkit-mask-image:linear-gradient(to right,#000 calc(100% - 32px),transparent);mask-image:linear-gradient(to right,#000 calc(100% - 32px),transparent)}
#climate_row[data-cs-fade="l"],#security_row[data-cs-fade="l"],#energy_row[data-cs-fade="l"],#rooms_row[data-cs-fade="l"],#room_sub_climate[data-cs-fade="l"],#room_sub_security[data-cs-fade="l"],#room_sub_lights[data-cs-fade="l"],#room_sub_presence[data-cs-fade="l"],#room_sub_energy[data-cs-fade="l"],#room_sub_media[data-cs-fade="l"]{-webkit-mask-image:linear-gradient(to right,transparent,#000 32px);mask-image:linear-gradient(to right,transparent,#000 32px)}
