card.--casora-badge-rows:
[[[
  const root = this.shadowRoot;
  if (root && typeof window._casoraBadgeRows === 'function') window._casoraBadgeRows(root);
  return '0';
]]]

climate_row.display:
[[[
  // casora_expanded_row is desktop/tablet-only; ignoring it here stops
  // desktop badge taps from toggling rows on mobile.
  const filter = states['input_select.casora_mobile_filter']?.state ?? 'all';
  return filter === 'climate' ? 'block' : 'none';
]]]

rooms_row.display:
[[[
  // Raumseite: dieselben Badges wie im Raum-Kopf am Desktop (variables.casora_rv).
  const f = states['input_select.casora_mobile_filter']?.state ?? 'all';
  const r = variables.casora_rv;
  return (String(f).startsWith('room_') && r && r._any) ? 'block' : 'none';
]]]

rooms_row.margin:
[[[
  // Mit offener Unter-Reihe rückt sie dicht an, der Abstand zu den Kacheln folgt unter ihr.
  return states['input_select.casora_mobile_filter']?.attributes?.casora_row
    ? '0 0 var(--casora-badge-subrow-gap-mobile, 10px) 0 !important'
    : '0 0 var(--casora-room-badges-gap-mobile, 24px) 0 !important';
]]]

rooms_row.--casora-badge-order-security:
[[[ const _rv = variables.casora_rv || {}; 
  // Standard wie das Studio (BADGE_ORDER_IDS): gespeicherte Reihenfolge zuerst, was fehlt, danach.
  const D = ['security', 'climate', 'lights', 'people', 'energy', 'scenes', 'media'];
  const o = (Array.isArray(_rv.badge_order) ? _rv.badge_order : []).filter((x) => D.includes(x));
  D.forEach((x) => { if (!o.includes(x)) o.push(x); });
  return o.indexOf('security') + 1;
]]]

