casora_mobile_weather.extra_styles:
@keyframes titleFadeIn {
  from { opacity: 0; transform: translateY(4px); }
  to   { opacity: 0.9; transform: translateY(0); }
}
#name { animation: titleFadeIn 0.3s ease-out both; }
ha-card.button-card-main {
  align-items: stretch !important;
  justify-content: flex-start !important;
  text-align: left !important;
}
#container, .button-card-content { width: 100% !important; }
#name { justify-self: start !important; }

casora_mobile_weather.name:
[[[
  const f = states['input_select.casora_mobile_filter']?.state ?? 'all';
  if (f === 'all') {
    /* Titel = Name der Übersicht (Studio: variables.home_name bei eigenem Namen). Übersetzt nur
       mit home_auto (von Casora angelegt, unverändert) – Regel casoraRoomName, 04.10.2026. */
    const own = String(variables.home_name || '').trim();
    const r = window.casoraRoomName ? window.casoraRoomName(own || 'Home',
      { casora_auto_name: !own && variables.home_auto === true ? 'home' : undefined, name_literal: !!own || variables.name_literal === true }) : null;
    /* Wörtlicher Name in <span data-no-i18n>: casora-i18n übersetzt beim Zeichnen sonst „Home“ zu
       „Zuhause“, die Stil-Regel unten schrieb danach wieder „Home“ – der Titel sprang (07.10.2026). */
    const text = r ? r.text : (own || 'Home');
    const lit = r ? r.literal : (variables.name_literal === true && !!own);
    if (!lit) return text;
    const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    return '<span data-no-i18n>' + esc(text) + '</span>';
  }
  const labels = {climate:'Klima',lights:'Beleuchtung',presence:'Personen',media:'Medien',security:'Sicherheit',energy:'Energie'};
  return labels[f] || 'Zuhause';
]]]

card.--casora-name-literal:
[[[
  /* Name der Übersicht nach casoraRoomName (04.10.2026): ohne home_auto nicht übersetzen, z. B.
     „Home“ auf Deutsch. Nur auf der Startseite (Filter „all“); Filter-Titel wie „Klima“ übersetzt
     casora-i18n weiter. */
  const f = states['input_select.casora_mobile_filter']?.state ?? 'all';
  const own = String(variables.home_name || '').trim();
  const r = window.casoraRoomName ? window.casoraRoomName(own || 'Home',
    { casora_auto_name: !own && variables.home_auto === true ? 'home' : undefined, name_literal: !!own || variables.name_literal === true }) : null;
  const lit = f === 'all' && (r ? r.literal : (variables.name_literal === true && !!own));
  const n = this.shadowRoot && this.shadowRoot.getElementById('name');
  if (n) {
    if (lit) {
      n.setAttribute('data-no-i18n', '');
      const want = r ? r.text : own;
      /* Nur den Textknoten ändern: textContent löschte Lits Marker in #name, beim nächsten
         Namen (z. B. Filter „Sicherheit“) warf button-card „nextSibling“ von null. */
      const tn = n.textContent !== want && Array.from(n.childNodes).find((c) => c.nodeType === 3 && c.data.trim());
      if (tn) tn.data = want;
    } else n.removeAttribute('data-no-i18n');
  }
  return lit ? '1' : '0';
]]]

notifications.display:
