  const bell = variables.show_notifications !== false;
  return (bell || variables.casora_ui_managed) ? 'block' : 'none';
]]]

casora_motion.entity:
[[[
  return (
    variables.sensor_1 ||
    variables.sensor_2 ||
    variables.sensor_3 ||
    variables.sensor_4 ||
    variables.sensor_5 ||
    variables.sensor_6 ||
    null
  );
]]]

icon_tap_action.entity:
[[[
  const sensors = [
    { id: variables.sensor_1, label: variables.label_1 },
    { id: variables.sensor_2, label: variables.label_2 },
    { id: variables.sensor_3, label: variables.label_3 },
    { id: variables.sensor_4, label: variables.label_4 },
    { id: variables.sensor_5, label: variables.label_5 },
    { id: variables.sensor_6, label: variables.label_6 },
  ].filter(s => s.id);
  const active = sensors.find(s => states[s.id]?.state === 'on');
  if (active) return active.id;
  if (sensors.length > 0) {
    return sensors.slice().sort((a, b) =>
      new Date(states[b.id]?.last_changed || 0) - new Date(states[a.id]?.last_changed || 0)
    )[0].id;
  }
  return entity?.entity_id || null;
]]]

casora_motion.name:
[[[
  const sensors = [
    { id: variables.sensor_1, label: variables.label_1 },
    { id: variables.sensor_2, label: variables.label_2 },
    { id: variables.sensor_3, label: variables.label_3 },
    { id: variables.sensor_4, label: variables.label_4 },
    { id: variables.sensor_5, label: variables.label_5 },
    { id: variables.sensor_6, label: variables.label_6 },
  ].filter(s => s.id);
  if (sensors.length === 0) return variables.default_name || 'Bewegung';
  const active = sensors.find(s => states[s.id]?.state === 'on');
  return active ? active.label : (variables.default_name || 'Bewegung');
]]]

state.value:
[[[
  const sensors = [
    variables.sensor_1, variables.sensor_2, variables.sensor_3,
    variables.sensor_4, variables.sensor_5, variables.sensor_6,
  ].filter(Boolean);
  if (sensors.length === 0) return false;
  return sensors.some(id => states[id]?.state === 'on');
]]]

casora_motion.state_display:
[[[
  const sensors = [
    variables.sensor_1, variables.sensor_2, variables.sensor_3,
    variables.sensor_4, variables.sensor_5, variables.sensor_6,
  ].filter(Boolean);
  if (sensors.length > 0) {
    return sensors.some(id => states[id]?.state === 'on') ? 'Erkannt' : 'Frei';
  }
  return entity?.state === 'on' ? 'Erkannt' : 'Frei';
]]]

state.color:
[[[
  const sensors = [
    variables.sensor_1, variables.sensor_2, variables.sensor_3,
    variables.sensor_4, variables.sensor_5, variables.sensor_6,
  ].filter(Boolean);
  const active = sensors.length > 0
    ? sensors.some(id => states[id]?.state === 'on')
    : entity?.state === 'on';
  return active
    ? 'var(--casora-entity-name-active, var(--primary-text-color))'
    : 'var(--casora-entity-state, var(--secondary-text-color))';
]]]

state.opacity:
[[[
  const sensors = [
    variables.sensor_1, variables.sensor_2, variables.sensor_3,
    variables.sensor_4, variables.sensor_5, variables.sensor_6,
  ].filter(Boolean);
  const active = sensors.length > 0
    ? sensors.some(id => states[id]?.state === 'on')
    : entity?.state === 'on';
  return active ? '1' : '0.55';
]]]

