casora_network.state_display:
[[[
  const dlId  = variables.entity_download || entity?.entity_id;
  const ulId  = variables.entity_upload   || variables.upload_sensor || null;
  const stat1 = variables.entity_stat_1 || null;
  const stat2 = variables.entity_stat_2 || null;
  const stat3 = variables.entity_stat_3 || null;
  const stat4 = variables.entity_stat_4 || null;

  const safe = (id) => { if (!id) return null; const n = parseFloat(states[id]?.state); return isNaN(n) ? null : n; };

  const fit = (t) => window.casoraStateFit?.(t) ?? t;

  const dlVals = [safe(dlId), safe(stat1), safe(stat3)].filter(v => v != null);
  const ulVals = [safe(ulId), safe(stat2), safe(stat4)].filter(v => v != null);
  const dlMax = dlVals.length > 0 ? Math.max(...dlVals) : null;
  const ulMax = ulVals.length > 0 ? Math.max(...ulVals) : null;
  const max = Math.max(dlMax ?? 0, ulMax ?? 0);

  const idle  = Number(variables.idle_threshold  ?? 1);

  if (max < idle) return fit('Inaktiv');

  const dir   = (dlMax == null || (ulMax != null && ulMax > dlMax)) ? 'Upload' : 'Download';
  const value = dir === 'Upload' ? ulMax : dlMax;
  // Same formatting as casora_popup_network.yaml's own tiles, so the badge
  // and the popup never disagree on how a number is rounded/displayed.
  const valueStr = value == null ? '—' : (value >= 100 ? Math.round(value).toString() : (window.casoraNum || ((x, a, b) => Number(x).toLocaleString(window.casoraLocale ? window.casoraLocale() : 'de-DE', { minimumFractionDigits: a, maximumFractionDigits: b == null ? a : b })))(value, 1));
  /* Kurz (01.10.2026): Pfeil statt „Upload“/„Download“ – passt auch schmal ohne Kürzen. */
  return fit(`${dir === 'Upload' ? '↑' : '↓'} ${valueStr} Mbit/s`);
]]]

card.--casora-icon-inactive-color:
[[[
  const safe = (id) => { if (!id) return null; const n = parseFloat(states[id]?.state); return isNaN(n) ? null : n; };
  const vals = [
    safe(variables.entity_download || entity?.entity_id),
    safe(variables.entity_upload || variables.upload_sensor),
    safe(variables.entity_stat_1), safe(variables.entity_stat_2),
    safe(variables.entity_stat_3), safe(variables.entity_stat_4),
  ].filter(v => v != null);
  const max  = vals.length > 0 ? Math.max(...vals) : 0;
  const idle = Number(variables.idle_threshold ?? 1);
  return max >= idle
    ? 'var(--casora-popup-primary-color, #00c3d0)'
    : 'var(--casora-icon-inactive-fallback-color, rgba(255,255,255,0.95))';
]]]

custom_fields.glyph:
[[[
  const card = this;
  if (!card._casoraNotifyBound) {
    card._casoraNotifyBound = true;
    const openIt = (e) => {
      if (card._casoraNotifyGuardUntil && Date.now() < card._casoraNotifyGuardUntil) return;
      card._casoraNotifyGuardUntil = Date.now() + 600;
      if (e.type === 'touchend' && e.cancelable) e.preventDefault();
      if (window._casoraNotify) window._casoraNotify.open(card);
    };
    card.addEventListener('touchend', openIt, { passive: false });
    card.addEventListener('click', openIt);
  }
  const n = window._casoraNotify ? window._casoraNotify.count : 0;
  const phone = window.matchMedia(
    '(max-width: 767px), (max-height: 500px)').matches;
  const badged = phone && n > 0;
  /* Weich (Runde 2): Das Hell-Design färbt die Glocke per Filter dunkel – der rote Punkt im
     bell-badge-Symbol wurde dabei mitgefärbt. Dort: schlichte Glocke + eigener Punkt in Alarmrot. */
  let dot = false;
  try { dot = badged && getComputedStyle(document.documentElement).getPropertyValue('--casora-bell-dot').trim() === '1'; } catch (e) {}
  if (dot) return `<img class="casora-bell" src="${window.casoraIconUrl('bell')}"
    alt="" aria-hidden="true"><span class="casora-bell-dot"></span>`;
  const url = window.casoraIconUrl(badged ? 'bell-badge' : 'bell');
  return `<img class="casora-bell${badged ? ' badged' : ''}" src="${url}"
    alt="" aria-hidden="true">`;
]]]

casora_notifications_button.extra_styles:
/* ha-card is overflow:visible so the count can sit proud of the circle,
   which also stopped it clipping button-card's ripple - a square layer
   filling the card's box, so the hover read as a box behind the disc. */
:host{
  --button-card-ripple-color: transparent !important;
  --button-card-ripple-hover-color: transparent !important;
  --ha-ripple-color: transparent !important;
  --ha-ripple-hover-color: transparent !important;
  --mdc-ripple-press-opacity: 0 !important;
}
:host ha-ripple,
:host mwc-ripple{ display: none !important; }
:host{
  display: grid !important;
  place-items: center !important;
  /* The count is mounted beside ha-card rather than inside it, and hangs
     over the circle's edge from here. */
  position: relative !important;
  overflow: visible !important;
  width: var(--casora-chrome-btn-size, 34px) !important;
  height: var(--casora-chrome-btn-size, 34px) !important;
  color: var(--casora-chrome-ink, #fff) !important;
  pointer-events: auto !important;
}

/* MUST match casora_settings_button and .np-head-wave: same size, same flat
   fill, blur but no rim. Three controls on one row read as one set only if
   nothing about them disagrees. */
:host ha-card{
  /* styles.card lands the var on ha-card, so it is read here - a custom
     property set on a child is invisible to its parent. */
  display: var(--casora-bell-vis, none) !important;
  position: relative !important;
  width: var(--casora-chrome-btn-size, 34px) !important;
  height: var(--casora-chrome-btn-size, 34px) !important;
  border-radius: 50% !important;
  place-items: center !important;
  background: var(--casora-bell-fill, var(--casora-chrome-fill, rgba(0,0,0,0.40))) !important;
  /* Weich (1.0.7, Kopfleiste D): Fläche mit weichem Schatten über Theme-Variablen, sonst flach. */
  backdrop-filter: var(--casora-chrome-backdrop, none) !important;
  -webkit-backdrop-filter: var(--casora-chrome-backdrop, none) !important;
  box-shadow: var(--casora-chrome-shadow, none) !important;
  transition: background 180ms cubic-bezier(.32,.72,0,1) !important;
}

/* The count hangs outside the circle, and .ellipsis both clips and
   bottom-aligns everything button-card puts inside it. */
:host .vertical,
:host .ellipsis,
:host .custom-field,
:host .custom-field-glyph{ overflow: visible !important; }

/* Height only, width auto: the source viewBox is taller than it is wide,
   so constraining both would squash it. */
:host .casora-bell{
  position: absolute !important;
  top: 50% !important;
  left: 50% !important;
  transform: translate(-50%, -50%) !important;
  height: var(--casora-bell-size, 17px) !important;
  width: auto !important;
  display: block !important;
  pointer-events: none !important;
  /* The glyph is an <img>, so it inverts with a filter rather than a fill.
     casora-core sets both this and --casora-bell-fill while the panel is up. */
  filter: var(--casora-bell-filter, var(--casora-chrome-glyph-filter, none)) !important;
  transition: filter 180ms cubic-bezier(.32,.72,0,1) !important;
}

/* bell-badge draws its bell across 87.87% of its viewBox, the rest being
   the badge above it, so at a shared height the bell came out 2px smaller
   than the plain glyph. 1/0.8787 renders the BELL at the same size. */
:host .casora-bell.badged{
  height: calc(var(--casora-bell-size, 17px) * 1.138) !important;
}

:host .casora-bell-dot{
  position: absolute !important;
  top: var(--casora-bell-dot-top, 12px) !important;
  right: var(--casora-bell-dot-right, 14px) !important;
  width: 8px !important;
  height: 8px !important;
  border-radius: 50% !important;
  background: var(--casora-bell-dot-fill, var(--casora-color-red, #D35A4E)) !important;
  box-shadow: 0 0 0 2px var(--casora-bell-fill, var(--casora-chrome-fill, rgba(0,0,0,0.40))) !important;
  pointer-events: none !important;
}
/* D-21: am Desktop ist der Kreis kleiner (40 px) – der Punkt sitzt dort oben rechts an der Glocke statt mitten darauf. */
@media (min-width: 768px) and (min-height: 501px) {
  :host .casora-bell-dot{ top: var(--casora-bell-dot-top-desk, 8px) !important; right: var(--casora-bell-dot-right-desk, 9px) !important; }
}

/* An app-icon badge: it overlaps the top-right corner and overhangs it,
   rather than being tucked inside the circle. */
:host .casora-bell-count{
  position: absolute !important;
  top: var(--casora-bell-count-top, -3px) !important;
  right: var(--casora-bell-count-right, -3px) !important;
  min-width: 16px !important;
