casora_popup.content:
[[[
  const _src = variables.src;
  const _ent = (_src && _src.entity) ? states[_src.entity] : null;
  if (!_ent) return { type: 'vertical-stack', cards: [] };
  /* Symbol je Player automatisch; eigene Angaben (icon, volume_entity) unter media.players in den Einstellungen. */
  const _mp = ((window.CASORA_SETTINGS || {}).media || {}).players || {};
  const _t = ((_ent.attributes?.friendly_name || '') + ' ' + _ent.entity_id + ' ' + (_ent.attributes?.device_class || '')).toLowerCase();
  const _meta = Object.assign({ icon: /apple.?tv/.test(_t) ? 'apple_tv' : /homepod/.test(_t) ? 'homepod'
    : /playstation|ps5|xbox/.test(_t) ? 'playstation' : / tv |fernseher|qled|oled|bravia/.test(_t) ? 'tv' : 'speaker' }, _mp[_ent.entity_id] || {});
  return ((entity, variables) => {
  const UI = window._casoraUI;
  if (!UI || !entity) return { type: 'vertical-stack', cards: [] };
  const id = entity?.entity_id;
  const reg = hass.entities || {};
  const devId = reg[id]?.device_id;
  const areaId = reg[id]?.area_id || (devId ? hass.devices?.[devId]?.area_id : null);
  const roomName = variables.room_name || (areaId ? hass.areas?.[areaId]?.name : null) || null;

  const uiCard = {
    type: 'custom:button-card',
    entity: id,
    triggers_update: [id].concat(variables.volume_entity ? [variables.volume_entity] : []),
    variables: { room_name: roomName, icon: variables.icon || null, volume_entity: variables.volume_entity || null },
    card_mod: { style:
      '
:host { --ha-card-backdrop-filter: none !important; --ha-card-background: transparent !important; --card-background-color: transparent !important; --ha-card-box-shadow: none !important; --ha-card-border-width: 0px !important; }'
      + '
ha-card::before, ha-card::after, #card::before, #card::after, #container::before, #container::after { display: none !important; }'
      + '
ha-card { will-change: auto !important; }'
      + '
@media (max-width: 600px) { ha-card { padding-left: 14px !important; padding-right: 14px !important; } }'
      /* Weich: kein Kachelschatten der Inhaltskarte – er stand als zweite Platte im Popup. */
      + (UI.soft && UI.soft() ? '
:host { --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; --button-card-box-shadow-active: none !important; } ha-card { box-shadow: none !important; }' : '')
    },
    tap_action: { action: 'none' },
    hold_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    styles: {
      card: [
        { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
        { padding: 'var(--casora-soft-card-top, 6px) 26px 22px 26px' },
      ],
      grid: [
        { 'grid-template-areas': '"body"' },
        { 'grid-template-columns': '1fr' },
      ],
      custom_fields: { body: [{ 'justify-self': 'stretch' }, { 'min-width': '0' }] },
    },
    custom_fields: { body: "[[[
  const UI = window._casoraUI;
  if (!UI || !entity) return '';
  const T = UI.tokens;
  const esc = UI.esc;
  const id = entity?.entity_id;
  const a = entity?.attributes || {};
  const st = entity?.state;
  const F = a.supported_features || 0;
  const has = (b) => (F & b) === b;
  /* Popup-Standard (24.09.2026): part = hero | ctl (breit), ohne part alles. */
  const P = variables.part;
  const svc = (service, data) => esc(JSON.stringify({ domain: 'media_player', service: service, data: data || {}, target: { entity_id: id } }));
  const ic = (n) => (typeof window.casoraIconUrl === 'function') ? window.casoraIconUrl(n) : '/casora_assets/icons/' + n + '.svg';
  const mask = (n, size, color) => '<div style="width:' + size + 'px;height:' + size + 'px;background-color:' + (color || 'currentColor') + ';'
    + "-webkit-mask:url('" + ic(n) + "') center / contain no-repeat;mask:url('" + ic(n) + "') center / contain no-repeat;\"></div>";

  const off = st === 'off' || st === 'unavailable' || st === 'unknown';
  const active = st === 'playing' || st === 'paused' || st === 'buffering';
  const stateMap = { playing: 'Wiedergabe', paused: 'Pausiert', buffering: 'Lädt', idle: 'Inaktiv', on: 'An', off: 'Aus', standby: 'Standby', unavailable: 'Nicht verfügbar', unknown: 'Unbekannt' };
  const stateTxt = stateMap[st] || st;

  const title  = active ? (a.media_title || a.app_name || a.source || stateTxt) : stateTxt;
  const artist = a.media_artist || a.media_album_artist || a.media_series_title || '';
  const subBits = [];
  if (active) {
    if (artist) subBits.push(artist);
    else if (a.media_album_name) subBits.push(a.media_album_name);
    if (a.app_name && a.app_name !== title) subBits.push(a.app_name);
    if (st === 'paused') subBits.push('Pausiert');
  } else if (!off && a.source) subBits.push(a.source);

  const pic = active ? (a.entity_picture_local || a.entity_picture) : null;
  const devIcon = { playstation: 'ps5' }[variables.icon] || variables.icon || 'media';

  let out = '<style>ha-card.disabled{pointer-events:auto!important;}'
    + '.hm-wrap{font-family:' + T.font + ';display:flex;flex-direction:column;align-items:center;text-align:center;}'
