    + '.hm-art::after{content:"";position:absolute;inset:0;border-radius:inherit;box-shadow:inset 0 0 0 1px rgba(255,255,255,.10);pointer-events:none;}'
    + '.hm-art img{width:100%;height:100%;object-fit:cover;display:block;}'
