    + '.hm-s{font-size:15px;color:' + T.ink2 + ';margin-top:3px;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-height:19px;}'
    + '.hm-prog{width:100%;margin-top:16px;}'
    + '.hm-track{height:5px;border-radius:999px;background:' + T.fill2 + ';overflow:hidden;}'
