  };

  const live = variables.src;
  const finish = (result) => {
    try { window._casoraNPSyncMobileRow?.(el, states); } catch (e) {}
    if (result && result.state === 'paused') {
      const until = Number(result.pauseUntil) || 0;
      const left = until ? (until - Date.now()) : 0;
      scheduleRecheck(until ? Math.min(30000, Math.max(1000, left + 150)) : 20000);
    }
    return result;
  };

  if (live) {
    store._npHoldSrc = live;
    store._npHoldAt = 0;
    return finish(live);
  }

  if (!store._npHoldSrc) return finish(null);
  if (!store._npHoldAt) store._npHoldAt = Date.now();
  const heldFor = Date.now() - store._npHoldAt;
  if (heldFor < 500) {
    scheduleRecheck(500 - heldFor);
    return finish(store._npHoldSrc);
  }
  store._npHoldSrc = null;
  return finish(null);
]]]

state.value:
[[[
  if (entity?.state === 'problem') return true;
  if (entity?.state === 'ok') return false;

  const sensors = Array.isArray(variables.sensors) ? variables.sensors.filter(Boolean) : [];
  if (sensors.length > 0) {
    const safeNum = (id) => {
      const s = states[id]?.state;
      if (!s || s === 'unavailable' || s === 'unknown') return null;
      const n = parseFloat(s);
      return isNaN(n) ? null : n;
    };
    const getSensorType = (eid) => {
      const id = eid.toLowerCase();
      if (id.includes('moisture'))                       return 'moisture';
      if (id.includes('illumin') || id.includes('lux')) return 'illuminance';
      if (id.includes('temp'))                           return 'temperature';
      if (id.includes('conductiv'))                      return 'conductivity';
      if (id.includes('humid'))                          return 'humidity';
      return null;
    };
    const attrs = entity?.attributes || {};
    const hasProblems = sensors.some(id => {
      if (safeNum(id) == null) return false;
      const type = getSensorType(id);
      if (!type) return false;
      const v = attrs[type + '_status'];
      return v && v !== 'ok' && v !== 'null';
    });
    if (hasProblems) return true;
  }

  const threshold = Number(variables.low_threshold ?? 30);
  const val = parseFloat(entity?.state);
  if (Number.isFinite(val)) return val <= threshold;
  const attr = parseFloat(entity?.attributes?.moisture);
  return Number.isFinite(attr) && attr <= threshold;
]]]

casora_plant.state_display:
[[[
  const fit = (t) => window.casoraStateFit?.(t) ?? t;

  /* Pflanzen-Wortlaut (03.10.2026) – wortgleich in casora_plant und casora_popup_plant:
     die Pflanze ist das Subjekt („Braucht Wasser“), wie in den Benachrichtigungen.
     Kachel und Popup sagen in jedem Fall dasselbe. Die Ursache kommt aus der Liste
     `problems` der Plant-Integration (als Liste oder als Text „[{'sensor_type': …}]“);
     `{typ}_status` nur, wenn die Liste fehlt – Licht/DLI stehen dort oft auf „Low“,
     obwohl die Integration sie gar nicht wertet. */
  const _PLANT_SAY = {
    'moisture:low': 'Braucht Wasser', 'moisture:high': 'Steht zu nass',
    'temperature:low': 'Steht zu kalt', 'temperature:high': 'Steht zu warm',
    'soil_temperature:low': 'Steht zu kalt', 'soil_temperature:high': 'Steht zu warm',
    'illuminance:low': 'Braucht mehr Licht', 'illuminance:high': 'Zu viel Sonne',
    'dli:low': 'Braucht mehr Licht', 'dli:high': 'Zu viel Sonne',
    'conductivity:low': 'Braucht Dünger', 'conductivity:high': 'Überdüngt',
    'humidity:low': 'Luft zu trocken', 'humidity:high': 'Luft zu feucht',
    'vpd:high': 'Luft zu trocken', 'vpd:low': 'Luft zu feucht',
  };
  /* Dringendes zuerst: Wasser, dann Kälte/Hitze, Licht, Nährstoffe, Luft. */
  const _PLANT_ORDER = ['moisture', 'temperature', 'soil_temperature', 'illuminance', 'dli', 'conductivity', 'humidity', 'vpd'];
  const _plantBad = (attrs) => {
    const out = {};
    let list = attrs.problems;
    if (typeof list === 'string') {
      const re = /'sensor_type':\s*'(\w+)'[^}]*?'status':\s*'(\w+)'/g;
      let m; list = [];
      while ((m = re.exec(attrs.problems))) list.push({ sensor_type: m[1], status: m[2] });
    }
    (Array.isArray(list) ? list : []).forEach(p => {
      if (p && p.sensor_type) out[p.sensor_type] = String(p.status || '').toLowerCase();
    });
    if (!Object.keys(out).length) _PLANT_ORDER.forEach(t => {
      const v = attrs[t + '_status'];
      if (v && v !== 'ok' && v !== 'null') out[t] = String(v).toLowerCase();
    });
    return out;
  };
  const _plantSay = (bad) => {
    for (const t of _PLANT_ORDER) { const s = _PLANT_SAY[t + ':' + bad[t]]; if (s) return s; }
    return null;
  };

  const st = entity?.state;
  if (!st || st === 'unavailable') return fit('Nicht verfügbar');
  if (st === 'ok') return fit('Fühlt sich wohl');
  if (st === 'problem') {
    const say = _plantSay(_plantBad(entity?.attributes || {}));
    if (say) return fit(say);
    // Eingetragene Messfühler, aber keiner liefert: das sagen statt raten.
    const sensors = Array.isArray(variables.sensors) ? variables.sensors.filter(Boolean) : [];
    const live = sensors.filter(id => { const s = states[id]?.state; return s && s !== 'unavailable' && s !== 'unknown'; });
    if (sensors.length && !live.length) return fit('Keine Messwerte');
    return fit('Bitte nachsehen');
  }

  // Ältere Einrichtungen: Bodenfeuchte-Sensor direkt als Kachel-Entität.
  const val = parseFloat(st);
  if (!Number.isNaN(val)) return fit(`${Math.round(val)} %`);
  const attr = parseFloat(entity?.attributes?.moisture);
  if (!Number.isNaN(attr)) return fit(`${Math.round(attr)} %`);
  return fit('Wartet auf Daten');
]]]

card.entity:
[[[
  /* Sparkline (1.2): Bodenfeuchte der letzten 7 Tage – eigener Sensor oder der des Pflanzengeräts. */
  if (!variables.sparkline) return '';
  const own = (Array.isArray(variables.sensors) ? variables.sensors : []).filter(Boolean);
  const reg = hass?.entities || {}, dev = reg[entity?.entity_id]?.device_id;
  const list = own.length ? own : Object.keys(reg).filter((id) => id.startsWith('sensor.') && dev && reg[id].device_id === dev);
  return list.find((id) => states[id]?.attributes?.device_class === 'moisture' || /moisture|bodenfeuchtigkeit/.test(id)) || '';
]]]

