tap_action.action:
[[[
  const dom = (entity?.entity_id || '').split('.')[0];
  if (dom === 'alarm_control_panel' || dom === 'binary_sensor')
    return window.casoraPopupAction ? window.casoraPopupAction() : 'more-info';
  /* Weich: ohne zugeordnetes Gerät das Popup mit „Noch kein Gerät zugeordnet“ statt der HA-Meldung „Keine Entität …“. */
  if (!dom && window._casoraSoft && window._casoraSoft() && window.casoraPopupAction) return window.casoraPopupAction();
  return 'more-info';
]]]

casora_popup.content:
[[[
  /* _casoraContacts */
  const _contacts = () => {
  const UI = window._casoraUI;
  if (!UI) return { type: 'vertical-stack', cards: [] };

  /* Türen/Fenster: eigene Gruppen + Kombi-Sensoren aus den Einstellungen, sonst nach Geräteklasse. */
  const _cc = window.casoraContacts ? window.casoraContacts(hass) : { groups: [], sub: {}, excl: [] };
  const GROUPS = _cc.groups;
  const _SUB = _cc.sub;
  const _EXCL = _cc.excl;
  /* Kontakt + Kippsensor ohne Kombi-Sensor: der Kippsensor meldet „gekippt“ (casoraContacts). */
  const _TILT = _cc.tilt || {};
  const _tilted = (id) => states[id]?.attributes?.tilt === true || (!!_TILT[id] && (states[_TILT[id]]?.state || '') === 'on');
  const _mem = (arr) => arr.filter((x) => !_EXCL.includes(x)).map((x) => _SUB[x] || x).filter((x, i, a) => a.indexOf(x) === i);

  const isOpen = (id) => {
    const s = (states[id]?.state || '').toLowerCase();
    return s === 'on' || s === 'open' || s === 'opening' || (!!_TILT[id] && (states[_TILT[id]]?.state || '') === 'on');
  };

  const allMembers = [];
  GROUPS.forEach((g) => {
    const mems = _mem(g.members || []);
    mems.forEach((id) => allMembers.push(id));
  });

  const openIds = allMembers.filter(isOpen);
  const oc = openIds.length, tot = allMembers.length;

  const tc = openIds.filter((id) => _tilted(id)).length;
  const value = oc === 0
    ? 'Alle geschlossen'
    : tc === oc
      ? tc + ' gekippt'
    : oc === tot
      ? 'Alle geöffnet'
      : oc + ' geöffnet';

  const ago = (iso) => {
    if (!iso) return null;
    const ms = Date.now() - new Date(iso).getTime();
    if (isNaN(ms) || ms < 0) return null;
    const m = ms/60000, h = m/60, d = h/24;
    if (m < 1) return 'gerade eben';
    if (m < 60) return 'vor ' + Math.floor(m) + (Math.floor(m)===1?' Minute':' Minuten');
    if (h < 24) return 'vor ' + Math.floor(h) + (Math.floor(h)===1?' Stunde':' Stunden');
    if (d < 7)  return 'vor ' + Math.floor(d) + (Math.floor(d)===1?' Tag':' Tagen');
    return 'vor ' + Math.floor(d/7) + 'w';
  };
  const newest = allMembers.map((id) => states[id]?.last_changed).filter(Boolean).sort().pop();

  const areas = [], fields = {}, fstyle = {};
  const add = (name, html) => {
    areas.push('"' + name + '"');
    fields[name] = html;
    /* overflow sichtbar: die Zelle ist so breit wie die Zeilen und schnitt deren weichen
       Schatten seitlich gerade ab – unten an den runden Ecken blieb ein eckiger Rest (05.10.2026). */
    fstyle[name] = [{ 'justify-self': 'stretch' }, { overflow: 'visible' }];
  };

  add('hero', UI.hero({
    value: value,
    sub: ago(newest),
    center: true,
    line: true,
    subTone: oc > 0 ? 'warn' : null,
  }));

  const areaOf = (id) => {
    const ent = hass?.entities?.[id];
    if (!ent) return null;
    const areaId = ent.area_id || (ent.device_id ? hass?.devices?.[ent.device_id]?.area_id : null);
    return areaId ? (hass?.areas?.[areaId]?.name || null) : null;
  };

  const rowFor = (id) => {
    const dc = String(states[id]?.attributes?.device_class || '').toLowerCase();
    const isWindow = dc === 'window';
    const open = isOpen(id);
    const rawName = states[id]?.attributes?.friendly_name || id;
    const area = areaOf(id);
    let label = area || rawName;
    let sub = null;
    /* Weich: Gerätename als Titel, Raum darunter – für jede Zeile, nicht nur bei mehreren Kontakten im Raum (Issue #1: „Flur“ statt „Haustür“). */
    if (UI.soft && UI.soft()) {
      const dev = hass?.devices?.[hass?.entities?.[id]?.device_id];
      const dn = String((dev && (dev.name_by_user || dev.name)) || rawName).trim()
        .replace(/^(kontaktsensor|kontakt|fenstersensor|t\u00fcrsensor|contact sensor|door sensor|window sensor)\s+/i, '')
        .replace(/\s+(contact|kontakt)$/i, '').trim();
      label = dn && dn !== area ? dn : rawName;
      sub = area && label !== area ? area : null;
    }
    return {
      entity: id,
      sub: sub,
      icon: isWindow ? (open ? 'window-open' : 'window-closed') : (open ? 'door-open' : 'door-closed'),
      iconTone: ((window._casoraSoft && window._casoraSoft()) && window.casoraSecurityLevel) ? window.casoraSecurityColor(window.casoraSecurityLevel(hass, [id])) : open ? 'warn' : null,
      label: label,
      value: open ? (_tilted(id) ? 'Gekippt' : 'Geöffnet') : 'Geschlossen',
      valueTone: open ? (((window._casoraSoft && window._casoraSoft()) && window.casoraSecurityLevel && window.casoraSecurityLevel(hass, [id]) === 'alarm') ? 'bad' : 'warn') : null,
      /* Weich: offenes Fenster/offene Tür als aktive Zeile (heller Grund) wie Pflanzen-/Batterie-Popup. */
      active: open,
    };
  };

  GROUPS.forEach((g, i) => {
    const mems = _mem(g.members || []);
    if (mems.length) add('grp' + i, UI.group(mems.map(rowFor), g.label));
  });

  const uiCard = {
    type: 'custom:button-card',
    card_mod: { style:
      '\n:host { --ha-card-backdrop-filter: none !important; --ha-card-background: transparent !important; --card-background-color: transparent !important; --ha-card-box-shadow: none !important; --ha-card-border-width: 0px !important; }'
      + '\nha-card::before, ha-card::after, #card::before, #card::after, #container::before, #container::after { display: none !important; }'
      + '\nha-card { will-change: auto !important; }'
      + '\n@media (max-width: 600px) { ha-card { padding-left: 14px !important; padding-right: 14px !important; } }'
      /* Weich: kein Kachelschatten der Inhaltskarte – er stand als zweite Platte im Popup. */
      + (UI.soft && UI.soft() ? '\n:host { --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; --button-card-box-shadow-active: none !important; } ha-card { box-shadow: none !important; }' : '')
    },
    tap_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    styles: {
      card: [
        { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
        { padding: 'var(--casora-soft-card-top, 6px) 26px 22px 26px' },
      ],
      grid: [
        { 'grid-template-areas': areas.join(' ') },
        { 'grid-template-columns': '1fr' },
        { 'row-gap': 'var(--casora-popup-sec-gap, 18px)' },
      ],
      custom_fields: fstyle,
    },
    custom_fields: fields,
  };
  return { type: 'vertical-stack', cards: [window._casoraStd ? window._casoraStd(uiCard, { top: ['hero', 'toggle'], center: ['toggle'], full: ['modes'] }) : uiCard] };
};
  const _alarm = () => {
  const UI = window._casoraUI;
  if (!UI) return { type: 'vertical-stack', cards: [] };
  const T2 = UI.tokens;

  const ent = variables.alarm_entity || (entity && entity?.entity_id) || 'alarm_control_panel.alarmo';
  /* Ohne Gerät und ohne vorhandene Alarmanlage leer lassen – Weich zeigt dann „Noch kein Gerät zugeordnet“. */
  if (!states[ent] && !entity?.entity_id) return { type: 'vertical-stack', cards: [] };
  const st = states[ent]?.state || 'unknown';
  const attrs = states[ent]?.attributes || {};

  const MODES = [
    { id: 'armed_home', label: 'Zuhause', description: 'Bewegungsmelder inaktiv', icon: 'shield_check' },
    { id: 'armed_away', label: 'Abwesend', description: 'Vollschutz aktiv', icon: 'shield_lock' },
    { id: 'armed_night', label: 'Nacht', description: 'Türen & Fenster überwacht', icon: 'shield_moon' },
    { id: 'armed_vacation', label: 'Urlaub', description: 'Vollschutz · Benachrichtigungen', icon: 'shield_vacation' },
    { id: 'armed_custom_bypass', label: 'Bypass', description: 'Einzelne Sensoren ausgenommen', icon: 'shield_bypass' },
  ];

  const STATE_LABEL = {
    disarmed: 'Deaktiviert',
    armed_home: 'Aktiviert · Zuhause',
    armed_away: 'Aktiviert · Abwesend',
    armed_night: 'Aktiviert · Nacht',
    armed_vacation: 'Aktiviert · Urlaub',
    armed_custom_bypass: 'Aktiviert · Bypass',
    triggered: 'Ausgelöst',
    arming: 'Scharfschaltung läuft',
    pending: 'Alarm läuft an',
    disarming: 'Wird unscharf geschaltet',
  };

  /* Weich: dieselben Wörter wie Kachel, Badge und Mitteilungen (casoraSecurityWord). */
  if ((window._casoraSoft && window._casoraSoft()) && window.casoraSecurityWord)
    Object.keys(STATE_LABEL).forEach((k) => { const w = window.casoraSecurityWord(ent, k); if (w) STATE_LABEL[k] = w; });
  const heroValue = STATE_LABEL[st] || 'Unbekannt';

  const openSensors = attrs.open_sensors ? Object.keys(attrs.open_sensors) : [];
  const heroSub = st === 'triggered'
    ? 'Alarm ausgelöst'
    : openSensors.length
      ? (openSensors.length === 1 ? '1 Sensor offen' : openSensors.length + ' Sensoren offen')
      : null;

  const areas = [], fields = {}, fstyle = {};
  const add = (name, html) => {
    areas.push('"' + name + '"');
    fields[name] = html;
    /* overflow sichtbar: die Zelle ist so breit wie die Zeilen und schnitt deren weichen
       Schatten seitlich gerade ab – unten an den runden Ecken blieb ein eckiger Rest (05.10.2026). */
    fstyle[name] = [{ 'justify-self': 'stretch' }, { overflow: 'visible' }];
  };

  const heroWords = JSON.stringify({ state: STATE_LABEL }).replace(/"/g, '&quot;');
  /* Weich: ausgelöst in der Gefahrenfarbe wie Badge und Mitteilung. */
  const heroSubColor = (st === 'triggered' && (window._casoraSoft && window._casoraSoft())) ? T2.red : (st === 'triggered' || openSensors.length) ? T2.amber : T2.ink2;
  /* Weich (01.10.2026): Unterzeile unter dem Ring-Kopf statt großer Zahl. */
  const _soft = !!(UI.soft && UI.soft());
  add('hero', '<div style="font-family:' + T2.font + ';text-align:center;padding:' + (_soft ? '0 4px 18px' : '2px 4px 18px') + ';">'
    + '<div data-casora-live="word" data-casora-ent="' + ent + '" data-casora-words="' + heroWords + '" '
    + 'style="' + (_soft ? 'font-size:19px;font-weight:700;' : 'font-size:36px;font-weight:400;') + 'letter-spacing:-0.01em;line-height:' + (_soft ? '1.25' : '1.08') + ';color:' + T2.ink + ';">'
    + heroValue + '</div>'
    + (heroSub ? '<div style="font-size:' + (_soft ? '15px;font-weight:500;margin-top:2px' : '16px;margin-top:6px') + ';color:' + heroSubColor + ';">' + heroSub + '</div>' : '')
    + '</div>');

  /* Quick on/off toggle: off -> arm_home, on -> disarm. The 5-mode
     list below covers picking a specific mode; this is the one-tap
     "is the house secured at all" control. */
  const isOn = st !== 'disarmed';
  const toggleSvc = isOn
    ? { domain: 'alarm_control_panel', service: 'alarm_disarm', data: { entity_id: ent } }
    : { domain: 'alarm_control_panel', service: 'alarm_arm_home', data: { entity_id: ent } };
  const svcAttr = JSON.stringify(toggleSvc).replace(/"/g, '&quot;');

  /* Every real alarm state maps to either the "on" or "off" side of
     the toggle, so the live patch (data-casora-live="prop") always has
     a value to apply instead of leaving a stale one behind. */
  const ON_STATES = ['armed_home','armed_away','armed_night','armed_vacation','armed_custom_bypass','triggered','arming','pending','disarming'];
  const trackMap = { state: { disarmed: 'rgba(255,255,255,0.16)' } };
  const knobPosMap = { state: { disarmed: '2px' } };
  const knobFillMap = { state: { disarmed: 'rgba(255,255,255,0.75)' } };
  const labelMap = { state: { disarmed: 'Aktivieren' } };
  ON_STATES.forEach((s) => {
    trackMap.state[s] = T2.accent;
    knobPosMap.state[s] = '20px';
    knobFillMap.state[s] = '#fff';
    labelMap.state[s] = 'Deaktivieren';
  });
  const attr = (o) => JSON.stringify(o).replace(/"/g, '&quot;');
  const trackFill = isOn ? T2.accent : 'rgba(255,255,255,0.16)';
  const toggleLabel = isOn ? 'Deaktivieren' : 'Aktivieren';
  const toggleHtml = '<div data-casora-svc="' + svcAttr + '" style="display:flex;align-items:center;justify-content:flex-end;'
    + 'gap:10px;padding:2px 4px 4px;font-family:' + T2.font + ';cursor:pointer;">'
    + '<div data-casora-live="word" data-casora-ent="' + ent + '" data-casora-words="' + attr(labelMap) + '" '
    + 'style="font-size:15px;font-weight:400;letter-spacing:-0.01em;color:' + T2.ink2 + ';">' + toggleLabel + '</div>'
    + '<div style="position:relative;width:46px;height:27px;border-radius:13.5px;flex:none;background:' + trackFill + ';"'
    + ' data-casora-live="prop" data-casora-ent="' + ent + '" data-casora-prop="background" data-casora-map="' + attr(trackMap) + '">'
    + '<div style="position:absolute;top:1.5px;left:' + (isOn ? '20px' : '2px') + ';width:24px;height:24px;border-radius:50%;'
    + 'background:' + (isOn ? '#fff' : 'rgba(255,255,255,0.75)') + ';transition:left .18s ease;"'
    + ' data-casora-live="prop" data-casora-ent="' + ent + '" data-casora-prop="left" data-casora-map="' + attr(knobPosMap) + '"></div>'
    + '</div>'
    + '</div>';
  /* Weich (01.10.2026): Schalter wie in den Licht-Zeilen, größer, in einer Sand-Pille. */
  if (UI.soft && UI.soft()) {
    /* Live als Vorlage: Dienst (Scharf/Unscharf), Text und Schalter folgen dem Zustand – auch ohne Neuöffnen. */
    add('toggle', '[[[ return window._casoraAlarmSoftToggle ? window._casoraAlarmSoftToggle(' + JSON.stringify(ent) + ', states) : ""; ]]]');
  } else
  add('toggle', toggleHtml);

  const armService = (id) => 'alarm_' + id.replace('armed_', 'arm_');
  const rows = MODES.map((m) => {
    const active = st === m.id;
    const words = { state: {} };
    MODES.forEach((mm) => { words.state[mm.id] = mm.id === m.id ? 'Aktiv' : ' '; });
    ['disarmed', 'triggered', 'arming', 'pending', 'disarming'].forEach((s) => { words.state[s] = ' '; });
    return {
      icon: active && !(window._casoraSoft && window._casoraSoft()) ? 'shield_check' : m.icon,
      /* Weich: nur der aktive Modus in der Stufenfarbe, die übrigen als Auswahl in Sand. */
      iconTone: active ? 'good' : ((window._casoraSoft && window._casoraSoft()) ? 'rgba(0,0,0,0)' : null),
      label: m.label,
      sub: m.description,
      value: active ? 'Aktiv' : ' ',
      valueTone: active ? 'good' : null,
      entity: ent,
      liveWords: words,
      // Always a real service call, even for the row that's already
      // active: re-arming the current mode is a harmless no-op, but it
      // keeps svc truthy so the row taps into the toggle (data-casora-svc)
      // instead of falling back to native more-info (which group() does
      // for any row that has an entity but no svc).
      svc: { domain: 'alarm_control_panel', service: armService(m.id), data: { entity_id: ent } },
    };
  });

  /* Weich (E3): kein „Aktiv“-Etikett – die aktive Zeile ist hinterlegt (live, 08-weich-kompakt.js). */
  if (UI.soft && UI.soft() && window._casoraSoftAlarm) {
    add('modes', '[[[ return window._casoraSoftAlarm ? window._casoraSoftAlarm(' + JSON.stringify(ent) + ', ' + JSON.stringify(MODES) + ', states) : ""; ]]]');
  } else
  add('modes', UI.group(rows, 'Modus'));

  const uiCard = {
    type: 'custom:button-card',
    triggers_update: [ent],
    card_mod: { style:
      '\n:host { --ha-card-backdrop-filter: none !important; --ha-card-background: transparent !important; --card-background-color: transparent !important; --ha-card-box-shadow: none !important; --ha-card-border-width: 0px !important; }'
      + '\nha-card::before, ha-card::after, #card::before, #card::after, #container::before, #container::after { display: none !important; }'
      + '\nha-card { will-change: auto !important; }'
      + '\n@media (max-width: 600px) { ha-card { padding-left: 14px !important; padding-right: 14px !important; } }'
      /* Weich: kein Kachelschatten der Inhaltskarte – er stand als zweite Platte im Popup. */
      + (UI.soft && UI.soft() ? '\n:host { --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; --button-card-box-shadow-active: none !important; } ha-card { box-shadow: none !important; }' : '')
    },
    tap_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    styles: {
      card: [
        { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
        { padding: 'var(--casora-soft-card-top, 6px) 26px 22px 26px' },
      ],
      grid: [
        { 'grid-template-areas': areas.join(' ') },
        { 'grid-template-columns': '1fr' },
        { 'row-gap': 'var(--casora-popup-sec-gap, 18px)' },
      ],
      custom_fields: fstyle,
    },
    custom_fields: fields,
  };
  return { type: 'vertical-stack', cards: [window._casoraStd ? window._casoraStd(uiCard, { top: ['hero', 'toggle'], center: ['toggle'], full: ['modes'] }) : uiCard] };
};
  return (entity?.entity_id || '').startsWith('binary_sensor.') ? _contacts() : _alarm();
]]]

popup_styles.styles:
/* Popup content cards are not buttons: the theme's hover lift (shadow + brightness) made a
   whole column look like a raised card under the pointer (Weich audit M1). Killed popup-wide. */
--casora-card-hover-filter: none;
--casora-hover-filter: none;
--casora-card-hover-shadow: none;
/* The pane stays - these are control sheets. Only the close control
   keeps what it gained: a surface of its own, and room above it so
   the fill is not against the top edge of the sheet. */
.header { padding-top: var(--casora-popup-header-gap, 10px); }
/* Equal inset on both axes: the bar's own padding plus the
   close control's 2px optical nudge has to come to the same
   number as the padding above it, or the circle sits further
   from the left edge than it does from the top. */
--casora-popup-header-gap: 14px;
  --casora-popup-gutter-wide: 20px;
/* The chrome arrives with the first plate instead of being there
   on frame one while everything under it fades in. */
--casora-popup-chrome-enter:
  casora-popup-chrome-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
.header-title { font-size: 20px; font-weight: 600; letter-spacing: -0.01em; }
.header-close {
  border-radius: 50%;
  background: var(--casora-popup-row-fill, rgba(255, 255, 255, 0.10));
  backdrop-filter: var(--casora-popup-plate-backdrop, blur(24px) saturate(180%));
  -webkit-backdrop-filter: var(--casora-popup-plate-backdrop, blur(24px) saturate(180%));
  box-shadow: var(--casora-popup-plate-shadow, none);
}
/* The sheet is full height, so short content floats mid-screen. On
   a phone the card has to fill it for the grid's `1fr` row to have
   any slack to hand the toggle - otherwise the rows bunch under it
   instead of sitting at the bottom.
   Flex, not percentages: .content is `flex: 1 1 auto` inside a
   surface with only a max-height, so `min-height: 100%` here had no
   definite height to resolve against and computed to nothing. A
   flex chain gives every link a real height without one. */
@media (max-width: 768px) {
  /* The root cause, and why two attempts at the chain below did
     nothing: .surface is capped with max-height, never given one.
     A flex item in a content-sized container is itself
     content-sized, so every percentage under it resolved to
     nothing and the grid's `1fr` row had no slack to hand out.
     Same expression as its own max-height, as a height. */
  .surface {
    height: calc(100svh - var(--casora-popup-top, 112px) - 8px
                 - var(--safe-area-inset-bottom, 0px));
  }
  .content { display: flex; flex-direction: column; }
  /* A viewport unit, not a percentage. Every attempt to make this
     work by giving each link a definite height failed in the real
     DOM even though the chain measures correct in isolation - so
     the height is taken from the viewport directly and nothing has
     to resolve against a parent at all. 112 is the surface's top
     offset, 58 the header row, 8 the bottom gap. */
  .content .container {
    flex: 1 1 auto;
    min-height: calc(100svh - var(--casora-popup-top, 112px)
                     - 58px - 8px
                     - var(--safe-area-inset-bottom, 0px));
    display: flex; flex-direction: column; box-sizing: border-box;
  }
  /* The direct child AND anything HA wraps the card in: measured in
     isolation this chain resolves and the tiles land 8px off the
     bottom, so the only way it can still fail is a link in the real
     DOM that this does not name. */
  .content .container > *,
  .content .container hui-card,
  .content .container > * > * {
    flex: 1 1 auto; min-height: 0;
    display: flex; flex-direction: column;
  }
}
/* One measure for a control-plus-list popup, whatever the count.
   The rows are short and a wider sheet only stretches them; cover
   is the same shape and holds the same width. */
--popup-min-width: 900px;
--popup-max-width: 920px;

casora_popup.title:
[[[
  /* Eigener Popup-Titel der Kachel (room_name) zuerst, sonst wie bisher. */
  const _own = window.casoraPopupTitle ? window.casoraPopupTitle(null, variables, '', [])
    : (() => { const r = String(variables.room_name || '').trim(); return r.startsWith('[[[') ? '' : r; })();
  if (_own) return _own;
  if ((entity?.entity_id || '').startsWith('binary_sensor.')) return "Türen & Fenster";
  const _t = () => {return "Sicherheit";};
  return _t();
]]]

