casora_popup.content:
[[[
  const iconOverrides = variables.device_icons || {};
  const nameOverrides = variables.device_names || {};
  const pairs = variables.battery_entities || {};

  const primaryOf = {};
  Object.keys(pairs).forEach(primary => {
    if (pairs[primary]) primaryOf[pairs[primary]] = primary;
  });

  const filterList = ((l) => (Array.isArray(l) && l.some((id) => states[id]?.attributes?.device_class === 'battery') ? l : null))(variables.batteries || variables.entity_filter)
    || (Object.keys(pairs).length ? Object.keys(pairs).map(k => pairs[k]) : null);

  const allBatteries = (filterList
      ? filterList.map(id => states[id]).filter(Boolean)
      : Object.values(states)
    )
    .map(e => ({
      ...e,
      battery_pct: parseFloat(e.state)
    }))
    .filter(e => {
      if (e.state === 'unavailable' || e.state === 'unknown') return false;
      if (isNaN(e.battery_pct)) return false;

      return e.attributes.device_class === 'battery';
    })
    .sort((a, b) => a.battery_pct - b.battery_pct);

  const batteryEntityIds = allBatteries.map(e => e.entity_id);

  const reg = (hass && hass.entities) || {};
  const devReg = (hass && hass.devices) || {};

  const siblingsOf = {};
  Object.keys(reg).forEach(id => {
    const dev = reg[id] && reg[id].device_id;
    if (!dev) return;
    (siblingsOf[dev] = siblingsOf[dev] || []).push(id);
  });

  const STRONG_DOMAINS = ['lock', 'cover', 'vacuum', 'camera', 'climate', 'fan', 'light', 'media_player', 'humidifier', 'valve', 'lawn_mower', 'water_heater'];

  const ICON_DOMAIN = {
    lock: 'lock',
    vacuum: 'vacuum',
    camera: 'camera|mdi:cctv',
    light: 'light',
    fan: 'fan',
    media_player: 'speaker',
    climate: 'thermostat',
    humidifier: 'humidifier',
    water_heater: 'hot_water',
    person: 'person',
    valve: 'valve|mdi:valve',
    lawn_mower: 'mower|mdi:robot-mower',
    remote: 'remote|mdi:remote',
    switch: 'plug',
    device_tracker: 'phone|mdi:cellphone',
  };

  const ICON_COVER_CLASS = {
    curtain: 'curtain-closed',
    blind: 'curtain-closed',
    shade: 'curtain-closed',
    shutter: 'curtain-closed',
    awning: 'curtain-closed',
    door: 'door-closed',
    garage: 'garage|mdi:garage',
    gate: 'gate|mdi:gate',
    window: 'window|mdi:window-closed-variant',
  };

  const ICON_BINARY_CLASS = {
    motion: 'motion',
    occupancy: 'motion',
    presence: 'person',
    door: 'door-closed',
    opening: 'door-closed',
    window: 'window|mdi:window-closed-variant',
    garage_door: 'garage|mdi:garage',
    moisture: 'leak|mdi:water-alert',
    smoke: 'smoke|mdi:smoke-detector',
    gas: 'gas',
    vibration: 'vibration|mdi:vibrate',
    sound: 'sound|mdi:ear-hearing',
  };

  const TEXT_RULES = [
    ['iphone|pixel|galaxy|oneplus|phone', 'phone|mdi:cellphone'],
    ['ipad|tablet', 'tablet|mdi:tablet'],
    ['watch', 'watch|mdi:watch'],
    ['macbook|laptop|imac|mac ?(mini|studio|pro)', 'laptop|mdi:laptop'],
    ['airpod|headphone|earbud|buds', 'headphones|mdi:headphones'],
    ['keypad', 'keypad|mdi:dialpad'],
    ['doorbell|chime', 'doorbell'],
    ['lock|deadbolt', 'lock'],
    ['curtain|blind|shade|shutter', 'curtain-closed'],
    ['vacuum|roomba|robot', 'vacuum'],
    ['camera|cam\\b', 'camera|mdi:cctv'],
    ['motion|presence|occupancy|pir', 'motion'],
    ['thermostat|radiator|trv|climate', 'thermostat'],
    ['speaker|sonos|homepod|echo', 'speaker'],
    ['remote', 'remote|mdi:remote'],
    ['plant|soil', 'plant'],
    ['leak|moisture|water', 'leak|mdi:water-alert'],
    ['smoke|fire', 'smoke|mdi:smoke-detector'],
    ['door|contact', 'door-closed'],
    ['window', 'window|mdi:window-closed-variant'],
    ['light|lamp|bulb', 'light'],
    ['plug|outlet|socket', 'plug'],
    ['temperature|thermo', 'temp-medium'],
    ['motion|sensor', 'motion'],
  ];

  const pickIcon = spec => {
    if (!spec || spec.indexOf('|') === -1) return spec;
    const parts = spec.split('|');
    const set = window.CASORA_ICONS;
    return (set && set[parts[0]]) ? parts[0] : parts[1];
  };

  const iconFromText = text => {
    if (!text) return null;
    const hay = String(text).toLowerCase();
    for (let i = 0; i < TEXT_RULES.length; i++) {
      if (new RegExp(TEXT_RULES[i][0]).test(hay)) return TEXT_RULES[i][1];
    }
    return null;
  };

  const iconFromEntity = id => {
    if (!id) return null;
    const domain = id.split('.')[0];
    const st = states[id];
    const cls = st && st.attributes ? st.attributes.device_class : null;

    if (domain === 'cover') return ICON_COVER_CLASS[cls] || 'curtain-closed';
    if (domain === 'binary_sensor') return ICON_BINARY_CLASS[cls] || null;
    return ICON_DOMAIN[domain] || null;
  };

  const resolveDevice = batteryId => {
    const explicitPrimary = primaryOf[batteryId] || null;
    const devId = (reg[batteryId] && reg[batteryId].device_id)
      || (explicitPrimary && reg[explicitPrimary] && reg[explicitPrimary].device_id)
      || null;
    const dev = devId ? devReg[devId] : null;
    const siblings = devId ? (siblingsOf[devId] || []) : [];

    const primary = explicitPrimary
      || siblings.find(id => STRONG_DOMAINS.indexOf(id.split('.')[0]) !== -1)
      || null;

    let icon = iconOverrides[batteryId]
      || (explicitPrimary ? iconOverrides[explicitPrimary] : null)
      || null;

    if (!icon && primary) icon = iconFromEntity(primary);
    if (!icon && dev) icon = iconFromText(dev.model) || iconFromText(dev.name_by_user || dev.name);
    if (!icon) {
      icon = siblings
        .map(id => iconFromEntity(id))
        .find(Boolean) || null;
    }
    if (!icon) {
      const bs = states[batteryId];
      icon = iconFromText(bs && bs.attributes ? bs.attributes.friendly_name : null)
        || iconFromText(batteryId);
    }
    if (!icon && primary) {
      const ps = states[primary];
      if (ps && ps.attributes && ps.attributes.icon) icon = ps.attributes.icon;
    }
    if (!icon) icon = 'battery';

    if (icon.indexOf('camera') === 0 && dev
      && /doorbell/i.test((dev.model || '') + ' ' + (dev.name_by_user || dev.name || ''))) {
      icon = 'doorbell';
    }

    icon = pickIcon(icon);

    const bs = states[batteryId];
    const rawName = (bs && bs.attributes && bs.attributes.friendly_name) || batteryId;
    let name = nameOverrides[batteryId]
      || (explicitPrimary ? nameOverrides[explicitPrimary] : null)
      || (dev ? (dev.name_by_user || dev.name) : null);

    if (!name && primary) {
      const ps = states[primary];
      name = ps && ps.attributes ? ps.attributes.friendly_name : null;
    }
    if (!name) name = rawName.replace(/\s*Battery(\s+(Level|State|Percentage))?$/i, '');

    const chargeIds = siblings.filter(id => {
      if (id.indexOf('binary_sensor.') === 0) return /_charging$/.test(id);
      if (id.indexOf('sensor.') === 0) return /_battery_state$/.test(id);
      return id.indexOf('vacuum.') === 0;
    });

    return { icon: icon, name: name, charge_ids: chargeIds };
  };

  const deviceInfo = {};
  batteryEntityIds.forEach(id => { deviceInfo[id] = resolveDevice(id); });

  /* Weich (E3, 01.10.2026): Ring-Unterzeile, „Bald wechseln“, alle Geräte zweispaltig,
     Diagramm erst nach Antippen einer Zeile – window._casoraSoftBat in 08-weich-kompakt.js. */
  if (window._casoraSoft && window._casoraSoft() && window._casoraSoftBat) {
    const _sb = window._casoraSoftBat.build({ states: states, hass: hass, batteries: allBatteries
      .filter((e) => filterList || !/iphone|ipad|\bwatch\b|ebike|e-bike|drive_unit|performance_line/i.test(e.entity_id + ' ' + (e.attributes.friendly_name || '')))
      .map((e) => ({ id: e.entity_id, name: (deviceInfo[e.entity_id] || {}).name || e.entity_id,
        icon: (deviceInfo[e.entity_id] || {}).icon, charge: (deviceInfo[e.entity_id] || {}).charge_ids })) });
    if (_sb) return { type: 'vertical-stack', cards: [_sb] };
  }

  const cleanCardStyle = `
    :host {
      --ha-card-box-shadow:none !important;
      --button-card-box-shadow:none !important;
      --button-card-box-shadow-hover:none !important;
    }

    ha-card::before,
    ha-card::after,
    #card::before,
    #card::after,
    #container::before,
    #container::after {
      display:none !important;
    }

    ha-ripple {
      display:none !important;
    }

    ha-card {
      cursor: default !important;
    }

    @media (max-width:600px) {
      ha-card {
        padding-left:14px !important;
        padding-right:14px !important;
      }
    }
  `;

  const roomName = variables.room_name ?? 'Geräte';

  const baseCardStyle = [
    { '--ha-card-box-shadow': 'none' },
    { '--button-card-box-shadow': 'none' },
    { '--button-card-box-shadow-hover': 'none' },
    { background: 'transparent' },
    { border: 'none' },
    { boxShadow: 'none' },
    { backdropFilter: 'none' },
    { WebkitBackdropFilter: 'none' },
  ];


  /* No hero: the subject is the list, not any one number. Sectioned by
     state the way Settings does, so "is anything low" reads without a
     summary stat above it. */
  const UI = window._casoraUI;
  if (UI) {
    if (!allBatteries.length) {
      return { type: 'vertical-stack', cards: [{
        type: 'custom:button-card',
        tap_action: { action: 'none' },
        show_icon: false, show_name: false, show_label: false, show_state: false,
        card_mod: { style: cleanCardStyle
          + '\nha-card { will-change: auto !important; }' },
        styles: {
          card: [...baseCardStyle, { padding: 'var(--casora-soft-card-top, 6px) 26px 22px 26px' }],
          grid: [{ 'grid-template-areas': '"empty"' }, { 'grid-template-columns': '1fr' }],
          custom_fields: { empty: [{ 'justify-self': 'stretch' }] },
        },
        custom_fields: { empty: UI.note('Keine Batteriesensoren gefunden') },
      }] };
    }
    const pctOf = (e) => Math.round(e.battery_pct);
    const toneOf = (v) => v <= 10 ? 'bad' : v <= 20 ? 'warn' : null;
    const rowOf = (e) => {
      const info = deviceInfo[e.entity_id] || {};
      const v = pctOf(e);
      /* "Not Charging" and "Discharging" both contain "charg", so this
         matches exact states only. */
      const charging = (info.charge_ids || []).some(id => {
        const st = states[id];
        if (!st) return false;
        const v = String(st.state || '').trim().toLowerCase();
        if (id.startsWith('binary_sensor.')) return v === 'on';
        return v === 'charging';
      });
      return {
        entity: e.entity_id,
        icon: info.icon || 'battery',
        /* No tone override: the icon tile carries the device's own tile
           color so a row reads the same here as on the dashboard. The
           low-battery warning is on the percentage and the section. */
        label: info.name || e.entity_id,
        sub: charging ? 'Lädt' : null,
        value: v + '%',
        valueTone: charging ? 'good' : toneOf(v),
      };
    };

    const low  = allBatteries.filter(e => pctOf(e) <= (window.casoraBattery ? window.casoraBattery.LOW : 20));
    const rest = allBatteries.filter(e => pctOf(e) > (window.casoraBattery ? window.casoraBattery.LOW : 20));

    const areas = [];
    const fields = {};
    const fstyle = {};
    const add = (name, html) => {
      areas.push('"' + name + '"');
      fields[name] = html;
      fstyle[name] = [{ 'justify-self': 'stretch' }];
    };

    // The main list is never captioned; only the aside names itself.
    if (rest.length) {
      add('rest', UI.group(rest.map(rowOf), null, null,
        { labelInside: true }));
    }
    if (low.length) {
      add('low', UI.group(low.map(rowOf), 'Akku schwach', null,
        { labelInside: true }));
    }

    /* The main list holds its solo width and the attention column is
       added beside it, widening the surface: a low battery must not
       reflow the list it is not in. */
    const split = areas.length === 2;
    const splitAreas = split
      ? '"' + areas.map((a) => a.replace(/"/g, '')).join(' ') + '"'
      : areas.join(' ');
    areas.forEach((a, i) => {
      const key = a.replace(/"/g, '');
      if (fstyle[key]) {
        fstyle[key].push({ overflow: 'visible' });
        fstyle[key].push({ '--casora-popup-plate-delay': (i * 55) + 'ms' });
      }
    });

    const listCard = {
      type: 'custom:button-card',
      tap_action: { action: 'none' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      card_mod: { style: cleanCardStyle
        + '\nha-card { will-change: auto !important; }' },
      styles: {
        card: [...baseCardStyle, { padding: '2px 26px 22px 26px' },
               /* Only the split layout needs the full surface. Centered
                  when there is one column, so it sits under the title
                  rather than off to one side of it. */
               { 'max-width': 'none' }, { margin: '0' }],
        grid: [
          { 'grid-template-areas': splitAreas },
          { 'grid-template-columns': split
              ? 'minmax(0, 1fr) 300px' : 'minmax(0, 1fr)' },
          { 'row-gap': 'var(--casora-popup-sec-gap, 18px)' },
          { 'column-gap': 'var(--casora-popup-col-gap, 18px)' },
          // Or the shorter list is stretched to match the taller one.
          { 'align-items': 'start' },
        ],
        custom_fields: fstyle,
      },
      custom_fields: fields,
      /* One column below the width the surface needs for both, so the
         main list is squeezed rather than stacked. Attention goes on
         top there. extra_styles rather than card_mod, which lands late
         enough to reflow visibly. */
      extra_styles: split
        ? '@media (max-width: 940px) { #container {'
          + ' grid-template-areas: ' + [...areas].reverse().join(' ') + ' !important;'
          + ' grid-template-columns: minmax(0, 1fr) !important; } }'
        : undefined,
    };
    return { type: 'vertical-stack', cards: [listCard] };
  }

  return { type: 'vertical-stack', cards: [] };
]]]

popup_styles.styles:
/* Eine Popup-Familie (01.10.2026): dieselbe Sheet-Fläche wie die Bedien-Popups –
   Fläche, Blur, Schatten und Abdunklung aus dem Standard, Höhe folgt dem Inhalt,
   Schließen-Kreuz mit demselben Abstand zur Sheet-Kante. */
.header { padding-top: var(--casora-popup-header-gap, 10px); }
--casora-popup-header-gap: 14px;
/* No chart here, so nothing to wait for. Read by each widget for
   itself, never by a wrapper - an animated opacity on an ancestor
   flattens the frost inside it. */
--casora-popup-plate-enter:
  casora-plate-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
@media (prefers-reduced-motion: reduce) {
  --casora-popup-plate-enter: none;
}

/* The surface is sized from the content by the style template
   below: two columns need the full measure, one does not, and a
   narrow card centered in a wide surface put the plate's edge 80px
   to the right of the close control. */

--casora-popup-hero-label-size: 15px;
--casora-popup-row-radius: 26px;
/* Frosted, not opaque. The pane's blur used to sit under these, and
   .content still nulls --ha-card-backdrop-filter for every card in
   the popup, so the frost has to be asked for here. The fills drop
   to let it read. */
/* The theme lifts every ha-card with filter: brightness(1.01) on
   hover. A filter on an ancestor makes every descendant's
   backdrop-filter inert, so hovering the empty space around a
   widget - the wrapper card - knocked the frost out of both of
   them. Killed popup-wide; the plate re-declares its own shadow. */
--casora-card-hover-filter: none;
--casora-hover-filter: none;
--casora-card-hover-shadow: none;

--casora-popup-row-pad-x: 26px;
--casora-popup-row-pad-y: 15px;
--casora-popup-plate-backdrop: blur(24px) saturate(180%);
--casora-popup-chart-fill: var(--casora-sheet-chart-fill, rgba(10, 12, 16, 0.68));
--casora-popup-row-fill: var(--casora-sheet-row-fill, rgba(12, 14, 19, 0.62));
/* Lifted, not slabbed: one wide soft pass carries the height, one
   short contact pass keeps the edge from dissolving into the room. */
--casora-popup-plate-shadow: var(--casora-sheet-plate-shadow,
  0 18px 40px -22px rgba(0, 0, 0, 0.50),
  0 2px 8px -5px rgba(0, 0, 0, 0.28));

/* visionOS puts nothing bare on the room: the only chrome outside a
   window is its close control, and that control is itself a glass
   object. The title was printed twice - here and in the widget
   eight pixels below - so it goes, clipped rather than removed so a
   screen reader still gets it. */

/* The chrome arrives with the first plate instead of being there
   on frame one while everything under it fades in. */
--casora-popup-chrome-enter:
  casora-popup-chrome-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
.content { animation: none; }
/* The title lives in the bar now, centered and level with the
   close control, so it is no longer hidden. */
.header-title { font-size: 20px; font-weight: 600; letter-spacing: -0.01em; }
/* 48px is left alone: the base sizes it so the glyph's ink lands on
   the same left margin as the widgets below. */
.header-close {
  border-radius: 50%;
  background: var(--casora-popup-row-fill, rgba(255, 255, 255, 0.10));
  backdrop-filter: var(--casora-popup-plate-backdrop, none);
  -webkit-backdrop-filter: var(--casora-popup-plate-backdrop, none);
  box-shadow: var(--casora-popup-plate-shadow, none);
}

ha-adaptive-dialog, ha-dialog, wa-drawer {
  --ha-card-backdrop-filter: none;
  --ha-card-background: transparent;
  --card-background-color: transparent;
  --ha-card-box-shadow: none;
  --ha-card-border-width: 0px;
}

/* Popup-Standard (24.09.2026): Info-Popup - Abschnittsüberschriften in der Karte. */
--casora-lbl-in: block;
--casora-lbl-out: none;

casora_popup.style:
[[[
  /* 500 for the main list plus the card's own 26px gutters. The
     attention column adds 318 on top; the main list never resizes. */
  /* Genau dieselbe Auswahl wie die Liste unten (Hemma 2.2.0, MIT): battery_entities ist ein Objekt
     (Gerät → Akku), kein Array – vorher zählte die Breite alle Akkus im Haus statt der gezeigten. */
  const _pairs = variables.battery_entities || {};
  const _filter = ((l) => (Array.isArray(l) && l.some((id) => states[id]?.attributes?.device_class === 'battery') ? l : null))(variables.batteries || variables.entity_filter)
    || (Object.keys(_pairs).length ? Object.keys(_pairs).map(k => _pairs[k]) : null);
  const _b = (_filter ? _filter.map(id => states[id]).filter(Boolean) : Object.values(states))
    .filter(e => e.state !== 'unavailable' && e.state !== 'unknown'
      && !isNaN(parseFloat(e.state)) && e.attributes?.device_class === 'battery');
  const _lo = _b.filter(e => Math.round(parseFloat(e.state)) <= 20).length;
  const _w = (_lo > 0 && _b.length > _lo) ? 870 : 552;
  return '--popup-min-width: min(' + _w + 'px, 92vw);'
       + ' --popup-max-width: min(' + _w + 'px, 92vw);';
]]]

casora_popup.content:
[[[
  const iconOverrides = variables.device_icons || {};
  const nameOverrides = variables.device_names || {};
  const pairs = variables.battery_entities || {};

  const primaryOf = {};
  Object.keys(pairs).forEach(primary => {
    if (pairs[primary]) primaryOf[pairs[primary]] = primary;
  });

  const filterList = ((l) => (Array.isArray(l) && l.some((id) => states[id]?.attributes?.device_class === 'battery') ? l : null))(variables.batteries || variables.entity_filter)
    || (Object.keys(pairs).length ? Object.keys(pairs).map(k => pairs[k]) : null);

  const PERSONAL_DEVICE_RE = /iphone|ipad|\bwatch\b|ebike|e-bike|drive_unit|performance_line/i;
  const EXCLUDED_IDS = new Set([window.casoraDevice && window.casoraDevice.byKey(hass, 'anker_solix', 'state_of_charge', 'sensor')].filter(Boolean));
  const allBatteries = (filterList
      ? filterList.map(id => states[id]).filter(Boolean)
      : Object.values(states).filter(e => !EXCLUDED_IDS.has(e.entity_id) && !PERSONAL_DEVICE_RE.test(
          e.entity_id + ' ' + (e.attributes.friendly_name || '')
        ))
    )
    .map(e => ({
      ...e,
      battery_pct: parseFloat(e.state)
    }))
    .filter(e => {
      if (e.state === 'unavailable' || e.state === 'unknown') return false;
      if (isNaN(e.battery_pct)) return false;

      return e.attributes.device_class === 'battery';
    })
    .sort((a, b) => a.battery_pct - b.battery_pct);

  const batteryEntityIds = allBatteries.map(e => e.entity_id);

  const reg = (hass && hass.entities) || {};
  const devReg = (hass && hass.devices) || {};

  const siblingsOf = {};
  Object.keys(reg).forEach(id => {
    const dev = reg[id] && reg[id].device_id;
    if (!dev) return;
    (siblingsOf[dev] = siblingsOf[dev] || []).push(id);
  });

  const STRONG_DOMAINS = ['lock', 'cover', 'vacuum', 'camera', 'climate', 'fan', 'light', 'media_player', 'humidifier', 'valve', 'lawn_mower', 'water_heater'];

  const ICON_DOMAIN = {
    lock: 'lock',
    vacuum: 'vacuum',
    camera: 'camera|mdi:cctv',
    light: 'light',
    fan: 'fan',
    media_player: 'speaker',
    climate: 'thermostat',
    humidifier: 'humidifier',
    water_heater: 'hot_water',
    person: 'person',
    valve: 'valve|mdi:valve',
    lawn_mower: 'mower|mdi:robot-mower',
    remote: 'remote|mdi:remote',
    switch: 'plug',
    device_tracker: 'phone|mdi:cellphone',
  };

  const ICON_COVER_CLASS = {
    curtain: 'curtain-closed',
    blind: 'curtain-closed',
    shade: 'curtain-closed',
    shutter: 'curtain-closed',
    awning: 'curtain-closed',
    door: 'door-closed',
    garage: 'garage|mdi:garage',
    gate: 'gate|mdi:gate',
    window: 'window|mdi:window-closed-variant',
  };

  const ICON_BINARY_CLASS = {
    motion: 'motion',
    occupancy: 'motion',
    presence: 'person',
    door: 'door-closed',
    opening: 'door-closed',
    window: 'window|mdi:window-closed-variant',
    garage_door: 'garage|mdi:garage',
    moisture: 'leak|mdi:water-alert',
    smoke: 'smoke|mdi:smoke-detector',
    gas: 'gas',
    vibration: 'vibration|mdi:vibrate',
    sound: 'sound|mdi:ear-hearing',
  };

  const TEXT_RULES = [
    ['iphone|pixel|galaxy|oneplus|phone', 'phone|mdi:cellphone'],
    ['ipad|tablet', 'tablet|mdi:tablet'],
    ['watch', 'watch|mdi:watch'],
    ['macbook|laptop|imac|mac ?(mini|studio|pro)', 'laptop|mdi:laptop'],
    ['airpod|headphone|earbud|buds', 'headphones|mdi:headphones'],
    ['keypad', 'keypad|mdi:dialpad'],
    ['doorbell|chime', 'doorbell'],
    ['lock|deadbolt', 'lock'],
    ['curtain|blind|shade|shutter', 'curtain-closed'],
    ['vacuum|roomba|robot', 'vacuum'],
    ['camera|cam\\b', 'camera|mdi:cctv'],
    ['motion|presence|occupancy|pir', 'motion'],
    ['thermostat|radiator|trv|climate', 'thermostat'],
    ['speaker|sonos|homepod|echo', 'speaker'],
    ['remote', 'remote|mdi:remote'],
    ['plant|soil', 'plant'],
    ['leak|moisture|water', 'leak|mdi:water-alert'],
    ['smoke|fire', 'smoke|mdi:smoke-detector'],
    ['door|contact', 'door-closed'],
    ['window', 'window|mdi:window-closed-variant'],
    ['light|lamp|bulb', 'light'],
    ['plug|outlet|socket', 'plug'],
    ['temperature|thermo', 'temp-medium'],
    ['motion|sensor', 'motion'],
  ];

  const pickIcon = spec => {
    if (!spec || spec.indexOf('|') === -1) return spec;
    const parts = spec.split('|');
    const set = window.CASORA_ICONS;
    return (set && set[parts[0]]) ? parts[0] : parts[1];
  };

  const iconFromText = text => {
    if (!text) return null;
    const hay = String(text).toLowerCase();
    for (let i = 0; i < TEXT_RULES.length; i++) {
      if (new RegExp(TEXT_RULES[i][0]).test(hay)) return TEXT_RULES[i][1];
    }
    return null;
  };

  const iconFromEntity = id => {
    if (!id) return null;
    const domain = id.split('.')[0];
    const st = states[id];
    const cls = st && st.attributes ? st.attributes.device_class : null;

    if (domain === 'cover') return ICON_COVER_CLASS[cls] || 'curtain-closed';
    if (domain === 'binary_sensor') return ICON_BINARY_CLASS[cls] || null;
    return ICON_DOMAIN[domain] || null;
  };

  const resolveDevice = batteryId => {
    const explicitPrimary = primaryOf[batteryId] || null;
    const devId = (reg[batteryId] && reg[batteryId].device_id)
      || (explicitPrimary && reg[explicitPrimary] && reg[explicitPrimary].device_id)
      || null;
    const dev = devId ? devReg[devId] : null;
    const siblings = devId ? (siblingsOf[devId] || []) : [];

    const primary = explicitPrimary
      || siblings.find(id => STRONG_DOMAINS.indexOf(id.split('.')[0]) !== -1)
      || null;

    let icon = iconOverrides[batteryId]
      || (explicitPrimary ? iconOverrides[explicitPrimary] : null)
      || null;

    if (!icon && primary) icon = iconFromEntity(primary);
    if (!icon && dev) icon = iconFromText(dev.model) || iconFromText(dev.name_by_user || dev.name);
    if (!icon) {
      icon = siblings
        .map(id => iconFromEntity(id))
        .find(Boolean) || null;
    }
    if (!icon) {
      const bs = states[batteryId];
      icon = iconFromText(bs && bs.attributes ? bs.attributes.friendly_name : null)
        || iconFromText(batteryId);
    }
    if (!icon && primary) {
      const ps = states[primary];
      if (ps && ps.attributes && ps.attributes.icon) icon = ps.attributes.icon;
    }
    if (!icon) icon = 'battery';

    if (icon.indexOf('camera') === 0 && dev
      && /doorbell/i.test((dev.model || '') + ' ' + (dev.name_by_user || dev.name || ''))) {
      icon = 'doorbell';
    }

    icon = pickIcon(icon);

    const bs = states[batteryId];
    const rawName = (bs && bs.attributes && bs.attributes.friendly_name) || batteryId;
    let name = nameOverrides[batteryId]
      || (explicitPrimary ? nameOverrides[explicitPrimary] : null)
      || (dev ? (dev.name_by_user || dev.name) : null);

    if (!name && primary) {
      const ps = states[primary];
      name = ps && ps.attributes ? ps.attributes.friendly_name : null;
    }
    if (!name) name = rawName.replace(/\s*Battery(\s+(Level|State|Percentage))?$/i, '');

    const chargeIds = siblings.filter(id => {
      if (id.indexOf('binary_sensor.') === 0) return /_charging$/.test(id);
      if (id.indexOf('sensor.') === 0) return /_battery_state$/.test(id);
      return id.indexOf('vacuum.') === 0;
    });

    return { icon: icon, name: name, charge_ids: chargeIds };
  };

  const deviceInfo = {};
  batteryEntityIds.forEach(id => { deviceInfo[id] = resolveDevice(id); });

  /* Weich (E3, 01.10.2026): Ring-Unterzeile, „Bald wechseln“, alle Geräte zweispaltig,
     Diagramm erst nach Antippen einer Zeile – window._casoraSoftBat in 08-weich-kompakt.js. */
  if (window._casoraSoft && window._casoraSoft() && window._casoraSoftBat) {
    const _sb = window._casoraSoftBat.build({ states: states, hass: hass, batteries: allBatteries
      .filter((e) => filterList || !/iphone|ipad|\bwatch\b|ebike|e-bike|drive_unit|performance_line/i.test(e.entity_id + ' ' + (e.attributes.friendly_name || '')))
      .map((e) => ({ id: e.entity_id, name: (deviceInfo[e.entity_id] || {}).name || e.entity_id,
        icon: (deviceInfo[e.entity_id] || {}).icon, charge: (deviceInfo[e.entity_id] || {}).charge_ids })) });
    if (_sb) return { type: 'vertical-stack', cards: [_sb] };
  }

  const cleanCardStyle = `
    :host {
      --ha-card-box-shadow:none !important;
