    const hideNarrow = two ? ['restA', 'restB'] : [];

    const listCard = {
      type: 'custom:button-card',
      tap_action: { action: 'none' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      card_mod: { style: cleanCardStyle
        + '\nha-card { will-change: auto !important; }' },
      styles: {
        card: [...baseCardStyle, { padding: '2px 26px 22px 26px' },
               { 'max-width': 'none' }, { margin: '0' }],
        grid: [
          { 'grid-template-areas': wideAreas },
          { 'grid-template-columns': wideCols },
          { 'grid-template-rows': wideRows },
          { 'row-gap': 'var(--casora-popup-sec-gap, 18px)' },
