      const headCard = {
        type: 'custom:button-card', tap_action: { action: 'none' },
        show_icon: false, show_name: false, show_label: false, show_state: false,
        card_mod: { style: cleanCardStyle },
        styles: { card: [...baseCardStyle, { padding: '4px 30px 0 30px' }],
                  grid: [{ 'grid-template-areas': '"t"' }, { 'grid-template-columns': '1fr' }],
