      /* A Ring stream without an audio track can't be unmuted; say so rather
         than leaving a button that looks broken. */
      hasAudio: function () {
        const v = this.video();
        if (!v) return false;
        if (v.audioTracks && typeof v.audioTracks.length === 'number') return v.audioTracks.length > 0;
        if (typeof v.mozHasAudio === 'boolean') return v.mozHasAudio;
        if (typeof v.webkitAudioDecodedByteCount === 'number') return v.webkitAudioDecodedByteCount > 0;
        return true;
      },

      syncAudio: function (scope) {
        const btn = scope && scope.querySelector('.cam-mute');
        const ic  = btn && btn.querySelector('ha-icon');
        const off = this._muted !== false;
        if (ic) ic.setAttribute('icon', off ? 'mdi:volume-off' : 'mdi:volume-high');
        if (btn) btn.setAttribute('data-tip', off ? 'Ton an' : 'Stumm');
        this.mark(btn, !off);
        if (btn) {
          btn.style.background = off
            ? 'var(--casora-glass-pill-fill, rgba(255,255,255,0.12))'
            : 'rgba(255,255,255,0.92)';
          btn.style.color = off ? 'var(--casora-cam-ctl-ink, rgba(255,255,255,0.92))' : '#1c1c1e';
          if (ic) ic.style.color = off ? 'var(--casora-cam-ctl-ink, rgba(255,255,255,0.92))' : '#1c1c1e';
        }
      },

      toggleMute: function (el) {
        const self = this;
        self._muted = self._muted === false;
        self.applyAudio();
        const scope = el.closest('.cam-detail');
        if (!scope) return;
        self.syncAudio(scope);
        if (self._audT) { clearTimeout(self._audT); self._audT = null; }
        self.setMode(scope, self._modeText || 'Live');
        if (self._muted) return;
        /* audioTracks/webkitAudioDecodedByteCount are both empty until the
           decoder has actually run, so an immediate verdict always reads
           "no audio" even when there is some. */
        self._audT = setTimeout(function () {
          self._audT = null;
          if (self._muted === false && !self.hasAudio()) {
            self.setMode(scope, (self._modeText || 'Live') + ' \xb7 no audio');
          }
        }, 1500);
      },

      /* Apple's gesture: tap the picture to fill the screen. The frame goes,
         not the <video>, so the rounded mask and the aspect box travel with it.
         iOS has no element fullscreen — there only the video can go. */
      /* The browser can leave fullscreen without us — Esc, the system gesture,
         iOS's own Done button — so the glyph follows the document, not our call. */
      paintFs: function () {
        const on = !!(document.fullscreenElement || document.webkitFullscreenElement);
        const scope = this._fsScope;
        const b = scope && scope.querySelector('.cam-fs');
        const ic = b && b.querySelector('ha-icon');
        if (ic) ic.setAttribute('icon', on ? 'mdi:arrow-collapse' : 'mdi:arrow-expand');
      },

      watchFs: function () {
        if (this._fsBound) return;
        this._fsBound = true;
        const self = this;
        const upd = function () { self.paintFs(); };
        document.addEventListener('fullscreenchange', upd);
        document.addEventListener('webkitfullscreenchange', upd);
      },

      fullscreen: function (el) {
        const scope = el.closest('.cam-detail');
        this._fsScope = scope;
        this.watchFs();
        const box = scope && scope.querySelector('.cam-frame');
        const d = document;
        if (d.fullscreenElement || d.webkitFullscreenElement) {
          if (d.exitFullscreen) d.exitFullscreen();
          else if (d.webkitExitFullscreen) d.webkitExitFullscreen();
          return;
        }
        const landscape = function () {
          try {
            const o = window.screen && window.screen.orientation;
            if (o && o.lock) {
              const p = o.lock('landscape');
              if (p && p.catch) p.catch(function () {});
            }
          } catch (e) {}
