      accState: function (id) {
        const ha = this._ha();
        const st = ha && ha.hass && ha.hass.states[id];
        if (!st) return null;
        const v = String(st.state).toLowerCase();
        if (id.indexOf('lock.') === 0) return v === 'unlocked' ? 'open' : 'shut';
        if (id.indexOf('cover.') === 0) return (v === 'open' || v === 'opening') ? 'open' : 'shut';
        if (id.indexOf('alarm_control_panel.') === 0) return v === 'disarmed' ? 'shut' : 'open';
        return v === 'on' ? 'open' : 'shut';
      },

      /* A pill is content-width, and auto can't be transitioned. Measure the
         old and new widths around the swap, animate between the two numbers,
         then hand the width back to the content. */
      morph: function (el, paint) {
        const from = el.getBoundingClientRect().width;
        el.style.transition = 'none';
        el.style.width = 'auto';
        el.style.overflow = '';
        paint();
        const to = el.getBoundingClientRect().width;
        if (!from || !to || Math.abs(to - from) < 0.5) {
          el.style.width = '';
          el.style.transition = 'background-color 260ms ease, color 260ms ease, box-shadow 180ms ease';
          return;
        }
        /* Clipped only while the label slides in — left on, it would cut the
           hover tooltip off at the pill's edge. */
        el.style.overflow = 'hidden';
        el.style.width = from + 'px';
        el.getBoundingClientRect();
        el.style.transition = 'width 420ms cubic-bezier(0.34,1.42,0.52,1),'
          + ' background-color 260ms ease, color 260ms ease';
        el.style.width = to + 'px';
        if (el._morphT) clearTimeout(el._morphT);
        el._morphT = setTimeout(function () {
          el._morphT = null;
          el.style.transition = 'background-color 260ms ease, color 260ms ease, box-shadow 180ms ease';
          el.style.width = '';
          el.style.overflow = '';
        }, 440);
      },

      /* One tap on the siren wakes the building, so it arms a confirm state
         and fires on the second tap. */
      needsConfirm: function (id) {
        return id.indexOf('siren.') === 0 || id.indexOf('alarm_control_panel.') === 0;
      },

      confirmLabel: function (id, open) {
        if (id.indexOf('siren.') === 0) return open ? 'Sirene stoppen?' : 'Sirene auslösen?';
        return open ? 'Unscharf schalten?' : 'Scharf schalten?';
      },

      clearConfirm: function () {
        if (this._cfT) { clearTimeout(this._cfT); this._cfT = null; }
        const el = this._cfEl;
        this._cfEl = null;
        if (!el) return;
        el.removeAttribute('data-confirm');
        this.paintAcc(el, this.accState(el.getAttribute('data-acc')));
      },

      armConfirm: function (id, el) {
        const self = this;
        self.clearConfirm();
        el.setAttribute('data-confirm', '1');
        self._cfEl = el;
        self.mark(el, true);

        self.morph(el, function () {
          el.style.background = 'var(--casora-popup-orange-color, #ff9230)';
          el.style.color = '#1c1c1e';
          const ic = el.querySelector('ha-icon');
          const tx = el.querySelector('span');
          if (ic) { ic.setAttribute('icon', 'mdi:alert-outline'); ic.style.color = '#1c1c1e'; }
          if (tx) {
            tx.textContent = self.confirmLabel(id, self.accState(id) === 'open');
            tx.style.display = '';
          }
          el.removeAttribute('data-tip');
        });

        self._cfT = setTimeout(function () { self._cfT = null; self.clearConfirm(); }, 5000);
      },

      accToggle: function (id, el) {
        const cur = this.accState(id);
        if (cur === null) return;
        if (this.needsConfirm(id) && el.getAttribute('data-confirm') !== '1') {
          this.armConfirm(id, el);
          return;
        }
        if (this._cfT) { clearTimeout(this._cfT); this._cfT = null; }
        this._cfEl = null;
        el.removeAttribute('data-confirm');
        const open = cur === 'open';
        if (id.indexOf('lock.') === 0)        this.svc('lock', open ? 'lock' : 'unlock', { entity_id: id });
        else if (id.indexOf('cover.') === 0)  this.svc('cover', open ? 'close_cover' : 'open_cover', { entity_id: id });
        else if (id.indexOf('alarm_control_panel.') === 0)
          this.svc('alarm_control_panel', open ? 'alarm_disarm' : 'alarm_arm_away', { entity_id: id });
        else                                  this.svc('homeassistant', open ? 'turn_off' : 'turn_on', { entity_id: id });
