        const self = this;
        setTimeout(function () { self.paintAcc(el, self.accState(id)); }, 1400);
      },

      paintAcc: function (el, state) {
        if (!el || !state) return;
        const open = state === 'open';
        const self = this;
        self.mark(el, open);
        self.morph(el, function () {
          el.style.background = open ? 'rgba(255,255,255,0.92)' : 'var(--casora-glass-pill-fill, rgba(255,255,255,0.12))';
          el.style.color = open ? '#1c1c1e' : 'var(--casora-cam-ctl-ink, rgba(255,255,255,0.92))';
          const ic = el.querySelector('ha-icon');
          const tx = el.querySelector('span');
          const on = el.getAttribute('data-icon-open'), off = el.getAttribute('data-icon-shut');
          const txt = open ? (el.getAttribute('data-label-open') || '') : '';
          if (ic) { ic.setAttribute('icon', open ? on : off); ic.style.color = open ? '#1c1c1e' : 'var(--casora-cam-ctl-ink, rgba(255,255,255,0.92))'; }
