        const mount = scope && scope.querySelector('.cam-stream-mount');
        if (this._recT) { clearTimeout(this._recT); this._recT = null; }
        this.mount(camId, mount);
        this._modeText = 'Live';
        this.setMode(scope, 'Live');
        this.paintRec(scope, false);
      },

      setMode: function (scope, txt) {
        const el = scope && scope.querySelector('.cam-mode');
