    const _l = fn ? (fn.replace(/\s*Live view$/i, '').trim() || fn) : cam.id.split('.').pop().replace(/_/g, ' ');
    /* Weich (E3): Gerätename statt Stream-Technik. */
    return (_soft && window._casoraCamSoft.label) ? window._casoraCamSoft.label(cam.id, cam.s, hass, _l) : _l;
  };

  const isMobile = window.innerWidth < 600;
  const cols = variables.columns || (isMobile ? 1 : 2);
  const pad  = isMobile ? 20 : 28;
  const GAP  = 12;

  const font = 'font-family:var(--primary-font-family,system-ui);';
  const tileW = cols === 1
    ? '100%'
    : 'calc((100% - ' + (GAP * (cols - 1)) + 'px) / ' + cols + ')';

  const wrapperStyle = `
    :host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; }
    ha-card { background: transparent !important; border: none !important; border-radius: 0 !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; cursor: default !important; width: 100% !important; box-sizing: border-box !important; }
    ha-card:hover { box-shadow: none !important; }
