        if (v.hasAttribute && v.hasAttribute('muted') && !want) v.removeAttribute('muted');
        if (!want) {
          if (!v.volume) v.volume = 0.8;
          const pl = v.play();
          if (pl && pl.catch) pl.catch(function () {});
