    const st = states[id];
    if (!st) return null;
    const v = String(st.state).toLowerCase();
    if (id.startsWith('lock.'))  return v === 'unlocked' ? 'open' : 'shut';
    if (id.startsWith('cover.')) return (v === 'open' || v === 'opening') ? 'open' : 'shut';
    if (id.startsWith('alarm_control_panel.')) return v === 'disarmed' ? 'shut' : 'open';
    return v === 'on' ? 'open' : 'shut';
