          { background: `[[[ const s=(states[${_cid}]?.state||'').toLowerCase(); return ['open','opening'].includes(s)?"${_cc.onBg}":"${_cc.offBg}";]]]` },
          { '--cc-nc': `[[[ const s=(states[${_cid}]?.state||'').toLowerCase(); return ['open','opening'].includes(s)?"${_cc.onName}":"${_cc.offName}";]]]` },
          { '--cc-lc': `[[[ const s=(states[${_cid}]?.state||'').toLowerCase(); return ['open','opening'].includes(s)?"${_cc.onLabel}":"${_cc.offLabel}";]]]` },
          { '--cc-io': `[[[ return "1";]]]` },
          { '--cc-clr': `[[[ const s=(states[${_cid}]?.state||'').toLowerCase(); return ['open','opening'].includes(s)?"#ffffff":"var(--casora-color-teal, #00c3d0)";]]]` },
          { '--cc-mask': `[[[
              const s = (states[${_cid}]?.state||'').toLowerCase();
              const open = ['open','opening'].includes(s);
              return "url('" + (open ? ${JSON.stringify(CURTAIN_OPEN_URI)} : ${JSON.stringify(CURTAIN_CLOSED_URI)}) + "')";
            ]]]` },
          { '--casora-card-hover-filter': `[[[ const s=(states[${_cid}]?.state||'').toLowerCase(); return ['open','opening'].includes(s)?"none":"brightness(1.10)";]]]` },
          { '--lc-hover-tint': `[[[ const s=(states[${_cid}]?.state||'').toLowerCase(); return ['open','opening'].includes(s)?"transparent":"rgba(255,255,255,0.06)";]]]` },
          { border: 'none' },
          { 'box-shadow': 'none' },
          { 'border-radius': '26px' },
          { cursor: 'pointer' },
          { padding: '12px 12px' },
          { width: '100%' },
        ],
        grid: [
          { 'grid-template-areas': '"i n" "i l"' },
          { 'grid-template-columns': 'auto 1fr' },
          { 'grid-template-rows': 'auto auto' },
          { 'column-gap': '10px' },
          { 'row-gap': '1px' },
          { 'align-items': 'start' },
        ],
        img_cell: [
          { background: `[[[ const s=(states[${_cid}]?.state||'').toLowerCase(); return ['open','opening'].includes(s)?"var(--casora-color-teal, #00c3d0)":"rgba(255,255,255,0.10)";]]]` },
          { 'border-radius': '50%' },
          { width: '38px' },
          { height: '38px' },
          { 'min-width': '38px' },
          { display: 'flex' },
          { 'align-items': 'center' },
          { 'justify-content': 'center' },
          { 'align-self': 'center' },
        ],
        entity_picture: [
          { width: '100%' },
          { height: '100%' },
          { 'object-fit': 'contain' },
        ],
        name: [
          { 'font-size': '14px' },
          { 'font-weight': '500' },
          { color: 'var(--cc-nc)' },
          { 'text-align': 'left' },
          { 'justify-self': 'start' },
          { 'align-self': 'end' },
          { 'line-height': '1.2' },
          { overflow: 'hidden' },
          { 'text-overflow': 'ellipsis' },
          { 'white-space': 'nowrap' },
        ],
        label: [
          { 'font-size': '12px' },
          { color: 'var(--cc-lc)' },
          { 'text-align': 'left' },
          { 'justify-self': 'start' },
          { 'align-self': 'start' },
          { 'line-height': '1.2' },
        ],
      },
    };
  };

  /* Dynamic grid */
  const colCount = coverIds.length > 1 ? 2 : 1;
  let tileAreas;
  if (colCount === 1) {
    tileAreas = coverIds.map((_, i) => '"t' + i + '"').join(' ');
  } else {
    const rows = [];
    for (let i = 0; i < coverIds.length; i += 2) {
      if (i + 1 < coverIds.length) {
        rows.push('"t' + i + ' t' + (i + 1) + '"');
      } else {
        rows.push('"t' + i + ' t' + i + '"');
      }
    }
    tileAreas = rows.join(' ');
  }
  const tileColDef = colCount === 1 ? '1fr' : '1fr 1fr';

  const tileCF = {}, tileFS = {};
  coverIds.forEach((id, i) => {
    tileCF['t' + i] = { card: makeCoverCard(id) };
    tileFS['t' + i] = [{ 'justify-self': 'stretch' }, { 'text-align': 'left' }];
  });

  const tilesCard = {
    type: 'custom:button-card',
    entity: groupId,
    tap_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: contentCardStyle },
    styles: {
      card: [
        { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
        { padding: '16px 28px 20px 28px' },
      ],
      grid: [
        { 'grid-template-areas': tileAreas },
        { 'grid-template-columns': tileColDef },
        { gap: '10px' },
        { 'align-items': 'start' },
      ],
      custom_fields: tileFS,
    },
    custom_fields: tileCF,
  };

  /* Shared popup anatomy. Position is the subject, so it is the hero;
     the preset pills become a segmented control; each cover becomes a
     row carrying its own position. */
  const UI = window._casoraUI;
  if (UI) {
    const posOf = (id) => {
      const p = states[id]?.attributes?.current_position;
      return typeof p === 'number' ? Math.round(p) : null;
    };
    const openStates = ['open', 'opening', 'stopping'];
    const known = coverIds.map(posOf).filter(v => v != null);
    const avg = known.length
      ? Math.round(known.reduce((a, b) => a + b, 0) / known.length)
      : null;
    const openCount = coverIds.filter(id => openStates.includes(states[id]?.state)).length;
    const allClosed = openCount === 0 && coverIds.length > 0;
    const allOpen = openCount === coverIds.length && coverIds.length > 0;

    const areas = [], fields = {}, fstyle = {};
    const add = (name, html) => {
      areas.push('"' + name + '"');
      fields[name] = html;
      fstyle[name] = [{ 'justify-self': 'stretch' }];
    };

    /* The more-info state header: the word, then how long it has read
       that way, centered over the control. The percentage lives on the
       slider and on each row, so it is not repeated here. A [[[ ]]]
       template, not a string, or the time never ticks. */
    const _cids = JSON.stringify(coverIds);
    add('hero', `[[[
      const ids = ${_cids};
      const ago = (iso) => {
        if (!iso) return null;
        const ms = Date.now() - new Date(iso).getTime();
        if (isNaN(ms) || ms < 0) return null;
        const m = ms/60000, h = m/60, d = h/24;
        if (m < 1) return 'gerade eben';
        if (m < 60) return 'vor ' + Math.floor(m) + (Math.floor(m)===1?' Minute':' Minuten');
        if (h < 24) return 'vor ' + Math.floor(h) + (Math.floor(h)===1?' Stunde':' Stunden');
        if (d < 7)  return 'vor ' + Math.floor(d) + (Math.floor(d)===1?' Tag':' Tagen');
        return 'vor ' + Math.floor(d/7) + 'w';
      };
      const posOf = (id) => {
        const p = states[id]?.attributes?.current_position;
        return typeof p === 'number' ? Math.round(p) : null;
      };
      const openStates = ['open', 'opening', 'stopping'];
      const known = ids.map(posOf).filter(v => v != null);
      const avg = known.length
        ? Math.round(known.reduce((a, b) => a + b, 0) / known.length)
        : null;
      const tot = ids.length;
      const openCount = ids.filter(id => openStates.includes(states[id]?.state)).length;
      const moving = ids.some(id => ['opening','closing'].includes(states[id]?.state));
      const part = avg != null && avg > 0 && avg < 100;
      const value = moving
        ? (ids.some(id => states[id]?.state === 'opening') ? 'Öffnet sich\u2026' : 'Schließt sich\u2026')
        : openCount === 0 ? (tot === 1 ? 'Geschlossen' : 'Alle geschlossen')
        : openCount === tot ? (part ? 'Teilweise geöffnet' : (tot === 1 ? 'Geöffnet' : 'Alle geöffnet'))
        : openCount + ' von ' + tot + ' geöffnet';
      const newest = ids.map(id => states[id]?.last_changed).filter(Boolean).sort().pop();
      return window._casoraUI.hero({
        value: value,
        sub: ago(newest),
        center: true,
        line: true,
      });
    ]]]`);

    /* The height goes to the control: a grab-anywhere vertical track,
       the way Home does blinds. */
    const coverIcon = (() => {
      const id = (coverIds[0] || '').toLowerCase();
      const dc = (states[coverIds[0]]?.attributes?.device_class || '').toLowerCase();
      /* Dasselbe Symbol wie Kachel und Zeilen (casoraCoverKind, Audit M2). */
      if (window.casoraCoverKind) return window.casoraCoverKind(dc, id).open;
      if (dc === 'shade' || id.includes('shade')) return 'roller-shade-open';
      return 'cover_open';
    })();
    /* D-06 (Weich): jeder Bereich mit Überschrift, wie Licht und Thermostat. */
    const _sfC = !!(UI.soft && UI.soft());
    add('slider', (_sfC && UI.label ? UI.label('Position') : '') + UI.slider({
      /* Shorter than the shared control height by the presets row this
         popup has and the lock does not, so both sheets land their
         tiles on the same line. */
      height: 267,
      value: avg == null ? (allClosed ? 0 : 100) : avg,
      invert: true,
      live: { entities: coverIds, attr: 'current_position' },
      icon: coverIcon,
      svc: { domain: 'cover', service: 'set_cover_position',
             target: { entity_id: coverIds }, field: 'position' },
    }));

    const setTo = (pos) => ({
      domain: 'cover', service: 'set_cover_position',
      target: { entity_id: coverIds }, data: { position: pos },
    });
    /* value + live: im Weich-Design folgt das aktive Feld der echten Position (30 % → keins). */
    /* D-13 (Weich): kurze Wörter mit Luft zum Rand, „25 %“ mit Leerzeichen wie der Regler. */
    add('presets', UI.segments([
      { label: _sfC ? 'Zu' : 'Schließen', svc: setTo(0),   active: avg === 0, value: 0 },
      { label: _sfC ? '25 %' : '25%',   svc: setTo(25),  active: avg === 25, value: 25 },
      { label: _sfC ? '50 %' : '50%',   svc: setTo(50),  active: avg === 50, value: 50 },
      { label: _sfC ? '75 %' : '75%',   svc: setTo(75),  active: avg === 75, value: 75 },
      { label: _sfC ? 'Auf' : 'Öffnen',  svc: setTo(100), active: avg === 100, value: 100 },
    ], null, { live: { entities: coverIds, attr: 'current_position' } }));

    /* Sectioned by device class. A header earns its place by telling
       two things apart, so one type gets one section named for what it
       actually is - never the generic "Cover". */
    /* The taxonomy lives in casora-core so the tile template resolves the
       same pair. The literal is only a guard for a stale core. */
    const CURTAIN = { key: 'curtain', label: 'Vorhänge',
                      open: 'curtain-open', closed: 'curtain-closed' };
    const kindOf = (id) => (window.casoraCoverKind
      ? window.casoraCoverKind(states[id]?.attributes?.device_class, id)
      : CURTAIN);

    const KIND = {};
    const byKind = {};
    coverIds.forEach((id) => {
      const k = kindOf(id);
      KIND[k.key] = k;
      (byKind[k.key] = byKind[k.key] || []).push(id);
    });
    const kinds = Object.keys(byKind);

    /* No per-row bar. The trailing word IS the state, the way the lock
       rows read - a 4px line under a row that already prints the number
       says the same thing twice, and it is not a control: it would be a
       drag target well under the 44px minimum, fighting the row's own
       tap-to-open. WORDS is shared so the first paint and the live
       repaint cannot drift apart. */
    const WORDS = {
      state: { opening: 'Öffnet sich\u2026', closing: 'Schließt sich\u2026' },
      attr: 'current_position',
      exact: { '0': 'Geschlossen', '100': 'Geöffnet' },
      tpl: '{n}% geöffnet',
      fallbackState: { open: 'Geöffnet', closed: 'Geschlossen', stopping: 'Gestoppt' },
    };
    const wordFor = (id) => {
      const st = states[id]?.state;
      if (WORDS.state[st]) return WORDS.state[st];
      const p = posOf(id);
      if (p == null) return WORDS.fallbackState[st] || 'Unbekannt';
      return WORDS.exact[String(p)] || WORDS.tpl.replace('{n}', String(p));
    };

    const rowFor = (id, k) => {
      const open = openStates.includes(states[id]?.state);
      return {
        entity: id,
        icon: open ? KIND[k].open : KIND[k].closed,
        label: hass?.entities?.[id]?.name
          || states[id]?.attributes?.friendly_name || id,
        value: wordFor(id),
        liveWords: WORDS,
        /* Weich: offene Jalousie als aktive Zeile wie die aktive Kachel (Vorschlag 03.10.2026). */
        active: open,
      };
    };

    /* A heading earns its place by telling two things apart. With one
       kind, or with grouping off, there is nothing to tell apart. */
    const grouped = variables.group_by_type !== false && kinds.length > 1;
    if (grouped) {
      kinds.forEach((k, i) => {
        add('k' + i, UI.group(byKind[k].map(id => rowFor(id, k)), KIND[k].label));
      });
    } else {
      const all = [];
      kinds.forEach((k) => byKind[k].forEach((id) => all.push(rowFor(id, k))));
      if (all.length) add('k0', UI.group(all, _sfC ? KIND[kinds[0]].label : null));
    }

    if (HZ_SYS && states[HZ_SYS]) {
      const on = states[HZ_SYS].state === 'on';
      add('auto', UI.group([{
        icon: 'scenes',
        label: hass?.entities?.[HZ_SYS]?.name
          || states[HZ_SYS].attributes?.friendly_name || 'Beschattungsautomatik',
        value: on ? 'An' : 'Aus',
        valueTone: on ? 'good' : null,
        svc: { domain: 'homeassistant', service: on ? 'turn_off' : 'turn_on',
               target: { entity_id: HZ_SYS } },
      }], 'Automatik'));
    }

    /* Gruppe: ab 761 px zweispaltig - links Status, Regler, Voreinstellungen; rechts die Liste. */
    const _two = coverIds.length > 1 && !(window.innerWidth > 760 && window._casoraStd);
    if (_two) {
      const rk = Object.keys(fields).filter(k => !['hero', 'slider', 'presets'].includes(k));
      if (rk.length) {
        fields.list = rk.map(k => fields[k]).join('<div style="height:28px"></div>');
        fstyle.list = [{ 'justify-self': 'stretch' }, { 'align-self': 'start' }];
        rk.forEach(k => { delete fields[k]; delete fstyle[k]; const i = areas.indexOf('"' + k + '"'); if (i > -1) areas.splice(i, 1); });
        areas.push('"list"');
      }
    }
    const uiCard = {
      type: 'custom:button-card',
      card_mod: { style: contentCardStyle
        + '\n:host { --ha-card-backdrop-filter: none !important; --ha-card-background: transparent !important; --card-background-color: transparent !important; --ha-card-box-shadow: none !important; --ha-card-border-width: 0px !important; }'
        + '\nha-card::before, ha-card::after, #card::before, #card::after, #container::before, #container::after { display: none !important; }'
        + '\nha-card { will-change: auto !important; }'
        + '\n#container { background: transparent !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; }' },
      entity: groupId || undefined,
      tap_action: { action: 'none' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      styles: {
        card: [
          { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
          { padding: 'var(--casora-soft-card-top, 6px) 26px 22px 26px' },
        ],
        grid: [
          { 'grid-template-areas': areas.join(' ') },
          { 'grid-template-columns': '1fr' },
          { 'row-gap': '28px' },
        ],
        custom_fields: fstyle,
      },
      custom_fields: fields,
    };
    if (_two && fields.list) {
      uiCard.extra_styles = '@media (min-width: 761px) { #container { grid-template-areas: "hero list" "slider list" "presets list" !important;'
        + ' grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) !important; grid-template-rows: auto auto auto !important;'
        + ' column-gap: 32px !important; align-items: start !important; align-content: center !important; }'
        + ' #list { align-self: center !important; } }';
    }
    /* Popup-Standard (24.09.2026): ab 761 px Status oben, links Regler/Voreinstellungen/Automatik, rechts die Jalousien. */
    return { type: 'vertical-stack', cards: [window._casoraStd ? window._casoraStd(uiCard, { left: ['slider', 'presets', 'auto'], single: coverIds.length < 2 }) : uiCard] };
  }

  const stackCards = [headerCard, controlsCard, tilesCard];
  if (hitzeschutzCard) stackCards.splice(1, 0, hitzeschutzCard);
  return { type: 'vertical-stack', cards: stackCards };
]]]

popup_styles.styles:
/* Popup content cards are not buttons: the theme's hover lift (shadow + brightness) made a
   whole column look like a raised card under the pointer (Weich audit M1). Killed popup-wide. */
--casora-card-hover-filter: none;
--casora-hover-filter: none;
--casora-card-hover-shadow: none;
/* The pane stays - these are control sheets. Only the close control
   keeps what it gained: a surface of its own, and room above it so
   the fill is not against the top edge of the sheet. */
.header { padding-top: var(--casora-popup-header-gap, 10px); }
/* Equal inset on both axes: the bar's own padding plus the
   close control's 2px optical nudge has to come to the same
   number as the padding above it, or the circle sits further
   from the left edge than it does from the top. */
--casora-popup-header-gap: 14px;
  --casora-popup-gutter-wide: 20px;
  --casora-popup-row-radius: 30px;
  /* The inactive presets read brighter than the tiles under them. */
  --casora-popup-seg-fill: rgba(255, 255, 255, 0.10);
  --casora-popup-seg-fill-hover: rgba(255, 255, 255, 0.16);
/* The chrome arrives with the first plate instead of being there
   on frame one while everything under it fades in. */
--casora-popup-chrome-enter:
  casora-popup-chrome-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
.header-title { font-size: 20px; font-weight: 600; letter-spacing: -0.01em; }
.header-close {
  border-radius: 50%;
  background: var(--casora-popup-row-fill, rgba(255, 255, 255, 0.10));
  backdrop-filter: var(--casora-popup-plate-backdrop, blur(24px) saturate(180%));
  -webkit-backdrop-filter: var(--casora-popup-plate-backdrop, blur(24px) saturate(180%));
  box-shadow: var(--casora-popup-plate-shadow, none);
}

/* Popup-Standard (24.09.2026): breit wie alle Popups. */
--popup-min-width: 900px;
--popup-max-width: 920px;

casora_popup.style:
[[[
  const ids = Array.isArray(variables.covers) && variables.covers.length ? variables.covers : [variables.cover_entity || entity?.entity_id];
  return ids.length > 1
    ? '--popup-min-width: 900px; --popup-max-width: 900px; --popup-min-width-narrow: calc(100vw - 16px);'
    : '--popup-min-width: 460px; --popup-max-width: 460px;';
]]]

casora_popup.title:
[[[
  /* Eigener Popup-Titel der Kachel (room_name) zuerst, sonst wie bisher. */
  const _own = window.casoraPopupTitle ? window.casoraPopupTitle(null, variables, '', ['Zuhause'])
    : (() => { const r = String(variables.room_name || '').trim(); return r.startsWith('[[[') ? '' : r; })();
  if (_own && !['Zuhause'].includes(_own)) return _own;
  return "Jalousien";
]]]

