casora_popup.content:
[[[
  /* Weich (E3, 01.10.2026): diese ältere Kopie zeigt im Weich-Design denselben entschlackten
     Inhalt wie tap_action (window._casoraSoftNet/_casoraSoftEnergy, 05-weich-mehr.js) – die
     Vorlage wertet dafür den Inhalt aus tap_action aus. Standard und Glas: unverändert. */
  if (window._casoraSoft && window._casoraSoft() && !window._casoraSoftFwd
      && this && typeof this._getTemplateOrValue === 'function') {
    const _nc = this._config && this._config.tap_action && this._config.tap_action.casora_popup
      && this._config.tap_action.casora_popup.content;
    if (typeof _nc === 'string' && _nc.trim().indexOf('[[[') === 0) {
      window._casoraSoftFwd = true;
      try { const _r = this._getTemplateOrValue(this._stateObj, _nc); if (_r && typeof _r === 'object') return _r; }
      catch (e) { console.warn('casora: Weich-Inhalt nicht verfügbar', e); }
      finally { window._casoraSoftFwd = false; }
    }
  }
  const powerId     = ((id) => { const s = id && states[id]; const a = (s && s.attributes) || {}; return !!s && (a.device_class === 'power' || /^[kMG]?W$/.test(String(a.unit_of_measurement || ''))); })(variables.entity_power || entity?.entity_id) ? (variables.entity_power || entity?.entity_id) : null;
  const todayId     = variables.entity_usage_today;
  const monthId     = variables.entity_usage_month;
  const costTodayId = variables.entity_cost_today;
  const costMonthId = variables.entity_cost_month;
  const roomName    = variables.room_name || 'Energie';

  const safeNum = (id) => {
    if (!id) return null;
    const s = states[id] && states[id].state;
    if (!s || s === 'unknown' || s === 'unavailable') return null;
    const n = parseFloat(s);
    return isNaN(n) ? null : n;
  };

  const costCurrency = (costTodayId && states[costTodayId]?.attributes?.unit_of_measurement)
    || (costMonthId  && states[costMonthId]?.attributes?.unit_of_measurement)
    || '';

  /* Raum ohne eigenen Sensor (04.10.2026): Summe der Geräte (power_entities) als Leistung,
     wie die Badge; die Geräte stehen einzeln weiter unten. */
  const _sumIds = !powerId && Array.isArray(variables.power_entities) ? variables.power_entities.filter(Boolean) : [];
  const _sumW = (id) => { const n = safeNum(id); if (n == null) return null;
    const u = String(states[id]?.attributes?.unit_of_measurement || 'W'); return u === 'kW' ? n * 1000 : u === 'MW' ? n * 1e6 : u === 'mW' ? n / 1000 : n; };
  const power = powerId ? _sumW(powerId) /* kW/MW → W wie die Summe */
    : (typeof window !== 'undefined' && window._casoraPowerSum && _sumIds.length) /* 06.10.2026: wie die Badge (nur Leistung, Messsteckdose nicht doppelt) */
      ? (() => { const s = window._casoraPowerSum({ energy_entities: _sumIds, energy_parent: variables.power_parent }, states).sum; return Number.isFinite(s) ? s : null; })()
      : (() => { const v = _sumIds.map(_sumW).filter((n) => n != null); return v.length ? v.reduce((x, y) => x + y, 0) : null; })();

  window._hc = window._hc || {};
  const _ck = 'casora_energy_v2_' + (powerId || 'x');
  const _memoSub = (subKey, dep, factory) => {
    const key = _ck + '_' + subKey;
    if (window._hc[key]?.h === dep) return window._hc[key].r;
    const r = factory();
    window._hc[key] = { h: dep, r };
    return r;
  };

  const tNormal  = Number(variables.normal_threshold  ?? 200);
  const tHeavy   = Number(variables.heavy_threshold   ?? 1000);
  const tExtreme = Number(variables.extreme_threshold ?? 3000);

  // Usage tier — drives the graph line and the memo keys below
  const statusLabel = power >= tExtreme ? 'Extrem' : power >= tHeavy ? 'Hoch' : power >= tNormal ? 'Normal' : ((powerId || _sumIds.length) ? (power > 5 ? 'Gering' : 'Inaktiv') : 'Kein Sensor gewählt');

  // Safe JSON literals for inner templates
  const _pid  = JSON.stringify(powerId     || '');
  const _tid  = JSON.stringify(todayId     || '');
  const _mid  = JSON.stringify(monthId     || '');
  const _ctid = JSON.stringify(costTodayId || '');
  const _cmid = JSON.stringify(costMonthId || '');
  const _cur  = JSON.stringify(costCurrency);

  // Shared helper snippets
  const _safe = "const safeNum=(id)=>{if(!id)return null;const s=states[id]&&states[id].state;if(!s||s==='unknown'||s==='unavailable')return null;const n=parseFloat(s);return isNaN(n)?null:n;};";
  const _fmt  = "const _fmtL=(hass&&hass.locale&&hass.locale.language)||'de';const fmtPower=(v)=>v==null?'—':String(Math.round(v));const fmtEnergy=(v)=>{if(v==null)return'—';const d=v<1?2:v<10?1:0;return v.toLocaleString(_fmtL,{minimumFractionDigits:d,maximumFractionDigits:d});};";

  // Power → color
  const _powerScore = `
    const tNormal = ${tNormal}, tHeavy = ${tHeavy}, tExtreme = ${tExtreme};
    const power = (() => { const n = safeNum(powerId); if (n == null) return null; /* kW/MW → W */
      const u = String((states[powerId] && states[powerId].attributes.unit_of_measurement) || 'W');
      return u === 'kW' ? n * 1000 : u === 'MW' ? n * 1e6 : u === 'mW' ? n / 1000 : n; })();
    let color = 'var(--casora-popup-green-color, #30D158)', label = powerId ? 'Inaktiv' : 'Kein Sensor gewählt';
    if (power >= tExtreme)     { color = 'var(--casora-popup-red-color, #ff4245)';    label = 'Extrem'; }
    else if (power >= tHeavy)  { color = 'var(--casora-popup-orange-color, #ff9230)'; label = 'Hoch'; }
    else if (power >= tNormal) { color = 'var(--casora-popup-yellow-color, #ffd600)'; label = 'Normal'; }
  `;


  /* Styles */

  const noHoverStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; }',
    'ha-card { background: transparent !important; border: none !important; border-radius: 0 !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; pointer-events: none !important; cursor: default !important; }',
    'ha-card:hover { box-shadow: none !important; }',
    'ha-ripple { display: none !important; }',
  ].join('\n');

  const wrapperStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; }',
    'ha-card { background: transparent !important; border: none !important; border-radius: 0 !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; overflow: visible !important; cursor: default !important; }',
    'ha-card:hover { box-shadow: none !important; }',
    '#container { overflow: visible !important; }',
    'ha-ripple { display: none !important; }',
  ].join('\n');

  const contentCardStyle = wrapperStyle + '\n@media (max-width: 600px) { ha-card { padding-left: 14px !important; padding-right: 14px !important; } }';

  const tileTapStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: inset 0 1px 0.5px -0.5px rgba(255,255,255,calc(var(--casora-popup-tiles-glow-top-tight,0.20) * 1.5)), inset 0 -1px 0.5px -0.5px rgba(255,255,255,calc(var(--casora-popup-tiles-glow-bottom-tight,0.15) * 1.5)), inset 0 3px 6px -3px rgba(255,255,255,calc(var(--casora-popup-tiles-glow-top-soft,0.08) * 1.5)), inset 0 -3px 6px -3px rgba(255,255,255,calc(var(--casora-popup-tiles-glow-bottom-soft,0.05) * 1.5)) !important; }',
    'ha-card { background: var(--casora-popup-tiles-fill, rgba(255,255,255,0.08)) !important; border: none !important; border-radius: 24px !important; box-shadow: inset 0 1px 0.5px -0.5px rgba(255,255,255,var(--casora-popup-tiles-glow-top-tight,0.20)), inset 0 -1px 0.5px -0.5px rgba(255,255,255,var(--casora-popup-tiles-glow-bottom-tight,0.15)), inset 0 3px 6px -3px rgba(255,255,255,var(--casora-popup-tiles-glow-top-soft,0.08)), inset 0 -3px 6px -3px rgba(255,255,255,var(--casora-popup-tiles-glow-bottom-soft,0.05)) !important; backdrop-filter: var(--casora-popup-tiles-backdrop, blur(10px) saturate(1.1)) !important; -webkit-backdrop-filter: var(--casora-popup-tiles-backdrop, blur(10px) saturate(1.1)) !important; cursor: pointer !important; transform: scale(1) !important; transition: background-color var(--casora-popup-tile-hover-duration, 0.2s) ease, transform var(--casora-popup-tile-hover-duration, 0.2s) ease, box-shadow 0.2s ease !important; }',
    'ha-card:hover { background: var(--casora-popup-tile-hover, rgba(255,255,255,0.09)) !important; transform: scale(var(--casora-popup-tile-hover-scale, 1.01)) !important; }',
    'ha-ripple { display: none !important; }',
  ].join('\n');

  const tapStyle = [
