      _bc.readout = 'hero'; _bc.read_as = powerId;
      _bc.series[0].unit = String(states[eid].attributes?.unit_of_measurement || _bc.series[0].unit);
    } else window._hpChartCfg(eid, _hpLabelFor(eid), _hpSpanFor(eid), _hpColorFor(eid), 120); } };


    /* Solaranlage: Solar / Akku / Netz — dieselben Werte wie die
       Solarbank-Sub-Badges auf der Home-Zeile, hier mit Heute/Monat-
       Zahlen, fuer die ein Badge keinen Platz hat. */
    const solarPowerId = variables.entity_solar_power || null;
    const solarTodayId = variables.entity_solar_today || null;
    const battPowerId  = variables.entity_battery_power || null;
    const battSocId    = variables.entity_battery_soc || null;
    const battTodayId  = variables.entity_battery_today || null;
    const netzPowerId  = variables.entity_netz_power || null;
    const netzTodayId  = variables.entity_netz_today || null;

    if (solarPowerId || battPowerId || netzPowerId) {
      const pvRows = [];
      if (solarPowerId) {
        const p = _sumW(solarPowerId);
        const t = safeNum(solarTodayId);
        pvRows.push({
          entity: solarPowerId,
          icon: 'energy',
          iconTone: '#FFD600',
          label: 'Solar',
          value: p != null ? fmtN(p) + ' W' : '—',
          sub: t != null ? 'Heute ' + fmtN(t) + ' kWh' : null,
        });
      }
      if (battPowerId || battSocId) {
        const p = _sumW(battPowerId);
        const soc = safeNum(battSocId);
        const t = safeNum(battTodayId);
        pvRows.push({
          entity: battPowerId || battSocId,
          icon: 'battery',
          iconTone: '#0A84FF',
          label: 'Akku',
          value: soc != null ? Math.round(soc) + '%' : (p != null ? fmtN(Math.abs(p)) + ' W' : '—'),
          sub: p != null
            ? (p > 5 ? 'Lädt · ' + fmtN(p) + ' W'
               : p < -5 ? 'Entlädt · ' + fmtN(Math.abs(p)) + ' W'
               : (t != null ? 'Heute ' + fmtN(t) + ' kWh entladen' : null))
            : null,
        });
      }
      if (netzPowerId) {
        const p = _sumW(netzPowerId);
        const t = safeNum(netzTodayId);
        pvRows.push({
          entity: netzPowerId,
          icon: 'electric',
          iconTone: (p != null && p < 0) ? '#30D158' : '#FF453A',
          label: 'Netz',
          value: p != null ? fmtN(Math.abs(p)) + ' W' : '—',
          sub: p != null
            ? (p < 0 ? 'Einspeisung' : (t != null ? 'Heute ' + fmtN(t) + ' kWh Bezug' : 'Bezug'))
            : null,
        });
      }
      if (pvRows.length) add('pv', UI.group(pvRows, 'Solaranlage', null, { labelInside: true }));
    }

    /* Solarbank-Erweiterung: Energiefluss, Autarkie, Solarbank-Details und
       Steuerung. Nur im Haus-Popup (dort ist entity_solar_power gesetzt),
       die Geräte-Popups bleiben wie sie sind. Jeder Bereich ist eine eigene
       Karte mit triggers_update, weil der Popup-Inhalt nur beim Öffnen
       gebaut wird und diese Werte sich ständig ändern. */
    const extended = !!solarPowerId;
    if (extended) {
      const C = {
        solar: solarPowerId, soc: battSocId, grid: netzPowerId, home: powerId,
        solarToday: solarTodayId, gridToday: netzTodayId,
        charge: variables.entity_battery_charge, discharge: variables.entity_battery_discharge,
        output: variables.entity_solarbank_output, export: variables.entity_grid_export,
        exportTotal: variables.entity_grid_export_total, savings: variables.entity_savings,
        state: variables.entity_solarbank_state, mode: variables.entity_solarbank_mode,
        error: variables.entity_solarbank_error, energy: variables.entity_solarbank_energy,
        capacity: variables.entity_solarbank_capacity, temp: variables.entity_solarbank_temp,
        loadTarget: variables.entity_solarbank_load_target, pv: variables.entity_pv_strings || [],
        limit: variables.entity_output_limit, exportSwitch: variables.entity_export_switch,
        socMin: variables.entity_soc_min, socMax: variables.entity_soc_max,
      };
      const _cj = 'const C = ' + JSON.stringify(C) + ';\n';
      const secCard = (watch, body) => ({
        type: 'custom:button-card',
        triggers_update: watch.filter((id) => id && states[id]),
        tap_action: { action: 'none' },
        show_icon: false, show_name: false, show_label: false, show_state: false,
        extra_styles: 'ha-card.disabled{pointer-events:auto!important;}'
          + ' .hui-plate{animation:none!important;}'
          + ' @keyframes casora-plate-in {'
          + ' from { opacity: 0; transform: perspective(900px) translateZ(-70px); }'
          + ' to { opacity: 1; transform: perspective(900px) translateZ(0); } }'
          + ' ha-card { animation: var(--casora-popup-plate-enter, none);'
          + ' animation-delay: var(--casora-popup-plate-delay, 0ms); }',
        card_mod: { style: wrapperStyle + '\nha-card { will-change: auto !important; }' },
        styles: {
          card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '0' }],
          grid: [{ 'grid-template-areas': '"c"' }, { 'grid-template-columns': 'minmax(0, 1fr)' }],
          custom_fields: { c: [{ 'justify-self': 'stretch' }, { 'text-align': 'left' }, { overflow: 'visible' }] },
        },
        custom_fields: { c: '[[[\n' + _INNER_COMMON + _cj + body + '\n]]]' },
      });
      const has = (id) => !!(id && states[id]);
      if (has(C.solar) && has(C.home)) {
        fields.flow = { card: secCard([C.solar, C.charge, C.discharge, C.output, C.grid, C.export, C.home, C.soc], _INNER_FLOW) };
      }
      if (has(C.home) && has(C.grid)) {
        fields.aut = { card: secCard([C.home, C.grid, C.export, C.solarToday, C.gridToday, C.savings, C.exportTotal], _INNER_AUT) };
      }
      if (has(C.state) || has(C.energy)) {
        fields.sb = { card: secCard([C.error, C.state, C.mode, C.soc, C.energy, C.capacity, C.temp, C.loadTarget].concat(C.pv), _INNER_SB) };
      }
      if (has(C.mode) || has(C.limit) || has(C.exportSwitch)) {
        fields.ctl = { card: secCard([C.mode, C.limit, C.exportSwitch, C.socMin, C.socMax], _INNER_CTL) };
      }
    }

    /* What is drawing it. A total answers "how much"; this answers
       "what", which is the question that brings you back - the same
       reason Battery leads with usage by app rather than a percentage.
       Ranked by current draw, and anything drawing nothing is dropped
       rather than listed at zero. */
    /* Everything is a plug unless you say otherwise. Guessing the glyph
       from the entity name put a gamepad on "Home Lab" - the rules
       matched /lab/ - and a wrong icon is worse than a neutral one.
       power_icons is set per sensor in the panel. */
    const iconFor = (id) => (variables.power_icons || {})[id] || 'plug';

    const consumers = (Array.isArray(variables.power_entities)
                         ? variables.power_entities : [])
      .filter(Boolean)
      .map((id) => ({ id: id, w: safeNum(id) }))
      .filter((x) => x.w != null && x.w > 0)
      .sort((a, b) => b.w - a.w);

    if (consumers.length) {
      const top = consumers.slice(0, UI.soft && UI.soft() ? 5 : 6);
      const share = power != null && power > 0 ? power : null;
      add('top', UI.group(top.map((x) => {
        const st = states[x.id];
        const nm = st?.attributes?.friendly_name || hass?.entities?.[x.id]?.name || x.id;
        const pct = share ? Math.round((x.w / share) * 100) : null;
        return {
          entity: x.id,
          icon: iconFor(x.id),
          label: String(nm).replace(/\s*(power|leistung)$/i, '').trim() || nm,
          sub: pct != null && pct > 0 ? pct + '% des aktuellen Verbrauchs' : null,
          subLive: powerId ? { total: powerId, suffix: '% des aktuellen Verbrauchs' } : null,
          value: fmtN(x.w) + ' W',
          liveAttr: 'state',
          liveSuffix: ' W',
        };
      }), null, null, { labelInside: true }));
    }

    /* One object: the number, its status and the curve it describes, on
       a single plate. They were two stacked blocks - a floating stat
       with a graph under it - which is the part that never read as
       Apple. Health, Battery and Stocks all bind the headline to the
       chart. The plate moved here from the chart card, which is
       transparent inside it now. */
    if (_hpOk && powerId) {
      const _sel = '<style>.hui-row.hp-sel{background:var(--casora-popup-row-hover, rgba(255,255,255,0.08));}</style>';
      const _wrap = (h) => '<div ontouchstart="window._hpPlantTap&&window._hpPlantTap(event,\'s\')" ontouchend="window._hpPlantTap&&window._hpPlantTap(event,\'t\')" onclick="window._hpPlantTap&&window._hpPlantTap(event,\'c\')">' + h + '</div>';
      /* Nur „Heute“/„Diesen Monat“ schalten das Diagramm um (Säulen je Tag); Solar- und
