popup_styles.styles:
/* Eine Popup-Familie (01.10.2026): dieselbe Sheet-Fläche wie die Bedien-Popups –
   Fläche, Blur, Schatten und Abdunklung aus dem Standard, Höhe folgt dem Inhalt,
   Schließen-Kreuz mit demselben Abstand zur Sheet-Kante. */
.header { padding-top: var(--casora-popup-header-gap, 10px); }
--casora-popup-header-gap: 14px;
--casora-popup-gutter-wide: 22px;

/* No chart to wait for, so the plates arrive as soon as they build. */
--casora-popup-plate-enter:
  casora-plate-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
@media (prefers-reduced-motion: reduce) {
  --casora-popup-plate-enter: none;
}

--casora-popup-hero-label-size: 15px;
--casora-popup-row-radius: 26px;
--casora-popup-plate-backdrop: blur(24px) saturate(180%);
/* The tiles and the room pills do blur - they are small, and an
   inactive tile with no blur reads as a hole rather than a control.
   Separate from the plate knob so this can go on its own. */
--casora-popup-tile-backdrop: blur(24px) saturate(180%);
--casora-popup-row-fill: var(--casora-sheet-row-fill, rgba(12, 14, 19, 0.62));
--casora-popup-chart-fill: var(--casora-sheet-chart-fill, rgba(10, 12, 16, 0.68));
/* The theme lifts every ha-card with filter: brightness(1.01) on
   hover, and a filter on an ancestor makes every backdrop-filter
   inside it inert - hovering the space around a plate knocked the
   frost out of it. Killed popup-wide; each plate re-declares its
   own shadow. */
--casora-card-hover-filter: none;
--casora-hover-filter: none;
--casora-card-hover-shadow: none;
/* Lifted, not slabbed: one wide soft pass carries the height, one
   short contact pass keeps the edge off the room. */
--casora-popup-plate-shadow: var(--casora-sheet-plate-shadow,
  0 18px 40px -22px rgba(0, 0, 0, 0.50),
  0 2px 8px -5px rgba(0, 0, 0, 0.28));

/* Nothing bare on the room but the close control, and that control
   is itself a glass object. The title is clipped rather than
   removed so a screen reader still gets it - the header widget
   below carries it on screen. */

/* The chrome arrives with the first plate instead of being there
   on frame one while everything under it fades in. */
--casora-popup-chrome-enter:
  casora-popup-chrome-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
.content { animation: none; }
/* The title lives in the bar now, centered and level with the
   close control, so it is no longer hidden. */
.header-title { font-size: 20px; font-weight: 600; letter-spacing: -0.01em; }
/* The toggle sits with the close rather than opposite it: two
   controls that belong to the same popup read as a pair, and the
   state reads left-to-right off the button it describes. The title
   is absolutely centered on the bar either way. */
.header-actions {
  order: 0;
  margin-left: 10px;
  margin-right: auto;
  padding-right: 0;
}
.header-close {
  border-radius: 50%;
  background: var(--casora-lp-close-bg, var(--casora-popup-row-fill, rgba(255, 255, 255, 0.10)));
  backdrop-filter: var(--casora-lp-close-backdrop, var(--casora-popup-plate-backdrop, none));
  -webkit-backdrop-filter: var(--casora-lp-close-backdrop, var(--casora-popup-plate-backdrop, none));
  box-shadow: var(--casora-lp-close-shadow, var(--casora-popup-plate-shadow, none));
  width: var(--casora-lp-close-size, 48px);
  height: var(--casora-lp-close-size, 48px);
  color: var(--casora-lp-close-ink, var(--casora-popup-header-title-color, var(--primary-text-color, #fff)));
}
/* Weich (soft) setzt diese Werte im Popup-Stil (style); ohne sie bleibt alles wie oben. */
.header {
  position: var(--casora-lp-head-pos, relative);
  top: 0; left: 0; right: 0;
  pointer-events: var(--casora-lp-head-pe, auto);
}
.header-nav {
  order: var(--casora-lp-close-order, 0);
  margin-left: var(--casora-lp-close-ml, 0px);
  translate: 0 var(--casora-lp-close-dy, 0px);
  pointer-events: auto;
}
.header-content { visibility: var(--casora-lp-title-vis, visible); }

ha-adaptive-dialog, ha-dialog, wa-drawer {
  --ha-card-backdrop-filter: none;
  --ha-card-background: transparent;
  --card-background-color: transparent;
  --ha-card-box-shadow: none;
  --ha-card-border-width: 0px;
}

.content .container > * {
  width: 100% !important;
  max-width: none !important;
  box-sizing: border-box !important;
}
.content .container {
  scrollbar-width: none;
  overscroll-behavior: contain;
  touch-action: pan-y;
  padding: 0 22px 24px 22px !important;
}
@media (max-width: 768px) {
  .content .container { padding: 0 0 24px 0 !important; }
  .header-actions { margin-left: auto !important; margin-right: 0 !important; }
}
.content .container::-webkit-scrollbar {
  display: none;
}
@media (max-width: 768px) {
wa-drawer {
    --size: calc(100dvh - env(safe-area-inset-top, 0px) - var(--casora-soft-sheet-gap, 0px)) !important;
    height: calc(100dvh - env(safe-area-inset-top, 0px) - var(--casora-soft-sheet-gap, 0px)) !important;
    min-height: calc(100dvh - env(safe-area-inset-top, 0px) - var(--casora-soft-sheet-gap, 0px)) !important;
}
.content .container {
    min-height: calc(100dvh - env(safe-area-inset-top, 0px) - var(--casora-soft-sheet-gap, 0px)) !important;
}
wa-drawer.casora-h-auto {
    --size: var(--ha-bottom-sheet-height, auto) !important;
    height: auto !important;
    min-height: 0 !important;
}
wa-drawer.casora-h-auto .content .container {
    min-height: 0 !important;
}
}

/* Popup-Standard (24.09.2026): Info-Popup - Abschnittsüberschriften in der Karte. */
--casora-lbl-in: block;
--casora-lbl-out: none;

