        + '   display: flex !important; flex-direction: column !important;'
        + '   box-sizing: border-box !important; }'
        /* min-height: 0 here was overriding the grid's own inline
           min-height: 100% and leaving `1fr` no slack to give. A
           viewport figure resolves against nothing above it:
           112 the surface top, 58 the header, 28 the card's own
           padding, 8 the bottom gap. */
        + ' #container { flex: 1 1 auto !important;'
        + '   min-height: calc(100svh - var(--casora-popup-top, 112px)'
        + '     - 58px - 28px - 8px'
        + '     - var(--safe-area-inset-bottom, 0px)) !important;'
        + '   box-sizing: border-box !important; } }'
        + '\n#container { background: transparent !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; }'
        /* Weich (E3): Etikett, Schalter und Liste stehen untereinander, nicht über die Sheet-Höhe verteilt. */
        + ((UI.soft && UI.soft()) ? '\n@media (max-width: 768px) { #container { min-height: 0 !important; align-content: start !important; } }' : '') },
      entity: groupId || undefined,
      tap_action: { action: 'none' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      styles: {
        card: [
          { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
          { padding: 'var(--casora-soft-card-top, 6px) 26px 22px 26px' },
        ],
        grid: [
          { 'grid-template-areas': areas.join(' ') },
          { 'grid-template-columns': '1fr' },
          // the toggle row takes the slack, so the rows sit at the bottom
          { 'grid-template-rows': (UI.soft && UI.soft()) ? 'auto' : 'auto 1fr auto' },
          { 'align-content': 'stretch' },
          { 'align-items': 'center' },
          { 'row-gap': 'var(--casora-popup-sec-gap, 18px)' },
          { 'min-height': '100%' },
        ],
        custom_fields: fstyle,
      },
      custom_fields: fields,
    };
    /* Returned bare, not wrapped in a one-card vertical-stack. The
       sheet's `height: 100%` is handed to `.content .container > *`,
       and a stack in between has none of its own to pass on - so the
       grid never got the slack its `1fr` row was there to absorb, and
       the tiles sat under the toggle instead of at the bottom. */
    /* Popup-Standard (24.09.2026): ab 761 px Status oben, links Schloss-Schalter, rechts die Schlösser. */
    return window._casoraStd ? window._casoraStd(uiCard, { left: ['tlbl', 'toggle'], right: ['locks'] }) : uiCard;
  }

  return { type: 'vertical-stack', cards: [headerCard, adviceCard, tilesCard] };
]]]

popup_styles.styles:
/* Popup content cards are not buttons: the theme's hover lift (shadow + brightness) made a
   whole column look like a raised card under the pointer (Weich audit M1). Killed popup-wide. */
--casora-card-hover-filter: none;
--casora-hover-filter: none;
--casora-card-hover-shadow: none;
/* The pane stays - these are control sheets. Only the close control
   keeps what it gained: a surface of its own, and room above it so
   the fill is not against the top edge of the sheet. */
.header { padding-top: var(--casora-popup-header-gap, 10px); }
/* Equal inset on both axes: the bar's own padding plus the
   close control's 2px optical nudge has to come to the same
   number as the padding above it, or the circle sits further
   from the left edge than it does from the top. */
--casora-popup-header-gap: 14px;
  --casora-popup-gutter-wide: 20px;
/* The chrome arrives with the first plate instead of being there
   on frame one while everything under it fades in. */
--casora-popup-chrome-enter:
  casora-popup-chrome-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
.header-title { font-size: 20px; font-weight: 600; letter-spacing: -0.01em; }
.header-close {
  border-radius: 50%;
  background: var(--casora-popup-row-fill, rgba(255, 255, 255, 0.10));
  backdrop-filter: var(--casora-popup-plate-backdrop, blur(24px) saturate(180%));
  -webkit-backdrop-filter: var(--casora-popup-plate-backdrop, blur(24px) saturate(180%));
  box-shadow: var(--casora-popup-plate-shadow, none);
}
/* The sheet is full height, so short content floats mid-screen. On
   a phone the card has to fill it for the grid's `1fr` row to have
   any slack to hand the toggle - otherwise the rows bunch under it
   instead of sitting at the bottom.
   Flex, not percentages: .content is `flex: 1 1 auto` inside a
   surface with only a max-height, so `min-height: 100%` here had no
   definite height to resolve against and computed to nothing. A
   flex chain gives every link a real height without one. */
@media (max-width: 768px) {
  /* The root cause, and why two attempts at the chain below did
     nothing: .surface is capped with max-height, never given one.
     A flex item in a content-sized container is itself
     content-sized, so every percentage under it resolved to
     nothing and the grid's `1fr` row had no slack to hand out.
     Same expression as its own max-height, as a height. */
  .surface {
    height: calc(100svh - var(--casora-popup-top, 112px) - 8px
                 - var(--safe-area-inset-bottom, 0px));
  }
  .content { display: flex; flex-direction: column; }
  /* A viewport unit, not a percentage. Every attempt to make this
     work by giving each link a definite height failed in the real
     DOM even though the chain measures correct in isolation - so
     the height is taken from the viewport directly and nothing has
     to resolve against a parent at all. 112 is the surface's top
     offset, 58 the header row, 8 the bottom gap. */
  .content .container {
    flex: 1 1 auto;
    min-height: calc(100svh - var(--casora-popup-top, 112px)
                     - 58px - 8px
                     - var(--safe-area-inset-bottom, 0px));
    display: flex; flex-direction: column; box-sizing: border-box;
  }
  /* The direct child AND anything HA wraps the card in: measured in
     isolation this chain resolves and the tiles land 8px off the
     bottom, so the only way it can still fail is a link in the real
     DOM that this does not name. */
  .content .container > *,
  .content .container hui-card,
  .content .container > * > * {
    flex: 1 1 auto; min-height: 0;
    display: flex; flex-direction: column;
  }
}
/* One measure for a control-plus-list popup, whatever the count.
   The rows are short and a wider sheet only stretches them; cover
   is the same shape and holds the same width. */
--popup-min-width: 900px;
--popup-max-width: 920px;

casora_popup.title:
[[[
  /* The lock badge's own `name:` is a template, and _config.name holds
     its raw source, so only a plain name may fall through to here.
     casoraPopupTitle drops a room name ("Home") as title. */
  if (window.casoraPopupTitle) return window.casoraPopupTitle(this, variables, 'Schlösser', ['Locks']);
  const n = String(this._config?.name || '').trim();
  return (variables.room_name || (n.startsWith('[[[') ? '' : n)).trim() || 'Schlösser';
]]]

casora_popup.content:
[[[
  /* Weich (E3, 01.10.2026): diese ältere Kopie zeigt im Weich-Design denselben entschlackten
     Inhalt wie tap_action (window._casoraSoftNet/_casoraSoftEnergy, 05-weich-mehr.js) – die
     Vorlage wertet dafür den Inhalt aus tap_action aus. Standard und Glas: unverändert. */
  if (window._casoraSoft && window._casoraSoft() && !window._casoraSoftFwd
      && this && typeof this._getTemplateOrValue === 'function') {
    const _nc = this._config && this._config.tap_action && this._config.tap_action.casora_popup
      && this._config.tap_action.casora_popup.content;
    if (typeof _nc === 'string' && _nc.trim().indexOf('[[[') === 0) {
      window._casoraSoftFwd = true;
      try { const _r = this._getTemplateOrValue(this._stateObj, _nc); if (_r && typeof _r === 'object') return _r; }
      catch (e) { console.warn('casora: Weich-Inhalt nicht verfügbar', e); }
      finally { window._casoraSoftFwd = false; }
    }
  }
  /* Helpers */

  const safeNum = (id) => {
    if (!id) return null;
    const s = states[id]?.state;
    if (!s || s === 'unavailable' || s === 'unknown') return null;
    const n = parseFloat(s);
    return isNaN(n) ? null : n;
  };

  const displayPrecision = (id) => {
    if (!id) return null;
    const reg = hass?.entities?.[id];
    if (reg?.display_precision != null) return reg.display_precision;
    const suggested = states[id]?.attributes?.suggested_display_precision;
    if (suggested != null) return suggested;
    return null;
  };

  const fmt = (v, id) => {
    if (v == null) return '—';
    const prec = displayPrecision(id);
    if (prec != null) return (window.casoraNum || ((x, a, b) => Number(x).toLocaleString(window.casoraLocale ? window.casoraLocale() : 'de-DE', { minimumFractionDigits: a, maximumFractionDigits: b == null ? a : b })))(v, prec);
    return v >= 100 ? Math.round(v).toString() : (window.casoraNum || ((x, a, b) => Number(x).toLocaleString(window.casoraLocale ? window.casoraLocale() : 'de-DE', { minimumFractionDigits: a, maximumFractionDigits: b == null ? a : b })))(v, 1);
  };

  const friendlyName = (id, fallback = 'Sensor') => {
    if (!id) return fallback;
    const raw = states[id]?.attributes?.friendly_name;
    if (raw) return raw;

    const slug = String(id).split('.')[1] || id;
    return slug
      .replace(/_/g, ' ')
      .replace(/(^|[^\p{L}\p{N}])(\p{L})/gu, (m, a, c) => a + c.toUpperCase());
  };

  const baseCard = {
    type: 'custom:button-card',
    show_icon: false,
    show_name: false,
    show_label: false,
    show_state: false,
  };


  /* Shared Local Styles */

  const noHoverStyle = `
    :host {
      --ha-card-box-shadow: none !important;
      --button-card-box-shadow: none !important;
      --button-card-box-shadow-hover: none !important;
    }

    ha-card {
      background: transparent !important;
      border: none !important;
      border-radius: 0 !important;
      box-shadow: none !important;
      backdrop-filter: none !important;
      -webkit-backdrop-filter: none !important;
      overflow: visible !important;
      cursor: default !important;
    }

    ha-card:hover {
      box-shadow: none !important;
      border-color: transparent !important;
    }

    ha-ripple {
      display: none !important;
    }
  `;

  const wrapperStyle = noHoverStyle;
  const contentCardStyle = noHoverStyle + `@media (max-width: 600px) { ha-card { padding-left: 14px !important; padding-right: 14px !important; } }`;

  const tileTapStyle = `
    :host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: inset 0 1px 0.5px -0.5px rgba(255,255,255,calc(var(--casora-popup-tiles-glow-top-tight,0.20) * 1.5)), inset 0 -1px 0.5px -0.5px rgba(255,255,255,calc(var(--casora-popup-tiles-glow-bottom-tight,0.15) * 1.5)), inset 0 3px 6px -3px rgba(255,255,255,calc(var(--casora-popup-tiles-glow-top-soft,0.08) * 1.5)), inset 0 -3px 6px -3px rgba(255,255,255,calc(var(--casora-popup-tiles-glow-bottom-soft,0.05) * 1.5)) !important; }
    ha-card { background: var(--casora-popup-tiles-fill, rgba(255,255,255,0.08)) !important; border: none !important; border-radius: 24px !important; box-shadow: inset 0 1px 0.5px -0.5px rgba(255,255,255,var(--casora-popup-tiles-glow-top-tight,0.20)), inset 0 -1px 0.5px -0.5px rgba(255,255,255,var(--casora-popup-tiles-glow-bottom-tight,0.15)), inset 0 3px 6px -3px rgba(255,255,255,var(--casora-popup-tiles-glow-top-soft,0.08)), inset 0 -3px 6px -3px rgba(255,255,255,var(--casora-popup-tiles-glow-bottom-soft,0.05)) !important; backdrop-filter: var(--casora-popup-tiles-backdrop, blur(10px) saturate(1.1)) !important; -webkit-backdrop-filter: var(--casora-popup-tiles-backdrop, blur(10px) saturate(1.1)) !important; cursor: pointer !important; transform: scale(1) !important; transition: background-color var(--casora-popup-tile-hover-duration, 0.2s) ease, transform var(--casora-popup-tile-hover-duration, 0.2s) ease, box-shadow 0.2s ease !important; }
    ha-card:hover { background: var(--casora-popup-tile-hover, rgba(255,255,255,0.09)) !important; transform: scale(var(--casora-popup-tile-hover-scale, 1.01)) !important; }
    ha-ripple { display: none !important; }
    @keyframes casora-action-swap { from { opacity:0; } to { opacity:1; } }
    @keyframes casora-ca-in { from { opacity:0; } to { opacity:1; } }
  `;

  const tapStyle = `
    :host {
      --ha-card-box-shadow: none !important;
      --button-card-box-shadow: none !important;
      --button-card-box-shadow-hover: none !important;
    }

    ha-card {
      background: transparent !important;
      border: none !important;
      border-radius: 0 !important;

      box-shadow: none !important;

      backdrop-filter: none !important;
      -webkit-backdrop-filter: none !important;

      overflow: visible !important;
    }

    ha-card #container {
      transition:
        opacity 0.18s ease,
        filter 0.18s ease !important;
    }

    ha-card:hover #container {

      opacity: 1;

      filter:
        brightness(1.12)
        saturate(1.08)
        drop-shadow(0 0 10px rgba(255,255,255,0.05));
    }

    ha-ripple {
      display: none !important;
    }
  `;

  /* Entity Resolution */

  const dlId =
    variables.entity_download ||
    entity?.entity_id;

  const ulId =
    variables.entity_upload ||
    variables.entity_stat_2;

  const statusId =
    variables.entity_status
    || Object.keys(states).find(id => /^binary_sensor\.\w*wan\w*_up\w*$/.test(id)
         && ['on', 'off'].includes(states[id]?.state))
    || null;

  const wiredDlId =
    variables.entity_stat_1 || variables.entity_wired_dl;

  const wiredUlId =
    variables.entity_stat_2 || variables.entity_wired_ul;

  const wifiDlId =
    variables.entity_stat_3 || variables.entity_wifi_dl;

  const wifiUlId =
    variables.entity_stat_4 || variables.entity_wifi_ul;

  const pingId = variables.entity_ping;

  const action1Id            = variables.action_1_entity         || null;
  const action1Label         = variables.action_1_label          || null;
  const action1Stat          = variables.action_1_status         || null;
  const action1ConfirmHelper = variables.action_1_confirm_helper
    || (action1Id ? 'input_boolean.casora_restart_confirm_1' : null);
  const action1DoneHelper    = variables.action_1_done_helper
    || (action1Id ? 'input_boolean.casora_restart_done_1'    : null);
  const action2Id            = variables.action_2_entity         || null;
  const action2Label         = variables.action_2_label          || null;
  const action2Stat          = variables.action_2_status         || null;
  const action2ConfirmHelper = variables.action_2_confirm_helper
    || (action2Id ? 'input_boolean.casora_restart_confirm_2' : null);
  const action2DoneHelper    = variables.action_2_done_helper
    || (action2Id ? 'input_boolean.casora_restart_done_2'    : null);
  const hasActions           = !!(action1Id || action2Id);

  /* Values */

  const dl = safeNum(dlId);
  const ul = safeNum(ulId);

  const _ck = 'casora_network_v2_' + (dlId || 'x');
  const _ch = [states[dlId]?.state, states[ulId]?.state, states[statusId]?.state, states[wiredDlId]?.state, states[wiredUlId]?.state, states[wifiDlId]?.state, states[wifiUlId]?.state, states[pingId]?.state, states[action1Stat]?.state, states[action2Stat]?.state, states[action1ConfirmHelper]?.state, states[action2ConfirmHelper]?.state, states[action1DoneHelper]?.state, states[action2DoneHelper]?.state, hass?.entities?.[action1Stat]?.name, hass?.entities?.[action2Stat]?.name, hass?.entities?.[action1Id]?.name, hass?.entities?.[action2Id]?.name].join('|');
  window._hc = window._hc || {};
  if (window._hc[_ck]?.h === _ch) return window._hc[_ck].r;

  const _memoSub = (subKey, dep, factory) => {
    const key = _ck + '_' + subKey;
    if (window._hc[key]?.h === dep) return window._hc[key].r;
    const r = factory();
    window._hc[key] = { h: dep, r };
    return r;
  };

  const dlOk = Number.isFinite(dl);
  const ulOk = Number.isFinite(ul);

  /* Status */

  const _stRaw0 = statusId ? states[statusId]?.state : null;
  // No usable status entity: live download/upload values mean the line is up.
  const statusRaw = (_stRaw0 === 'on' || _stRaw0 === 'off')
    ? _stRaw0
    : ((Number.isFinite(dl) || Number.isFinite(ul)) ? 'on' : null);
  const online = statusRaw === 'on';

  const statusLabel = statusRaw
    ? (online ? 'Online' : 'Offline')
    : '—';

  const statusColor = online
    ? 'var(--casora-badge-network-online-color, #44e371)'
    : (
        statusRaw
          ? 'var(--casora-badge-network-offline-color, #ff4245)'
          : 'rgba(255,255,255,0.4)'
      );

  /* Advice */

  const roomName = variables.room_name || 'Netzwerk';

  const idle = Number(variables.idle_threshold ?? 1);
  const light = Number(variables.light_threshold ?? 10);
  const heavy = Number(variables.heavy_threshold ?? 50);

  const _allVals = [dl, ul,
    safeNum(wiredDlId), safeNum(wiredUlId),
    safeNum(wifiDlId),  safeNum(wifiUlId),
  ].filter(v => v != null);
  const max = _allVals.length > 0 ? Math.max(..._allVals) : 0;

  const tier = max < idle
    ? 'Inaktiv'
    : max < light
      ? 'Gering'
      : max < heavy
        ? 'Aktiv'
        : 'Hoch';

  // Judged from WAN dl/ul, not the wired/wifi tiles below.
  const dir = (!dlOk || (ulOk && ul > dl)) ? 'Upload' : 'Download';

  let advice;

  if (dlOk || ulOk) {
    advice = max < idle
      ? 'Kaum Aktivität'
      : ({ Gering: 'Geringer', Aktiv: 'Aktiver', Hoch: 'Starker' }[tier] || tier) + ' ' + dir;
  } else if (statusRaw) {
    advice = online
      ? 'Verbindung stabil'
      : 'Keine Verbindung';
  } else {
    advice = 'Keine Statusdaten';
  }

  /* Ping Gauge */

  const ping = safeNum(pingId);
  const pingMax = 200;
  const pingRadius = 42;
  const pingCircumference = 2 * Math.PI * pingRadius;
  const pingProgress = ping != null ? 1 - Math.min(ping / pingMax, 1) : 0;
  const pingDashOffset = pingCircumference - (pingProgress * pingCircumference);

  let pingColor = 'var(--casora-popup-green-color, #30D158)';
  if (ping == null) {
    pingColor = 'rgba(255,255,255,0.15)';
  } else if (ping >= 150) {
    pingColor = 'var(--casora-popup-red-color, #ff4245)';
  } else if (ping >= 60) {
    pingColor = 'var(--casora-popup-orange-color, #ff9230)';
  } else if (ping >= 20) {
    pingColor = 'var(--casora-popup-yellow-color, #ffd600)';
  }

  const fmtPing = (v) => v == null ? '—' : String(Math.round(v));

  /* Stat Cards */

  const dlStatCard = {
    ...baseCard,
    entity: dlId,
    tap_action: { action: 'more-info' },
    card_mod: { style: tapStyle },
    styles: {
      card: [
        { background: 'transparent' },
        { border: 'none' },
        { 'box-shadow': 'none' },
        { padding: '0' },
      ],
      grid: [
        { 'grid-template-areas': '"c"' },
        { 'grid-template-columns': '1fr' },
      ],
      custom_fields: {
        c: [{ 'justify-self': 'start' }],
      },
    },
    custom_fields: {
      c: `[[[
        const s = states['${dlId}'];
        const v = parseFloat(s?.state);
        const prec = hass?.entities?.['${dlId}']?.display_precision ?? s?.attributes?.suggested_display_precision ?? null;
        const d = isNaN(v) ? '—' : (prec != null ? (window.casoraNum || ((x, a, b) => Number(x).toLocaleString(window.casoraLocale ? window.casoraLocale() : 'de-DE', { minimumFractionDigits: a, maximumFractionDigits: b == null ? a : b })))(v, prec) : (v >= 100 ? Math.round(v).toString() : (window.casoraNum || ((x, a, b) => Number(x).toLocaleString(window.casoraLocale ? window.casoraLocale() : 'de-DE', { minimumFractionDigits: a, maximumFractionDigits: b == null ? a : b })))(v, 1)));
        return '<div>'
          + '<div style="display:flex;align-items:baseline;gap:4px;padding-right:6px;">'
          + '<span style="font-size:26px;font-weight:400;color:var(--casora-popup-tiles-text-primary);line-height:1.15;">' + d + '</span>'
          + '<span style="font-size:14px;color:var(--casora-popup-tiles-text-secondary);">Mbit/s</span>'
          + '</div>'
          + '<div style="display:flex;align-items:center;gap:6px;margin-top:7px;">'
          + '<span style="width:8px;height:8px;background:var(--casora-badge-network-low-color, #44e371);border-radius:50%;display:inline-block;flex-shrink:0;"></span>'
          + '<span style="font-size:14px;color:var(--casora-popup-tiles-text-secondary);">Download</span>'
          + '</div>'
          + '</div>';
      ]]]`,
    },
  };

  const ulStatCard = {
    ...baseCard,
    entity: ulId || dlId,
    tap_action: ulId ? { action: 'more-info' } : { action: 'none' },
    card_mod: { style: ulId ? tapStyle : noHoverStyle },
    styles: {
      card: [
        { background: 'transparent' },
        { border: 'none' },
        { 'box-shadow': 'none' },
        { padding: '0' },
      ],
      grid: [
        { 'grid-template-areas': '"c"' },
        { 'grid-template-columns': '1fr' },
      ],
      custom_fields: {
        c: [{ 'justify-self': 'start' }],
      },
    },
    custom_fields: {
      c: `[[[
        const s = states['${ulId || dlId}'];
        const v = parseFloat(s?.state);
        const prec = hass?.entities?.['${ulId || dlId}']?.display_precision ?? s?.attributes?.suggested_display_precision ?? null;
        const d = isNaN(v) ? '—' : (prec != null ? (window.casoraNum || ((x, a, b) => Number(x).toLocaleString(window.casoraLocale ? window.casoraLocale() : 'de-DE', { minimumFractionDigits: a, maximumFractionDigits: b == null ? a : b })))(v, prec) : (v >= 100 ? Math.round(v).toString() : (window.casoraNum || ((x, a, b) => Number(x).toLocaleString(window.casoraLocale ? window.casoraLocale() : 'de-DE', { minimumFractionDigits: a, maximumFractionDigits: b == null ? a : b })))(v, 1)));
        return '<div>'
          + '<div style="display:flex;align-items:baseline;gap:4px;padding-left:6px;">'
          + '<span style="font-size:26px;font-weight:400;color:var(--casora-popup-tiles-text-primary);line-height:1.15;">' + d + '</span>'
          + '<span style="font-size:14px;color:var(--casora-popup-tiles-text-secondary);">Mbit/s</span>'
          + '</div>'
          + '<div style="display:flex;align-items:center;gap:6px;margin-top:7px;margin-left:6px;">'
          + '<span style="width:8px;height:8px;background:var(--casora-badge-network-active-color, #ffd600);border-radius:50%;display:inline-block;flex-shrink:0;"></span>'
          + '<span style="font-size:14px;color:var(--casora-popup-tiles-text-secondary);">Upload</span>'
          + '</div>'
          + '</div>';
      ]]]`,
    },
  };

  const statsWrapperCard = {
    ...baseCard,
    entity: dlId,
    tap_action: { action: 'none' },
    card_mod: { style: wrapperStyle },
    styles: {
      card: [
