    const infoPE = (_ch || _dh)
      ? `[[[return (states['${_ch}']?.state === 'on' || states['${_dh}']?.state === 'on') ? 'none' : 'auto']]]`
      : 'auto';
    // animation-fill-mode:both applies from{opacity:0} the same tick display:flex takes effect.
    const caVisible = _ch
      ? `states['${_ch}']?.state === 'on' && states['${_dh}']?.state !== 'on'`
      : 'false';
    const caDisplay      = _ch ? `[[[return ${caVisible} ? 'flex' : 'none']]]` : 'none';
    const caContainerAnim = _ch ? `[[[return ${caVisible} ? 'casora-ca-in' : 'none']]]` : 'none';

    /* Info field */
    const infoField = _sid ? `[[[
      const sid = '${_sid}', name = '${_esc}';
      const ss = states[sid];
      const unav = !ss || ss.state === 'unavailable' || ss.state === 'unknown';
      let stc = 'rgba(255,255,255,0.4)', stt = unav ? 'Unbekannt' : null;
      if (!unav) { if (ss.state === 'on') { stt = 'Verbunden'; stc = 'var(--casora-badge-network-online-color,#44e371)'; } else { stt = 'Offline'; stc = 'var(--casora-badge-network-offline-color,#ff4245)'; } }
      const sr = stt ? '<div style="margin-top:0;"><span style="font-size:12px;color:' + stc + ';font-weight:500;letter-spacing:.01em;">' + stt + '</span></div>' : '';
      return '<div style="display:flex;flex-direction:column;align-items:flex-start;">'
        + '<span style="font-size:13px;font-weight:600;color:var(--casora-popup-tiles-text-primary);letter-spacing:.01em;white-space:nowrap;">' + name + '</span>'
        + sr + '</div>';
    ]]]` : '<div style="display:flex;flex-direction:column;align-items:flex-start;"><span style="font-size:13px;font-weight:600;color:var(--casora-popup-tiles-text-primary);letter-spacing:.01em;white-space:nowrap;">' + nameLabel + '</span></div>';

    /* Outer tile */
    const outerTap = _ch ? {
      action: `[[[return states['${_ch}']?.state === 'on' ? 'call-service' : '${_sid || entityId ? 'more-info' : 'none'}']]]`,
      service: 'input_boolean.turn_off',
      service_data: { entity_id: _ch },
      entity: statusId || entityId,
    } : (statusId ? { action: 'more-info', entity: statusId } : (entityId ? { action: 'more-info' } : { action: 'none' }));

    return {
      ...baseCard,
      entity: entityId || dlId,
      tap_action: outerTap,
      card_mod: { style: tileTapStyle },
      styles: {
        card: [{ padding: '18px 18px 16px 18px' }],
        grid: [{ display: 'flex' }, { 'flex-direction': 'row' }, { 'align-items': 'center' }, { gap: '10px' }],
        custom_fields: {
          icon:   [{ flex: '0 0 auto' }],
          info:   [{ flex: '1 1 auto' }, { 'min-width': '0' }, { 'text-align': 'left' }, { transition: 'opacity 0.3s ease' }, { opacity: infoOpacity }, { 'pointer-events': infoPE }],
          ca:     [{ 'flex-shrink': '0' }, { overflow: 'hidden' }, { display: caDisplay }, { 'animation-name': caContainerAnim }, { 'animation-duration': '0.3s' }, { 'animation-timing-function': 'ease' }, { 'animation-fill-mode': 'both' }],
          action: [{ 'flex-shrink': '0' }, { 'animation-name': actionContainerAnim }, { 'animation-duration': '0.3s' }, { 'animation-timing-function': 'ease' }, { 'animation-fill-mode': 'both' }],
        },
      },
      custom_fields: {
        icon:   '<ha-icon icon="' + iconAttr + '" style="--mdc-icon-size:22px;width:22px;height:22px;display:flex;align-items:center;justify-content:center;flex-shrink:0;color:var(--casora-popup-tiles-text-muted);"></ha-icon>',
        info:   infoField,
        ca:     { card: cancelPillCard },
        action: entityId ? { card: actionPillCard } : '<div></div>',
      },
    };
  };

  const actionCount = (action1Id ? 1 : 0) + (action2Id ? 1 : 0);
  const actionAreas = actionCount === 1 ? (action1Id ? '"a1"' : '"a2"') : '"a1 a2"';
  const actionCols  = actionCount === 1 ? '1fr' : '1fr 1fr';

  const actionsCard = hasActions ? {
    ...baseCard,
    entity: dlId,
    tap_action: { action: 'none' },
    card_mod: { style: contentCardStyle + '\n@media (max-width:600px){#container{grid-template-columns:1fr !important;grid-template-areas:"a1" "a2" !important;}}' },
    styles: {
      card: [
        { background: 'transparent' },
        { border: 'none' },
        { 'box-shadow': 'none' },
        { padding: '0 28px 20px 28px' },
      ],
      grid: [
        { 'grid-template-areas': actionAreas },
        { 'grid-template-columns': actionCols },
        { gap: '8px' },
        { 'align-items': 'start' },
      ],
      custom_fields: {
        a1: [{ 'grid-area': 'a1' }, { 'justify-self': 'stretch' }],
        a2: [{ 'grid-area': 'a2' }, { 'justify-self': 'stretch' }],
      },
    },
    custom_fields: {
      a1: action1Id ? { card: makeActionButton(action1Id, action1Label, action1Stat, action1ConfirmHelper, action1DoneHelper) } : '<div></div>',
      a2: action2Id ? { card: makeActionButton(action2Id, action2Label, action2Stat, action2ConfirmHelper, action2DoneHelper) } : '<div></div>',
    },
  } : null;

  /* Final Stack */

  /* Shared popup anatomy. The advice caption becomes the hero, the
     Download|Upload block becomes the graph's own legend, and the four
     tiles plus the restart buttons become grouped rows. */
  const UI = window._casoraUI;
  let _cards;
  if (UI) {
    const _LANG = hass?.locale?.language || hass?.language || 'de';
    const fmt = (v) => v == null ? '\u2014' : (v >= 100 ? Math.round(v) : Math.round(v * 10) / 10).toLocaleString(_LANG);
    const dlCol = 'var(--casora-chart-c1, #5C93D6)';
    const ulCol = 'var(--casora-chart-c2, #CF7840)';

    const areas = [], fields = {}, fstyle = {};
    const add = (name, html) => {
      areas.push('"' + name + '"');
      fields[name] = html;
      fstyle[name] = [{ 'justify-self': 'stretch' }, { overflow: 'visible' }];
    };

    const tone = !online ? 'bad' : (tier === 'Hoch' ? 'warn' : 'good');
    const metricAreas = [], metricFields = {}, metricStyle = {};
    const addMetric = (n2, html) => {
      metricAreas.push('"' + n2 + '"');
      metricFields[n2] = html;
      metricStyle[n2] = [{ 'justify-self': 'stretch' }, { overflow: 'visible' }];
    };

    addMetric('head', UI.hero({
      compact: true,
      label: 'Verbindung',
      read: '*',
      value: online ? advice : 'Offline',
      trailingLabel: ping != null ? 'Ping' : null,
      trailing: ping != null ? Math.round(ping) + ' ms' : null,
    }));

    /* The chart goes under the number it explains, not at the foot of
       the sheet. Health, Battery and Stocks all do this: headline,
       chart, then the lists. It was last only because that is where the
       pre-redesign layout left it. As a field inside the content card
       rather than a sibling in the stack, so it can sit between the
       hero and the first group - and the side gutter comes from the
       card, so the chart drops its own. */
    addMetric('chart', { card: graphCard });
    addMetric('legend', UI.legend([
      { color: dlCol, value: fmt(dl), label: 'Mbit/s Download' },
      { color: ulCol, value: fmt(ul), label: 'Mbit/s Upload' },
    ]));

    const throughput = [];
    const push = (label, icon, id) => {
      const v = safeNum(id);
      if (id) throughput.push({ icon: icon,
        iconTone: /upload/i.test(label) ? ulCol : dlCol,
        label: label, value: fmt(v) + ' Mbit/s', entity: id });
    };
    push('LAN-Download', 'arrow-down', wiredDlId);
    push('LAN-Upload',   'arrow-up',   wiredUlId);
    push('WLAN-Download', 'wifi',       wifiDlId);
    push('WLAN-Upload',   'wifi',       wifiUlId);
    if (throughput.length) {
      add('tp', UI.group(throughput, null, null, { labelInside: true }));
    }

    /* Confirm lives in the row and is entirely client-side: the popup
       content is built once, so anything that needs the template to
       re-evaluate cannot update in place. */
    const devices = [];
    const nameFor = (id, label, statId) => label
      || (statId && (hass?.entities?.[statId]?.name || states[statId]?.attributes?.friendly_name))
      || hass?.entities?.[id]?.name
      || states[id]?.attributes?.friendly_name
      || (id ? id.split('.')[1].replace(/_/g, ' ').replace(/(^|[^\p{L}\p{N}])(\p{L})/gu, (m, a, c) => a + c.toUpperCase()) : 'Gerät');
    const deviceGlyph = (id, label) => {
      const t = ((label || '') + ' ' + (id || '')).toLowerCase();
      if (/mesh|wifi|wi-fi|access.?point|ap\b/.test(t)) return 'mesh';
      if (/internet|wan|status|modem|gateway|isp/.test(t)) return 'network';
      return 'access_point';
    };
    const addDevice = (id, label, statId) => {
      if (!id) return;
      const dom = id.split('.')[0];
      devices.push({
        icon: deviceGlyph(id, nameFor(id, label, statId)),
        label: nameFor(id, label, statId),
        entity: statId || id,
        action: 'Neu starten',
        confirm: true,
        svc: dom === 'button'
          ? { domain: 'button', service: 'press', target: { entity_id: id } }
          : { domain: 'homeassistant', service: 'turn_on', target: { entity_id: id } },
      });
    };
    addDevice(action1Id, action1Label, action1Stat);
    addDevice(action2Id, action2Label, action2Stat);
    if (devices.length) {
      add('dev', UI.group(devices, null, null, { labelInside: true }));
    }

    /* One object: the number, its status and the curve it describes, on
       a single plate. They were two stacked blocks - a floating stat
       with a graph under it - which is the part that never read as
       Apple. Health, Battery and Stocks all bind the headline to the
       chart. The plate moved here from the chart card, which is
       transparent inside it now. */
    const metricCard = {
      type: 'custom:button-card',
      tap_action: { action: 'none' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      extra_styles: '@keyframes casora-plate-hold { from, to { opacity: 0; } }'
        + ' @keyframes casora-plate-in {'
        + ' from { opacity: 0; transform: perspective(900px) translateZ(-70px); }'
        + ' to { opacity: 1; transform: perspective(900px) translateZ(0); } }'
        + ' ha-card { animation: var(--casora-popup-plate-enter, none);'
        + ' animation-delay: var(--casora-popup-plate-delay, 0ms); }',
      card_mod: { style: [
        ':host { --ha-card-box-shadow: none !important;'
          + ' --button-card-box-shadow: none !important;'
          + ' --button-card-box-shadow-hover: var(--casora-popup-plate-shadow, none) !important;'
          + ' --casora-card-hover-shadow: var(--casora-popup-plate-shadow, none) !important;'
          + ' --casora-card-hover-filter: none !important;'
          + ' --casora-hover-filter: none !important;'
          + ' --ha-card-backdrop-filter: none !important; }',
        'ha-card { background: var(--casora-popup-chart-fill, rgba(0,0,0,0.26)) !important;'
          + ' border: none !important;'
          + ' border-radius: var(--casora-popup-row-radius, 20px) !important;'
          + ' box-shadow: var(--casora-popup-plate-shadow, none) !important;'
          + ' backdrop-filter: var(--casora-popup-plate-backdrop, none) !important;'
          + ' -webkit-backdrop-filter: var(--casora-popup-plate-backdrop, none) !important;'
          + ' overflow: visible !important;'
          + ' will-change: auto !important; cursor: default !important; }',
        '#container > * { --casora-card-hover-shadow: none !important;'
          + ' --button-card-box-shadow-hover: none !important; }',
        'ha-card::before, ha-card::after { display: none !important; }',
        'ha-card:hover { box-shadow: var(--casora-popup-plate-shadow, none) !important;'
          + ' background: var(--casora-popup-chart-fill, rgba(0,0,0,0.26)) !important;'
          + ' border-color: transparent !important; filter: none !important; }',
        'ha-ripple { display: none !important; }',
      ].join('\n') },
      styles: {
        card: [
          { background: 'var(--casora-popup-chart-fill, rgba(0,0,0,0.26))' },
          { 'border-radius': 'var(--casora-popup-row-radius, 20px)' },
          { 'backdrop-filter': 'var(--casora-popup-plate-backdrop, none)' },
          { '-webkit-backdrop-filter': 'var(--casora-popup-plate-backdrop, none)' },
          { 'box-shadow': 'var(--casora-popup-plate-shadow, none)' },
          { border: 'none' }, { padding: '30px 28px 26px 28px' },
        ],
        grid: [{ 'grid-template-areas': metricAreas.join(' ') },
               { 'grid-template-columns': 'minmax(0, 1fr)' },
               { 'row-gap': '0' }],
        custom_fields: metricStyle,
      },
      custom_fields: metricFields,
    };
    areas.unshift('"metric"');
    fields.metric = { card: metricCard };
    fstyle.metric = [{ 'justify-self': 'stretch' }, { overflow: 'visible' }];

    const aside = fstyle.dev ? 'dev' : null;
    const mainAreas = areas
      .map((a) => a.replace(/"/g, ''))
      .filter((k) => k !== aside);
    const sideBySide = !!aside && mainAreas.length >= 1;
    const sideAreas = sideBySide
      ? mainAreas.map((k, i) => '"' + k + ' ' + (i === 0 ? aside : '.') + '"').join(' ')
      : '';

    const order = sideBySide ? [mainAreas[0], aside].concat(mainAreas.slice(1))
                             : areas.map((a) => a.replace(/"/g, ''));
    order.forEach((key, i) => {
      if (fstyle[key]) {
        fstyle[key].push({ '--casora-popup-plate-delay': (i * 55) + 'ms' });
      }
    });


    const uiCard = {
      type: 'custom:button-card',
      card_mod: { style: contentCardStyle
        + '\nha-card { will-change: auto !important; }' },
      extra_styles: sideBySide
        ? '@media (max-width: 760px) { #container {'
          + ' grid-template-areas: ' + areas.join(' ') + ' !important;'
          + ' grid-template-columns: minmax(0, 1fr) !important; } }'
        : undefined,
      tap_action: { action: 'none' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      styles: {
        card: [
          { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
          { padding: 'var(--casora-soft-card-top, 6px) 26px 22px 26px' },
        ],
        grid: [
          { 'grid-template-areas': sideBySide ? sideAreas : areas.join(' ') },
          { 'grid-template-columns': sideBySide
              ? 'minmax(0, 1fr) fit-content(var(--casora-popup-aside-max, 420px))'
              : 'minmax(0, 1fr)' },
          { 'row-gap': 'var(--casora-popup-sec-gap, 18px)' },
          { 'column-gap': 'var(--casora-popup-col-gap, 18px)' },
          { 'align-items': 'start' },
        ],
        custom_fields: fstyle,
      },
      custom_fields: fields,
    };


    _cards = [uiCard];
  } else {
    _cards = [headerCard, graphCard, tilesCard];
    if (hasActions) _cards.push(actionsCard);
  }
  const _r = { type: 'vertical-stack', cards: _cards };
  window._hc[_ck] = { h: _ch, r: _r };
  return _r;
]]]

popup_styles.styles:
--casora-popup-plate-enter:
  casora-plate-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
@media (prefers-reduced-motion: reduce) {
  --casora-popup-plate-enter: none;
}

/* Eine Popup-Familie (01.10.2026): dieselbe Sheet-Fläche wie die Bedien-Popups –
   Fläche, Blur, Schatten und Abdunklung aus dem Standard, Höhe folgt dem Inhalt,
   Schließen-Kreuz mit demselben Abstand zur Sheet-Kante. */
.header { padding-top: var(--casora-popup-header-gap, 10px); }
--casora-popup-header-gap: 14px;
/* The totals read as one line when the label is a hair from the
   number - "This month" was touching "36 kWh". */
--casora-popup-value-gap-wide: 28px;
--casora-popup-gutter-wide: 34px;
--casora-popup-gutter-phone: 22px;

/* Held. A chart has to fetch its history, so revealing the widgets
   first only meant watching the graph arrive late. casora-popup
   stamps data-casora-charts-ready once every chart in the popup has
   drawn, or gives up on one that never will, and the entry below
   swaps the hold for the entrance. Read by each widget for itself,
   never by a wrapper. */
--casora-popup-plate-enter: casora-plate-hold 10s linear both;

/* Wide enough for the aside. .surface already caps itself at
   calc(100vw - 16px), so a narrow screen shrinks rather than
   overflows, and the grid collapses to one column under 760px. */
--popup-min-width: 900px;
--popup-max-width: 920px;
--casora-popup-aside-w: 300px;

--casora-popup-hero-label-size: 15px;
--casora-popup-row-radius: 26px;
/* Frosted, not opaque. The pane's blur used to sit under these, and
   .content still nulls --ha-card-backdrop-filter for every card in
   the popup, so the frost has to be asked for here. The fills drop
   to let it read. */
/* The theme lifts every ha-card with filter: brightness(1.01) on
   hover. A filter on an ancestor makes every descendant's
   backdrop-filter inert, so hovering the empty space around a
   widget - the wrapper card - knocked the frost out of both of
   them. Killed popup-wide; the plate re-declares its own shadow. */
--casora-card-hover-filter: none;
--casora-hover-filter: none;
--casora-card-hover-shadow: none;

--casora-popup-row-pad-x: 26px;
--casora-popup-row-pad-y: 15px;
--casora-popup-plate-backdrop: blur(24px) saturate(180%);
--casora-popup-chart-fill: var(--casora-sheet-chart-fill, rgba(10, 12, 16, 0.68));
--casora-popup-row-fill: var(--casora-sheet-row-fill, rgba(12, 14, 19, 0.62));
/* Lifted, not slabbed: one wide soft pass carries the height, one
   short contact pass keeps the edge from dissolving into the room. */
--casora-popup-plate-shadow: var(--casora-sheet-plate-shadow,
  0 18px 40px -22px rgba(0, 0, 0, 0.50),
  0 2px 8px -5px rgba(0, 0, 0, 0.28));

/* visionOS puts nothing bare on the room: the only chrome outside a
   window is its close control, and that control is itself a glass
   object. The title was printed twice - here and in the widget
   eight pixels below - so it goes, clipped rather than removed so a
   screen reader still gets it. */

/* The chrome arrives with the first plate instead of being there
   on frame one while everything under it fades in. */
--casora-popup-chrome-enter:
  casora-popup-chrome-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
.content { animation: none; }
/* The title lives in the bar now, centered and level with the
   close control, so it is no longer hidden. */
.header-title { font-size: 20px; font-weight: 600; letter-spacing: -0.01em; }
/* 48px is left alone: the base sizes it so the glyph's ink lands on
   the same left margin as the widgets below. */
.header-close {
  border-radius: 50%;
  background: var(--casora-popup-row-fill, rgba(255, 255, 255, 0.10));
  backdrop-filter: var(--casora-popup-plate-backdrop, none);
  -webkit-backdrop-filter: var(--casora-popup-plate-backdrop, none);
  box-shadow: var(--casora-popup-plate-shadow, none);
}

ha-adaptive-dialog, ha-dialog, wa-drawer {
  --ha-card-backdrop-filter: none;
  --ha-card-background: transparent;
  --card-background-color: transparent;
  --ha-card-box-shadow: none;
  --ha-card-border-width: 0px;
}

/* Popup-Standard (24.09.2026): Info-Popup - Abschnittsüberschriften in der Karte. */
--casora-lbl-in: block;
--casora-lbl-out: none;

casora_popup.content:
[[[
  /* Helpers */

  const safeNum = (id) => {
    if (!id) return null;
    const s = states[id]?.state;
    if (!s || s === 'unavailable' || s === 'unknown') return null;
    const n = parseFloat(s);
    return isNaN(n) ? null : n;
  };

  const displayPrecision = (id) => {
    if (!id) return null;
    const reg = hass?.entities?.[id];
    if (reg?.display_precision != null) return reg.display_precision;
    const suggested = states[id]?.attributes?.suggested_display_precision;
    if (suggested != null) return suggested;
    return null;
  };

  const fmt = (v, id) => {
    if (v == null) return '—';
    const prec = displayPrecision(id);
    if (prec != null) return (window.casoraNum || ((x, a, b) => Number(x).toLocaleString(window.casoraLocale ? window.casoraLocale() : 'de-DE', { minimumFractionDigits: a, maximumFractionDigits: b == null ? a : b })))(v, prec);
    return v >= 100 ? Math.round(v).toString() : (window.casoraNum || ((x, a, b) => Number(x).toLocaleString(window.casoraLocale ? window.casoraLocale() : 'de-DE', { minimumFractionDigits: a, maximumFractionDigits: b == null ? a : b })))(v, 1);
  };

  const friendlyName = (id, fallback = 'Sensor') => {
    if (!id) return fallback;
    const raw = states[id]?.attributes?.friendly_name;
    if (raw) return raw;

    const slug = String(id).split('.')[1] || id;
    return slug
      .replace(/_/g, ' ')
      .replace(/(^|[^\p{L}\p{N}])(\p{L})/gu, (m, a, c) => a + c.toUpperCase());
  };

  const baseCard = {
    type: 'custom:button-card',
    show_icon: false,
    show_name: false,
    show_label: false,
    show_state: false,
  };


  /* Shared Local Styles */

  const noHoverStyle = `
    :host {
      --ha-card-box-shadow: none !important;
      --button-card-box-shadow: none !important;
      --button-card-box-shadow-hover: none !important;
    }

    ha-card {
      background: transparent !important;
      border: none !important;
      border-radius: 0 !important;
      box-shadow: none !important;
      backdrop-filter: none !important;
      -webkit-backdrop-filter: none !important;
      overflow: visible !important;
      cursor: default !important;
    }

    ha-card:hover {
      box-shadow: none !important;
      border-color: transparent !important;
    }

    ha-ripple {
      display: none !important;
    }
  `;

  const wrapperStyle = noHoverStyle;
  const contentCardStyle = noHoverStyle + `@media (max-width: 600px) { ha-card { padding-left: 14px !important; padding-right: 14px !important; } }`;

