            { 'grid-template-areas': sideBySide ? sideAreas : areas.join(' ') },
            { 'grid-template-columns': sideBySide
                ? 'minmax(0, 1fr) fit-content(var(--casora-popup-aside-max, 420px))'
                : 'minmax(0, 1fr)' },
            { 'row-gap': 'var(--casora-popup-sec-gap, 18px)' },
            { 'column-gap': 'var(--casora-popup-col-gap, 18px)' },
