casora_popup.content:
[[[
  const updateIds = Object.keys(states).filter(id => id.startsWith('update.'));
  const _allIds = JSON.stringify(updateIds);
  const updates = updateIds.map(id => states[id])
    .filter(e => e.state === 'on')
    .sort((a, b) =>
      (a.attributes.friendly_name || a.entity_id)
        .localeCompare(b.attributes.friendly_name || b.entity_id)
    );

  const restartEntities = updateIds.map(id => states[id])
    .filter(e => {
      const rs = (e.attributes.release_summary || '').toLowerCase();
      return rs.includes('restart') && e.state === 'off' && e.attributes.installed_version === e.attributes.latest_version;
    })
    .sort((a, b) =>
      (a.attributes.friendly_name || a.entity_id)
        .localeCompare(b.attributes.friendly_name || b.entity_id)
    );

  /* Styles */
  const noHoverStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; }',
    'ha-card { background: transparent !important; border: none !important; border-radius: 0 !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; cursor: default !important; }',
    'ha-card:hover { box-shadow: none !important; border-color: transparent !important; }',
    'ha-ripple { display: none !important; }',
  ].join('\n') + '\n@media (max-width: 600px) { ha-card { padding-left: 14px !important; padding-right: 14px !important; } }';

  /* Shared popup anatomy: hero, then grouped rows. The glass status pill
     and the advice sentence are both gone - the state is the hero and
     the action is a button only when there is something to do. */
  const UI = window._casoraUI;
  if (UI) {
