    const WARN = 'var(--casora-popup-ui-warn, #FF9F0A)';

    /* Counted in a nested template, which the parent card re-evaluates
       on every update.* state change - reading each id through the
       states Proxy is what subscribes it. Everything about the heading
       moves once the installs finish: the caption, the label, the tint
       and the service, and none of it can be settled here, because the
       popup's card is built once at open and never again. */
    const headCount = ' const _ids = ' + _allIds + ';'
      + ' const _pending = []; let _rest = 0; const _inst = []; const _aiS = states["sensor.casora_update_ki_analyse"];'
      + ' _ids.forEach(function (id) {'
      + '   const s = states[id]; if (!s) return;'
      + '   const a = s.attributes || {};'
      + '   if (s.state === "on") { if (!a.in_progress) { _pending.push(id); if (!(window._casoraUpdAiBlocked && window._casoraUpdAiBlocked(id, states))) _inst.push(id); } return; }'
      + '   if (String(a.release_summary || "").toLowerCase().indexOf("restart") !== -1'
      + '       && a.installed_version && a.installed_version === a.latest_version) _rest++;'
      + ' });'
      + ' const _waiting = !_pending.length && _rest > 0;';

    /* 1.0.5: Auch ohne offene Updates, wenn ein Neustart aussteht – Kopf und Liste sind live
       (Kopf: „Wartet auf Neustart“ + „Jetzt neu starten“, Liste: die Neustart-Zeilen). */
    if (n || restartEntities.length) {
      const rows = updates.map(e => ({
        entity: e.entity_id,
        iconTone: 'rgba(0,0,0,0)', image: logoOf(e),
        label: nameOf(e),
        /* Erste Zeile der Kurzfassung, falls die Integration eine liefert;
           Versionshinweise und Überspringen stecken im HA-Dialog. */
        sub: [verOf(e), String(e.attributes.release_summary || '').replace(/<[^>]+>/g, '')
          .split('\n').map((l) => l.trim()).filter(Boolean)[0]].filter(Boolean),
        action: e.attributes.in_progress ? 'Wird aktualisiert' : 'Aktualisieren',
        actionTone: 'accent', actionBusy: !!e.attributes.in_progress, actionIcon: 'mdi:download',
        /* An update whose notes say it needs a restart is not finished
           when it installs - the new version is not running yet, which
           is exactly what HA itself calls "Restart required". Green
           "Installed" would say done.
           The test has to be a RULE the bridge evaluates, not a branch
           taken here: release_summary is empty while the update is
           pending and only says "Restart of Home Assistant required"
           once the install has finished, so reading it at build time
           sends every row down the "Installed" branch. */
        actionLive: {
          rules: [
            { attr: 'in_progress', text: 'Wird aktualisiert', busy: true,
              color: 'var(--casora-soft-sub, var(--casora-popup-tiles-text-secondary, rgba(255,255,255,0.56)))' },
            { attr: 'state', eq: 'off', and: [{ attr: 'skipped_version' }], text: 'Übersprungen', icon: 'mdi:skip-next',
              color: 'var(--casora-popup-ui-tertiary, rgba(255,255,255,0.42))' },
            { attr: 'state', eq: 'off',
              and: [{ attr: 'release_summary', has: 'restart' }],
              text: 'Neustart erforderlich', icon: 'mdi:restart', color: WARN },
            { attr: 'state', eq: 'off', text: 'Installiert', icon: 'mdi:check',
              color: 'var(--casora-popup-ui-good, #30D158)' },
          ],
          text: 'Aktualisieren', icon: 'mdi:download',
          color: TEAL,
        },
      }));
      /* One heading that follows the work. Update All while more than
         one is left to install - a single update needs none, its own
         row is the button - then Restart Now the moment the last
         install lands on something that says it needs one. That last
         turn is the whole point: an update that needs a restart is not
         finished when it installs, and the popup you installed from is
         still open and is where you would look for the button. */
      const headBtn = actionButton(
        '[[[' + headCount
          + ' if (_waiting) return ' + JSON.stringify(btnLabel('Jetzt neu starten', WARN)) + ';'
          + ' if (_inst.length > 1) return ' + JSON.stringify(btnLabel('Alle aktualisieren', TEAL)) + ';'
          + ' return ""; ]]]',
        '[[[' + headCount
          + ' if (_waiting) return { action: "call-service",'
          + '   service: "homeassistant.restart", service_data: {},'
          + '   confirmation: { text: "Home Assistant jetzt neu starten?" } };'
          + ' if (_inst.length > 1) return { action: "call-service",'
          + '   service: "update.install", target: { entity_id: _inst },'
          + '   service_data: {},'
          + '   confirmation: { text: "Alle " + _inst.length + " Updates jetzt installieren?" } };'
          + ' return { action: "none" }; ]]]');
      add('listhead', { card: sectionHead(
        '[[[' + headCount
          + ' return _waiting ? ' + JSON.stringify(headText('Wartet auf Neustart'))
          + ' : ' + JSON.stringify(headText('Verfügbare Updates')) + '; ]]]',
        headBtn) });
      /* 25.09.2026: Liste live (Überspringen/Wieder anzeigen sofort sichtbar) – window._casoraUpdX.list, sonst die beim Öffnen gebaute Liste. */
      add('list', { card: secCard(_allUpd.concat(['sensor.casora_update_ki_analyse']), 'return (window._casoraUpdX && window._casoraUpdX.list) ? window._casoraUpdX.list(states, { UI: UI, logoOf: logoOf }) : ' + JSON.stringify(UI.group(rows, null)) + ';') });
      /* KI-Check (23.09.2026): Logik in casora-notify-local.js, window._casoraUpdAi. */
      add('ai', { card: secCard(_allUpd.filter((id) => states[id].state === 'on').concat(['sensor.casora_update_ki_analyse']), 'return (window._casoraUpdAi && window._casoraUpdAi(states, { INK: INK, INK3: INK3, headOut: headOut, logoOf: logoOf, nameOf: nameOf })) || String();') });
      /* Weich (E3): Etikett wie die übrigen Weich-Bereiche, Kopf und Liste als ein Block.
         03.10.2026: Der Etikett-Abstand nach unten (10 px) lag in der Rasterzeile – „Alle aktualisieren“
         saß dadurch 5 px tiefer als das Etikett. Abstand jetzt an der Kopfkarte, beide mittig.
         04.10.2026: Padding im card_mod (sonst nimmt padding:0 !important es nach dem ersten Bild weg).
         08.10.2026: Der Stapel hat keinen eigenen Abstand mehr – 10 px direkt an der Kopfkarte, wie „KI-Check“ daneben. */
      if (UI.soft && UI.soft()) {
        fields._softUpd = { card: { type: 'vertical-stack', cards: [sectionHead(
          '[[[' + headCount + ' return window._casoraUI.label(_waiting ? "Wartet auf Neustart" : "Verfügbare Updates").replace("margin:0 6px 10px;", "margin:0 6px;"); ]]]', headBtn, '0 0 10px'),
          fields.list.card] } };
      }
    }
    /* 1.0.5: „Wartet auf Neustart“ live (window._casoraUpdX.restart) statt beim Öffnen gebaut –
       installiert man im offenen Popup, erschien der Bereich sonst erst nach erneutem Öffnen.
       Leer ohne offene Updates (dann stehen die Zeilen in der Liste) und ohne Neustart. */
    if (n || restartEntities.length) {
      add('restart', { card: secCard(_allUpd, 'return (window._casoraUpdX && window._casoraUpdX.restart) ? window._casoraUpdX.restart(states, { UI: UI, headOut: headOut, logoOf: logoOf }) : String();') });
    }

    /* 25.09.2026: Übersprungen (klappbar), System und Verlauf – Logik in 03-popups.js, window._casoraUpdX. */
    const _hx = '{ UI: UI, C: C, headOut: headOut, logoOf: logoOf, nameOf: nameOf, ago: ago }';
    add('skipped', { card: secCard(_allUpd, 'const _s = window._casoraUpdX && window._casoraUpdX.skip(states, ' + _hx + '); return _s ? \'<div style="' + ((n || restartEntities.length || !(typeof window !== 'undefined' && window.innerWidth > 760)) ? 'padding-top' : 'padding-bottom') + ':18px">\' + _s + \'</div>\' : String();') });
    add('sys', { card: secCard(C.system.map((sy) => sy[0]).concat(['update.hacs_update', 'update.casora_update', C.backupLast, C.backupNext, C.backupState, (window.casoraDevice && window.casoraDevice.keyAny(hass, 'last_attempted_automatic_backup', 'sensor'))].filter(Boolean)), 'return (window._casoraUpdX && window._casoraUpdX.sys(states, ' + _hx + ')) || String();') });
    add('hist', { card: secCard(_allUpd, 'return (window._casoraUpdX && window._casoraUpdX.hist(states, hass, ' + _hx + ')) || String();') });

    /* Weich (E3, 01.10.2026): Ring-Unterzeile, links die Liste, rechts der KI-Check nur bei
       einer Warnung, alles Übrige unter „Mehr“ – window._casoraSoftUpd in 08-weich-kompakt.js. */
    if (UI.soft && UI.soft() && window._casoraSoftUpd) {
      const _su = window._casoraSoftUpd.build({ states: states, hass: hass, C: C, allIds: _allUpd,
        fields: { upd: fields._softUpd, ai: fields.ai } });
      if (_su) return { type: 'vertical-stack', cards: [_su] };
    }
    /* Zwei Spalten ab 761 px: links was zu tun ist (verfügbare Updates, Neustart,
       Übersprungen), rechts der KI-Check. Schmal: eine Spalte. */
    const _subFix = ' .hui-sub{display:block!important;max-width:100%;} .hui-sub2::before{content:none!important;}';
    const _keys = areas.map((a) => a.replace(/"/g, ''));
    /* Oben die Statuskarte über beide Spalten; Ohne KI-Check (keine offenen
       Updates) einspaltig. Das alte "Aktuell"-Hero
       entfällt, die Statuskarte sagt dasselbe. */
    /* 25.09.2026: links Updates + System, rechts KI-Check + Verlauf (etwa gleich hoch). */
    const _right = ['ai', 'hist'].filter((k) => _keys.indexOf(k) > -1);
    const _left = _keys.filter((k) => k !== 'hero' && k !== 'ov' && _right.indexOf(k) === -1);
    const _wide = typeof window !== 'undefined' && window.innerWidth > 760;
    /* 26.09.2026: Abstand je Bereich statt row-gap – ein leeres "Übersprungen" belegt sonst 18 px und die Spaltenköpfe stehen versetzt.
       "skipped" bringt seinen Abstand im Inhalt selbst mit (nur wenn nicht leer). */
    const _gapSt = (keys, i) => { const st = fstyle[keys[i]].slice(); if (keys[i] !== 'skipped' && keys[i] !== 'restart' && keys.slice(0, i).some((x) => x !== 'skipped' && x !== 'restart')) st.push({ 'margin-top': '18px' }); return st; };
    const _col = (keys) => ({
      type: 'custom:button-card',
      tap_action: { action: 'none' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      extra_styles: 'ha-card.disabled{pointer-events:auto!important;}' + _subFix,
      card_mod: { style: ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; }'
        + '\nha-card { background: transparent !important; border: none !important; border-radius: 0 !important; box-shadow: none !important;'
        + ' backdrop-filter: none !important; -webkit-backdrop-filter: none !important; overflow: visible !important;'
        + ' cursor: default !important; will-change: auto !important; pointer-events: auto !important; }'
        + '\nha-card:hover { box-shadow: none !important; }\nha-ripple { display: none !important; }' },
      styles: {
        card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '0' }],
        grid: [{ 'grid-template-areas': keys.map((k) => '"' + k + '"').join(' ') },
               { 'grid-template-columns': 'minmax(0, 1fr)' }, { 'row-gap': '0' }, { 'align-items': 'start' }],
        custom_fields: Object.fromEntries(keys.map((k, i) => [k, _gapSt(keys, i)])),
      },
      custom_fields: Object.fromEntries(keys.map((k) => [k, fields[k]])),
    });
    const _two = _wide && _left.length && _right.length;
    /* Einspaltig nur die Felder übergeben, die im Raster stehen. Ein Feld
       ohne Platz im Raster (das alte "hero" bei 0 Updates) legt sonst eine
       unsichtbare Zusatzspalte an und staucht alles auf ~70 % Breite. */
    const _narrow = ['ov'].concat(_keys.filter((k) => k !== 'hero' && k !== 'ov' && k !== 'sys' && k !== 'hist'), ['sys', 'hist']).filter((k) => fields[k]);
    const uiCard = {
      type: 'custom:button-card',
      tap_action: { action: 'none' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      extra_styles: _subFix,
      card_mod: { style: noHoverStyle },
      styles: {
        card: [
          { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
          { padding: 'var(--casora-soft-card-top, 6px) 26px 22px 26px' },
        ],
        grid: _two ? [
          { 'grid-template-areas': '"ov ov" "left right"' },
          { 'row-gap': 'var(--casora-popup-sec-gap, 18px)' },
          { 'grid-template-columns': 'minmax(0, 1fr) minmax(0, 1fr)' },
          { 'column-gap': 'var(--casora-popup-col-gap, 18px)' },
          { 'align-items': 'start' },
        ] : [
          { 'grid-template-areas': _narrow.map((k) => '"' + k + '"').join(' ') },
          { 'grid-template-columns': 'minmax(0, 1fr)' },
          { 'row-gap': '0' },
        ],
        custom_fields: _two
          ? { ov: [{ 'justify-self': 'stretch' }], left: [{ 'justify-self': 'stretch' }], right: [{ 'justify-self': 'stretch' }] }
          : Object.fromEntries(_narrow.map((k, i) => [k, _gapSt(_narrow, i)])),
      },
      custom_fields: _two ? { ov: fields.ov, left: { card: _col(_left) }, right: { card: _col(_right) } } : Object.fromEntries(_narrow.map((k) => [k, fields[k]])),
    };
    return { type: 'vertical-stack', cards: [uiCard] };
  }

  return { type: 'vertical-stack', cards: [] };
]]]

popup_styles.styles:
/* Popup content cards are not buttons: the theme's hover lift (shadow + brightness) made a
   whole column look like a raised card under the pointer (Weich audit M1). Killed popup-wide. */
--casora-card-hover-filter: none;
--casora-hover-filter: none;
--casora-card-hover-shadow: none;
/* The pane stays - these are control sheets. Only the close control
   keeps what it gained: a surface of its own, and room above it so
   the fill is not against the top edge of the sheet. */
.header { padding-top: var(--casora-popup-header-gap, 10px); }
/* Equal inset on both axes: the bar's own padding plus the
   close control's 2px optical nudge has to come to the same
   number as the padding above it, or the circle sits further
   from the left edge than it does from the top. */
--casora-popup-header-gap: 14px;
  --casora-popup-gutter-wide: 20px;
/* The chrome arrives with the first plate instead of being there
   on frame one while everything under it fades in. */
--casora-popup-chrome-enter:
  casora-popup-chrome-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
.header-title { font-size: 20px; font-weight: 600; letter-spacing: -0.01em; }
.header-close {
  border-radius: 50%;
  background: var(--casora-popup-row-fill, rgba(255, 255, 255, 0.10));
  backdrop-filter: var(--casora-popup-plate-backdrop, blur(24px) saturate(180%));
  -webkit-backdrop-filter: var(--casora-popup-plate-backdrop, blur(24px) saturate(180%));
  box-shadow: var(--casora-popup-plate-shadow, none);
}
/* The sheet is full height, so short content floats mid-screen. On
   a phone the card has to fill it for the grid's `1fr` row to have
   any slack to hand the toggle - otherwise the rows bunch under it
   instead of sitting at the bottom.
   Flex, not percentages: .content is `flex: 1 1 auto` inside a
   surface with only a max-height, so `min-height: 100%` here had no
   definite height to resolve against and computed to nothing. A
   flex chain gives every link a real height without one. */
@media (max-width: 768px) {
  /* The root cause, and why two attempts at the chain below did
     nothing: .surface is capped with max-height, never given one.
     A flex item in a content-sized container is itself
     content-sized, so every percentage under it resolved to
     nothing and the grid's `1fr` row had no slack to hand out.
     Same expression as its own max-height, as a height. */
  .surface {
    height: calc(100svh - var(--casora-popup-top, 112px) - 8px
                 - var(--safe-area-inset-bottom, 0px));
  }
  .content { display: flex; flex-direction: column; }
  /* A viewport unit, not a percentage. Every attempt to make this
     work by giving each link a definite height failed in the real
     DOM even though the chain measures correct in isolation - so
     the height is taken from the viewport directly and nothing has
     to resolve against a parent at all. 112 is the surface's top
     offset, 58 the header row, 8 the bottom gap. */
  .content .container {
    flex: 1 1 auto;
    min-height: calc(100svh - var(--casora-popup-top, 112px)
                     - 58px - 8px
                     - var(--safe-area-inset-bottom, 0px));
    display: flex; flex-direction: column; box-sizing: border-box;
  }
  /* The direct child AND anything HA wraps the card in: measured in
     isolation this chain resolves and the tiles land 8px off the
     bottom, so the only way it can still fail is a link in the real
     DOM that this does not name. */
  .content .container > *,
  .content .container hui-card,
  .content .container > * > * {
    flex: 1 1 auto; min-height: 0;
    display: flex; flex-direction: column;
  }
}
/* One measure for a control-plus-list popup, whatever the count.
   The rows are short and a wider sheet only stretches them; cover
   is the same shape and holds the same width. */
--popup-min-width: 900px;
--popup-max-width: 920px;

/* Popup-Standard (24.09.2026): großes Bedien-Popup als Sheet - die Handy-Vollhöhen-Regeln der kleinen Sheets hier zurücksetzen. */
@media (max-width: 768px) {
  .surface { height: auto; }
  .content { display: block; }
  .content .container { min-height: 0; display: block; }
  .content .container > *, .content .container hui-card, .content .container > * > * { flex: none; min-height: 0; display: block; }
}

