popup_styles.styles:
/* Eine Popup-Familie (01.10.2026): dieselbe Sheet-Fläche wie die Bedien-Popups –
   Fläche, Blur, Schatten und Abdunklung aus dem Standard, Höhe folgt dem Inhalt,
   Schließen-Kreuz mit demselben Abstand zur Sheet-Kante. */
.header { padding-top: var(--casora-popup-header-gap, 10px); }
--casora-popup-header-gap: 14px;
/* Aquarien: breit wie Energie, zwei Spalten ab 761 px; schmale Screens deckelt .surface selbst. */
--popup-min-width: 900px;
--popup-max-width: 920px;
--casora-popup-gutter-wide: 34px;
--casora-popup-gutter-phone: 22px;

/* No chart here, so nothing to wait for: the widgets arrive as
   soon as they are built. Read by each widget for itself, never by
   a wrapper - an animated opacity on an ancestor flattens the frost
   inside it. */
--casora-popup-plate-enter:
  casora-plate-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
@media (prefers-reduced-motion: reduce) {
  --casora-popup-plate-enter: none;
}

--casora-popup-hero-label-size: 15px;
--casora-popup-row-radius: 26px;
/* Frosted, not opaque. The pane's blur used to sit under these, and
   .content still nulls --ha-card-backdrop-filter for every card in
   the popup, so the frost has to be asked for here. The fills drop
   to let it read. */
/* The theme lifts every ha-card with filter: brightness(1.01) on
   hover. A filter on an ancestor makes every descendant's
   backdrop-filter inert, so hovering the empty space around a
   widget - the wrapper card - knocked the frost out of both of
   them. Killed popup-wide; the plate re-declares its own shadow. */
--casora-card-hover-filter: none;
--casora-hover-filter: none;
--casora-card-hover-shadow: none;

--casora-popup-row-pad-x: 26px;
--casora-popup-row-pad-y: 15px;
--casora-popup-plate-backdrop: blur(24px) saturate(180%);
--casora-popup-chart-fill: var(--casora-sheet-chart-fill, rgba(10, 12, 16, 0.68));
--casora-popup-row-fill: var(--casora-sheet-row-fill, rgba(12, 14, 19, 0.62));
/* Lifted, not slabbed: one wide soft pass carries the height, one
   short contact pass keeps the edge from dissolving into the room. */
--casora-popup-plate-shadow: var(--casora-sheet-plate-shadow,
  0 18px 40px -22px rgba(0, 0, 0, 0.50),
  0 2px 8px -5px rgba(0, 0, 0, 0.28));

/* visionOS puts nothing bare on the room: the only chrome outside a
   window is its close control, and that control is itself a glass
   object. The title was printed twice - here and in the widget
   eight pixels below - so it goes, clipped rather than removed so a
   screen reader still gets it. */

/* The chrome arrives with the first plate instead of being there
   on frame one while everything under it fades in. */
--casora-popup-chrome-enter:
  casora-popup-chrome-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
.content { animation: none; }
/* The title lives in the bar now, centered and level with the
   close control, so it is no longer hidden. */
.header-title { font-size: 20px; font-weight: 600; letter-spacing: -0.01em; }
/* 48px is left alone: the base sizes it so the glyph's ink lands on
   the same left margin as the widgets below. */
.header-close {
  border-radius: 50%;
  background: var(--casora-popup-row-fill, rgba(255, 255, 255, 0.10));
  backdrop-filter: var(--casora-popup-plate-backdrop, none);
  -webkit-backdrop-filter: var(--casora-popup-plate-backdrop, none);
  box-shadow: var(--casora-popup-plate-shadow, none);
}

ha-adaptive-dialog, ha-dialog, wa-drawer {
  --ha-card-backdrop-filter: none;
  --ha-card-background: transparent;
  --card-background-color: transparent;
  --ha-card-box-shadow: none;
  --ha-card-border-width: 0px;
}

/* Titel: mittig, solange er zwischen die Knöpfe passt; sonst ab rechts vom Schließen-Knopf (safe center), notfalls mit … am rechten Rand. Nie unter dem Schließen-Knopf. */
.header-content { left: calc(var(--casora-popup-gutter, 26px) + 56px) !important; right: calc(var(--casora-popup-gutter, 26px) + 56px) !important; margin-inline: 0 !important; width: auto !important; max-width: none !important; overflow: visible !important; align-items: safe center !important; }
.header-title { max-width: calc(100% + 56px) !important; overflow: hidden !important; text-overflow: ellipsis !important; white-space: nowrap !important; }

/* Popup-Standard (24.09.2026): Info-Popup - Abschnittsüberschriften in der Karte. */
--casora-lbl-in: block;
--casora-lbl-out: none;

casora_popup.title:
[[[
  /* Eigener Popup-Titel der Kachel (room_name) zuerst, sonst wie bisher. */
  const _own = window.casoraPopupTitle ? window.casoraPopupTitle(null, variables, '', ['Raumklima'])
    : (() => { const r = String(variables.room_name || '').trim(); return r.startsWith('[[[') ? '' : r; })();
  if (_own && !['Raumklima'].includes(_own)) return _own;
  return "Raumklima";
]]]

casora_popup.content:
[[[
  const UI = window._casoraUI;
  if (!UI) return { type: 'vertical-stack', cards: [] };
  const T2 = UI.tokens;
  const esc = UI.esc;

  const sensorIds = Array.isArray(variables.sensors) ? variables.sensors : (entity ? [entity?.entity_id] : []);

  const escBr = (v) => esc(v).replace(/&lt;br\s*\/?&gt;/gi, '<br>');

  const severityToLevel = (sev) => {
    if (sev === 'Extrem')   return 4;
    if (sev === 'Severe')   return 3;
    if (sev === 'Moderate') return 2;
    if (sev === 'Minor')    return 1;
    return 0;
  };

  const levelInfo = (level) => {
    if (level >= 4) return { label: 'Extrem',  title: 'Extreme Warnung',  color: 'var(--casora-color-purple, #9333ea)', tone: 'bad' };
    if (level >= 3) return { label: 'Schwer',  title: 'Schwere Warnung',  color: T2.red,    tone: 'bad'  };
    if (level >= 2) return { label: 'Warnung', title: 'Amtliche Warnung', color: T2.amber,  tone: 'warn' };
    if (level >= 1) return { label: 'Hinweis', title: 'Hinweis',          color: 'var(--casora-popup-yellow-color, #ffd600)', tone: 'warn' };
    return           { label: 'Ruhig',   title: 'Keine Warnung',    color: T2.green,  tone: 'good' };
  };

  const warningIcon = (attrs, fallbackLevel) => {
    const text = [attrs?.headline, attrs?.description, attrs?.instruction, attrs?.event]
      .filter(Boolean).join(' ').toLowerCase();
    if (text.includes('gewitter') || text.includes('blitz') || text.includes('unwetter')) return 'mdi:weather-lightning-rainy';
    if (text.includes('starkregen') || text.includes('dauerregen') || text.includes('regen')) return 'mdi:weather-pouring';
    if (text.includes('schnee')) return 'mdi:weather-snowy-heavy';
    if (text.includes('glätte') || text.includes('glatteis') || text.includes('frost') || /(^|\s|\.|,|;|:|-)(eis|eisregen|eisglätte)(\s|\.|,|;|:|-|$)/i.test(text)) return 'mdi:snowflake-alert';
    if (text.includes('nebel')) return 'mdi:weather-fog';
    if (text.includes('hitze') || text.includes('uv')) return 'mdi:white-balance-sunny';
    if (text.includes('wind') || text.includes('sturm') || text.includes('böen') || text.includes('orkan')) return 'mdi:weather-windy';
    if (text.includes('hochwasser') || text.includes('überschwemmung') || text.includes('flut')) return 'mdi:home-flood';
    if (text.includes('feuer') || text.includes('brand') || text.includes('waldbrand')) return 'mdi:fire-alert';
    if (text.includes('corona') || text.includes('virus')) return 'mdi:biohazard';
    const map = { 4: 'mdi:alert-octagram', 3: 'mdi:alert-circle', 2: 'mdi:alert', 1: 'mdi:information', 0: 'mdi:shield-check' };
    return map[fallbackLevel] || 'mdi:shield-check';
  };

  const fmtUpdated = (value) => {
    if (!value) return '—';
    const d = new Date(value);
    if (Number.isNaN(d.getTime())) return '—';
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const day = new Date(d.getFullYear(), d.getMonth(), d.getDate());
    const diff = Math.round((today - day) / 86400000);
    const time = d.toLocaleString((window.casoraLocale ? window.casoraLocale() : 'de-DE'), { hour: '2-digit', minute: '2-digit' });
    if (diff === 0) return `Heute ${time}`;
    if (diff === 1) return `Gestern ${time}`;
    if (diff === 2) return `Vorgestern ${time}`;
    if (diff < 7) return `vor ${diff} Tagen ${time}`;
    return d.toLocaleString((window.casoraLocale ? window.casoraLocale() : 'de-DE'), { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
  };

  const fmtDateTime = (value) => {
    if (!value) return '—';
    const d = new Date(value);
    if (Number.isNaN(d.getTime())) return '—';
    return d.toLocaleString((window.casoraLocale ? window.casoraLocale() : 'de-DE'), { weekday: 'short', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }).replace(',', ' ·');
  };

  const cleanTextBr = (v) => String(v || '')
    .replace(/[ \t]*(<br\s*\/?>)[ \t]*/gi, '$1')
    .replace(/[ \t]{2,}/g, ' ')
    .trim();

  const warnings = sensorIds
    .map((id) => states[id])
    .filter((s) => s && s.state === 'on')
    .map((s) => {
      const a = s.attributes || {};
      return {
        headline: a.headline || a.title || '',
        description: cleanTextBr(a.description || ''),
        instruction: cleanTextBr(a.instruction || ''),
        severity: a.severity || 'Minor',
        level: severityToLevel(a.severity),
        effective: a.effective || a.onset || a.sent || a.start_time || null,
        expires: a.expires || a.end_time || null,
        event: a.event || '',
        msgType: a.message_type || a.msgType || '',
      };
    })
    .reduce((acc, w) => {
      const key = w.headline + '||' + w.description;
      const existing = acc.find((x) => x.headline + '||' + x.description === key);
      if (!existing) acc.push(w);
      else if (w.expires && (!existing.expires || new Date(w.expires) > new Date(existing.expires))) existing.expires = w.expires;
      return acc;
    }, [])
    .sort((a, b) => b.level - a.level);

  const highest = warnings.length ? warnings[0].level : 0;
  const highestInfo = levelInfo(highest);

  const latestUpdate = (() => {
    const fromAttrs = warnings.reduce((latest, w) => {
      const t = w.effective;
      return t && (!latest || new Date(t) > new Date(latest)) ? t : latest;
    }, null);
    if (fromAttrs) return fromAttrs;
    const firstActive = sensorIds.map((id) => states[id]).find((s) => s && s.state === 'on');
    if (firstActive?.last_changed) return firstActive.last_changed;
    return states[sensorIds[0]]?.last_changed || null;
  })();

  const region = (() => {
    const id = sensorIds[0] || '';
    const match = id.match(/nina_warning_(.+?)(?:_\d+)?$/);
    if (!match) return null;
    return match[1].split('_').map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
  })();

  const areas = [], fields = {}, fstyle = {};
  const add = (name, html) => {
    areas.push('"' + name + '"');
    fields[name] = html;
    fstyle[name] = [{ 'justify-self': 'stretch' }];
  };

  const _softN = !!(UI.soft && UI.soft());
  /* Region auch ohne variables.sensors aus der Kachel-Entität (nina_warning_<region>_N). */
  const _regionN = region || (() => { const m = String(entity?.entity_id || '').match(/nina_warning_(.+?)(?:_\d+)?$/);
    return m ? m[1].split('_').map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join(' ') : null; })();
  add('hero', _softN ? UI.hero({
    /* Weich (E3): eine Aussage statt dreimal „ruhig“ – Ring-Unterzeile, Region dahinter. */
    value: warnings.length ? highestInfo.title : 'Keine Warnungen',
    sub: (warnings.length ? [_regionN, fmtUpdated(latestUpdate)] : [_regionN]).filter((x) => x && x !== '—' && x !== '\u2014').join(' · ') || null,
    center: true, line: true,
    valueTone: warnings.length ? highestInfo.tone : null,
  }) : UI.hero({
    value: highestInfo.label,
    /* Ohne Region/Zeitpunkt keine Platzhalter wie "Deine Region · —". */
    sub: [region, fmtUpdated(latestUpdate)].filter((x) => x && x !== '—' && x !== '\u2014').join(' · ') || null,
    center: true,
    subTone: null,
  }));

  /* Weich (01.10.2026): Sand-Pillen mit Symbolkreis aus den Bausteinen statt Platte mit Trennlinien. */
  const _soft = !!(UI.soft && UI.soft());
  if (!warnings.length && _soft) {
    /* Weich (E3): kein zweiter Block „Keine aktiven Warnungen“ – das sagt der Ring-Kopf. */
  } else if (!warnings.length) {
    add('empty', '<div style="display:flex;align-items:center;gap:12px;background:' + T2.fill + ';border-radius:20px;padding:16px;font-family:' + T2.font + ';">'
      + '<div style="width:38px;height:38px;border-radius:13px;flex:none;display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,0.08);">'
      + '<ha-icon icon="mdi:shield-check" style="--mdc-icon-size:21px;color:' + T2.green + ';"></ha-icon></div>'
      + '<div style="min-width:0;text-align:left;"><div style="font-size:15px;font-weight:500;color:' + T2.ink + ';text-align:left;">Keine aktiven Warnungen</div>'
      + '<div style="font-size:13px;color:' + T2.ink3 + ';margin-top:2px;white-space:normal;overflow-wrap:break-word;text-align:left;">Aktuell keine NINA-Meldungen' + (region ? ' für ' + esc(region) : '') + '</div></div>'
      + '</div>');
  } else {
    const rows = warnings.map((w, i) => {
      const info = levelInfo(w.level);
      const icon = warningIcon(w, w.level);
      const title = w.headline || w.event || 'NINA-Warnung';
      const subtitle = (w.effective || w.expires)
        ? (fmtDateTime(w.effective) + ' bis ' + fmtDateTime(w.expires))
        : esc(w.severity);
      const details = w.description || 'Keine Detailbeschreibung verfügbar.';
      const meta = [w.msgType ? ('Typ: ' + esc(w.msgType)) : '', w.event ? esc(w.event) : ''].filter(Boolean).join(' · ');

      return '<div style="display:flex;gap:12px;align-items:flex-start;padding:14px 16px;'
        + (i ? 'border-top:1px solid ' + T2.div + ';' : '') + '">'
        + '<div style="width:38px;height:38px;border-radius:13px;flex:none;display:flex;align-items:center;justify-content:center;'
        + 'background:color-mix(in srgb,' + info.color + ' 14%, transparent);">'
        + '<ha-icon icon="' + icon + '" style="--mdc-icon-size:21px;color:' + info.color + ';"></ha-icon></div>'
        + '<div style="min-width:0;flex:1;white-space:normal;overflow-wrap:anywhere;word-break:break-word;">'
        + '<div style="font-size:15px;font-weight:500;color:' + T2.ink + ';letter-spacing:-0.01em;">' + esc(title) + '</div>'
        + '<div style="font-size:12px;color:' + T2.ink3 + ';margin-top:2px;">' + esc(subtitle) + '</div>'
        + '<div style="font-size:13px;color:' + T2.ink2 + ';line-height:1.4;margin-top:8px;">' + escBr(details) + '</div>'
        + (w.instruction ? '<div style="font-size:12px;color:' + T2.ink3 + ';line-height:1.4;margin-top:6px;">' + escBr(w.instruction) + '</div>' : '')
        + (meta ? '<div style="display:inline-flex;margin-top:8px;padding:3px 9px;border-radius:999px;font-size:11px;font-weight:500;color:' + T2.ink3 + ';background:' + T2.fill2 + ';">' + meta + '</div>' : '')
        + '</div></div>';
    }).join('');
    if (_soft) {
      add('list', '<div style="display:flex;flex-direction:column;gap:8px;font-family:' + T2.font + ';text-align:left;white-space:normal;overflow-wrap:anywhere;word-break:break-word;">'
        + warnings.map((w) => {
          const info = levelInfo(w.level);
          const title = w.headline || w.event || 'NINA-Warnung';
          const subtitle = (w.effective || w.expires) ? (fmtDateTime(w.effective) + ' bis ' + fmtDateTime(w.expires)) : esc(w.severity);
          const meta = w.event ? esc(w.event) : '';
          return '<div style="display:flex;gap:12px;align-items:flex-start;padding:12px 16px 14px 10px;border-radius:var(--casora-popup-row-radius, 24px);background:var(--casora-soft-row-fill, rgba(140,115,90,0.07));">'
            + '<div style="width:38px;height:38px;border-radius:50%;flex:none;display:flex;align-items:center;justify-content:center;background:' + info.color + ';">'
            + '<ha-icon icon="' + warningIcon(w, w.level) + '" style="--mdc-icon-size:19px;display:flex;color:var(--casora-soft-glyph, #fff);"></ha-icon></div>'
            + '<div style="min-width:0;flex:1;padding-top:1px;">'
            + '<div style="font-size:14.5px;font-weight:700;letter-spacing:-0.01em;line-height:1.3;color:' + T2.ink + ';">' + esc(title) + '</div>'
            + '<div style="font-size:12.5px;font-weight:500;color:var(--casora-soft-sub, ' + T2.ink2 + ');margin-top:1px;">' + esc(subtitle) + '</div>'
            + '<div style="font-size:13.5px;color:' + T2.ink2 + ';line-height:1.45;margin-top:8px;">' + escBr(w.description || 'Keine Detailbeschreibung verfügbar.') + '</div>'
            + (w.instruction ? '<div style="font-size:12.5px;color:var(--casora-soft-sub, ' + T2.ink3 + ');line-height:1.4;margin-top:6px;">' + escBr(w.instruction) + '</div>' : '')
            + (meta ? '<div style="display:inline-flex;margin-top:10px;padding:5px 11px;border-radius:999px;font-size:12px;font-weight:600;color:var(--casora-soft-sub, ' + T2.ink3 + ');background:var(--casora-soft-control-fill, ' + T2.fill2 + ');">' + meta + '</div>' : '')
            + '</div></div>';
        }).join('') + '</div>');
    } else
    add('list', '<div style="background:' + T2.fill + ';border-radius:20px;overflow:hidden;font-family:' + T2.font + ';text-align:left;white-space:normal;overflow-wrap:anywhere;word-break:break-word;">' + rows + '</div>');
  }

  const uiCard = {
    type: 'custom:button-card',
    triggers_update: sensorIds,
    card_mod: { style:
      '\n:host { --ha-card-backdrop-filter: none !important; --ha-card-background: transparent !important; --card-background-color: transparent !important; --ha-card-box-shadow: none !important; --ha-card-border-width: 0px !important; }'
      + '\nha-card::before, ha-card::after, #card::before, #card::after, #container::before, #container::after { display: none !important; }'
      + '\nha-card { will-change: auto !important; }'
      + '\n@media (max-width: 600px) { ha-card { padding-left: 14px !important; padding-right: 14px !important; } }'
      /* Weich: kein Kachelschatten der Inhaltskarte – er stand als zweite Platte im Popup. */
      + (UI.soft && UI.soft() ? '\n:host { --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; --button-card-box-shadow-active: none !important; } ha-card { box-shadow: none !important; }' : '')
    },
    tap_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    styles: {
      card: [
        { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
        { padding: 'var(--casora-soft-card-top, 6px) 26px 22px 26px' },
      ],
      grid: [
        { 'grid-template-areas': areas.join(' ') },
        { 'grid-template-columns': '1fr' },
        { 'row-gap': 'var(--casora-popup-sec-gap, 18px)' },
      ],
      custom_fields: fstyle,
    },
    custom_fields: fields,
  };
  return { type: 'vertical-stack', cards: [window._casoraStd ? window._casoraStd(uiCard, {}) : uiCard] };
]]]

