casora_presence.state_display:
[[[
  const fit = (t) => window.casoraStateFit?.(t) ?? t;
  const s = (entity?.state || '').toLowerCase().replace(/_/g, ' ');
  if (s === 'home' || s === 'just arrived') return 'Zuhause';
  if (s === 'not home' || s === 'away')     return 'Unterwegs';
  if (!s || ['unavailable', 'unknown'].includes(s)) return '';
  return fit((entity?.state || '').replace(/_/g, ' ').replace(/(^|[^\p{L}\p{N}])(\p{L})/gu, (m, a, c) => a + c.toUpperCase()));
]]]

