card.cards:
[[[
  // Alle Szenen (30.09.2026, vorher zehn feste Plätze): je Szene eine Unter-Badge, die Reihe
  // blättert seitwärts (window._casoraBadgeRows). Neu gebaut wird nur bei geänderter Liste.
  if ((window.casoraSeen?window.casoraSeen(variables,'scenes',user,variables.show_scenes):variables.show_scenes) !== true) return [];
  const ids = Array.isArray(variables.scene_entities) ? variables.scene_entities : [];
  const seen = new Set();
  return ids.filter((id) => typeof id === 'string' && id && !seen.has(id) && seen.add(id))
    .map((id) => ({ type: 'custom:button-card', template: 'casora_badge_scene', entity: id,
      variables: { enabled: true } }));
]]]

casora_room.extra_styles:
/* Same exemption themes/casora/casora.yaml gives .casora-entity cards via
   :host(.casora-entity){ contain: none !important; } — this card doesn't
   carry that class, but contain establishes a backdrop root just like
   transform/filter/isolation, and it sits above every Now Playing tile. */
:host{
  contain: none !important;
}
ha-card{
  contain: none !important;
}

#mp1, #mp2, #mp3, #mp4,
#activity1, #activity2 {
  overflow: visible;
}

#badges,
#badges_climate,
#badges_presence,
#badges_media,
#badges_lights,
#badges_security,
#badges_energy,
#badges_scenes {
  overflow-x: visible !important;
  overflow-y: visible !important;
  overscroll-behavior-x: contain !important;
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}

#badges::-webkit-scrollbar,
#badges_climate::-webkit-scrollbar,
#badges_presence::-webkit-scrollbar,
#badges_media::-webkit-scrollbar,
#badges_lights::-webkit-scrollbar,
#badges_security::-webkit-scrollbar,
#badges_energy::-webkit-scrollbar,
#badges_scenes::-webkit-scrollbar {
  display: none;
}

/* Zu breite Badge-Reihe (data-cs-scroll/-fade setzt window._casoraBadgeRows, 01-basis.js):
   seitwärts scrollbar, weicher Rand dort, wo noch Badges liegen. */
#badges[data-cs-scroll],
#badges_climate[data-cs-scroll],
#badges_presence[data-cs-scroll],
#badges_media[data-cs-scroll],
#badges_lights[data-cs-scroll],
#badges_security[data-cs-scroll],
#badges_energy[data-cs-scroll],
#badges_scenes[data-cs-scroll] {
  overflow-x: auto !important;
  overflow-y: hidden !important;
  overscroll-behavior-x: contain !important;
}
#badges[data-cs-fade="r"],
#badges_climate[data-cs-fade="r"],
#badges_presence[data-cs-fade="r"],
#badges_media[data-cs-fade="r"],
#badges_lights[data-cs-fade="r"],
#badges_security[data-cs-fade="r"],
#badges_energy[data-cs-fade="r"],
#badges_scenes[data-cs-fade="r"] {
  -webkit-mask-image: linear-gradient(to right, #000 calc(100% - var(--casora-badge-row-fade, 40px)), transparent);
  mask-image: linear-gradient(to right, #000 calc(100% - var(--casora-badge-row-fade, 40px)), transparent);
}
#badges[data-cs-fade="l"],
#badges_climate[data-cs-fade="l"],
#badges_presence[data-cs-fade="l"],
#badges_media[data-cs-fade="l"],
#badges_lights[data-cs-fade="l"],
#badges_security[data-cs-fade="l"],
#badges_energy[data-cs-fade="l"],
#badges_scenes[data-cs-fade="l"] {
  -webkit-mask-image: linear-gradient(to right, transparent, #000 var(--casora-badge-row-fade, 40px));
  mask-image: linear-gradient(to right, transparent, #000 var(--casora-badge-row-fade, 40px));
}
#badges[data-cs-fade="l r"],
#badges_climate[data-cs-fade="l r"],
#badges_presence[data-cs-fade="l r"],
#badges_media[data-cs-fade="l r"],
#badges_lights[data-cs-fade="l r"],
#badges_security[data-cs-fade="l r"],
#badges_energy[data-cs-fade="l r"],
#badges_scenes[data-cs-fade="l r"] {
  -webkit-mask-image: linear-gradient(to right, transparent, #000 var(--casora-badge-row-fade, 40px), #000 calc(100% - var(--casora-badge-row-fade, 40px)), transparent);
  mask-image: linear-gradient(to right, transparent, #000 var(--casora-badge-row-fade, 40px), #000 calc(100% - var(--casora-badge-row-fade, 40px)), transparent);
}

/* Tablet/Desktop: längerer Auslauf, damit eine abgeschnittene Badge sichtbar weich ausläuft
   statt am Rand zu enden (Tablet mit angedockter HA-Seitenleiste, 02.10.2026). */
@media (min-width: 768px) {
  :host { --casora-badge-row-fade: 88px; }
}

@media (max-width: 767px) and (orientation: portrait) {
  :host .button-card-main {
    padding-top: var(--hero-top) !important;
  }

  #badges,
  #badges_climate,
  #badges_presence,
  #badges_media,
  #badges_lights,
  #badges_security,
  #badges_energy,
#badges_scenes {
    overflow-x: auto !important;
    width: calc(100% + 2 * var(--hero-gutter) - var(--casora-header-badge-nudge, 0px)) !important;
    max-width: none !important;
    margin-left: calc(-1 * var(--hero-gutter) + var(--casora-header-badge-nudge, 0px)) !important;
    padding-left: var(--hero-gutter) !important;
    padding-right: var(--hero-gutter) !important;
    box-sizing: border-box !important;
  }

  #badges_media {
    padding-left: calc(var(--hero-gutter) + var(--casora-header-media-badge-nudge-current, 0px)) !important;
  }
}

@media (hover: none) and (pointer: coarse) and (orientation: landscape) and (max-height: 600px) {
  #badges,
  #badges_climate,
  #badges_presence,
  #badges_media,
  #badges_lights,
  #badges_security,
  #badges_energy,
#badges_scenes {
    max-width: calc(100vw - (2 * var(--casora-entity-col-width-landscape, 200px)) - 8px - var(--casora-tiles-right-pad-landscape, 0px) - var(--hero-gutter, 18px) - var(--casora-landscape-badge-stop-pad, 60px)) !important;
    overflow-x: auto !important;
    box-sizing: border-box !important;
  }
}

#time {
  display: none;
}

@media (min-width: 769px) and (hover: hover) and (pointer: fine) {
  #time {
    display: var(--casora-time-nav-open, block);
    top: calc(env(safe-area-inset-top, 0px) + var(--casora-chrome-row-center-desktop, 56px)
      - (var(--casora-clock-font-size, var(--casora-chrome-font-size, 18px)) / 2));
    left: var(--casora-time-left, calc(var(--hero-gutter) + var(--hero-room-name-margin-left-current, 0px) + var(--casora-time-edge, 0px)));
  }
}

@media (min-width: 600px) and (max-width: 767px) and (min-height: 501px) {
  #time {
    display: var(--casora-time-nav-open, block);
    top: calc(env(safe-area-inset-top, 0px) + var(--casora-nav-top-current, 46px) - var(--casora-time-nudge-small-tablet, 43px));
    left: var(--casora-time-left, calc(var(--hero-gutter) + var(--hero-room-name-margin-left-current, 0px) + var(--casora-time-edge, 0px)));
  }
}

/* Tablet - Time: leading rail, optical center on the navbar label row. */
@media (min-width: 768px) and (max-width: 1600px) and (min-height: 501px) and (orientation: landscape) and (pointer: coarse),
       (min-width: 768px) and (max-width: 1600px) and (min-height: 501px) and (orientation: landscape) and (hover: none) {
  #time {
    display: var(--casora-time-nav-open, block);
    top: calc(env(safe-area-inset-top, 0px) + var(--casora-chrome-row-top-tablet, 30px) + var(--casora-time-row-offset-tablet, 12px));
    left: var(--hero-gutter);
    right: auto;
  }
}

@media (min-width: 768px) and (max-width: 1600px) and (min-height: 501px) and (orientation: portrait) and (pointer: coarse),
       (min-width: 768px) and (max-width: 1600px) and (min-height: 501px) and (orientation: portrait) and (hover: none) {
  #time {
    display: var(--casora-time-nav-open, block);
    top: calc(env(safe-area-inset-top, 0px) + var(--casora-chrome-row-top-tablet-portrait, 32px) + var(--casora-time-row-offset-tablet, 12px));
    left: var(--hero-gutter);
    right: auto;
  }
}

/* Now Playing Text - Hidden on Tablet */
/* The settings button and the Now Playing waveform share this row, so one
   number moves both and they cannot drift apart. Desktop is measured off the
   nav label (y 16, height 26, center 29) less half a 34px button. */
:host {
  --casora-chrome-btn-size: var(--casora-chrome-btn-size-desktop, 34px);
  --casora-chrome-btn-top: calc(var(--casora-chrome-row-center-desktop, 56px)
    - (var(--casora-chrome-btn-size, 34px) / 2));
}

@media (min-width: 768px) and (max-width: 1600px) and (min-height: 501px) and (orientation: landscape) and (pointer: coarse),
       (min-width: 768px) and (max-width: 1600px) and (min-height: 501px) and (orientation: landscape) and (hover: none) {
  :host {
    --casora-chrome-btn-top: calc(var(--casora-chrome-row-top-tablet, 30px)
      + (var(--casora-nav-pill-height-tablet, 46px) / 2)
      - (var(--casora-chrome-btn-size, 34px) / 2));
  }
}

/* Portrait sits the pill 2px lower, so the buttons follow it. Without this
   the row fell back to the desktop center and every button sat 9px low. */
@media (min-width: 768px) and (max-width: 1600px) and (min-height: 501px) and (orientation: portrait) and (pointer: coarse),
       (min-width: 768px) and (max-width: 1600px) and (min-height: 501px) and (orientation: portrait) and (hover: none) {
  :host {
    --casora-chrome-btn-top: calc(var(--casora-chrome-row-top-tablet-portrait, 32px)
      + (var(--casora-nav-pill-height-tablet, 46px) / 2)
      - (var(--casora-chrome-btn-size, 34px) / 2));
  }

  /* Portrait alone cannot fit the waveform beside the pill, so it gives up
     its seat in the row and takes the one below. Assist is already in the
     dots menu on every tablet - see the block after this one. */
  #now_playing { --casora-np-head-inset: 0px !important; }
}

/* A tablet keeps Assist in the dots menu in BOTH orientations. Landscape has
   the width for it, but a control that moves when the iPad is turned is
   worse than one that lives in one place. The row collapses the way a UIKit
   toolbar does; the bell then closes Assist's gap and the waveform's own
   reserve drops a step with it. !important because every one of these is
   stamped inline from styles.custom_fields.
   --casora-chrome-side-reserve-tablet* in the theme counts what is left;
   changing what shows here means changing those. */
@media (min-width: 768px) and (max-width: 1600px) and (min-height: 501px) and (pointer: coarse),
       (min-width: 768px) and (max-width: 1600px) and (min-height: 501px) and (hover: none) {
  #assist { display: none !important; }

  #notifications {
    transform: translateX(calc(-1 * var(--casora-chrome-dots-step, 46px))) !important;
  }

  #now_playing {
    --casora-np-head-inset: calc(var(--casora-chrome-dots-step, 46px)
      + var(--casora-chrome-bell-step, 46px)) !important;
  }
}

/* Portrait again, last: its waveform is not in the row at all, so it
   reserves nothing. Same weight as the block above, so order settles it. */
@media (min-width: 768px) and (max-width: 1600px) and (min-height: 501px) and (orientation: portrait) and (pointer: coarse),
       (min-width: 768px) and (max-width: 1600px) and (min-height: 501px) and (orientation: portrait) and (hover: none) {
  #now_playing { --casora-np-head-inset: 0px !important; }
}

#now_playing {
  --np-vp: 0;
  pointer-events: none;
}

/* The container is only a positioning box: right-anchored and up to 560px
   wide, it reaches across chrome it does not draw. Left capturing pointer
   events it swallowed every click on the settings button beside it whenever
   media was playing - and did nothing when nothing was. Only what it
   actually paints should be clickable, so the box stays transparent to
   pointers and its content opts back in. This does not depend on z-index. */
#now_playing { pointer-events: none !important; }
#now_playing > * { pointer-events: auto; }

@media (min-width: 769px) and (hover: hover) and (pointer: fine) {
  #now_playing {
    --np-vp: 1;
    pointer-events: auto;
    top: calc(env(safe-area-inset-top, 0px) + var(--casora-chrome-btn-top, 12px));
    right: calc(var(--hero-gutter) + var(--hero-room-name-margin-left-current, 0px));
    max-width: min(560px, 34vw);
  }
}

/* Tablet - Now Playing */
@media (min-width: 768px) and (max-width: 1600px) and (min-height: 501px) and (orientation: landscape) and (pointer: coarse),
