card.--casora-font-set:
[[[
  const STACKS = {
    inter:   '"Inter", -apple-system, BlinkMacSystemFont, system-ui, sans-serif',
    hanken:  '"Hanken Grotesk", -apple-system, BlinkMacSystemFont, system-ui, sans-serif',
    jakarta: '"Inter", -apple-system, BlinkMacSystemFont, system-ui, sans-serif',
    system:  '-apple-system, BlinkMacSystemFont, system-ui, "Segoe UI", Roboto, sans-serif'
  };
  const link = (id, href) => {
    let l = document.getElementById(id);
    if (l && l.getAttribute('href') === href) return;
    if (!l) { l = document.createElement('link'); l.id = id; l.rel = 'stylesheet'; document.head.appendChild(l); }
    l.href = href;
  };
  const key = String(variables.font || '').trim().toLowerCase();
  let want = STACKS[key] || '';
  if (key === 'custom') {
    /* Eigene Schrift (z. B. gekaufte Gilroy), im Studio hochgeladen – CSS schreibt fonts.py. */
    const fam = String(variables.font_family || '').replace(/["'<>;{}\\]/g, '').trim();
    link('casora-font-custom', '/local/casora/fonts/casora-fonts.css');
    want = fam ? '"' + fam + '", ' + STACKS.inter : '';
  }
  /* Casoras Schriften immer bereitstellen – auch die Designs setzen sie (Inter, Hanken Grotesk). */
  link('casora-font-faces', '/casora_assets/fonts/hanken-grotesk.css');
  const ID = 'casora-font-v1';
  let el = document.getElementById(ID);
  if (!want) { if (el) el.remove(); return '0'; }
  if (!el) {
    el = document.createElement('style');
    el.id = ID;
    document.head.appendChild(el);
  }
  const css = 'html{--primary-font-family:' + want + ' !important;}';
  if (el.textContent !== css) el.textContent = css;
  return '1';
]]]

