card.padding-top:
[[[
  const mm = (q) => (window.matchMedia ? window.matchMedia(q).matches : false);
  const isPhonePortrait =
    (mm('(pointer: coarse)') || mm('(hover: none)')) &&
    mm('(max-width: 767px)') &&
    mm('(orientation: portrait)');

  if (isPhonePortrait) return 'calc(var(--hero-top) - 20px)';
  return 'var(--hero-top)';
]]]

card.padding-bottom:
[[[
  const mm = (q) => (window.matchMedia ? window.matchMedia(q).matches : false);
  const isPhonePortrait =
    (mm('(pointer: coarse)') || mm('(hover: none)')) &&
    mm('(max-width: 767px)') &&
    mm('(orientation: portrait)');

  return isPhonePortrait
    ? `calc(env(safe-area-inset-bottom, 0px) + var(--casora-entity-mobile-bottom-gap, 20px))`
    : `calc(130px + env(safe-area-inset-bottom))`;
]]]

card.--hero-img:
[[[
  const isDark =
    typeof hass?.themes?.darkMode === 'boolean'
      ? hass.themes.darkMode
      : window.matchMedia('(prefers-color-scheme: dark)').matches;

  const base = variables.image || 'default';
  const picked = isDark ? (variables.image_night || `${base}-night`) : base;
  return `url("/casora_assets/rooms/${picked}.jpg")`;
]]]

card.--casora-time-reserve:
[[[
  const w = window?.innerWidth || 1024;
  const h = window?.innerHeight || 800;
  const isTablet = (w >= 768 && w <= 1400 && h > 500);
  return isTablet ? '140px' : '160px';
]]]

card.--casora-room-nav:
[[[
  const k = variables.image || 'default';
  const prev = window._casoraRoomNav;
  if (!prev || prev.key !== k) {
    window._casoraRoomNav = { key: k };
    const isActive = eid => {
      if (!eid) return false;
      const s = hass.states[eid];
      if (!s) return false;
      const st = (s.state || '').toLowerCase();
      if (['playing','buffering','on'].includes(st)) return true;
      if (st === 'paused') {
        const a = s.attributes || {};
        const hasContent = !!(
          String(a.media_title || '').trim() ||
          String(a.media_artist || a.artist || a.media_album_artist || '').trim()
        );
        if (!hasContent) return false;
        const timeout = Number(variables.pause_timeout_minutes ?? 10);
        if (timeout <= 0) return true;
        return ((new Date() - new Date(window._casoraPausedSince?.(s, states) ?? s.last_changed)) / 60000) <= timeout;
      }
      return false;
    };
    const mediaEids = [
      !!variables.media_player_1 && variables.media_player_1,
      !!variables.media_player_2 && variables.media_player_2,
      !!variables.media_player_3 && variables.media_player_3,
      !!variables.media_player_4 && variables.media_player_4,
      !!variables.media_player_5 && variables.media_player_5,
      !!variables.media_player_6 && variables.media_player_6,
      !!variables.media_player_7 && variables.media_player_7,
      !!variables.media_player_8 && variables.media_player_8,
      !!variables.media_player_9 && variables.media_player_9,
      !!variables.media_player_10 && variables.media_player_10,
      !!variables.psn_1 && variables.psn_1,
      !!variables.psn_2 && variables.psn_2,
    ].filter(Boolean);
    const _pc = window._casoraPCSources?.(hass.states, variables) || {};
    const pcActive = !!(_pc.discord || _pc.steam);
    const opt = (!variables.show_now_playing &&
      (mediaEids.some(isActive) || pcActive)) ? 'media' : 'none';
    /* callWS statt callService: kein Fehler-Toast, wenn HA gerade neu startet (Hemma 2.2.0). */
    if (hass.connection?.connected !== false) {
      Promise.resolve(hass.callWS({ type: 'call_service', domain: 'input_select', service: 'select_option',
        service_data: { entity_id: 'input_select.casora_expanded_row', option: opt } })).catch(() => {});
    }
  }
  return k;
]]]

card.--casora-badge-rows:
[[[
  const root = this.shadowRoot;
  if (root && typeof window._casoraBadgeRows === 'function') window._casoraBadgeRows(root);
  return '0';
]]]

card.--casora-name-literal:
[[[
  /* Raumname nach casoraRoomName (04.10.2026): übersetzt nur, was Casora angelegt hat und
     unverändert ist (variables.casora_auto_name); „Home“ ohne Markierung steht, wie gespeichert. */
  const lit = window.casoraRoomName
    ? window.casoraRoomName(this._config && this._config.name, variables).literal
    : variables.name_literal === true;
  const n = this.shadowRoot && this.shadowRoot.getElementById('name');
  if (n) {
    if (lit) {
      n.setAttribute('data-no-i18n', '');
      const want = String(this._config && this._config.name || '');
      /* Nur den Textknoten ändern – textContent löscht Lits Marker (Fehler „nextSibling“). */
      const tn = want && !want.startsWith('[[[') && n.textContent !== want
        && Array.from(n.childNodes).find((c) => c.nodeType === 3 && c.data.trim());
      if (tn) tn.data = want;
    } else n.removeAttribute('data-no-i18n');
  }
  return lit ? '1' : '0';
]]]

card.--casora-badge-order-security:
[[[
  // Standard wie das Studio (BADGE_ORDER_IDS): gespeicherte Reihenfolge zuerst, was fehlt, danach.
  const D = ['security', 'climate', 'lights', 'people', 'energy', 'scenes', 'media'];
  const o = (Array.isArray(variables.badge_order) ? variables.badge_order : []).filter((x) => D.includes(x));
  D.forEach((x) => { if (!o.includes(x)) o.push(x); });
  return o.indexOf('security') + 1;
]]]

