badges.--casora-converge-init:
[[[
  if (!window._casoraEnterPReg) {
    window._casoraEnterPReg = true;
    try {
      CSS.registerProperty({
        name: '--casora-badge-enter-p',
        syntax: '<number>',
        inherits: true,
        initialValue: '0'
      });
    } catch (e) {}
  }
  if (!window._casoraMediaAnim) {
    window._casoraMediaAnim = function (rootEl) {
      try {
        const row = rootEl.querySelector('#badges_media');
        if (!row) return;
        const SPRING = 'cubic-bezier(0.32, 0.72, 0, 1)';
        const OUT    = 'cubic-bezier(0.4, 0, 0.2, 1)';
        const dig = (el, out, d) => {
          if (!el || d > 8) return out;
          for (const c of Array.from(el.children || [])) {
            const t = c.localName === 'button-card' && c._config && c._config.template;
            if (t) { out.push(c); continue; }
            if (c.shadowRoot) dig(c.shadowRoot, out, d + 1);
            dig(c, out, d + 1);
          }
          return out;
        };
        requestAnimationFrame(() => {
          for (const b of dig(row, [], 0)) {
            const f = b.parentElement;
            if (!f || !f.id) continue;
            const op = parseFloat(
              getComputedStyle(b).getPropertyValue('--casora-badge-opacity')) || 0;
            const vis = op > 0;
            if (b._casoraVis === vis) continue;
            const first = b._casoraVis === undefined;
            b._casoraVis = vis;
            if (b._casoraA) { b._casoraA.cancel(); b._casoraA = null; }
            if (f._casoraA) { f._casoraA.cancel(); f._casoraA = null; }
            const gap = parseFloat(getComputedStyle(f).marginRight) || 10;
            if (first) {
              // No animation on the first pass; just settle state.
              b.style.setProperty('--casora-badge-enter-p', vis ? '0' : '1');
              continue;
            }
            if (vis) {
              f.style.maxWidth = 'none';
              void row.offsetWidth;
              const w = b.offsetWidth || 0;
              f.style.maxWidth = '';
              f.style.setProperty('--casora-field-ovf', 'hidden');
              f._casoraA = f.animate(
                [{ maxWidth: '0px', marginRight: '0px' },
                 { maxWidth: w + 'px', marginRight: gap + 'px' }],
                { duration: 420, easing: SPRING, fill: 'none' });
              f._casoraA.onfinish = () => { f.style.removeProperty('--casora-field-ovf'); };
              b.style.setProperty('--casora-badge-enter-p', '1');
              b._casoraA = b.animate(
                [{ '--casora-badge-enter-p': 1 }, { '--casora-badge-enter-p': 0 }],
                { duration: 460, easing: SPRING, fill: 'forwards' });
            } else {
              const w = f.offsetWidth || 0;
              b._casoraA = b.animate(
                [{ '--casora-badge-enter-p': 0 }, { '--casora-badge-enter-p': 1 }],
                { duration: 320, easing: OUT, fill: 'forwards' });
              b._casoraA.onfinish = () => {
                f._casoraA = f.animate(
                  [{ maxWidth: w + 'px', marginRight: gap + 'px' },
                   { maxWidth: '0px', marginRight: '0px' }],
                  { duration: 380, easing: SPRING, fill: 'forwards' });
              };
            }
          }
        });
      } catch (e) {}
    };
  }
  if (!window._casoraConverge) {
    window._casoraConverge = function (rootEl, rowId, groupTpl, useRects, cold) {
      try {
        const row = rootEl.querySelector('#' + rowId);
        const top = rootEl.querySelector('#badges');
        if (!row || !top) return;
        if (!cold && getComputedStyle(row).getPropertyValue('--casora-row-fade').trim() !== '1') return;
        const dig = (el, out, d) => {
          if (!el || d > 8) return out;
          for (const c of Array.from(el.children || [])) {
            const t = c.localName === 'button-card' && c._config && c._config.template;
