  const wx = window.casoraWx ? window.casoraWx(variables, 'entity') : (variables.weather_entity || '');
  const wxt = window.casoraWx ? window.casoraWx(variables, 'temp') : (variables.weather_temp_sensor || '');
  const hasData = !!(wx || wxt);
  const ok = !!wx && hasData;
  return (isPhonePortrait && ok) ? 'block' : 'none';
]]]

casora_notify_config.value:
[[[
  // Stash regardless: on a cold load this runs before casora-core.js,
  // and the module picks the stash up when it initializes. Without it
  // a layout that renders once - the phone - never applied its
  // switches at all.
  window._casoraNotifyCfg = variables;
  if (window._casoraNotify) window._casoraNotify.configureFrom(variables);
  return true;
]]]

casora_scene_core_guard.value:
[[[
    if (typeof window._casoraSC !== 'object' || window._casoraSCv !== 35) {
      window._casoraSCv = 35;

      const CFG_KEY = 'casora_scene_cfg_v1';
      const IGN_KEY = 'casora_scene_ignore_v1';
      const UD_KEY = 'casora_scene_ignore';

      const SETTLE_PAD_MS = 1500;
      const settleMs = (t) => (Number(t) || 0) * 1000 + SETTLE_PAD_MS;

      const load = (k) => { try { return JSON.parse(localStorage.getItem(k) || '{}') || {}; } catch (_) { return {}; } };
      const save = (k, v) => { try { localStorage.setItem(k, JSON.stringify(v)); } catch (_) {} };

      const cfgCache = load(CFG_KEY);
      const ignore   = load(IGN_KEY);
      // Szenen ohne abrufbare Konfiguration (404, z. B. aus YAML-Paketen): pro Sitzung merken –
      // fensterweit (übersteht eine Neuinitialisierung) und in sessionStorage (übersteht Neuladen),
      // sonst fragt jede Seite sie erneut ab und die Konsole füllt sich mit 404ern.
      const NOCFG_KEY = 'casora_scene_nocfg_v1';
      const noCfg = window._casoraSCnoCfg || (window._casoraSCnoCfg = new Set((() => {
        try {
          const o = JSON.parse(localStorage.getItem(NOCFG_KEY) || 'null');
          return o && o.t > Date.now() - 86400000 && Array.isArray(o.ids) ? o.ids : [];
        } catch (_) { return []; }
      })()));
      const markNoCfg = (id) => {
        noCfg.add(id);
        try { localStorage.setItem(NOCFG_KEY, JSON.stringify({ t: Date.now(), ids: [...noCfg] })); } catch (_) {}
      };
      let apiDead    = false;
      let optimistic = null;
      const RECENT_MS = 2 * 60000;
      const inFlight = new Set();
      const refreshed = new Set();

      const els = new Set();
      window._casoraSCReg = (el) => { if (el) els.add(el); };

      const SORT_HOLD_MS = 2500;
      const SORT_MS      = 450;
      const SORT_EASE    = 'cubic-bezier(0.4, 0, 0.2, 1)';  // matches SORT_MS/EASE in smart-row.js
      const seenIds      = new Set();
      let   heldActive   = null;
      let   sortTimer    = null;
      let   firstSort    = true;
      let   noAnimUntil  = 0;
      let   userTapped   = false;
      let   sortNotBefore = 0;
      let   tapSurface   = null;
      const flipStat     = { runs: 0, moved: 0, skipped: '', stores: [], chips: 0, frozen: 0 };
      let   storeSeq     = 0;
      // Keyed by surface, not by element: smart-row rebuilds its children, and
      // anything cached on the card dies with it.
      const surfaces     = new Map();
      const surfaceOf = (key) => {
        let su = surfaces.get(key || 'default');
        if (!su) { su = { rects: null, freezeUntil: 0, flipTs: 0, html: '', id: ++storeSeq }; surfaces.set(key || 'default', su); }
        return su;
      };
      const reduceMotion = () => {
        try { return window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (_) { return false; }
      };
      const nudge = () => els.forEach((el) => {
        try { if (el.isConnected === false) { els.delete(el); return; } el.requestUpdate && el.requestUpdate(); } catch (_) {}
      });

      const liveHass = () => document.querySelector('home-assistant')?.hass || null;

      // Hold before re-sorting: a scene you just tapped must not jump out
      // from under your finger, and a strip mid-scroll must not reflow.
      const scheduleSort = () => {
        if (sortTimer) return;
        // Boot means the configs arriving, not anything the user did. Once a
        // scene has been tapped, every sort is a real one and animates.
        const first = firstSort && !userTapped;
        // Wait out the scene transition: while lights fade, every state change
        // re-renders the row and replaces the chips mid-animation.
        const wait = first ? 350 : Math.max(SORT_HOLD_MS, sortNotBefore - Date.now());
        sortTimer = setTimeout(function run() {
          if (!first && Date.now() - (window._casoraSCBusy || 0) < 1200) { sortTimer = setTimeout(run, 800); return; }
          sortTimer = null;
          firstSort = false;
          if (first) noAnimUntil = Date.now() + 800;
          const st = liveHass()?.states || null;
          if (st) heldActive = window._casoraSC.activeList(Array.from(seenIds), st);
          tapSurface = null;
          nudge();
        }, wait);
      };

      const eqArr = (a, b) => Array.isArray(a) && Array.isArray(b)
        && a.length === b.length && a.every((v, i) => v === b[i]);

      const SC_C = {
        onBg: 'var(--casora-entity-active-tint-current, rgba(255,255,255,0.94))',
        offBg: 'var(--casora-entity-background, rgba(0,0,0,0.40))',
        onName: 'var(--casora-entity-name-active, rgba(0,0,0,0.88))',
        /* Weich (04.10.2026): Name und Symbol aus dem Theme – auf heller Leinenfläche dunkel, sonst weiß wie bisher. */
        offName: 'var(--casora-scene-off-name, rgba(255,255,255,0.90))',
        offIcon: 'var(--casora-scene-off-icon, rgba(255,255,255,0.90))',
        rim: 'var(--casora-tile-glass-rim, inset 0 1px 0 -0.5px rgba(255,255,255,0.10), 0 2px 8px rgba(0,0,0,0.10))',
        backdrop: 'var(--casora-scene-chip-backdrop, blur(22px) saturate(1.2))',
      };

      const EFFECT_OFF = new Set(['off', 'none', 'no effect', 'effect_stop', 'solid']);
      const effectIsOff = (v) => v == null || EFFECT_OFF.has(String(v).toLowerCase());

      const attrMatch = (t, live) => {
        const la = live.attributes || {};

        if (!effectIsOff(t.effect)) return String(la.effect) === String(t.effect);
        if (t.effect != null && !effectIsOff(la.effect)) return false;

        if (t.brightness != null && t.brightness !== la.brightness) return false;
        const mode = t.color_mode;
        if (mode != null && mode !== la.color_mode) return false;
        if (mode === 'color_temp') {
          if (t.color_temp_kelvin != null && t.color_temp_kelvin !== la.color_temp_kelvin) return false;
        } else if (mode != null) {
          if (t.rgb_color != null && !eqArr(t.rgb_color, la.rgb_color)) return false;
        }
        return true;
      };

      const roomEntityIds = (hass, roomName) => {
        const areas = hass?.areas || {};
        const devices = hass?.devices || {};
        const ents = hass?.entities || {};
        const want = String(roomName || '').trim().toLowerCase();
        if (!want) return null;
        const areaIds = new Set(Object.keys(areas)
          .filter((id) => id.toLowerCase() === want || String(areas[id]?.name || '').trim().toLowerCase() === want));
        if (!areaIds.size) return null;
        const out = new Set();
        Object.keys(ents).forEach((eid) => {
          const e = ents[eid];
          const aid = e?.area_id || (e?.device_id ? devices[e.device_id]?.area_id : null);
          if (aid && areaIds.has(aid)) out.add(eid);
        });
        return out.size ? out : null;
      };

      // Raum ohne gleichnamigen Bereich (umbenannt): Bereiche der Kachel-Entitäten, sonst die Entitäten selbst.
      const roomEntityIdsFrom = (hass, ids) => {
        if (!Array.isArray(ids) || !ids.length) return null;
        const devices = hass?.devices || {};
        const ents = hass?.entities || {};
        const areaOf = (eid) => { const e = ents[eid]; return e?.area_id || (e?.device_id ? devices[e.device_id]?.area_id : null); };
        const cnt = {};
        ids.map(areaOf).filter(Boolean).forEach((a) => { cnt[a] = (cnt[a] || 0) + 1; });
        const top = Math.max(0, ...Object.values(cnt));
        const areaIds = new Set(Object.keys(cnt).filter((a) => cnt[a] === top));
        const out = new Set(ids);
        if (areaIds.size) Object.keys(ents).forEach((eid) => { const a = areaOf(eid); if (a && areaIds.has(a)) out.add(eid); });
        return out;
      };

      const expandEntity = (eid, states, seen) => {
        seen = seen || new Set();
        if (!eid || seen.has(eid)) return [];
        seen.add(eid);
        const mems = states[eid]?.attributes?.entity_id;
        if (Array.isArray(mems)) return mems.flatMap((m) => expandEntity(m, states, seen));
        return [eid];
      };

      const sceneTouchesRoom = (sceneId, states, roomSet) => {
        const targets = states[sceneId]?.attributes?.entity_id;
        if (!Array.isArray(targets)) return false;
        for (const t of targets) {
          if (typeof t !== 'string') continue;
          if (roomSet.has(t)) return true;
          const leaves = expandEntity(t, states);
          for (const l of leaves) if (roomSet.has(l)) return true;
        }
        return false;
      };

      const entityMatch = (eid, t, states) => {
        const live = states[eid];
        if (!live) return false;
        if (String(t.state) !== String(live.state)) return false;
        if (String(t.state) !== 'on') return true;
        if (!eid.startsWith('light.')) return true;
        return attrMatch(t, live);
      };

      const fetchCfg = (sceneId) => {
        if (apiDead || noCfg.has(sceneId) || inFlight.has(sceneId)) return;
        const h = liveHass();
        if (!h) return;
        const sid = h.states[sceneId]?.attributes?.id;
        if (!sid) { markNoCfg(sceneId); return; }
        /* Nur Szenen aus dem HA-Szeneneditor (Plattform „homeassistant“) haben eine
           abrufbare Konfiguration – alle anderen gäben nur einen 404 in der Konsole. */
        const _reg = h.entities && h.entities[sceneId];
        if (h.entities && (!_reg || _reg.platform !== 'homeassistant')) { markNoCfg(sceneId); return; }
        inFlight.add(sceneId);
        h.callApi('GET', 'config/scene/config/' + sid).then((c) => {
          inFlight.delete(sceneId);
          if (c && c.entities) {
            const changed = JSON.stringify(cfgCache[sceneId]) !== JSON.stringify(c);
            cfgCache[sceneId] = c;
            save(CFG_KEY, cfgCache);
            if (changed) nudge();
          }
        }).catch((e) => {
          inFlight.delete(sceneId);
          const code = e?.status_code || e?.status;
          if (code === 401 || code === 403) apiDead = true;
          else markNoCfg(sceneId);
        });
      };

      let udPulled = false;
      let udPullAt = 0;

      const pullShared = (force) => {
        const h = liveHass();
        if (!h || !h.callWS) return;
        if (!force && udPulled) return;
        if (Date.now() - udPullAt < 3000) return;
        udPulled = true;
        udPullAt = Date.now();
        h.callWS({ type: 'frontend/get_user_data', key: UD_KEY }).then((r) => {
          const v = r && r.value;
          if (!v || typeof v !== 'object') return;
          if (JSON.stringify(v) === JSON.stringify(ignore)) return;
          Object.keys(ignore).forEach((k) => delete ignore[k]);
          Object.keys(v).forEach((k) => { ignore[k] = v[k]; });
          save(IGN_KEY, ignore);
          nudge();
        }).catch(() => {});
      };

      const pushShared = () => {
        const h = liveHass();
        if (!h || !h.callWS) return;
        udPullAt = Date.now();
        h.callWS({ type: 'frontend/set_user_data', key: UD_KEY, value: ignore }).catch(() => {});
      };

      const seenTs = {};
      const watchForRemoteApply = (ids, states) => {
        let changed = false;
        (ids || []).forEach((id) => {
          const t = states[id]?.state;
          if (seenTs[id] !== undefined && seenTs[id] !== t) changed = true;
          seenTs[id] = t;
        });
        if (changed) setTimeout(() => pullShared(true), 6000);
      };

      const learn = (sceneId) => {
        const cfg = cfgCache[sceneId];
        const h = liveHass();
        if (!cfg || !h) return;
        const ents = cfg.entities || {};
        const ids = Object.keys(ents);
        if (!ids.length) return;
        const bad = ids.filter((eid) => !entityMatch(eid, ents[eid], h.states));
        if (bad.length > ids.length / 2) return;
        const set = new Set(ignore[sceneId] || []);
        const badSet = new Set(bad);
        ids.forEach((eid) => { if (badSet.has(eid)) set.add(eid); else set.delete(eid); });
        const before = JSON.stringify(ignore[sceneId] || null);
        if (set.size) ignore[sceneId] = Array.from(set); else delete ignore[sceneId];
        save(IGN_KEY, ignore);
        if (JSON.stringify(ignore[sceneId] || null) !== before) { pushShared(); nudge(); }
      };

      window._casoraSC = {
        iconColors: {},

        noteColors(map) {
          // A YAML list of single-key maps is the easy slip next to `scenes:`.
          if (Array.isArray(map)) map = Object.assign({}, ...map.filter((x) => x && typeof x === 'object'));
          if (map && typeof map === 'object') Object.assign(this.iconColors, map);
        },

        list(states, hass, vars) {
          const v = vars || {};
          const reg = hass?.entities || {};
          const getReg = (id) => reg[id] || (reg.get && reg.get(id)) || null;
          const excl = new Set(Array.isArray(v.scene_exclude) ? v.scene_exclude : []);

          const explicit = Array.isArray(v.scenes) && v.scenes.length > 0;
          let ids = explicit
            ? v.scenes.filter((id) => states[id])
            : Object.keys(states || {})
                .filter((id) => id.startsWith('scene.') && !id.startsWith('scene.casora'))
                .filter((id) => {
                  const re = getReg(id);
                  return re && !(re.hidden || re.hidden_by || re.disabled || re.disabled_by);
                });

          ids = ids.filter((id) => !excl.has(id));

          // Bereich des Raums: gespeicherte Zuordnung (area), sonst gleichnamiger Bereich, sonst der
          // häufigste Bereich der Kachel-Entitäten (umbenannter Raum). Nichts gefunden: keine Szenen statt aller.
          if (v.area || v.room || (Array.isArray(v.room_entities) && v.room_entities.length)) {
            const roomSet = roomEntityIds(hass, v.area) || roomEntityIds(hass, v.room) || roomEntityIdsFrom(hass, v.room_entities);
            ids = roomSet ? ids.filter((id) => roomSet.has(id) || sceneTouchesRoom(id, states, roomSet)) : [];
          }
          if (!explicit) {
            const nameOf = (id) => states[id]?.attributes?.friendly_name
              || id.replace('scene.', '').replace(/_/g, ' ');
            ids.sort((a, b) => nameOf(a).localeCompare(nameOf(b)));
          }

          if (Array.isArray(v.scene_order)) {
            const so = v.scene_order;
            ids.sort((a, b) => {
              const ai = so.indexOf(a), bi = so.indexOf(b);
              if (ai !== -1 && bi !== -1) return ai - bi;
              if (ai !== -1) return -1;
              if (bi !== -1) return 1;
              return 0;
            });
          }
          return ids;
        },

        prefetch(ids, states) {
          pullShared(false);
          if (states) watchForRemoteApply(ids, states);
          (ids || []).forEach((id) => {
            if (!cfgCache[id]) { fetchCfg(id); return; }
            if (!refreshed.has(id)) { refreshed.add(id); fetchCfg(id); }
          });
        },

        isActive(sceneId, states) {
          if (optimistic && optimistic.id === sceneId && Date.now() < optimistic.until) return true;
          const cfg = cfgCache[sceneId];
          /* Szene ohne lesbare Konfiguration (YAML, Hue, andere Integrationen): Ob sie noch gilt, lässt
             sich nicht prüfen. Kurz nach dem Start gilt sie als aktiv – ruhige Rückmeldung statt
             „Keine aktiv“ direkt nach dem Antippen. */
          if (!cfg || !cfg.entities) {
            const t = Date.parse(states?.[sceneId]?.state);
            return isFinite(t) && Date.now() - t >= -5000 && Date.now() - t < RECENT_MS;
          }
          const ign = new Set(ignore[sceneId] || []);
          const ents = cfg.entities;
          let checked = 0;
          for (const eid of Object.keys(ents)) {
            if (ign.has(eid)) continue;
            if (!entityMatch(eid, ents[eid], states)) return false;
            checked++;
          }
          return checked > 0;
        },

        activeList(ids, states) {
          const ts = (id) => {
            const t = Date.parse(states[id]?.state);
            return isNaN(t) ? 0 : t;
          };
          return (ids || [])
            .filter((id) => this.isActive(id, states))
            .sort((a, b) => ts(b) - ts(a));
        },

        activeOf(ids, states) {
          return this.activeList(ids, states)[0] || null;
        },

        // Visual order only: the caller keeps building chips in its own
        // order, so the DOM stays stable and flip() has something to move.
        order(ids, states, sid) {
          const list = ids || [];
          list.forEach((id) => seenIds.add(id));
          const live = this.activeList(list, states);
          if (heldActive === null) heldActive = live;
          else {
            const liveSet = new Set(live);
            const heldSet = new Set(heldActive);
            if (list.some((id) => liveSet.has(id) !== heldSet.has(id))) scheduleSort();
          }
          // The hold exists so a tapped chip cannot jump out from under the
          // finger. Every other surface is off-screen, so it sorts now and is
          // already correct when the user gets back to it.
          const held = (tapSurface != null && sid != null && sid !== tapSurface)
            ? live : (heldActive || []);
          const rank = new Map();
          held.forEach((id, i) => rank.set(id, i));
          const active = list.filter((id) => rank.has(id)).sort((a, b) => rank.get(a) - rank.get(b));
          const rest   = list.filter((id) => !rank.has(id));
          const out = new Map();
          active.concat(rest).forEach((id, i) => out.set(id, i));
          return out;
        },

        // FLIP across renders: chips are rebuilt from innerHTML every time,
        // so positions are cached per container and keyed by scene id.
        flip(el, key) {
          // The caller may hand us the field element, the card, or the card's
          // shadow root; find whichever one actually holds chips.
          const cands = [];
          if (el) {
            cands.push(el);
            if (el.shadowRoot) cands.push(el.shadowRoot);
            const h = el.getRootNode && el.getRootNode().host;
            if (h) { cands.push(h); if (h.shadowRoot) cands.push(h.shadowRoot); }
          }
          let root = null;
          for (let i = 0; i < cands.length; i++) {
            const c = cands[i];
            if (c && c.querySelector && c.querySelector('[data-scene]')) { root = c; break; }
          }
          if (!root) { flipStat.runs++; flipStat.skipped = 'no-chips-found'; return; }
          const nodes = Array.from(root.querySelectorAll('[data-scene]'));
          const su = surfaceOf(key);
          if (su.flipTs && Date.now() - su.flipTs < 50) return;
          su.flipTs = Date.now();
          // Overlays are built inside a display:none subtree, so every offset
          // reads 0 and a snapshot taken here would fling each chip in from
          // the container's corner on the next render.
          if (!nodes.some((n) => n.offsetWidth || n.offsetHeight)) {
            su.rects = null;
            flipStat.runs++;
            flipStat.skipped = 'not-laid-out';
            return;
          }
          flipStat.stores.push(su.id);
          if (flipStat.stores.length > 6) flipStat.stores.shift();
          flipStat.chips = nodes.length;
          const prev = su.rects;
          const cur = {};
          nodes.forEach((n) => { cur[n.dataset.scene] = { l: n.offsetLeft, t: n.offsetTop }; });
          su.rects = cur;
          flipStat.runs++;
          flipStat.skipped = !prev ? 'no-previous-positions'
            : reduceMotion() ? 'prefers-reduced-motion'
            : Date.now() < noAnimUntil ? 'boot-window'
            : (tapSurface != null && su.id !== tapSurface) ? 'other-surface' : '';
          if (flipStat.skipped) return;
          let moved = 0;
          nodes.forEach((n) => {
            const p = prev[n.dataset.scene];
            if (!p) return;
            const c = cur[n.dataset.scene];
            const dx = p.l - c.l, dy = p.t - c.t;
            if (Math.abs(dx) < 1 && Math.abs(dy) < 1) return;
            moved++;
            const t0 = n.style.transition;
            n.style.transition = 'none';
            n.style.transform = 'translate(' + dx + 'px,' + dy + 'px)';
            requestAnimationFrame(() => requestAnimationFrame(() => {
              n.style.transition = 'transform ' + SORT_MS + 'ms ' + SORT_EASE;
              n.style.transform = '';
              setTimeout(() => { n.style.transition = t0; }, SORT_MS + 60);
            }));
          });
          flipStat.moved = moved;
          if (!moved) flipStat.skipped = 'no-position-change';
          else {
            // Every light the scene touches re-renders the row, and a re-render
            // swaps in fresh chips mid-transition. Hold the markup steady until
            // the slide is done: an identical string means no DOM churn.
            su.freezeUntil = Date.now() + SORT_MS + 120;
            flipStat.frozen++;
          }
        },

        chipHtml(sceneId, states, opts) {
          const o = opts || {};
          const on = this.isActive(sceneId, states);
          const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;')
            .replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
          const st = states[sceneId];
          const name = esc(st?.attributes?.friendly_name
            || sceneId.replace('scene.', '').replace(/_/g, ' '));
          // Last activation, same wording as the desktop scene badges.
          const ago = (() => {
            const t = Date.parse(st?.state);
            if (!isFinite(t)) return 'Noch nie';
            const m = Math.round((Date.now() - t) / 60000);
            if (m < 1) return 'Gerade eben';
            if (m < 60) return 'Vor ' + m + ' Min.';
            const h = Math.round(m / 60);
            // Calendar days, not 24-hour blocks: 36 hours ago is still yesterday.
            const day = (x) => { const o = new Date(x); return new Date(o.getFullYear(), o.getMonth(), o.getDate()); };
            const d = Math.round((day(Date.now()) - day(t)) / 86400000);
            if (h < 24 || d < 1) return 'Vor ' + h + ' Std.';
            return d === 1 ? 'Gestern' : 'Vor ' + d + ' Tagen';
          })();
          const trans = o.transition == null ? 4 : o.transition;
          const accent = 'var(--casora-color-yellow, #FFCC00)';
          // Eine Quelle für alle Flächen (1.1.2): casoraSceneColor liest die Vorlage des Dashboards; alte Kopien
          // in Karten-Variablen zählen nicht mehr.
          const clr = o.color || (window.casoraSceneColor ? window.casoraSceneColor(sceneId) : this.iconColors[sceneId]) || null;
          const tint = on
            ? (clr ? String(clr).replace(/["<>]/g, '') : accent)
            : SC_C.offIcon;
          /* Symbol im Kreis wie die übrigen Kacheln, wenn das Theme es will (--casora-scene-icon-circle: 1,
             Weich): aus = neutraler Kreis, aktiv = Kreis in der Szenenfarbe mit hellem Symbol. */
          const _ring = 'calc(var(--casora-scene-icon-circle, 0) * 100%)';
          const circleBg = on
            ? 'color-mix(in srgb, ' + tint + ' ' + _ring + ', transparent)'
            : 'color-mix(in srgb, var(--casora-icon-circle-bg, transparent) ' + _ring + ', transparent)';
          const ink = on ? 'color-mix(in srgb, #ffffff ' + _ring + ', ' + tint + ')' : tint;

          const glyph = o.icon
            ? '<div style="width:var(--casora-scene-glyph, 26px);height:var(--casora-scene-glyph, 26px);background-color:' + ink
              + ';transition:background-color 0.45s ease'
              + ';-webkit-mask:url(' + esc(o.icon) + ') no-repeat center/contain;mask:url('
              + esc(o.icon) + ') no-repeat center/contain;"></div>'
            : '<ha-icon icon="' + esc(st?.attributes?.icon || 'mdi:palette')
              + '" style="--mdc-icon-size:var(--casora-scene-glyph, 26px);transition:color 0.45s ease;color:' + ink + ';"></ha-icon>';

          const sizing = (o.grid
            ? 'width:100%;'
            : 'flex:0 0 auto;width:' + (o.width || '41vw') + ';')
            + (o.order == null ? '' : 'order:' + o.order + ';');

          const tap = ' onpointerdown="this.dataset.sx=event.clientX;this.dataset.sy=event.clientY"'
            + ' onpointerup="var dx=Math.abs(event.clientX-this.dataset.sx),'
            + 'dy=Math.abs(event.clientY-this.dataset.sy);if(dx>8||dy>8)return;'
            + 'event.stopPropagation();window._casoraSC&amp;&amp;window._casoraSC.apply(&#39;'
            + sceneId + '&#39;,' + trans + ',' + (o.sid == null ? 'null' : o.sid) + ')"';

          return '<div role="button" tabindex="0" data-scene="' + esc(sceneId) + '"' + tap
            + ' style="' + sizing
            + 'display:flex;align-items:center;gap:10px;box-sizing:border-box;'
            // Content-sized chips need extra air after the text.
            + 'padding:' + (o.width === 'auto' ? '12px 20px 12px 12px' : '12px') + ';'
            // One height and radius for every surface: the home row and the
            // Scenes page are the same component and must not diverge.
            + 'min-height:var(--casora-scene-tile-h, 56px);'
            + 'border-radius:var(--casora-scene-tile-radius, 20px);'
            + 'cursor:pointer;pointer-events:auto;-webkit-tap-highlight-color:transparent;'
            + 'user-select:none;-webkit-user-select:none;'
            + 'transition:background 0.45s ease,transform 0.2s ease;'
            + 'box-shadow:' + SC_C.rim + ';'
            + '-webkit-backdrop-filter:' + SC_C.backdrop + ';backdrop-filter:' + SC_C.backdrop + ';'
            + 'background:' + (on ? SC_C.onBg : SC_C.offBg) + ';">'
              + '<div style="width:var(--casora-scene-icon-box, 28px);height:var(--casora-scene-icon-box, 28px);'
                + 'min-width:var(--casora-scene-icon-box, 28px);display:flex;border-radius:50%;'
                + 'background:' + circleBg + ';transition:background 0.45s ease;'
                + 'align-items:center;justify-content:center;">' + glyph + '</div>'
              + '<div style="display:flex;flex-direction:column;align-items:flex-start;text-align:left;min-width:0;'
                + 'font-family:var(--primary-font-family,system-ui);">'
                + '<div style="font-size:14px;font-weight:var(--casora-scene-name-weight, 500);line-height:1.2;max-width:100%;' + (o.grid ? 'white-space:normal;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;' : 'white-space:nowrap;')
                + 'overflow:hidden;text-overflow:ellipsis;'
                + 'color:' + (on ? SC_C.onName : SC_C.offName) + ';">' + name + '</div>'
                // Same state typography as casora_entity tiles.
                + '<div style="display:none;font-size:12px;font-weight:500;line-height:1.15;margin-top:2px;white-space:nowrap;max-width:100%;'
                + 'overflow:hidden;text-overflow:ellipsis;transition:color 0.45s ease;'
                + 'opacity:var(--casora-state-opacity, 0.75);'
                + 'color:' + (on ? SC_C.onName : SC_C.offName) + ';">' + esc(ago) + '</div>'
                + '</div>'
            + '</div>';
        },

        chip(sceneId, opts) {
          const o = opts || {};
          const sid = JSON.stringify(sceneId);
          const icon = o.icon || null;
          const trans = o.transition == null ? 4 : o.transition;
          const act = 'var _sca = window._casoraSC ? window._casoraSC.isActive(' + sid + ', states) : false;';
          const maskCss = icon
            ? '#img-cell img{opacity:0!important;}div#img-cell::after{content:""!important;display:block!important;position:absolute!important;inset:0!important;background-color:var(--sc-clr,#ffffff)!important;-webkit-mask-image:url(' + JSON.stringify(icon) + ')!important;-webkit-mask-repeat:no-repeat!important;-webkit-mask-position:center!important;-webkit-mask-size:auto 58%!important;mask-image:url(' + JSON.stringify(icon) + ')!important;mask-repeat:no-repeat!important;mask-position:center!important;mask-size:auto 58%!important;pointer-events:none!important;transform:translateZ(0)!important;}'
            : '';
          const card = [
            { background: '[[[ ' + act + ' return _sca?"' + SC_C.onBg + '":"' + SC_C.offBg + '"; ]]]' },
            { '--sc-nc': '[[[ ' + act + ' return _sca?"' + SC_C.onName + '":"' + SC_C.offName + '"; ]]]' },
            { '--sc-clr': '[[[ ' + act + ' return _sca?"#ffffff":"var(--casora-color-yellow, #FFCC00)"; ]]]' },
            { '--casora-card-hover-filter': '[[[ ' + act + ' return _sca?"none":"brightness(1.10)"; ]]]' },
            { '--sc-hover-tint': '[[[ ' + act + ' return _sca?"transparent":"rgba(255,255,255,0.06)"; ]]]' },
            { border: 'none' },
            { 'box-shadow': 'none' },
            { 'border-radius': '26px' },
            { cursor: 'pointer' },
            { padding: '12px 12px' },
            { width: o.width || '100%' },
          ];
          if (o.width) card.push({ 'min-width': o.width });
          return {
            type: 'custom:button-card',
            entity: sceneId,
            tap_action: {
              action: 'fire-dom-event',
              event_data: { casora_scene_tap: sceneId, casora_scene_transition: trans },
            },
            haptic: 'medium',
            show_icon: true,
            show_entity_picture: true,
            entity_picture: '[[[ return ' + JSON.stringify(icon) + ' || states[' + sid + ']?.attributes?.entity_picture || undefined; ]]]',
            icon: '[[[ return states[' + sid + ']?.attributes?.icon || "mdi:palette"; ]]]',
            show_name: true,
            show_state: false,
            show_label: false,
            name: '[[[ return states[' + sid + ']?.attributes?.friendly_name || ' + sid + '.replace("scene.", "").replace(/_/g, " "); ]]]',
            extra_styles: ':host{--casora-card-hover-filter:brightness(1.10);width:100%!important;max-width:none!important;display:block!important;box-sizing:border-box!important;--button-card-ripple-color:transparent!important;--button-card-ripple-hover-color:transparent!important;--ha-ripple-color:transparent!important;--ha-ripple-hover-color:transparent!important;}ha-card{transition:background 0.45s ease,transform var(--casora-popup-tile-hover-duration,0.2s) ease,filter var(--casora-popup-tile-hover-duration,0.2s) ease!important;transform:scale(1)!important;}ha-card:hover{transform:scale(var(--casora-popup-tile-hover-scale,1.01))!important;}ha-card:active{transform:scale(0.97)!important;}@media (hover:hover){ha-card:hover{filter:var(--casora-card-hover-filter,brightness(1.06))!important;}ha-card:hover::after{background:var(--sc-hover-tint,rgba(255,255,255,0.06))!important;}}ha-card::before{display:none!important;}ha-card::after{content:""!important;position:absolute!important;inset:0!important;border-radius:inherit!important;background:transparent!important;transition:background var(--casora-popup-tile-hover-duration,0.2s) ease!important;pointer-events:none!important;}ha-ripple{display:none!important;}div#img-cell{position:relative!important;overflow:hidden!important;}div#img-cell::before{display:none!important;}ha-icon{--mdc-icon-size:22px!important;color:var(--sc-clr,#ffffff)!important;}#img-cell img{width:60%!important;height:60%!important;object-fit:contain!important;}' + maskCss,
            styles: {
              card: card,
              grid: [
                { 'grid-template-areas': '"i n"' },
                { 'grid-template-columns': 'auto minmax(0, 1fr)' },
                { 'column-gap': '10px' },
                { 'align-items': 'center' },
              ],
              img_cell: [
                { background: '[[[ ' + act + ' return _sca?"var(--casora-color-yellow,#FFCC00)":"rgba(255,255,255,0.10)"; ]]]' },
                { 'border-radius': '50%' },
                { width: '38px' },
                { height: '38px' },
                { 'min-width': '38px' },
                { display: 'flex' },
                { 'align-items': 'center' },
                { 'justify-content': 'center' },
                { 'align-self': 'center' },
              ],
              entity_picture: [{ width: '60%' }, { height: '60%' }, { 'object-fit': 'contain' }],
              name: [
                { 'font-size': '14px' },
                { 'font-weight': '500' },
                { color: 'var(--sc-nc)' },
                { 'text-align': 'left' },
                { 'justify-self': 'start' },
                { 'align-self': 'center' },
                { 'line-height': '1.2' },
                { overflow: 'hidden' },
                { 'text-overflow': 'ellipsis' },
                { 'white-space': 'nowrap' },
              ],
            },
          };
        },

        apply(sceneId, transition, sid) {
          const h = liveHass();
          if (!h) return;
          const t = transition == null ? 4 : transition;
          const settle = settleMs(t);
          optimistic = { id: sceneId, until: Date.now() + settle + 750 };
          userTapped = true;
          tapSurface = sid == null ? null : sid;
          sortNotBefore = Date.now() + t * 1000 + 400;
          h.callService('scene', 'turn_on', { entity_id: sceneId, transition: t });
          setTimeout(() => learn(sceneId), settle);
        },

        debug() {
          return { apiDead, noCfg: Array.from(noCfg), cached: Object.keys(cfgCache), ignore };
        },

        surfaceId(key) { return surfaceOf(key).id; },

        frozenHtml(key) {
          const su = surfaces.get(key || 'default');
          return (su && su.freezeUntil > Date.now() && su.html) ? su.html : null;
        },

        noteHtml(key, h) { surfaceOf(key).html = h; },

        sortDebug() {
          return 'v=' + window._casoraSCv + ' flips=' + flipStat.runs + ' moved=' + flipStat.moved
            + ' skipped=' + (flipStat.skipped || 'none')
            + ' firstSort=' + firstSort + ' userTapped=' + userTapped
            + ' waitLeft=' + Math.max(0, sortNotBefore - Date.now())
            + ' chips=' + flipStat.chips + ' frozen=' + flipStat.frozen
            + ' stores=[' + flipStat.stores.join(',') + ']'
            + ' held=[' + (heldActive || []).join(',') + ']';
        },
      };
    }

    if (!window._casoraSCTap) {
      window._casoraSCTap = true;
      document.addEventListener('ll-custom', (e) => {
        const d = (e.detail && e.detail.event_data) ? e.detail.event_data : (e.detail || {});
        if (!d.casora_scene_tap) return;
        window._casoraSC.apply(d.casora_scene_tap, d.casora_scene_transition);
      });
    }
    return true;
  ]]]

custom_fields.sc_init:
[[[
  try {
    const host = this.getRootNode && this.getRootNode().host;
    if (host && typeof window._casoraSCReg === 'function') window._casoraSCReg(host);
    const rail = host && host.shadowRoot ? host.shadowRoot.getElementById('scenes_row') : null;
    if (rail && window._casoraSC && window._casoraSC.flip) {
      if (!rail._scBusyBound) {
        rail._scBusyBound = true;
        rail.addEventListener('scroll', () => { window._casoraSCBusy = Date.now(); }, { passive: true });
      }
      requestAnimationFrame(() => { try { window._casoraSC.flip(rail); } catch (_) {} });
    }
  } catch (_) {}
  return '';
]]]

custom_fields.scenes_row:
[[[
  const SC = window._casoraSC;
  if (!SC) return '';

  const _self = this;
  const ids = SC.list(states, typeof hass !== 'undefined' ? hass : null, variables);
  if (!ids.length) return '';

  // Surface key survives a card rebuild; smart-row recreates its children.
  const _key = (variables.layout || 'row') + '|' + (variables.room || '') + '|' + ids.join(',');

  // Colors live on SC so the JS-built Scenes page and room rows see them too.
  // Vor frozenHtml und als ganze Liste (B-SZENE): eine im Studio zurückgesetzte Farbe verschwindet
  // sofort, nicht erst nach dem Neuladen.
  if (SC.noteColors && variables.scene_colors && typeof variables.scene_colors === 'object') {
    if (SC.iconColors) Object.keys(SC.iconColors).forEach((k) => { delete SC.iconColors[k]; });
    SC.noteColors(variables.scene_colors);
  }

  if (SC.frozenHtml) {
    const _frozen = SC.frozenHtml(_key);
    if (_frozen) return _frozen;
  }
  SC.prefetch(ids, states);

  const grid = variables.layout === 'grid';
  const icons = variables.scene_icons || {};
  const opts = {
    transition: variables.scene_transition == null ? 4 : variables.scene_transition,
    width: variables.chip_width || 'min(41vw, 176px)',
    grid: grid,
  };

  const _sid = SC.surfaceId ? SC.surfaceId(_key) : null;
  const ord = SC.order ? SC.order(ids, states, _sid) : null;

  if (SC.flip) {
    if (!_self._scBusyBound) {
      _self._scBusyBound = true;
      try {
        _self.addEventListener('scroll', () => { window._casoraSCBusy = Date.now(); }, { passive: true });
      } catch (_) {}
    }
    requestAnimationFrame(() => { try { SC.flip(_self, _key); } catch (_) {} });
  }

  const inner = grid
    ? 'display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--casora-scene-grid-row-gap, 12px) var(--casora-scene-grid-col-gap, 11px);width:100%;pointer-events:auto;'
    : 'display:flex;flex-direction:row;gap:8px;width:max-content;min-width:100%;pointer-events:auto;';

  const dbg = (variables.sort_debug === true && SC.sortDebug)
    ? '<div style="font:11px/1.4 ui-monospace,monospace;color:rgba(255,255,255,0.75);'
      + 'padding:2px 0 6px 0;white-space:pre-wrap;word-break:break-all;">'
      + SC.sortDebug() + '</div>'
    : '';

  const _html = dbg + '<div style="' + inner + '">'
    + ids.map((id) => SC.chipHtml(id, states, Object.assign(
        { icon: icons[id] || null, order: ord ? ord.get(id) : null, sid: _sid }, opts))).join('')
    + '</div>';
  if (SC.noteHtml) SC.noteHtml(_key, _html);
  return _html;
]]]

casora_scene_row.extra_styles:
/* max-width: overlay hosts are fit-content and collapse without this. */
:host {
  display: block !important;
  width: 100% !important;
  max-width: none !important;
  min-width: 0 !important;
  box-sizing: border-box !important;
}
/* Theme sets will-change on every ha-card; that kills descendant blur. */
ha-card {
  will-change: auto !important;
  transform: none !important;
  filter: none !important;
  isolation: auto !important;
  contain: none !important;
}
#scenes_row::-webkit-scrollbar { display: none !important; }

state.value:
[[[
  const SC = window._casoraSC;
  if (!SC) return false;
  const ids = SC.list(states, typeof hass !== 'undefined' ? hass : null, variables);
  SC.prefetch(ids, states);
  return !!SC.activeOf(ids, states);
]]]

casora_scenes.state_display:
[[[
  const fit = (t) => window.casoraStateFit?.(t) ?? t;
  const SC = window._casoraSC;
  if (!SC) return 'Szenen';
  const ids = SC.list(states, typeof hass !== 'undefined' ? hass : null, variables);
  if (!ids.length) return 'Keine Szenen';
  SC.prefetch(ids, states);
  const active = SC.activeList(ids, states);
  if (active.length) {
    const name = states[active[0]]?.attributes?.friendly_name
      || active[0].replace('scene.', '').replace(/_/g, ' ');
    return fit(active.length > 1 ? name + ' +' + (active.length - 1) : name);
  }
  return fit(ids.length + (ids.length === 1 ? ' Szene' : ' Szenen'));
]]]

casora_settings_button.extra_styles:
/* ha-card is overflow:visible so the count can sit proud of the circle,
   which also stopped it clipping button-card's ripple - a square layer
   filling the card's box, so the hover read as a box behind the disc. */
:host{
  --button-card-ripple-color: transparent !important;
  --button-card-ripple-hover-color: transparent !important;
  --ha-ripple-color: transparent !important;
  --ha-ripple-hover-color: transparent !important;
  --mdc-ripple-press-opacity: 0 !important;
}
:host ha-ripple,
:host mwc-ripple{ display: none !important; }
:host{
  display: grid !important;
  place-items: center !important;
  width: var(--casora-chrome-btn-size, 34px) !important;
  height: var(--casora-chrome-btn-size, 34px) !important;
  color: var(--casora-chrome-ink, #fff) !important;
  pointer-events: auto !important;
}

/* MUST match .np-head-wave in casora_now_playing_header exactly: same size,
   same flat fill, blur but no rim. --casora-settings-fill is set while the
   menu is open, so the button inverts the way the waveform does. */
:host ha-card{
  /* The var is set by styles.card, which lands on ha-card - so it has to be
     read here. Reading it from :host always fell back to none, because a
     custom property set on a child is invisible to its parent. */
  display: var(--casora-settings-vis, none) !important;
  position: relative !important;
  width: var(--casora-chrome-btn-size, 34px) !important;
  height: var(--casora-chrome-btn-size, 34px) !important;
  border-radius: 50% !important;
  place-items: center !important;
  background: var(--casora-settings-fill, var(--casora-chrome-fill, rgba(0,0,0,0.40))) !important;
  /* Weich (1.0.7, Kopfleiste D): Fläche mit weichem Schatten über Theme-Variablen, sonst flach. */
  backdrop-filter: var(--casora-chrome-backdrop, none) !important;
  -webkit-backdrop-filter: var(--casora-chrome-backdrop, none) !important;
  box-shadow: var(--casora-chrome-shadow, none) !important;
  transition: background 180ms cubic-bezier(.32,.72,0,1) !important;
}

/* button-card wraps custom fields in .vertical > .ellipsis, and .ellipsis is
   bottom-aligned AND clips - it was cutting the top pixel off the glyph. */
:host .vertical,
:host .ellipsis,
:host .custom-field,
:host .custom-field-glyph{ overflow: visible !important; }

:host .casora-settings{
  position: absolute !important;
  top: 50% !important;
  left: 50% !important;
  transform: translate(-50%, -50%) !important;
  width: var(--casora-settings-size, 14px) !important;
  height: var(--casora-settings-size, 14px) !important;
  display: block !important;
  fill: var(--casora-settings-ink, var(--casora-chrome-ink, #fff)) !important;
  pointer-events: none !important;
  transition: fill 180ms cubic-bezier(.32,.72,0,1) !important;
}

@media (hover: hover) and (pointer: fine){
  :host ha-card:hover{
    background: var(--casora-settings-fill, var(--casora-chrome-fill-hover, rgba(0,0,0,0.55))) !important;
  }
}

/* Weich (1.0.7): Symbole etwas leichter (--casora-chrome-glyph-opacity, sonst 1). */
:host .casora-settings{ opacity: var(--casora-chrome-glyph-opacity, 1); }

tap_action.javascript:
[[[
  const OPEN = 'casora-settings-menu';
  const gone = document.querySelector('.' + OPEN);
  if (gone) { if (gone._close) gone._close(); return; }

  const host = this;
  const PHONE = window.matchMedia(
    '(max-width: 767px), (max-height: 500px)').matches;
  const lift = function (on) {
    if (PHONE) return;
    if (on) {
      host.style.setProperty('--casora-settings-fill', '#fff');
      host.style.setProperty('--casora-settings-ink', '#1c1c20');
    } else {
      host.style.removeProperty('--casora-settings-fill');
      host.style.removeProperty('--casora-settings-ink');
    }
  };
  lift(true);

  const card = host.shadowRoot && host.shadowRoot.querySelector('ha-card');
  let r = (card || host).getBoundingClientRect();
  for (let up = host, i = 0; up && i < 6; i++) {
    const rootNode = up.getRootNode && up.getRootNode();
    up = rootNode && rootNode.host;
    const tpl = up && up._config && up._config.template;
    if (tpl && [].concat(tpl).indexOf('casora_mobile_chrome') >= 0) {
      const cap = up.shadowRoot && up.shadowRoot.querySelector('ha-card');
      if (cap) r = cap.getBoundingClientRect();
      break;
    }
  }

  // document.body, or button-card's .ellipsis wrapper clips it.
  const menu = document.createElement('div');
  menu.className = OPEN;
  menu.setAttribute('role', 'menu');
  Object.assign(menu.style, {
    position: 'fixed', zIndex: '99999', padding: '6px', minWidth: '168px',
    boxSizing: 'border-box',
  });
  if (window.casoraMenuGlass) {
    window.casoraMenuGlass.apply(menu);
    if (window.casoraMenuGlass.lockScroll) window.casoraMenuGlass.lockScroll(menu);
  }

  let overflowAssist = false;
  if (variables.assist_available) {
    for (let up = host, i = 0; up && i < 6; i++) {
      const rn = up.getRootNode && up.getRootNode();
      up = rn && rn.host;
      const t = up && up._config && up._config.template;
      if (t && [].concat(t).indexOf('casora_room') >= 0) {
        const slot = up.shadowRoot && up.shadowRoot.getElementById('assist');
        try {
          overflowAssist = !!slot && getComputedStyle(slot).display === 'none';
        } catch (e) {}
        break;
      }
    }
  }

  const ITEMS = [
    // Ein Eintrag: lädt neu und leert dabei Casoras Zwischenspeicher (04.10.2026, 1.0.6).
    { label: 'Aktualisieren', icon: 'mdi:refresh', tone: 'general',
      run: function () {
        if (window.casoraHardReload) window.casoraHardReload(); else window.location.reload();
      } },
    /* D-16 (Weich): alle Menü-Symbole im selben Farbkreis wie „Aktualisieren“ und das Räume-Menü. */
    { label: 'Dashboard bearbeiten', icon: 'mdi:pencil', tone: (window._casoraSoft && window._casoraSoft()) ? 'general' : 'settings', run: function () {
      const seg = (window.location.pathname || '').split('/').filter(Boolean);
      const view = seg.length > 1 ? seg[1] : '';
      const dash = seg.length ? seg[0] : '';
      // Muss zu PANEL_URL in custom_components/casora/const.py passen
      window.location.assign('/casora-studio' + (view ? '/' + view : '')
        + (dash ? '?dash=' + encodeURIComponent(dash) : ''));
    } },
  ];

  if (overflowAssist) {
    ITEMS.unshift({ label: 'Assist', glyph: 'assist-fill', tone: 'general', run: function () {
      if (window._casoraAssist && window._casoraAssist.open()) return;
      const root = document.querySelector('home-assistant') || host;
      root.dispatchEvent(new CustomEvent('hass-action', {
        bubbles: true, composed: true,
        detail: { config: { tap_action: { action: 'assist' } }, action: 'tap' },
      }));
    } });
  }

  const mkItem = function (spec) {
  const item = document.createElement('button');
  item.type = 'button';
  item.setAttribute('role', 'menuitem');
  Object.assign(item.style, {
    display: 'flex', alignItems: 'center', gap: 'var(--casora-menu-ic-gap, 14px)',
    width: '100%', textAlign: 'left', border: '0',
    background: 'transparent', color: 'var(--casora-menu-fg, #fff)', font: 'inherit',
    fontSize: 'var(--casora-menu-item-size, 14px)', fontWeight: 'var(--casora-menu-item-weight, 500)', letterSpacing: '-0.01em',
    lineHeight: '1.35', padding: 'var(--casora-menu-item-pad, 9px 13px)',
    // Concentric: the panel's radius less the 6px it sits inside.
    borderRadius: 'var(--casora-menu-item-radius, calc(var(--casora-menu-radius, 28px) - 6px))',
    cursor: 'default', outline: 'none'
  });
  const gl = document.createElement(spec.glyph ? 'span' : 'ha-icon');
  if (spec.glyph) {
    const u = (typeof window.casoraIconUrl === 'function'
      ? window.casoraIconUrl(spec.glyph)
      : '/casora_assets/icons/' + spec.glyph + '.svg');
    gl.style.background = 'var(--casora-menu-fg, rgba(255,255,255,0.92))';
    gl.style.setProperty('-webkit-mask', 'url("' + u + '") no-repeat center / contain');
    gl.style.setProperty('mask', 'url("' + u + '") no-repeat center / contain');
  } else {
    gl.setAttribute('icon', spec.icon);
  }
  Object.assign(gl.style, {
    width: '21px', height: '21px',
    color: 'var(--casora-menu-fg, rgba(255,255,255,0.92))', flex: 'none',
  });
  // A custom property never lands through Object.assign.
  gl.style.setProperty('--mdc-icon-size', '21px');
  const tx = document.createElement('span');
  tx.textContent = spec.label;
  tx.style.whiteSpace = 'nowrap';
  /* Farbsystem (Fix-Runde 1): Symbol im Ton seiner Bedeutung, nur wenn das Design es setzt. */
  item.appendChild(window.casoraMenuGlass && window.casoraMenuGlass.icon
    ? window.casoraMenuGlass.icon(gl, spec.tone, 'var(--casora-menu-fg, rgba(255,255,255,0.92))', !!spec.glyph) : gl);
  item.appendChild(tx);
  const lit = function (on) {
    item.style.background = on ? 'var(--casora-menu-hover, rgba(255,255,255,0.18))' : 'transparent';
  };
  item.onmouseenter = function () { lit(true); };
  item.onmouseleave = function () { lit(false); };
  item.onfocus = function () { lit(true); };
  item.onblur = function () { lit(false); };
  item.onclick = function () { menu._close(); spec.run(); };
  return item;
  };

  ITEMS.forEach(function (spec) { menu.appendChild(mkItem(spec)); });
  document.body.appendChild(menu);

  const w = menu.offsetWidth;
  menu.style.top = (window.casoraMenuGlass && window.casoraMenuGlass.dropTop
    ? window.casoraMenuGlass.dropTop(r, 10)
    : Math.round(r.bottom + 10)) + 'px';
  menu.style.left = Math.round(Math.max(12, Math.min(r.right - w, window.innerWidth - w - 12))) + 'px';
  if (window.casoraMenuGlass) window.casoraMenuGlass.enter(menu);

  const onKey = function (e) { if (e.key === 'Escape') menu._close(); };
  const onAway = function (e) {
    const t = e.composedPath ? e.composedPath()[0] : e.target;
    if (!menu.contains(t)) menu._close();
  };
  menu._close = function () {
    lift(false);
    window.removeEventListener('keydown', onKey, true);
    document.removeEventListener('pointerdown', onAway, true);
    window.removeEventListener('scroll', menu._close, true);
    window.removeEventListener('resize', menu._close);
    if (window.casoraMenuGlass) {
      window.casoraMenuGlass.exit(menu, function () {
        if (menu.parentNode) menu.remove();
      });
    } else if (menu.parentNode) { menu.remove(); }
  };

  setTimeout(function () {
    window.addEventListener('keydown', onKey, true);
    document.addEventListener('pointerdown', onAway, true);
    window.addEventListener('scroll', menu._close, true);
    window.addEventListener('resize', menu._close);
  }, 0);
]]]

casora_shared.extra_styles:
[[[
  const rooms = variables.preload_rooms || [];
  const suffix = variables.preload_night_suffix || '-night';
  const basePath = variables.preload_path || '/casora_assets/rooms';
  const ext = variables.preload_extension || '.jpg';

  const isDark =
    typeof hass?.themes?.darkMode === 'boolean'
      ? hass.themes.darkMode
      : window.matchMedia('(prefers-color-scheme: dark)').matches;

  // Keyed so a dark-mode switch re-warms the other variant and releases the previous one.
  const preloadKey = (isDark ? 'night' : 'day') + '|' + rooms.join(',');

  if (window.casoraPreloadKey !== preloadKey) {
    window.casoraPreloadKey = preloadKey;
    window.casoraPreloadedImages = [];

    const warm = (src) => {
      const img = new Image();
      img.decoding = 'async';
      if ('fetchPriority' in img) img.fetchPriority = 'low';
      img.src = src;
      window.casoraPreloadedImages.push(img);
      return (img.decode ? img.decode() : Promise.resolve()).catch(() => {});
    };

    // One at a time on idle, so warming other rooms never competes with the current paint.
    const queue = rooms.map(r => `${basePath}/${r}${isDark ? suffix : ''}${ext}`);
    const idle = window.requestIdleCallback
      ? (fn) => window.requestIdleCallback(fn, { timeout: 3000 })
      : (fn) => setTimeout(fn, 300);
    const step = () => {
      const next = queue.shift();
      if (next) warm(next).then(() => idle(step));
    };
    idle(step);
  }

  return `

:host{
  position: relative;
  z-index: 0;

  --hero-gutter: var(--content-rail,
                  var(--casora-rail-left,
                  var(--page-gutter, 8vw)));
  --hero-top: var(--header-top-desktop, clamp(220px, 26vh, 340px));
  --hero-temp-font-size: var(--hero-temp-font-size-desktop, 18px);
  --hero-temp-font-weight: 600;
  --hero-temp-letter-spacing: 0.04em;
  --hero-temp-reserve: calc(var(--hero-temp-font-size) * 1.2);
  /* Read by casora_room as the weather widget's own height, which it subtracts to
     bottom-anchor the block. Must track the real height or the widget drifts down
     into the room name as the weather scales. 48px at the 10px floor. */
  --hero-weather-hero-height: calc(var(--casora-u-weather, 10px) * 4.8);
  --hero-header-gap-current: var(--hero-header-gap-desktop, 6px);
  --hero-img-blur-current: var(--hero-img-blur, 4px) !important;
  --hero-img-scale-current: var(--hero-img-scale, 1.08);
  --hero-img-filter: blur(var(--hero-img-blur-current))
    saturate(var(--hero-img-saturate, 1.02))
    brightness(var(--hero-img-brightness, .985));
  --hero-img-filter-from: blur(var(--hero-img-blur-current))
    saturate(var(--hero-img-saturate-from, 1.0))
    brightness(var(--hero-img-brightness-from, .97));
  --casora-hover-filter: none !important;
  --casora-card-hover-filter: none !important;
  --casora-card-hover-shadow: none !important;
  -webkit-tap-highlight-color: transparent !important;
  --mdc-ripple-press-opacity: 0 !important;
}

:host ha-card{
  position: relative;
  pointer-events: auto !important;
  cursor: default !important;
  filter: none !important;
  opacity: 1 !important;
  transform: none !important;
  box-shadow: none !important;
  --ha-card-box-shadow: none !important;
  transition: none !important;
  -webkit-tap-highlight-color: transparent !important;
  --mdc-ripple-press-opacity: 0 !important;
  background-repeat: no-repeat, no-repeat !important;
  background-position: center center, center center !important;
  background-size: cover, cover !important;
  background-attachment: local, local !important;
  isolation: isolate !important;
  overflow-x: hidden !important;
  overflow-y: hidden !important;
}

:host ha-card:hover,
:host ha-card:focus-within,
:host ha-card:active{
  filter:none !important;
  box-shadow:none !important;
  transform:none !important;
  cursor:default !important;
  --ha-card-box-shadow: none !important;
