casora_popup.content:
[[[
  const UI = window._casoraUI;
  if (!UI || !entity) return { type: 'vertical-stack', cards: [] };
  const id = entity?.entity_id;
  const _id = JSON.stringify(id);
  const CTRL_H = (UI.tokens && UI.tokens.controlH) || 260;
  const CTRL_W = (UI.tokens && UI.tokens.controlW) || 124;
  const iconOn = variables.icon && variables.icon !== 'power_on' ? variables.icon : 'power_on';
  const iconOff = variables.icon && variables.icon !== 'power_on' ? variables.icon : 'power_off';

  /* Messwerte desselben Geräts (Steckdose): Leistung, Energie */
  const reg = hass.entities || {};
  const devId = reg[id]?.device_id;
  const sib = {};
  if (devId) {
    Object.values(reg).forEach((e) => {
      if (e.device_id !== devId || !e.entity_id.startsWith('sensor.') || !states[e.entity_id]) return;
      const eid = e.entity_id;
      const unit = states[eid].attributes?.unit_of_measurement;
      if (unit === 'W' && !sib.power) sib.power = eid;
      else if (/energy_today$/.test(eid)) sib.today = eid;
      else if (unit === 'kWh' && /energy$/.test(eid) && !sib.total) sib.total = eid;
    });
  }
  const _sib = JSON.stringify(sib);

  const areas = [], fields = {}, fstyle = {};
  const add = (name, html) => {
    areas.push('"' + name + '"');
    fields[name] = html;
    fstyle[name] = [{ 'justify-self': 'stretch' }];
  };

  add('hero', `[[[
    const id = ${_id};
    const st = states[id]?.state;
    const ago = (iso) => {
      if (!iso) return null;
      const ms = Date.now() - new Date(iso).getTime();
      if (isNaN(ms) || ms < 0) return null;
      const m = ms/60000, h = m/60, d = h/24;
      if (m < 1) return 'gerade eben';
      if (m < 60) return 'vor ' + Math.floor(m) + (Math.floor(m)===1?' Minute':' Minuten');
      if (h < 24) return 'vor ' + Math.floor(h) + (Math.floor(h)===1?' Stunde':' Stunden');
      if (d < 7)  return 'vor ' + Math.floor(d) + (Math.floor(d)===1?' Tag':' Tagen');
      return 'vor ' + Math.floor(d/7) + 'w';
    };
    const value = st === 'on' ? 'An' : st === 'off' ? 'Aus' : st === 'unavailable' ? 'Nicht verfügbar' : 'Unbekannt';
    return window._casoraUI.hero({ value: value, sub: ago(states[id]?.last_changed), center: true });
  ]]]`);

  const toggleCard = {
    type: 'custom:button-card',
    entity: id,
    show_icon: false, show_name: false, show_state: false, show_label: false,
    haptic: 'medium',
    tap_action: `[[[
      const id = ${_id};
      if (!['on', 'off'].includes(states[id]?.state)) return { action: 'none' };
      return { action: 'call-service', service: 'switch.toggle', service_data: { entity_id: id } };
    ]]]`,
    extra_styles: `
      :host { display: block !important;
              --casora-card-hover-filter: none;
              --casora-hover-filter: none;
              --casora-card-hover-shadow: none;
              --button-card-box-shadow-hover: none; }
      ha-card { background: transparent !important; border: none !important;
                box-shadow: none !important; backdrop-filter: none !important;
                padding: 0 !important; cursor: pointer !important; }
      #container { padding: 0 !important; }
      ha-ripple { display: none !important; }
    `,
    styles: {
      card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '0' }],
      grid: [{ 'grid-template-areas': '"t"' }, { 'grid-template-columns': 'auto' },
             { 'justify-items': 'center' }],
      custom_fields: { t: [{ 'line-height': '0' }] },
    },
    custom_fields: {
      t: `[[[
        const id = ${_id};
        const s = states[id]?.state;
        const atTop = s === 'on';
        const dead = s !== 'on' && s !== 'off';

        const W = ${CTRL_W}, H = ${CTRL_H}, PAD = 7;
        const TH = Math.round(H * 0.49);
        const TOP = PAD, BOT = H - TH - PAD;

        const ON = 'var(--casora-color-teal, #00C3D0)';
        const OFF = 'rgba(255,255,255,0.13)';
        const thumbFill = atTop ? ON : OFF;
        const inkFill = atTop ? '#ffffff' : 'rgba(255,255,255,0.7)';

        const key = '_casora_swtg_' + id.replace(/[^a-zA-Z0-9]/g, '_');
        const prev = window[key];
        window[key] = s;
        const prevTop = prev === undefined ? atTop : prev === 'on';
        const moved = prev !== undefined && prevTop !== atTop;
        const pThumb = prevTop ? ON : OFF;
        const pInk = prevTop ? '#ffffff' : 'rgba(255,255,255,0.7)';
        const from = moved ? (prevTop ? TOP : BOT) : (atTop ? TOP : BOT);
        const to = atTop ? TOP : BOT;

        const ic = (n) => (typeof window.casoraIconUrl === 'function')
          ? window.casoraIconUrl(n) : '/casora_assets/icons/' + n + '.svg';
        const glyph = ic(atTop ? ${JSON.stringify(iconOn)} : ${JSON.stringify(iconOff)});

        return '<style>'
          + '.swtg{position:relative;width:' + W + 'px;height:' + H + 'px;'
          +   'border-radius:var(--casora-popup-control-radius, 37px);'
          +   'background:rgba(0,0,0,0.34);overflow:hidden;' + (dead ? 'opacity:.45;' : '') + '}'
          + '.swtg::before{content:"";position:absolute;inset:0;'
          +   'border-radius:inherit;pointer-events:none;'
          +   'background:var(--casora-toggle-hover-tint, rgba(255,255,255,0.02));'
          +   'opacity:0;transition:opacity var(--casora-toggle-hover-duration, .18s) ease;}'
          + '@media (hover:hover){.swtg:hover::before{opacity:1;}}'
          + '.swtg-t{position:absolute;left:' + PAD + 'px;right:' + PAD + 'px;'
          +   'top:0;height:' + TH + 'px;border-radius:' + Math.round((W - PAD * 2) * 0.30) + 'px;'
          +   'background:' + thumbFill + ';transform:translateY(' + to + 'px);'
          +   'display:flex;align-items:center;justify-content:center;}'
          + '.swtg-i{width:30px;height:30px;background-color:' + inkFill + ';'
          +   "-webkit-mask:url('" + glyph + "') center / contain no-repeat;"
          +   "mask:url('" + glyph + "') center / contain no-repeat;}"
          + (moved
              ? '.swtg-t{animation:swtg-mv .34s cubic-bezier(.36,0,.16,1) forwards,swtg-cf .34s ease forwards}'
              + '@keyframes swtg-mv{from{transform:translateY(' + from + 'px)}to{transform:translateY(' + to + 'px)}}'
              + '@keyframes swtg-cf{from{background:' + pThumb + '}to{background:' + thumbFill + '}}'
              + '.swtg-i{animation:swtg-kf .34s ease forwards}'
              + '@keyframes swtg-kf{from{background-color:' + pInk + '}to{background-color:' + inkFill + '}}'
              : '')
          + '</style>'
          + '<div class="swtg"><div class="swtg-t"><div class="swtg-i"></div></div></div>';
      ]]]`,
    },
  };
  add('toggle', { card: toggleCard });

  add('rows', `[[[
    const id = ${_id};
    const sib = ${_sib};
    const num = (eid) => { if (!eid || !states[eid]) return null; const n = parseFloat(states[eid].state); return isNaN(n) ? null : n; };
    const f = (n, d) => n.toLocaleString((window.casoraLocale ? window.casoraLocale() : 'de-DE'), { minimumFractionDigits: d, maximumFractionDigits: d });
    const rows = [];
    const p = num(sib.power);
    if (p != null) rows.push({ icon: 'mdi:flash', iconTone: 'good', label: 'Leistung', value: f(p, p < 10 ? 1 : 0) + ' W', entity: sib.power });
    const t = num(sib.today);
    if (t != null) rows.push({ icon: 'mdi:lightning-bolt-outline', iconTone: 'good', label: 'Energie heute', value: f(t, 2) + ' kWh', entity: sib.today });
    else {
      const g = num(sib.total);
      if (g != null) rows.push({ icon: 'mdi:lightning-bolt-outline', iconTone: 'good', label: 'Energie gesamt', value: f(g, 1) + ' kWh', entity: sib.total });
    }
    rows.push({ icon: 'mdi:tune-variant', label: 'Weitere Einstellungen', entity: id });
    return window._casoraUI.group(rows, null);
  ]]]`);

  const wrapperStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; overflow: visible !important; }',
    'ha-card { background: transparent !important; border: none !important; border-radius: 0 !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; cursor: default !important; overflow: visible !important; }',
    'ha-card:hover { box-shadow: none !important; }',
    'ha-ripple { display: none !important; }',
    '@media (max-width: 600px) { ha-card { padding-left: 14px !important; padding-right: 14px !important; } }',
  ].join('\n');

  /* Popup-Standard (24.09.2026): ab 761 px links Schalter, rechts Werte. */
  return (window._casoraStd ? (c) => window._casoraStd(c, { left: ['toggle'], right: ['rows'] }) : (c) => c)({
    type: 'custom:button-card',
    entity: id,
    triggers_update: [id].concat(Object.values(sib)),
    card_mod: { style: wrapperStyle
      + '\n:host { --ha-card-backdrop-filter: none !important; --ha-card-background: transparent !important; --card-background-color: transparent !important; --ha-card-box-shadow: none !important; --ha-card-border-width: 0px !important; }'
      + '\nha-card::before, ha-card::after, #card::before, #card::after, #container::before, #container::after { display: none !important; }'
      + '\nha-card { will-change: auto !important; }'
      + '\n@media (max-width: 768px) {'
      + ' :host { flex: 1 1 auto !important; min-height: 0 !important; display: flex !important; flex-direction: column !important; }'
      + ' ha-card { flex: 1 1 auto !important; min-height: 0 !important; display: flex !important; flex-direction: column !important; box-sizing: border-box !important; }'
      + ' #container { flex: 1 1 auto !important;'
      + '   min-height: calc(100svh - var(--casora-popup-top, 112px) - 58px - 28px - 8px - var(--safe-area-inset-bottom, 0px)) !important;'
      + '   box-sizing: border-box !important; } }'
      + '\n#container { background: transparent !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; }' },
    tap_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    styles: {
      card: [
        { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
        { padding: 'var(--casora-soft-card-top, 6px) 26px 22px 26px' },
      ],
      grid: [
        { 'grid-template-areas': areas.join(' ') },
        { 'grid-template-columns': '1fr' },
        { 'grid-template-rows': 'auto 1fr auto' },
        { 'align-content': 'stretch' },
        { 'align-items': 'center' },
        { 'row-gap': 'var(--casora-popup-sec-gap, 18px)' },
        { 'min-height': '100%' },
      ],
      custom_fields: fstyle,
    },
    custom_fields: fields,
  });
]]]

popup_styles.styles:
/* Popup content cards are not buttons: the theme's hover lift (shadow + brightness) made a
   whole column look like a raised card under the pointer (Weich audit M1). Killed popup-wide. */
--casora-card-hover-filter: none;
--casora-hover-filter: none;
--casora-card-hover-shadow: none;
/* The pane stays - these are control sheets. Only the close control
   keeps what it gained: a surface of its own, and room above it so
   the fill is not against the top edge of the sheet. */
.header { padding-top: var(--casora-popup-header-gap, 10px); }
/* Equal inset on both axes: the bar's own padding plus the
   close control's 2px optical nudge has to come to the same
   number as the padding above it, or the circle sits further
   from the left edge than it does from the top. */
--casora-popup-header-gap: 14px;
  --casora-popup-gutter-wide: 20px;
/* The chrome arrives with the first plate instead of being there
   on frame one while everything under it fades in. */
--casora-popup-chrome-enter:
  casora-popup-chrome-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
.header-title { font-size: 20px; font-weight: 600; letter-spacing: -0.01em; }
.header-close {
  border-radius: 50%;
  background: var(--casora-popup-row-fill, rgba(255, 255, 255, 0.10));
  backdrop-filter: var(--casora-popup-plate-backdrop, blur(24px) saturate(180%));
  -webkit-backdrop-filter: var(--casora-popup-plate-backdrop, blur(24px) saturate(180%));
  box-shadow: var(--casora-popup-plate-shadow, none);
}
/* The sheet is full height, so short content floats mid-screen. On
   a phone the card has to fill it for the grid's `1fr` row to have
   any slack to hand the toggle - otherwise the rows bunch under it
   instead of sitting at the bottom.
   Flex, not percentages: .content is `flex: 1 1 auto` inside a
   surface with only a max-height, so `min-height: 100%` here had no
   definite height to resolve against and computed to nothing. A
   flex chain gives every link a real height without one. */
@media (max-width: 768px) {
  /* The root cause, and why two attempts at the chain below did
     nothing: .surface is capped with max-height, never given one.
     A flex item in a content-sized container is itself
     content-sized, so every percentage under it resolved to
     nothing and the grid's `1fr` row had no slack to hand out.
     Same expression as its own max-height, as a height. */
  .surface {
    height: calc(100svh - var(--casora-popup-top, 112px) - 8px
                 - var(--safe-area-inset-bottom, 0px));
  }
  .content { display: flex; flex-direction: column; }
  /* A viewport unit, not a percentage. Every attempt to make this
     work by giving each link a definite height failed in the real
     DOM even though the chain measures correct in isolation - so
     the height is taken from the viewport directly and nothing has
     to resolve against a parent at all. 112 is the surface's top
     offset, 58 the header row, 8 the bottom gap. */
  .content .container {
    flex: 1 1 auto;
    min-height: calc(100svh - var(--casora-popup-top, 112px)
                     - 58px - 8px
                     - var(--safe-area-inset-bottom, 0px));
    display: flex; flex-direction: column; box-sizing: border-box;
  }
  /* The direct child AND anything HA wraps the card in: measured in
     isolation this chain resolves and the tiles land 8px off the
     bottom, so the only way it can still fail is a link in the real
     DOM that this does not name. */
  .content .container > *,
  .content .container hui-card,
  .content .container > * > * {
    flex: 1 1 auto; min-height: 0;
    display: flex; flex-direction: column;
  }
}
/* One measure for a control-plus-list popup, whatever the count.
   The rows are short and a wider sheet only stretches them; cover
   is the same shape and holds the same width. */
--popup-min-width: 900px;
--popup-max-width: 920px;

