custom_fields.temp_puck:
[[[
  // Deliberately mode-only (not hvac_action) — the circle/icon/card glow
  // stay a plain on/off indicator like every other Casora card (colored
  // circle + white icon whenever hvac_mode is heat/cool); only the text
  // label (state_display, below) distinguishes "Heizt" from "Bereit".
  const s = String(entity?.state || '').toLowerCase();
  const isCool = s === 'cool';
  const isHeat = s === 'heat';
  // No device in this house actually cools — several climate entities
  // (the per-room ones especially) report 'cool' in hvac_modes anyway,
  // so that attribute can't be trusted to gate this. Icon always wins.
  const showIcon = true;

  let raw = entity?.attributes?.current_temperature;
  const eid = variables.temp_sensor;
  if (eid && ((s) => { const _a = (s && s.attributes) || {}; const _u = String(_a.unit_of_measurement || ''); return !!s && (_a.device_class === 'temperature' || /°|^K$/.test(_u) || (!_u && !_a.device_class)); })(states[eid]) && !['unknown','unavailable'].includes(states[eid]?.state)) {
    raw = states[eid]?.state;
  }
  const n = Math.round(Number(raw));

  // Explicit neutral fallback, not '' — an empty string left the circle
  // inheriting whatever teal climate/lock/cover-domain default happens
  // to be in scope higher up the DOM, so "Bereit" (idle) showed a
  // colored circle with a non-white icon, breaking the "colored circle
  // = white icon" rule every other active/inactive icon-circle follows.
  const circleBg = isCool
    ? '--casora-icon-circle-bg:var(--casora-puck-cool-color, #00d2e0);'
    : isHeat
      ? '--casora-icon-circle-bg:var(--casora-puck-heat-color, #FF4245);'
      : '--casora-icon-circle-bg:var(--casora-puck-off-bg, rgba(0,0,0,0.20));';

  const eid2 = entity?.entity_id;
  const stop = `event.stopPropagation();event.stopImmediatePropagation()`;
  const moreInfo = `${stop};this.dispatchEvent(new CustomEvent('hass-more-info',{bubbles:true,composed:true,detail:{entityId:'${eid2}'}}))`;
  /* Wie toggle_service_data: jeder Modus außer Aus gilt als an; einschalten mit einem Modus, den das Gerät kennt. */
  const _modes = (entity?.attributes?.hvac_modes || []).filter((m) => m !== 'off');
  const _want = states['input_select.casora_thermostat_mode']?.state || 'heat';
  const onMode = !_modes.length || _modes.includes(_want) ? _want : _modes.includes('heat') ? 'heat' : _modes[0];
  const nextMode = entity?.state && !['off','unavailable','unknown'].includes(entity.state) ? 'off' : onMode;
  const smartToggle = `${stop};document.querySelector('home-assistant').hass.callService('climate','set_hvac_mode',{entity_id:'${eid2}',hvac_mode:'${nextMode}'})`;
  const info = variables.has_controls ? moreInfo : smartToggle;
  // Handy: Gruppen (FBH ganzes Haus) schalten nie direkt - Tipp fällt zur Karte durch und öffnet
  // das Popup (dort mit Bestätigung). Räume schalten weiter direkt, aber nicht beim Scrollen
  // (Bewegung > 10 px) und nur einmal (kein zusätzlicher Klick nach dem Touch).
  const isGroup = Array.isArray(entity?.attributes?.member_entities);
  const tStart = `${stop};var t=event.touches[0];this._hx=t.clientX;this._hy=t.clientY;`;
  const tEnd = `${stop};var t=event.changedTouches[0];if(Math.abs(t.clientX-(this._hx||0))>10||Math.abs(t.clientY-(this._hy||0))>10)return;if(event.cancelable)event.preventDefault();window._casoraPuckT=Date.now();` + info.slice(stop.length + 1);
  const tClick = `${stop};if(Date.now()-(window._casoraPuckT||0)<700)return;` + info.slice(stop.length + 1);
  const handlers = (!variables.has_controls && isGroup)
    ? ''
    : `onpointerdown="${stop}" ontouchstart="${tStart}" ontouchend="${tEnd}" onclick="${tClick}"`;

  const heatIconUrl = window.casoraIconUrl('heating_coil');
  // Standard Casora icon logic: inactive = neutral circle + tinted icon,
  // active = colored circle + white icon (see #img-cell / casora_entity.yaml).
  // temp_puck builds its own markup instead of the shared #img-cell, so
  // that swap is reproduced by hand here rather than inherited.
  const iconColor = isHeat
    ? 'rgba(255,255,255,0.9)'
    // Weich (A-12): Aus-Zustand in Aus-Grau wie alle anderen Kacheln (nur mit --casora-icon-off-mix).
    : 'color-mix(in srgb, var(--casora-icon-off-ink, transparent) var(--casora-icon-off-mix, 0%), var(--casora-puck-heat-color, #FF4245))';
  const inner = showIcon
    ? `<div style="width:58%;height:58%;background-color:${iconColor};-webkit-mask-image:url('${heatIconUrl}');mask-image:url('${heatIconUrl}');-webkit-mask-size:contain;mask-size:contain;-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat;-webkit-mask-position:center;mask-position:center;"></div>`
    : `${n}`;

  return `<div class="casora-icon-circle" ${handlers} style="${circleBg}cursor:pointer;touch-action:manipulation;-webkit-tap-highlight-color:transparent;color:rgba(255,255,255,0.9);font-weight:var(--casora-puck-font-weight, 800);font-size:calc(var(--casora-u, 10px) * 1.7);font-family:system-ui,-apple-system,sans-serif;">${inner}</div>`;
]]]

