custom_fields.ctl_up:
[[[
  const stop = "event.stopPropagation();event.stopImmediatePropagation();";
  const noGhost = "event.preventDefault();";
  const getHass = "const h=document.querySelector('home-assistant').hass;";
  const fx = "const w=this.parentElement;"
    + "const d=(getComputedStyle(w).getPropertyValue('--thermo-btn-press-scale')||'0.92').trim();"
    + "w.animate([{transform:'scale(1)'},{transform:'scale('+d+')',offset:0.38},{transform:'scale(1)'}],"
    + "{duration:280,easing:'ease-out'});";
  const svc = "h.callService('input_number','increment',{entity_id:'input_number.casora_thermostat_target_temperature'});";
  const body = fx + getHass + svc;
  const tap = stop + noGhost + body + "window._casoraCtlTouch=Date.now();";
  const clk = stop + "if(window._casoraCtlTouch&&Date.now()-window._casoraCtlTouch<600)return;" + body;
  return `<div class="casora-ctl-hit" onpointerdown="${stop}" onpointerup="${stop}" ontouchstart="${stop}" ontouchend="${tap}" onclick="${clk}"></div>`;
]]]

custom_fields.ctl_set:
[[[
  const stop = "event.stopPropagation();event.stopImmediatePropagation();";
