  const fx = "const w=this.parentElement;"
    + "const d=(getComputedStyle(w).getPropertyValue('--thermo-btn-press-scale')||'0.92').trim();"
    + "w.animate([{transform:'scale(1)'},{transform:'scale('+d+')',offset:0.38},{transform:'scale(1)'}],"
