    + "this.animate([{backgroundColor:c1,offset:0},{backgroundColor:c1,offset:0.62},"
    + "{backgroundColor:'rgba(255,255,255,0)',offset:1}],{duration:340,easing:'ease-out'});";
  const body = fx + confirm + getHass + svc;
  const tap = stop + noGhost + body + "window._casoraCtlTouch=Date.now();";
