casora_thermostat.extra_styles:
/* Optical sizing: 800 is right at 17px, too heavy once the puck scales up.
   1740px is where --casora-u leaves its floor, i.e. where the digits start growing. */
:host { --casora-puck-font-weight: 800; }
@media (min-width: 1740px) { :host { --casora-puck-font-weight: 700; } }

#temp_puck {
  grid-area: i !important;
  height: var(--casora-icon-circle-size, 44px);
}

/* Closed by default; the JS-templated opacity lands a frame later. */
#target_temperature, #ctl_up, #ctl_set, #ctl_down {
  opacity: 0;
  pointer-events: none;
}

.casora-ctl-hit {
  position: absolute;
  inset: 0;
  /* Under the glyph/label pseudo (z-index 1), which is pointer-events:none
     and so does not intercept the tap. */
  z-index: 0;
  cursor: pointer;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}

/* Control glyphs */
#ctl_up::before,
#ctl_down::before,
#ctl_set::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background-repeat: no-repeat;
  background-position: center center;
  background-size: var(--thermo-glyph-size, 68%) auto;
  filter: var(--thermostat-control-icon-filter, none);
}
/* Optical centering */
#ctl_up::before {
  background-image: var(--thermo-icon-up);
  background-position: center calc(50% - 1px);
}
#ctl_down::before {
  background-image: var(--thermo-icon-down);
  background-position: center calc(50% + 1px);
}
/* 22px on a 44px-tall button is exactly half its height, which is a full
   oval. 16px keeps it clearly a squircle while sitting a shade rounder
   than the entity-actions pills (13px on 40px, a 0.325 ratio, against
   0.364 here).
   A real media query, not a matchMedia snapshot baked into an inline
   style - that goes stale on rotation. */
ha-card { --thermo-btn-radius: 16px; }

@media (max-width: 767px), (max-height: 600px) {
  ha-card { --thermo-btn-radius: 15px; }
}

/* Hover/press */
@media (hover: hover) {
  #ctl_up:hover,
  #ctl_set:hover,
  #ctl_down:hover {
    background: var(--thermo-btn-bg-hover, rgba(255,255,255,0.16)) !important;
    transform: scale(var(--thermo-btn-hover-scale, 1.02));
  }
}

#ctl_set::before {
  content: 'Set';
  display: flex;
  align-items: center;
  justify-content: center;
  background-image: none;
  filter: none;
  font-size: var(--thermo-set-font, 18px);
  font-weight: 600;
  letter-spacing: -0.005em;
  line-height: 1.15;
  color: var(--thermo-set-color, #fff);
}

casora_popup.content:
[[[
  const UI = window._casoraUI;
  if (!UI || !entity) return { type: 'vertical-stack', cards: [] };
  const id = entity?.entity_id;
  const reg = hass.entities || {};
  const devId = reg[id]?.device_id;
  const areaId = reg[id]?.area_id || (devId ? hass.devices?.[devId]?.area_id : null);
  const members = Array.isArray(entity?.attributes?.member_entities) ? entity?.attributes.member_entities : [];
  const roomName = variables.room_name
    || (members.length ? 'Ganzes Haus' : null)
    || (areaId ? hass.areas?.[areaId]?.name : null)
    || entity?.attributes?.friendly_name || 'Thermostat';
  const tempSensor = variables.temp_sensor && variables.temp_sensor !== 'None' && ((s) => { const _a = (s && s.attributes) || {}; const _u = String(_a.unit_of_measurement || ''); return !!s && (_a.device_class === 'temperature' || /°|^K$/.test(_u) || (!_u && !_a.device_class)); })(states[variables.temp_sensor]) ? variables.temp_sensor : null;

  const uiCard = {
    type: 'custom:button-card',
    entity: id,
    triggers_update: [id].concat(members).concat(tempSensor ? [tempSensor] : []),
    variables: { room_name: roomName, temp_sensor: tempSensor },
    card_mod: { style:
      '
:host { --ha-card-backdrop-filter: none !important; --ha-card-background: transparent !important; --card-background-color: transparent !important; --ha-card-box-shadow: none !important; --ha-card-border-width: 0px !important; }'
      + '
ha-card::before, ha-card::after, #card::before, #card::after, #container::before, #container::after { display: none !important; }'
      + '
ha-card { will-change: auto !important; }'
      + '
@media (max-width: 600px) { ha-card { padding-left: 14px !important; padding-right: 14px !important; } }'
    },
    tap_action: { action: 'none' },
    hold_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    styles: {
      card: [
        { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
        { padding: 'var(--casora-soft-card-top, 6px) 26px 22px 26px' },
      ],
      grid: [
        { 'grid-template-areas': '"body"' },
        { 'grid-template-columns': '1fr' },
      ],
      custom_fields: { body: [{ 'justify-self': 'stretch' }] },
    },
    custom_fields: { body: "[[[
  const UI = window._casoraUI;
  if (!UI || !entity) return '';
  const T = UI.tokens;
  const id = entity?.entity_id;
  const a  = entity?.attributes || {};
  const mode = entity?.state;

  const num = (v) => { const n = parseFloat(v); return isNaN(n) ? null : n; };
  const sNum = (eid) => { if (!eid || !states[eid]) return null; const s = states[eid].state; return (s === 'unknown' || s === 'unavailable') ? null : num(s); };
  const fmt = (n) => n.toLocaleString((window.casoraLocale ? window.casoraLocale() : 'de-DE'), { minimumFractionDigits: 1, maximumFractionDigits: 1 });
  const act = (e) => window.casoraClimateActive?.(e) || {};

  const cur = sNum(variables.temp_sensor) ?? num(a.current_temperature) ?? (() => { const ms = (Array.isArray(a.member_entities) ? a.member_entities : []).map((m) => num(states[m]?.attributes?.current_temperature)).filter((x) => x != null); return ms.length ? Math.round(ms.reduce((p, q) => p + q, 0) / ms.length * 10) / 10 : null; })();
  const target = num(a.temperature);
  const step = num(a.target_temp_step) || 0.5;
  const tMin = num(a.min_temp) ?? 5, tMax = num(a.max_temp) ?? 30;

  const statusText = (e) => {
    const m = e.state, t = num(e.attributes?.temperature);
    const ac = act(e);
    const tt = t != null ? fmt(t) + ' °C' : null;
    if (m === 'unavailable') return 'Nicht verfügbar';
    if (m === 'off') return 'Aus';
    if (ac.heating) return tt ? 'Heizt auf ' + tt : 'Heizt';
    if (m === 'auto') return tt ? 'Automatik · ' + tt : 'Automatik';
    if (m === 'heat') return tt ? 'Bereit · ' + tt : 'Bereit';
    return m;
  };

  /* Popup-Standard (24.09.2026): part = hero | seg | ctl | info (breit), ohne part alles (schmal). */
  const P = variables.part;
  let out = (!P || P === 'hero') ? UI.hero({
    label: variables.room_name,
    value: cur != null ? fmt(cur) : '–',
    unit: cur != null ? '°C' : null,
    sub: statusText(entity),
    subTone: act(entity).heating ? 'warn' : null,
    center: true,
  }) : '';

  const tgt = { entity_id: id };
  if ((!P || P === 'ctl') && mode !== 'off' && mode !== 'unavailable' && target != null) {
    const dn = Math.max(tMin, Math.round((target - step) / step) * step);
    const up = Math.min(tMax, Math.round((target + step) / step) * step);
    const btn = (label, t, dis) => '<div class="hp-st-b' + (dis ? ' dis' : '') + '"'
      + (dis ? '' : ' data-casora-svc="' + UI.esc(JSON.stringify({ domain: 'climate', service: 'set_temperature', data: { temperature: t }, target: tgt })) + '"')
      + '>' + label + '</div>';
    out += '<div style="height:18px"></div>'
      + '<style>'
      + '.hp-st{display:flex;align-items:center;justify-content:space-between;gap:12px;font-family:' + T.font + ';'
      +   'background:var(--casora-popup-row-fill, rgba(255,255,255,0.10));border-radius:var(--casora-popup-row-radius, 20px);padding:12px;}'
      + '.hp-st-b{width:52px;height:52px;flex:none;border-radius:999px;display:grid;place-items:center;cursor:pointer;'
      +   'line-height:0;color:' + T.ink + ';'
      +   'background:var(--casora-popup-seg-fill, rgba(255,255,255,0.16));transition:background-color .16s ease,transform .12s ease;user-select:none;-webkit-user-select:none;}'
      + '.hp-st-b.dis{opacity:.3;cursor:default;}.hp-st-b svg{pointer-events:none;}'
      + '.hp-st-b:not(.dis):active{transform:scale(.92);}'
      + '@media (hover:hover){.hp-st-b:not(.dis):hover{background:var(--casora-popup-seg-fill-hover, rgba(255,255,255,0.24));}}'
      + '.hp-st-v{text-align:center;pointer-events:none;}'
      + '.hp-st-v .l{font-size:13px;color:' + T.ink2 + ';}'
      + '.hp-st-v .n{font-size:30px;font-weight:500;letter-spacing:-0.02em;font-variant-numeric:tabular-nums;color:' + T.ink + ';}'
      + '.hp-st-v .n span{font-size:16px;font-weight:400;color:' + T.ink2 + ';}'
      + '</style>'
      + '<div class="hp-st">'
      +   btn('<svg width="20" height="20" viewBox="0 0 20 20" style="display:block"><path d="M4 10H16" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/></svg>', dn, target <= tMin)
      +   '<div class="hp-st-v"><div class="l">Zieltemperatur</div><div class="n">' + fmt(target) + '<span> °C</span></div></div>'
      +   btn('<svg width="20" height="20" viewBox="0 0 20 20" style="display:block"><path d="M4 10H16M10 4V16" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/></svg>', up, target >= tMax)
      + '</div>';
    const kPct = ((target - tMin) / (tMax - tMin) * 100).toFixed(1);
    out += '<style>'
      + '.hp-tb{margin-top:14px;padding:14px 4px;cursor:pointer;touch-action:none;}'
      + '.hp-tb-t{position:relative;height:8px;border-radius:999px;pointer-events:none;'
      +   'background:var(--casora-temp-gradient, linear-gradient(90deg,#0A84FF 0%,#64D2FF 30%,#FF9F0A 65%,#FF453A 100%));}'
      + '.hp-tb-k{position:absolute;top:50%;width:22px;height:22px;margin:-11px 0 0 -11px;border-radius:999px;background:#fff;'
      +   'box-shadow:0 1px 4px rgba(0,0,0,.45);transition:left .15s ease;}'
      + '.hp-tb-s{display:flex;justify-content:space-between;font-size:12px;color:' + T.ink3 + ';margin-top:6px;font-variant-numeric:tabular-nums;}'
      + '</style>'
      + '<div class="hp-tb" ontouchstart="event.stopPropagation();var h=this,tr=h.firstElementChild,b=tr.getBoundingClientRect(),lo=' + tMin + ',hi=' + tMax + ',st=' + step + ';var tv=function(x){var f=Math.max(0,Math.min(1,(x-b.left)/b.width));return Math.round((lo+f*(hi-lo))/st)*st;};var paint=function(t){var f=(t-lo)/(hi-lo)*100;tr.querySelector(&quot;.hp-tb-k&quot;).style.left=f+&quot;%&quot;;var n=h.getRootNode().querySelector(&quot;.hp-st-v .n&quot;);if(n)n.firstChild.nodeValue=t.toLocaleString(&quot;de-DE&quot;,{minimumFractionDigits:1,maximumFractionDigits:1});};var send=function(t){document.querySelector(&quot;home-assistant&quot;).hass.callService(&quot;climate&quot;,&quot;set_temperature&quot;,{temperature:t},{entity_id:&quot;' + id + '&quot;});};h._t=tv(event.touches[0].clientX);paint(h._t);" ontouchmove="event.stopPropagation();if(event.cancelable)event.preventDefault();var h=this,tr=h.firstElementChild,b=tr.getBoundingClientRect(),lo=' + tMin + ',hi=' + tMax + ',st=' + step + ';var tv=function(x){var f=Math.max(0,Math.min(1,(x-b.left)/b.width));return Math.round((lo+f*(hi-lo))/st)*st;};var paint=function(t){var f=(t-lo)/(hi-lo)*100;tr.querySelector(&quot;.hp-tb-k&quot;).style.left=f+&quot;%&quot;;var n=h.getRootNode().querySelector(&quot;.hp-st-v .n&quot;);if(n)n.firstChild.nodeValue=t.toLocaleString(&quot;de-DE&quot;,{minimumFractionDigits:1,maximumFractionDigits:1});};var send=function(t){document.querySelector(&quot;home-assistant&quot;).hass.callService(&quot;climate&quot;,&quot;set_temperature&quot;,{temperature:t},{entity_id:&quot;' + id + '&quot;});};h._t=tv(event.touches[0].clientX);paint(h._t);" ontouchend="event.stopPropagation();if(event.cancelable)event.preventDefault();var h=this,tr=h.firstElementChild,b=tr.getBoundingClientRect(),lo=' + tMin + ',hi=' + tMax + ',st=' + step + ';var tv=function(x){var f=Math.max(0,Math.min(1,(x-b.left)/b.width));return Math.round((lo+f*(hi-lo))/st)*st;};var paint=function(t){var f=(t-lo)/(hi-lo)*100;tr.querySelector(&quot;.hp-tb-k&quot;).style.left=f+&quot;%&quot;;var n=h.getRootNode().querySelector(&quot;.hp-st-v .n&quot;);if(n)n.firstChild.nodeValue=t.toLocaleString(&quot;de-DE&quot;,{minimumFractionDigits:1,maximumFractionDigits:1});};var send=function(t){document.querySelector(&quot;home-assistant&quot;).hass.callService(&quot;climate&quot;,&quot;set_temperature&quot;,{temperature:t},{entity_id:&quot;' + id + '&quot;});};window._hpTbT=Date.now();if(h._t!=null)send(h._t);" onclick="event.stopPropagation();if(Date.now()-(window._hpTbT||0)<700)return;var h=this,tr=h.firstElementChild,b=tr.getBoundingClientRect(),lo=' + tMin + ',hi=' + tMax + ',st=' + step + ';var tv=function(x){var f=Math.max(0,Math.min(1,(x-b.left)/b.width));return Math.round((lo+f*(hi-lo))/st)*st;};var paint=function(t){var f=(t-lo)/(hi-lo)*100;tr.querySelector(&quot;.hp-tb-k&quot;).style.left=f+&quot;%&quot;;var n=h.getRootNode().querySelector(&quot;.hp-st-v .n&quot;);if(n)n.firstChild.nodeValue=t.toLocaleString(&quot;de-DE&quot;,{minimumFractionDigits:1,maximumFractionDigits:1});};var send=function(t){document.querySelector(&quot;home-assistant&quot;).hass.callService(&quot;climate&quot;,&quot;set_temperature&quot;,{temperature:t},{entity_id:&quot;' + id + '&quot;});};var t=tv(event.clientX);paint(t);send(t);">'
      + '<div class="hp-tb-t"><div class="hp-tb-k" style="left:' + kPct + '%"></div></div>'
      + '<div class="hp-tb-s"><span>' + fmt(tMin) + ' °C</span><span>' + fmt(tMax) + ' °C</span></div></div>';
  }

  if ((!P || P === 'seg') && mode !== 'unavailable') {
    const labels = { off: 'Aus', heat: 'Heizen', auto: 'Auto' };
    const modes = (a.hvac_modes || []).filter((m) => labels[m]);
    const order = ['off', 'heat', 'auto'];
    modes.sort((x, y) => order.indexOf(x) - order.indexOf(y));
    if (modes.length > 1) {
      const seg = modes.map((m) => ({ label: labels[m], active: mode === m,
        svc: { domain: 'climate', service: 'set_hvac_mode', data: { hvac_mode: m }, target: tgt } }));
      out += '<div style="height:18px"></div><style>.hp-seg .hui-seg{flex-wrap:nowrap;gap:6px;}.hp-seg .hui-sg{flex:1 1 0;min-width:0;padding:11px 4px;}.hp-seg .hui-sg{min-height:var(--casora-climate-seg-h, 46px);}</style>'
        + (P ? '<div style="display:var(--casora-lbl15, block);font-family:var(--primary-font-family,system-ui);font-size:var(--casora-h15-fs,15px);font-weight:var(--casora-h15-fw,600);letter-spacing:var(--casora-h15-ls,-0.01em);text-transform:var(--casora-h15-tt,none);color:var(--casora-h15-c, var(--casora-popup-tiles-text-primary,#fff));text-align:left;padding:0 4px 8px;">Modus</div><div style="display:var(--casora-lbl12, none);font-family:var(--primary-font-family,system-ui);font-size:12px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--casora-soft-label,var(--secondary-text-color));text-align:left;margin:0 6px 10px;">Modus</div>' : '') + '<div class="hp-seg">' + UI.segments(seg) + '</div>';
    }
  }

  const members = Array.isArray(a.member_entities) ? a.member_entities.filter((m) => states[m]) : [];
  if ((!P || P === 'info') && members.length) {
    const rows = members.map((m) => {
      const e = states[m];
      const ea = e.attributes || {};
      const c = num(ea.current_temperature);
      const h = act(e).heating;
      let label = String(ea.friendly_name || m).replace(/^(Fu(ß|ss)bodenheizung|Room Climate)\s*/i, '').trim() || ea.friendly_name || m;
      return { icon: 'mdi:heating-coil', iconTone: h ? 'var(--casora-color-red, #FF453A)' : (e.state === 'off' ? 'var(--casora-popup-ui-fill-2, rgba(255,255,255,0.16))' : 'accent'),
               label: label, sub: statusText(e), value: c != null ? fmt(c) + ' °C' : null, entity: m };
    });
    out += '<div style="height:18px"></div>' + UI.group(rows, 'Räume');
  }

  /* Ohne Räume bekommt die Zeile eine Überschrift wie „Modus“ links, sonst liegt sie höher als die Tasten (02.10.2026). */
  if (!P || P === 'info') out += '<div style="height:18px"></div>'
    + UI.group([{ icon: 'mdi:tune-variant', label: 'Weitere Einstellungen', entity: id }], members.length ? undefined : 'Einstellungen');
  return out;
]]]" },
  };
  /* Popup-Standard (24.09.2026): oben Raum + Temperatur. Breit: links Modus-Tasten (mit Überschrift)
     + Zieltemperatur, rechts Räume + Einstellungen. Schmal (Handy) dieselbe Reihenfolge untereinander. */
  const pc = (part, pad) => Object.assign({}, uiCard, { variables: Object.assign({}, uiCard.variables, { part: part }),
    styles: Object.assign({}, uiCard.styles, { card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: pad }] }) });
  if (window.innerWidth > 760) {
    return { type: 'vertical-stack', cards: [pc('hero', 'var(--casora-soft-card-top, 6px) 26px 0 26px'),
      { type: 'grid', columns: 2, square: false, cards: [
        { type: 'vertical-stack', cards: [pc('seg', '0 12px 0 26px'), pc('ctl', '0 12px 22px 26px')] },
        pc('info', '0 26px 22px 12px')] }] };
  }
  return { type: 'vertical-stack', cards: [pc('hero', 'var(--casora-soft-card-top, 6px) 26px 0 26px'), pc('seg', '0 26px'), pc('ctl', '0 26px'), pc('info', '0 26px 22px 26px')] };
]]]

popup_styles.styles:
/* The pane stays - these are control sheets. Only the close control
   keeps what it gained: a surface of its own, and room above it so
   the fill is not against the top edge of the sheet. */
.header { padding-top: var(--casora-popup-header-gap, 10px); }
/* Equal inset on both axes: the bar's own padding plus the
   close control's 2px optical nudge has to come to the same
   number as the padding above it, or the circle sits further
   from the left edge than it does from the top. */
--casora-popup-header-gap: 14px;
  --casora-popup-gutter-wide: 20px;
/* The chrome arrives with the first plate instead of being there
   on frame one while everything under it fades in. */
--casora-popup-chrome-enter:
  casora-popup-chrome-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
.header-title { font-size: 20px; font-weight: 600; letter-spacing: -0.01em; }
.header-close {
  border-radius: 50%;
  background: var(--casora-popup-row-fill, rgba(255, 255, 255, 0.10));
  backdrop-filter: var(--casora-popup-plate-backdrop, blur(24px) saturate(180%));
  -webkit-backdrop-filter: var(--casora-popup-plate-backdrop, blur(24px) saturate(180%));
  box-shadow: var(--casora-popup-plate-shadow, none);
}
/* The sheet is full height, so short content floats mid-screen. On
   a phone the card has to fill it for the grid's `1fr` row to have
   any slack to hand the toggle - otherwise the rows bunch under it
   instead of sitting at the bottom.
   Flex, not percentages: .content is `flex: 1 1 auto` inside a
   surface with only a max-height, so `min-height: 100%` here had no
   definite height to resolve against and computed to nothing. A
   flex chain gives every link a real height without one. */
@media (max-width: 768px) {
  /* The root cause, and why two attempts at the chain below did
     nothing: .surface is capped with max-height, never given one.
     A flex item in a content-sized container is itself
     content-sized, so every percentage under it resolved to
     nothing and the grid's `1fr` row had no slack to hand out.
     Same expression as its own max-height, as a height. */
  .surface {
    height: calc(100svh - var(--casora-popup-top, 112px) - 8px
                 - var(--safe-area-inset-bottom, 0px));
  }
  .content { display: flex; flex-direction: column; }
  /* A viewport unit, not a percentage. Every attempt to make this
     work by giving each link a definite height failed in the real
     DOM even though the chain measures correct in isolation - so
     the height is taken from the viewport directly and nothing has
     to resolve against a parent at all. 112 is the surface's top
     offset, 58 the header row, 8 the bottom gap. */
  .content .container {
    flex: 1 1 auto;
    min-height: calc(100svh - var(--casora-popup-top, 112px)
                     - 58px - 8px
                     - var(--safe-area-inset-bottom, 0px));
    display: flex; flex-direction: column; box-sizing: border-box;
  }
  /* The direct child AND anything HA wraps the card in: measured in
     isolation this chain resolves and the tiles land 8px off the
     bottom, so the only way it can still fail is a link in the real
     DOM that this does not name. */
  .content .container > *,
  .content .container hui-card,
  .content .container > * > * {
    flex: 1 1 auto; min-height: 0;
    display: flex; flex-direction: column;
  }
}
/* One measure for a control-plus-list popup, whatever the count.
   The rows are short and a wider sheet only stretches them; cover
   is the same shape and holds the same width. */
--popup-min-width: 900px;
--popup-max-width: 920px;

casora_popup.title:
[[[
  const n = String(this._config?.name || '').trim();
  if (n && !n.startsWith('[[[')) return n;
  return entity?.attributes?.member_entities ? 'Fußbodenheizung' : (entity?.attributes?.friendly_name || 'Thermostat');
]]]

casora_thermostat.state_display:
[[[
  const fit = (t) => window.casoraStateFit?.(t) ?? t;
  const mode = entity?.state;
  const a = entity?.attributes || {};
  /* Ziel: temperature, sonst Bereich target_temp_low–high (Heizen/Kühlen); fehlt beides, ohne Zahl. */
  /* Dezimalkomma (19,5° statt 19.5°) wie überall; eigener Ersatz für die Studio-Vorschau. */
  const nf = (n) => window.casoraNum ? window.casoraNum(n, 0, 1) : String(n).replace('.', ',');
  const target = a.temperature != null ? nf(a.temperature) + "°"
    : a.target_temp_low != null && a.target_temp_high != null ? nf(a.target_temp_low) + "–" + nf(a.target_temp_high) + "°" : null;
  const act = window.casoraClimateActive?.(entity) || {};
  if (act.cooling) {
    return fit(target ? "Kühlt auf " + target : "Kühlt");
  } else if (act.heating) {
    return fit(target ? "Heizt auf " + target : "Heizt");
  } else if (mode === 'cool' || mode === 'heat') {
    // hvac_mode is set but hvac_action reports idle (room's already at
    // or past target) — say so instead of claiming it's actively heating.
    return fit(target ? "Bereit · " + target : "Bereit");
  } else if (mode === 'auto' || mode === 'heat_cool') {
    return fit(target ? "Automatik · " + target : "Automatik");
  } else if (mode === 'dry' || mode === 'fan_only') {
    return fit(mode === 'dry' ? "Entfeuchten" : "Nur Lüfter");
  } else if (mode === 'unavailable') {
    return "Nicht verfügbar";
  } else {
    return "Aus";
  }
]]]

