dth));return Math.round((lo+f*(hi-lo))/st)*st;};var paint=function(t){var f=(t-lo)/(hi-lo)*100;tr.querySelector(&quot;.hp-tb-k&quot;).style.left=f+&quot;%&quot;;var n=h.getRootNode().querySelector(&quot;.hp-st-v .n&quot;);if(n)n.firstChild.nodeValue=t.toLocaleString(&quot;de-DE&quot;,{minimumFractionDigits:1,maximumFractionDigits:1});};var send=function(t){document.querySelector(&quot;home-assistant&quot;).hass.callService(&quot;climate&quot;,&quot;set_temperature&quot;,{temperature:t' + (offH ? ',hvac_mode:&quot;heat&quot;' : '') + '},{entity_id:&quot;' + id + '&quot;});};window._hpTbT=Date.now();if(h._t!=null)send(h._t);" onclick="event.stopPropagation();if(Date.now()-(window._hpTbT||0)<700)return;var h=this,tr=h.firstElementChild,b=tr.getBoundingClientRect(),lo=' + tMin + ',hi=' + tMax + ',st=' + step + ';var tv=function(x){var f=Math.max(0,Math.min(1,(x-b.left)/b.width));return Math.round((lo+f*(hi-lo))/st)*st;};var paint=function(t){var f=(t-lo)/(hi-lo)*100;tr.querySelector(&quot;.hp-tb-k&quot;).style.left=f+&quot;%&quot;;var n=h.getRootNode().querySelector(&quot;.hp-st-v .n&quot;);if(n)n.firstChild.nodeValue=t.toLocaleString(&quot;de-DE&quot;,{minimumFractionDigits:1,maximumFractionDigits:1});};var send=function(t){document.querySelector(&quot;home-assistant&quot;).hass.callService(&quot;climate&quot;,&quot;set_temperature&quot;,{temperature:t' + (offH ? ',hvac_mode:&quot;heat&quot;' : '') + '},{entity_id:&quot;' + id + '&quot;});};var t=tv(event.clientX);paint(t);send(t);">'
      + '<div class="hp-tb-t"><div class="hp-tb-k" style="left:' + kPct + '%"></div></div>'
