variables.toggle_service_data:
[[[
  /* An ist jeder Modus außer Aus (auch Automatik, Heizen/Kühlen, Entfeuchten, Lüfter): Tippen schaltet aus. */
  const st = entity?.state;
  if (st && !['off','unavailable','unknown'].includes(st)) {
    return { entity_id: entity?.entity_id, hvac_mode: 'off' };
  }
  /* Einschalten: Modus aus dem Helfer, wenn das Gerät ihn kennt – sonst Heizen bzw. sein erster Modus. */
  const modes = (entity?.attributes?.hvac_modes || []).filter((m) => m !== 'off');
  const want = states['input_select.casora_thermostat_mode']?.state || 'heat';
  return { entity_id: entity?.entity_id,
    hvac_mode: !modes.length || modes.includes(want) ? want : modes.includes('heat') ? 'heat' : modes[0] };
]]]

casora_time.name:
[[[
  const id  = variables.time_entity || "sensor.time";
  const ent = states[id];
  if (!ent) return "";

  const raw    = String(ent.state || "");
  const use12  = variables.use_12h === true;
  const suffix = (variables.time_suffix || "").toString().trim();

  const to12h = (timeStr) => {
    const m = String(timeStr).match(/^(\d{1,2}):(\d{2})$/);
    if (!m) return timeStr;
    let h = parseInt(m[1], 10);
    const min = m[2];
    const ampm = h >= 12 ? "PM" : "AM";
    h = h % 12;
    if (h === 0) h = 12;
    return `${h}:${min} ${ampm}`;
  };

  let timePart = raw;
  if (raw.includes(",")) {
    const parts = raw.split(",");
    timePart = (parts[1] || "").trim() || raw;
  }

  let display = timePart;
  if (use12 && /^\d{1,2}:\d{2}$/.test(timePart)) {
    display = to12h(timePart);
  }

  if (suffix) display = `${display} ${suffix}`;

  return display.toUpperCase();
]]]

card.--casora-icon-circle-bg:
[[[
  const W = window.casoraDevice && window.casoraDevice.waste ? window.casoraDevice.waste(hass, variables) : null;
  if (!W || W.days !== 0 || !W.next) return 'rgba(255,255,255,0.10)';
  return W.next.tint;
]]]

card.--casora-icon-off-ink:
[[[
  /* Weich (05.10.2026): am Abholtag steht das Symbol hell auf dem vollen Tonnenkreis.
     --casora-icon-off-ink wirkt nur im Weich-Look (--casora-icon-off-mix), sonst bleibt alles gleich. */
  const W = window.casoraDevice && window.casoraDevice.waste ? window.casoraDevice.waste(hass, variables) : null;
  if (!W || W.days !== 0 || !W.next) return 'var(--casora-soft-glyph-off, transparent)';
  return 'var(--casora-waste-glyph, var(--casora-soft-glyph-off, transparent))';
]]]

state.value:
[[[
  const W = window.casoraDevice && window.casoraDevice.waste ? window.casoraDevice.waste(hass, variables) : null;
  if (!W || W.duty === false || W.days == null) return false;
  return W.days <= 1;
]]]

casora_trash.state_display:
[[[
  /* Abfall-Kalender vorladen (23.09.2026): das Popup braucht mehr Termine,
     als die Sensoren liefern, und wird synchron gebaut. Alle 6 h neu. */
  if (!window._casoraTrashFetch) {
    window._casoraTrashFetch = (h, cal) => {
      const c = window._casoraTrashCal;
      if (!h || !h.callApi || window._casoraTrashBusy) return;
      if (c && c.id === cal && Date.now() - c.ts < 6 * 3600000) return;
      window._casoraTrashBusy = true;
      const s = new Date(); s.setHours(0, 0, 0, 0);
      const e = new Date(s.getTime() + 400 * 86400000);
      h.callApi('GET', 'calendars/' + cal + '?start=' + encodeURIComponent(s.toISOString()) + '&end=' + encodeURIComponent(e.toISOString()))
        .then((r) => { window._casoraTrashCal = { id: cal, ts: Date.now(), ev: Array.isArray(r) ? r : [] }; })
        .catch(() => {})
        .finally(() => { window._casoraTrashBusy = false; });
    };
  }
  const W = window.casoraDevice && window.casoraDevice.waste ? window.casoraDevice.waste(hass, variables) : null;
  const fit = (t) => window.casoraStateFit?.(t) ?? t;
  if (!W) return '…';
  if (W.calendar) window._casoraTrashFetch(hass, W.calendar);
  /* Dienstplan (optional): kein Dienst → Kachel ruhig (nicht aktiv), zeigt aber die nächste Abholung. */
  const label = W.next ? W.next.label : '';
  const days = W.days;
  /* Quelle weg und keine Termine (04.10.2026): ruhig „Nicht erreichbar“ statt leer. */
  if (days == null && window.casoraDevice.wasteDown && window.casoraDevice.wasteDown(hass, W)) return fit('Nicht erreichbar');
  if (days == null) return fit(W.bins.length ? 'Keine Daten' : 'Keine Tonnen gefunden');
  if (days === 0) return fit(`Heute ${label}`);
  if (days === 1) return fit(`Morgen ${label}`);
  return fit(`${days} Tage · ${label}`);
]]]

casora_popup.content:
[[[
  const UI = window._casoraUI;
  if (!UI) return { type: 'vertical-stack', cards: [] };
  const T = UI.tokens;
  const esc = UI.esc;

  /* Erweitert 23.09.2026: 4-Wochen-Kalender, mehrere Termine je Tonne mit
     Rhythmus, verschobene Termine (Feiertage), Dienstmonate, Erinnerung.
     Termine kommen aus den Sensor-Attributen und, wo die zu kurz sind (Bio
     hat nur einen), aus dem Abfall-Kalender, den die Kachel vorlädt. */
  /* Tonnen, Kalender, Dienst und Erinnerung über den Finder (Casora) –
     Kartenvariablen trash_* und CASORA_SETTINGS.waste haben Vorrang. */
  const W = window.casoraDevice && window.casoraDevice.waste ? window.casoraDevice.waste(hass, variables) : null;
  if (!W) return { type: 'vertical-stack', cards: [] };
  const CAL = W.calendar;
  const REMINDER = W.reminder;
  const DUTY = W.months || [];
  if (CAL && window._casoraTrashFetch) window._casoraTrashFetch(hass, CAL);

  const BINS = W.bins;
  const DAY = 86400000;
  const WD = ['Sonntag', 'Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag'];
  const MON = ['Jan', 'Feb', 'Mär', 'Apr', 'Mai', 'Jun', 'Jul', 'Aug', 'Sep', 'Okt', 'Nov', 'Dez'];
  const MONL = ['Januar', 'Februar', 'März', 'April', 'Mai', 'Juni', 'Juli', 'August', 'September', 'Oktober', 'November', 'Dezember'];
  const today = new Date(); today.setHours(0, 0, 0, 0);
  const ISO = /^\d{4}-\d{2}-\d{2}$/;
  const dOf = (iso) => { const d = new Date(String(iso).slice(0, 10) + 'T00:00:00'); return isNaN(d) ? null : d; };
  const key = (d) => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
  const diff = (d) => Math.round((d - today) / DAY);
  const fmt = (d) => d.toLocaleDateString((window.casoraLocale ? window.casoraLocale() : 'de-DE'), { weekday: 'short', day: '2-digit', month: '2-digit' });
  const fmtS = (d) => d.toLocaleDateString((window.casoraLocale ? window.casoraLocale() : 'de-DE'), { day: '2-digit', month: '2-digit' });
  const rel = (n) => n === 0 ? 'Heute' : n === 1 ? 'Morgen' : 'in ' + n + ' Tagen';

  const cal = (window._casoraTrashCal && window._casoraTrashCal.id === CAL) ? window._casoraTrashCal.ev : [];
  const datesOf = (b) => {
    const a = states[b.id]?.attributes || {};
    const set = {};
    Object.keys(a).forEach((k) => {
      if (ISO.test(k)) set[k] = 1;
      else if (typeof a[k] === 'string' && ISO.test(a[k])) set[a[k]] = 1;
    });
    cal.forEach((e) => {
      const s = e && e.start && (e.start.date || e.start.dateTime);
      if (s && b.re.test(e.summary || '')) set[String(s).slice(0, 10)] = 1;
    });
    return Object.keys(set).map(dOf).filter((d) => d && d >= today).sort((x, y) => x - y);
  };

  const bins = BINS.map((b) => {
    const st = states[b.id];
    if (!st) return null;
    const ds = datesOf(b);
    let days = parseInt(st.state, 10);
    if (isNaN(days)) days = parseInt(st.attributes?.daysTo, 10);
    if (isNaN(days) && ds.length) days = diff(ds[0]);
    if (isNaN(days)) return null;
    /* Countdown und Datum aus demselben Termin: passt kein Termin zum
       Sensor-Countdown, gilt der nächste Termin - und der Countdown folgt ihm. */
    let next = ds.find((d) => diff(d) === days);
    if (!next && ds.length) { next = ds[0]; days = diff(next); }
    if (!next) next = new Date(today.getTime() + days * DAY);
    /* Rhythmus und üblicher Wochentag aus den Abständen; ein Termin, der
       auf einen anderen Wochentag fällt, ist verschoben (Feiertag). */
    const gaps = ds.slice(1).map((d, i) => Math.round((d - ds[i]) / DAY)).sort((x, y) => x - y);
    const weeks = gaps.length ? Math.round(gaps[Math.floor(gaps.length / 2)] / 7) : 0;
    const cnt = [0, 0, 0, 0, 0, 0, 0];
    ds.forEach((d) => cnt[d.getDay()]++);
    const usual = ds.length >= 3 ? cnt.indexOf(Math.max.apply(null, cnt)) : null;
    return Object.assign({}, b, { days, next, ds, weeks, usual });
  }).filter(Boolean).sort((x, y) => x.days - y.days);

  const byDay = {};
  bins.forEach((b) => b.ds.forEach((d) => { (byDay[key(d)] = byDay[key(d)] || []).push(b); }));

  const plate = (inner, pad) => '<div class="hui-plate" style="background:var(--casora-popup-row-fill, rgba(255,255,255,0.10));'
    + 'border-radius:var(--casora-popup-row-radius, 20px);overflow:hidden;'
    + 'box-shadow:var(--casora-popup-plate-shadow, none);'
    + 'backdrop-filter:var(--casora-popup-plate-backdrop, none);'
    + '-webkit-backdrop-filter:var(--casora-popup-plate-backdrop, none);'
    + 'padding:' + (pad || 'var(--casora-popup-row-pad-y, 8px) var(--casora-popup-row-pad-x, 16px)') + ';'
    + 'font-family:' + T.font + ';text-align:left;">' + inner + '</div>';
  const title = (t, v, vTone) => '<div style="display:flex;justify-content:space-between;align-items:baseline;gap:12px;'
    + 'padding:0 4px 8px;">'
    + '<div style="font-size:var(--casora-h15-fs,15px);font-weight:var(--casora-h15-fw,600);letter-spacing:var(--casora-h15-ls,-0.01em);text-transform:var(--casora-h15-tt,none);color:var(--casora-h15-c, ' + T.ink + ');">' + esc(t) + '</div>'
    + (v ? '<div style="font-size:15px;letter-spacing:-0.01em;color:' + (vTone || T.ink2) + ';white-space:nowrap;">' + esc(v) + '</div>' : '')
    + '</div>';
  const gap = '<div style="height:18px"></div>';

  const first = bins[0];
  /* Abfall-Quelle nicht erreichbar (04.10.2026): Kalender/Sensoren unavailable und keine Termine. */
  const DOWN = window.casoraDevice.wasteDown ? window.casoraDevice.wasteDown(hass, W) : null;
  const duty = W.duty === true;
  let out = '<style>ha-card.disabled{pointer-events:auto!important;}'
    + '.tr-cal{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));row-gap:4px;}'
    + '.tr-wd{font-size:12px;font-weight:600;color:' + T.ink3 + ';text-align:center;padding-bottom:6px;}'
    + '.tr-d{display:flex;flex-direction:column;align-items:center;gap:4px;padding:4px 0 6px;border-radius:12px;}'
    + '.tr-d.hit{background:' + T.fill + ';}'
    + '.tr-n{width:30px;height:30px;border-radius:50%;display:grid;place-items:center;font-size:16px;letter-spacing:-0.02em;color:' + T.ink + ';}'
    + '.tr-d.past .tr-n,.tr-d.past .tr-dots{opacity:.32;}'
    + '.tr-d.today .tr-n{background:' + T.accent + ';color:#fff;font-weight:600;}'
    + '.tr-m{font-size:10px;font-weight:600;color:' + T.ink3 + ';line-height:1;margin-top:-2px;}'
    + '.tr-dots{display:flex;gap:3px;height:7px;}'
    + '.tr-dot{width:7px;height:7px;border-radius:50%;}'
    + '.tr-leg{display:flex;flex-wrap:wrap;gap:6px 14px;margin-top:12px;font-size:13px;color:' + T.ink2 + ';}'
    + '.tr-leg span{display:inline-flex;align-items:center;gap:6px;}'
    + '.tr-mo{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:4px;}'
    + '.tr-mc{height:30px;border-radius:8px;display:grid;place-items:center;font-size:12px;font-weight:600;color:' + T.ink3 + ';background:' + T.fill + ';}'
    + '.tr-mc.duty{background:' + T.accent + ';color:#fff;}'
    + '.tr-mc.now{box-shadow:inset 0 0 0 2px ' + T.ink + ';color:' + T.ink + ';}'
    + '.tr-mc.duty.now{color:#fff;}'
    + '</style>';

  const heroH = UI.hero(first
    ? { label: (UI.soft && UI.soft()) ? null : 'Nächste Abholung', value: first.label,
        sub: rel(first.days) + ' · ' + fmt(first.next) + (first.days === 1 ? ' · heute Abend raus' : ''),
        subTone: first.days <= 1 ? 'warn' : null, center: true }
    : { value: 'Keine Termine', center: true });

  /* Kalender: diese und die drei folgenden Wochen, Montag zuerst. */
  let calH = '', rightH = '';
  if (bins.length) {
    const start = new Date(today); start.setDate(start.getDate() - ((start.getDay() + 6) % 7));
    let g = '<div class="tr-cal">' + ['Mo', 'Di', 'Mi', 'Do', 'Fr', 'Sa', 'So'].map((w) => '<div class="tr-wd">' + w + '</div>').join('');
    for (let i = 0; i < 28; i++) {
      const d = new Date(start); d.setDate(start.getDate() + i);
      const hits = byDay[key(d)] || [];
      const cls = 'tr-d' + (d < today ? ' past' : '') + (+d === +today ? ' today' : '') + (hits.length && d >= today ? ' hit' : '');
      g += '<div class="' + cls + '" title="' + esc(hits.map((b) => b.label).join(', ')) + '">'
        + (d.getDate() === 1 ? '<div class="tr-m">' + MON[d.getMonth()] + '</div>' : '')
        + '<div class="tr-n">' + d.getDate() + '</div>'
        + '<div class="tr-dots">' + hits.map((b) => '<div class="tr-dot" style="background:' + b.color + '"></div>').join('') + '</div></div>';
    }
    g += '</div><div class="tr-leg">' + BINS.filter((b) => bins.some((x) => x.id === b.id))
      .map((b) => '<span><i class="tr-dot" style="display:inline-block;background:' + b.color + '"></i>' + esc(b.label) + '</span>').join('') + '</div>';
    calH = title('Nächste 4 Wochen') + plate(g);
  }

  if (bins.length) {
    const rows = bins.map((b) => {
      const rhythm = b.weeks === 1 ? 'jede Woche' : b.weeks > 1 ? 'alle ' + b.weeks + ' Wochen' : null;
      return {
        icon: 'mdi:trash-can', iconTone: b.color,
        label: b.label,
        sub: fmt(b.next) + (rhythm ? ' · ' + rhythm : ''),
        value: rel(b.days),
        valueTone: b.days <= 1 ? 'warn' : null,
      };
    });
    rightH += UI.group(rows, 'Tonnen');
  }

  /* Verschobene Termine der nächsten vier Monate. */
  const moved = [];
  bins.forEach((b) => {
    if (b.usual == null) return;
    b.ds.forEach((d) => { if (diff(d) <= 120 && d.getDay() !== b.usual) moved.push({ b, d }); });
  });
  moved.sort((x, y) => x.d - y.d);
  /* Verschobene Termine ausgeblendet (24.09.2026, Wunsch). */
  if (false && moved.length) {
    rightH += (rightH ? gap : '') + UI.group(moved.slice(0, 4).map((m) => ({
      icon: 'mdi:calendar-alert', iconTone: m.b.color,
      label: m.b.label + ' am ' + WD[m.d.getDay()],
      sub: fmtS(m.d) + ' statt ' + WD[m.b.usual],
      value: rel(diff(m.d)),
    })), 'Verschobene Termine');
  }

  /* Dienstmonate: wer die Tonnen rausstellt. */
  const cm = today.getMonth() + 1;
  let nextDuty = null;
  for (let i = 1; i <= 12 && nextDuty == null; i++) { const m = ((cm - 1 + i) % 12) + 1; if (DUTY.indexOf(m) > -1) nextDuty = m; }
  const mo = '<div class="tr-mo">' + MON.map((n, i) => '<div class="tr-mc' + (DUTY.indexOf(i + 1) > -1 ? ' duty' : '')
    + (i + 1 === cm ? ' now' : '') + '">' + n.charAt(0) + '</div>').join('') + '</div>'
    + '<div style="font-size:13px;color:' + T.ink3 + ';margin-top:10px;">'
    + esc(duty ? 'Diesen Monat bist du dran' + (nextDuty ? ', danach wieder im ' + MONL[nextDuty - 1] : '') + '.'
               : 'Nächster Dienst im ' + (nextDuty ? MONL[nextDuty - 1] : '–') + '.') + '</div>';
  /* Überschrift über der Karte wie „Tonnen“ rechts, damit beide Spalten auf einer Linie liegen (02.10.2026). */
  const dutyTxt = duty ? 'Du bist dran' : 'Nicht dran';
  const dutyLbl = UI.soft && UI.soft() && UI.label
    ? UI.label('Rausstellen').slice(0, -6) + '<div style="font-size:13px;font-weight:600;white-space:nowrap;color:' + (duty ? T.green : T.ink3) + ';">' + esc(dutyTxt) + '</div></div>'
    : title('Rausstellen', dutyTxt, duty ? T.green : null);
  const dutyH = dutyLbl + plate(mo);

  /* Popup-Standard (24.09.2026): Erinnerung bekommt eine Überschrift wie alle Abschnitte. */
  const REM_HEAD = title('Erinnerung').replace('padding:0 4px 8px;', 'padding:0 0 10px;');
  const REM_TPL = '[[[\n'
      + 'const T = window._casoraUI ? window._casoraUI.tokens : {};\n'
      + 'const st = states[' + JSON.stringify(REMINDER) + '];\n'
      + 'if (!st) return "";\n'
      + 'const on = st.state === "on";\n'
      + 'const lt = st.attributes.last_triggered ? new Date(st.attributes.last_triggered) : null;\n'
      + 'const sub = on ? "um 20 Uhr" + (lt ? " · zuletzt " + lt.toLocaleDateString("de-DE", { day: "2-digit", month: "2-digit" }) : "") : "Keine Push-Erinnerung";\n'
      + 'const svc = { domain: "automation", service: on ? "turn_off" : "turn_on", target: { entity_id: st.entity_id } };\n'
      + 'return "<style>ha-card.disabled{pointer-events:auto!important;}'
      +   '.tr-row{display:flex;align-items:center;gap:12px;cursor:pointer;min-height:52px;}'
      +   '.tr-sw{position:relative;width:var(--casora-sw-w,51px);height:var(--casora-sw-h,31px);flex:none;border-radius:999px;pointer-events:none;background:var(--casora-sw-off,rgba(120,120,128,0.36));transition:background-color .2s ease;}'
      +   '.tr-sw.on{background:var(--casora-sw-on,#30D158);}'
      +   '.tr-kn{position:absolute;top:var(--casora-sw-pad,2px);left:var(--casora-sw-pad,2px);width:var(--casora-sw-k,27px);height:var(--casora-sw-k,27px);border-radius:50%;background:#fff;box-shadow:var(--casora-sw-ks,0 2px 4px rgba(0,0,0,0.25));transition:transform .2s cubic-bezier(.36,0,.16,1);}'
      +   '.tr-sw.on .tr-kn{transform:translateX(var(--casora-sw-x,20px));}'
      +   '@media (prefers-reduced-motion:reduce){.tr-sw,.tr-kn{transition:none;}}</style>"\n'
      + ' + "<div style=\\"background:var(--casora-popup-row-fill, rgba(255,255,255,0.10));border-radius:var(--casora-popup-row-radius, 20px);overflow:hidden;box-shadow:var(--casora-popup-plate-shadow, none);backdrop-filter:var(--casora-popup-plate-backdrop, none);-webkit-backdrop-filter:var(--casora-popup-plate-backdrop, none);padding:var(--casora-popup-row-pad-y, 8px) var(--casora-popup-row-pad-x, 16px);font-family:" + T.font + ";text-align:left;\\">" + ' + JSON.stringify(REM_HEAD) + '\n'
      + ' + "<div class=\\"tr-row\\" data-casora-svc=\\"" + window._casoraUI.esc(JSON.stringify(svc)) + "\\">"\n'
      + ' + "<div style=\\"flex:1;min-width:0;pointer-events:none;\\"><div style=\\"font-size:17px;letter-spacing:-0.022em;color:" + T.ink + ";\\">Push am Vorabend</div>"\n'
      + ' + "<div style=\\"font-size:13px;color:" + T.ink3 + ";margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;\\">" + sub + "</div></div>"\n'
      + ' + "<div class=\\"tr-sw" + (on ? " on" : "") + "\\"><div class=\\"tr-kn\\"></div></div></div></div>";\n'
      + ']]]';

  /* Desktop/Tablet zweispaltig (23.09.2026): links Kalender, Dienst und
     Erinnerung, rechts Tonnen und Verschiebungen. Die rechte Spalte
     überspannt die linken Zeilen; ihr Überschuss geht in die letzte Zeile,
     damit links nichts auseinanderrutscht. Schmal eine Spalte in der
     alten Reihenfolge. */
  const wrap = '\n:host { --ha-card-backdrop-filter: none !important; --ha-card-background: transparent !important; --card-background-color: transparent !important; --ha-card-box-shadow: none !important; --ha-card-border-width: 0px !important; }'
    + '\nha-card::before, ha-card::after, #card::before, #card::after, #container::before, #container::after { display: none !important; }'
    + '\nha-card { will-change: auto !important; }';
  const fields = { hero: out + heroH };
  /* Hinweis statt Leere; Zeilen dürfen umbrechen (Weich klemmt die Unterzeile sonst am Handy). */
  if (DOWN) {
    fields.down = '<style>.tr-down *,.tr-down .hui-srow .hui-sub{white-space:normal!important;text-overflow:clip!important;-webkit-line-clamp:unset!important;}.tr-down .hui-srow .hui-sub{display:block!important;}</style><div class="tr-down">'
      + UI.group([{ icon: 'mdi:cloud-off-outline', iconTone: 'warn', label: 'Abfallkalender gerade nicht erreichbar',
        sub: 'Die Abholtermine kommen wieder, sobald ' + (DOWN.source || 'der Entsorger') + ' antwortet.' }]) + '</div>';
  }
  /* 4-Wochen-Kalender ausgeblendet (24.09.2026, Wunsch). */
  if (rightH) fields.right = rightH;
  if (W.months) fields.duty = dutyH;
  if (states[REMINDER]) {
    fields.rem = { card: {
      type: 'custom:button-card',
      triggers_update: [REMINDER],
      /* Überschrift nicht abschneiden (button-card-Felder sind overflow:hidden). */
      card_mod: { style: wrap + '\nha-card, #container, #body { overflow: visible !important; text-align: left !important; }' },
      tap_action: { action: 'none' }, hold_action: { action: 'none' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      styles: {
        card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '0' }, { overflow: 'visible' }],
        grid: [{ 'grid-template-areas': '"body"' }, { 'grid-template-columns': 'minmax(0, 1fr)' }],
        custom_fields: { body: [{ 'justify-self': 'stretch' }, { 'min-width': '0' }, { overflow: 'visible' }] },
      },
      custom_fields: { body: REM_TPL },
    } };
  }
  /* Monatskalender (optional, Studio → Einstellungen → Haus & Geräte, 03.10.2026): derselbe
     Monat wie im Kalender-Popup, die Abholtage in der Farbe der Tonne, Tippen zeigt den Tag. */
  const KAL = window._casoraCalendar;
  if (W.calendarPopup && (bins.length || DOWN) && KAL && KAL.wcol) {
    /* Issue #7 (04.10.2026): Tageskarte als eigener Abschnitt, breit rechts oben über den Tonnen,
       am Handy direkt unter dem Kopf. */
    const watch = BINS.map((b) => b.id).concat(CAL ? [CAL] : []);
    /* Nicht erreichbar: Monat bleibt, aber keine leere Tageskarte. */
    if (!DOWN) fields.wday = { card: KAL.wcol(variables, watch, ['wday']) };
    fields.cal = { card: KAL.wcol(variables, watch, ['wmonth']) };
  }
  const has = (k) => fields[k] !== undefined;
  /* Popup-Standard (24.09.2026): links Erinnerung + Rausstellen, rechts die Tonnen. Schmal in derselben Reihenfolge. */
  const leftK = ['rem', 'duty'].filter(has);
  const q = (k) => '"' + k + '"';
  let wideAreas, wideCols = 'minmax(0, 1fr)', wideRows = 'auto';
  if (has('cal')) {
    /* Links der Kalender, rechts Hinweis (nicht erreichbar), Tageskarte, Tonnen, Erinnerung und Rausstellen. */
    const rk = ['down', 'wday', 'right', 'rem', 'duty'].filter(has);
    wideAreas = '"hero hero" ' + rk.map((k) => '"cal ' + k + '"').join(' ');
    wideCols = 'minmax(0, 1fr) minmax(0, 1fr)';
    wideRows = 'auto ' + rk.map((k, i) => i === rk.length - 1 ? '1fr' : 'auto').join(' ');
  } else if (has('right') && leftK.length) {
    wideAreas = '"hero hero" ' + (has('down') ? '"down down" ' : '') + leftK.map((k) => '"' + k + ' right"').join(' ');
    wideCols = 'minmax(0, 1fr) minmax(0, 1fr)';
    wideRows = 'auto ' + (has('down') ? 'auto ' : '') + leftK.map((k, i) => i === leftK.length - 1 ? '1fr' : 'auto').join(' ');
  } else {
    wideAreas = ['hero', 'down', 'cal', 'rem', 'duty', 'right'].filter(has).map(q).join(' ');
  }
  /* Handy (24.09.): Tonnen zuerst, dann Kalender, Erinnerung und Rausstellen. Mit Kalender
     (Issue #7, Variante B): die Tageskarte direkt unter dem Kopf, darüber den Tonnen. */
  const narrowAreas = ['hero', 'down', 'wday', 'right', 'cal', 'rem', 'duty'].filter(has).map(q).join(' ');
  const fstyle = {};
  Object.keys(fields).forEach((k, i) => {
    fstyle[k] = [{ 'justify-self': 'stretch' }, { 'min-width': '0' }, { overflow: 'visible' },
      { '--casora-popup-plate-delay': (i * 55) + 'ms' }];
  });
  /* Monat links (05.10.2026): über die volle Höhe der rechten Spalte, damit beide Spalten bündig enden. */
  if (has('cal')) fstyle.cal.push({ 'align-self': 'stretch' }, { display: 'flex' }, { 'flex-direction': 'column' });
  return { type: 'vertical-stack', cards: [{
    type: 'custom:button-card',
    card_mod: { style: wrap
      + '\n@media (max-width: 600px) { ha-card { padding-left: 14px !important; padding-right: 14px !important; } }' },
    tap_action: { action: 'none' }, hold_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    styles: {
      card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: 'var(--casora-soft-card-top, 6px) 26px 22px 26px' }],
      grid: [
        { 'grid-template-areas': wideAreas },
        { 'grid-template-columns': wideCols },
        { 'grid-template-rows': wideRows },
        { 'row-gap': 'var(--casora-popup-sec-gap, 18px)' },
        { 'column-gap': 'var(--casora-popup-col-gap, 18px)' },
        { 'align-items': 'start' },
      ],
      custom_fields: fstyle,
    },
    custom_fields: fields,
    extra_styles: '#cal > * { flex: 1 1 auto; }'
      + ' @media (max-width: 760px) { #cal { align-self: start !important; } #container {'
      + ' grid-template-areas: ' + narrowAreas + ' !important;'
      + ' grid-template-columns: minmax(0, 1fr) !important;'
      + ' grid-template-rows: auto !important; } }',
  }] };
]]]

popup_styles.styles:
/* Eine Popup-Familie (01.10.2026): dieselbe Sheet-Fläche wie die Bedien-Popups –
   Fläche, Blur, Schatten und Abdunklung aus dem Standard, Höhe folgt dem Inhalt,
   Schließen-Kreuz mit demselben Abstand zur Sheet-Kante. */
.header { padding-top: var(--casora-popup-header-gap, 10px); }
--casora-popup-header-gap: 14px;
--casora-popup-gutter-wide: 34px;
--casora-popup-gutter-phone: 22px;

/* No chart here, so nothing to wait for: the widgets arrive as
   soon as they are built. Read by each widget for itself, never by
   a wrapper - an animated opacity on an ancestor flattens the frost
   inside it. */
--casora-popup-plate-enter:
  casora-plate-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
@media (prefers-reduced-motion: reduce) {
  --casora-popup-plate-enter: none;
}

--casora-popup-hero-label-size: 15px;
--casora-popup-row-radius: 26px;
/* Frosted, not opaque. The pane's blur used to sit under these, and
   .content still nulls --ha-card-backdrop-filter for every card in
   the popup, so the frost has to be asked for here. The fills drop
   to let it read. */
/* The theme lifts every ha-card with filter: brightness(1.01) on
   hover. A filter on an ancestor makes every descendant's
   backdrop-filter inert, so hovering the empty space around a
   widget - the wrapper card - knocked the frost out of both of
   them. Killed popup-wide; the plate re-declares its own shadow. */
--casora-card-hover-filter: none;
--casora-hover-filter: none;
--casora-card-hover-shadow: none;

--casora-popup-row-pad-x: 26px;
--casora-popup-row-pad-y: 15px;
--casora-popup-plate-backdrop: blur(24px) saturate(180%);
--casora-popup-chart-fill: var(--casora-sheet-chart-fill, rgba(10, 12, 16, 0.68));
--casora-popup-row-fill: var(--casora-sheet-row-fill, rgba(12, 14, 19, 0.62));
/* Lifted, not slabbed: one wide soft pass carries the height, one
   short contact pass keeps the edge from dissolving into the room. */
--casora-popup-plate-shadow: var(--casora-sheet-plate-shadow,
  0 18px 40px -22px rgba(0, 0, 0, 0.50),
  0 2px 8px -5px rgba(0, 0, 0, 0.28));

/* visionOS puts nothing bare on the room: the only chrome outside a
   window is its close control, and that control is itself a glass
   object. The title was printed twice - here and in the widget
   eight pixels below - so it goes, clipped rather than removed so a
   screen reader still gets it. */

/* The chrome arrives with the first plate instead of being there
   on frame one while everything under it fades in. */
--casora-popup-chrome-enter:
  casora-popup-chrome-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
.content { animation: none; }
/* The title lives in the bar now, centered and level with the
   close control, so it is no longer hidden. */
.header-title { font-size: 20px; font-weight: 600; letter-spacing: -0.01em; }
/* 48px is left alone: the base sizes it so the glyph's ink lands on
   the same left margin as the widgets below. */
.header-close {
  border-radius: 50%;
  background: var(--casora-popup-row-fill, rgba(255, 255, 255, 0.10));
  backdrop-filter: var(--casora-popup-plate-backdrop, none);
  -webkit-backdrop-filter: var(--casora-popup-plate-backdrop, none);
  box-shadow: var(--casora-popup-plate-shadow, none);
}

ha-adaptive-dialog, ha-dialog, wa-drawer {
  --ha-card-backdrop-filter: none;
  --ha-card-background: transparent;
  --card-background-color: transparent;
  --ha-card-box-shadow: none;
  --ha-card-border-width: 0px;
}
/* Anzeige-Popup: Pflanzen/Energie-Stil ohne Pane (23.09.2026). */
--popup-min-width: min(900px, 92vw);
--popup-max-width: min(900px, 92vw);

/* Popup-Standard (24.09.2026): Info-Popup - Abschnittsüberschriften in der Karte. */
--casora-lbl-in: block;
--casora-lbl-out: none;

