casora_popup.content:
[[[
  const UI = window._casoraUI;
  if (!UI || !entity) return { type: 'vertical-stack', cards: [] };
  const T = UI.tokens, esc = UI.esc;
  const id = entity?.entity_id, a = entity?.attributes || {};
  const COND = {
    'clear-night': ['Klar', 'mdi:weather-night'], cloudy: ['Bewölkt', 'mdi:weather-cloudy'], exceptional: ['Unwetter', 'mdi:alert-circle-outline'],
    fog: ['Nebel', 'mdi:weather-fog'], hail: ['Hagel', 'mdi:weather-hail'], lightning: ['Gewitter', 'mdi:weather-lightning'],
    'lightning-rainy': ['Gewitter mit Regen', 'mdi:weather-lightning-rainy'], partlycloudy: ['Teils bewölkt', 'mdi:weather-partly-cloudy'],
    pouring: ['Starkregen', 'mdi:weather-pouring'], rainy: ['Regen', 'mdi:weather-rainy'], snowy: ['Schnee', 'mdi:weather-snowy'],
    'snowy-rainy': ['Schneeregen', 'mdi:weather-snowy-rainy'], sunny: ['Sonnig', 'mdi:weather-sunny'], windy: ['Windig', 'mdi:weather-windy'],
    'windy-variant': ['Windig & bewölkt', 'mdi:weather-windy-variant'],
  };
  const cond = (c) => COND[c] || [c || '–', 'mdi:weather-cloudy'];
  const r0 = (v) => v == null || isNaN(v) ? '–' : Math.round(v);
  const tsId = variables.weather_temp_sensor && ((s) => { const _a = (s && s.attributes) || {}; const _u = String(_a.unit_of_measurement || ''); return !!s && (_a.device_class === 'temperature' || /°|^K$/.test(_u) || (!_u && !_a.device_class)); })(states[variables.weather_temp_sensor]) ? variables.weather_temp_sensor : null;
  const curT = tsId && !isNaN(parseFloat(states[tsId].state)) ? parseFloat(states[tsId].state) : a.temperature;
  const key = 'hw_' + id.replace(/[^a-zA-Z0-9]/g, '_');
  window._hwFc = window._hwFc || {};

  /* Renderer für die nachgeladenen Vorhersagen (auch bei gecachten Daten sofort) */
  const hourly = (list) => {
    const now = Date.now() - 3600000;
    const items = (list || []).filter((f) => new Date(f.datetime).getTime() >= now).slice(0, 24);
    if (!items.length) return '';
    const anyRain = items.some((f) => f.precipitation_probability || f.precipitation);
    return '<div class="hw-src' + (anyRain ? ' rain' : '') + '" ontouchstart="event.stopPropagation();var w=this;cancelAnimationFrame(w._raf);var t=event.touches[0];w._sx=t.clientX;w._sy=t.clientY;w._sl=w.scrollLeft;w._h=null;w._js=false;w._lx=t.clientX;w._lt=event.timeStamp;w._v=0;w._m=w.scrollWidth-w.clientWidth;" ontouchmove="event.stopPropagation();var w=this,t=event.touches[0];var dx=t.clientX-w._sx,dy=t.clientY-w._sy;if(w._h===null&&(Math.abs(dx)>6||Math.abs(dy)>6))w._h=Math.abs(dx)>Math.abs(dy);if(!w._h)return;if(!w._js&&Math.abs(dx)>40&&w.scrollLeft===w._sl&&w._m>0&&!((dx>0&&w._sl<=0)||(dx<0&&w._sl>=w._m))){w._js=true;w._sx=t.clientX;w._sl=w.scrollLeft;dx=0;}if(!w._js)return;if(event.cancelable)event.preventDefault();w.scrollLeft=w._sl-dx;var dt=Math.max(1,event.timeStamp-w._lt);w._v=0.8*((w._lx-t.clientX)/dt)+0.2*w._v;w._lx=t.clientX;w._lt=event.timeStamp;" ontouchend="event.stopPropagation();var w=this;if(!w._js)return;var v=w._v*16,last=performance.now();var step=function(now){var f=Math.min(3,(now-last)/16);last=now;w.scrollLeft+=v*f;v*=Math.pow(0.95,f);if(Math.abs(v)>0.2)w._raf=requestAnimationFrame(step);};w._raf=requestAnimationFrame(step);" ontouchcancel="event.stopPropagation()"><div class="hw-trk">' + items.map((f, i) => {
      const d = new Date(f.datetime); const c = cond(f.condition);
      const rain = f.precipitation_probability != null ? f.precipitation_probability + ' %' : (f.precipitation ? (window.casoraNum ? window.casoraNum(f.precipitation, 0, 2) : String(f.precipitation).replace('.', ',')) + ' ' + (entity?.attributes?.precipitation_unit || 'mm') : '');
      return '<div class="hw-h"><div class="hw-ht">' + (i === 0 ? 'Jetzt' : d.getHours() + ' Uhr') + '</div>'
        + '<div class="hw-hi"><ha-icon icon="' + c[1] + '" style="--mdc-icon-size:28px;width:28px;height:28px;display:flex;"></ha-icon></div>'
        + '<div class="hw-hv">' + r0(f.temperature) + '°</div>' + (anyRain ? '<div class="hw-hr">' + (rain || '&nbsp;') + '</div>' : '') + '</div>';
    }).join('') + '</div></div>';
  };
  const daily = (list) => {
    const today = new Date(); today.setHours(0, 0, 0, 0);
    const items = (list || []).filter((f) => new Date(f.datetime).getTime() >= today.getTime() - 86400000 / 2).slice(0, 7);
    if (!items.length) return '';
    const lo = Math.min.apply(null, items.map((f) => f.templow != null ? f.templow : f.temperature));
    const hi = Math.max.apply(null, items.map((f) => f.temperature));
    const span = Math.max(1, hi - lo);
    return '<div class="hw-days">' + items.map((f, i) => {
      const d = new Date(f.datetime); const c = cond(f.condition);
      const tl = f.templow != null ? f.templow : f.temperature;
      const left = ((tl - lo) / span * 100).toFixed(1), width = Math.max(4, (f.temperature - tl) / span * 100).toFixed(1);
      const rain = f.precipitation ? (window.casoraNum ? window.casoraNum(Math.round(f.precipitation * 10) / 10, 0, 1) : String(Math.round(f.precipitation * 10) / 10).replace('.', ',')) + ' ' + (entity?.attributes?.precipitation_unit || 'mm') : '';
      return '<div class="hw-d"><div class="hw-dn">' + (i === 0 ? 'Heute' : d.toLocaleDateString((window.casoraLocale ? window.casoraLocale() : 'de-DE'), { weekday: 'short' }).replace('.', '')) + '</div>'
        + '<div class="hw-di"><ha-icon icon="' + c[1] + '" style="--mdc-icon-size:24px;width:24px;height:24px;display:flex;"></ha-icon></div>'
        + '<div class="hw-dr">' + rain + '</div>'
        + '<div class="hw-dl">' + r0(tl) + '°</div>'
        + '<div class="hw-bar"><div style="left:' + left + '%;width:' + width + '%"></div></div>'
        + '<div class="hw-dh">' + r0(f.temperature) + '°</div></div>';
    }).join('') + '</div>';
  };
  window._hwRender = window._hwRender || {};
  window._hwRender[key] = { hourly: hourly, daily: daily };

  const fillLater = () => {
    const ha = document.querySelector('home-assistant');
    const conn = ha && ha.hass && ha.hass.connection;
    if (!conn) return;
    const find = (sel) => { const out = []; const walk = (n) => { if (!n || !n.querySelectorAll) return; n.querySelectorAll(sel).forEach((x) => out.push(x)); n.querySelectorAll('*').forEach((x) => { if (x.shadowRoot) walk(x.shadowRoot); }); }; walk(ha.shadowRoot || document); return out; };
    ['hourly', 'daily'].forEach((type) => {
      conn.subscribeMessage((msg) => {
        window._hwFc[key + '_' + type] = msg.forecast || [];
        const html = window._hwRender[key][type](msg.forecast || []);
        find('.hw-slot-' + type + '-' + key).forEach((el) => { el.innerHTML = html; });
        if (type === 'daily' && msg.forecast && msg.forecast[0]) { const f0 = msg.forecast[0]; find('.hw-slot-hilo-' + key).forEach((el) => { el.textContent = 'H ' + r0(f0.temperature) + '° · T ' + r0(f0.templow) + '°'; }); }
      }, { type: 'weather/subscribe_forecast', forecast_type: type, entity_id: id })
        .then((unsub) => setTimeout(() => { try { unsub(); } catch (e) {} }, 120000)).catch(() => {});
    });
  };
  setTimeout(fillLater, 50);

  const c0 = cond(entity?.state);
  const d0 = (window._hwFc[key + '_daily'] || [])[0];
  const hiLo = d0 ? 'H ' + r0(d0.temperature) + '° · T ' + r0(d0.templow) + '°' : null;
  /* Himmelsrichtung je Sprache (casoraTr übersetzt einzelne Kürzel nicht): Englisch NE/E/SE. */
  const WD = String(hass?.locale?.language || 'de').startsWith('de') ? ['N', 'NO', 'O', 'SO', 'S', 'SW', 'W', 'NW']
    : ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];
  const wdir = a.wind_bearing != null ? WD[Math.round(a.wind_bearing / 45) % 8] : '';
  const rows = [];
  if (a.humidity != null) rows.push({ icon: 'humidity', iconTone: 'accent', label: 'Luftfeuchtigkeit', value: r0(a.humidity) + ' %' });
  if (a.wind_speed != null) rows.push({ icon: 'mdi:weather-windy', iconTone: 'accent', label: 'Wind', value: (window.casoraNum ? window.casoraNum(Math.round(a.wind_speed * 10) / 10, 0, 1) : String(Math.round(a.wind_speed * 10) / 10).replace('.', ',')) + ' ' + (a.wind_speed_unit || 'km/h') + (wdir ? ' · ' + wdir : '') });
  if (a.pressure != null) rows.push({ icon: 'mdi:gauge', iconTone: 'accent', label: 'Luftdruck', value: r0(a.pressure) + ' ' + (a.pressure_unit || 'hPa') });
  if (a.uv_index != null) rows.push({ icon: 'mdi:white-balance-sunny', iconTone: 'var(--casora-color-yellow, #FFCC00)', label: 'UV-Index', value: String(a.uv_index) });
  if (a.visibility != null) rows.push({ icon: 'mdi:eye-outline', iconTone: 'accent', label: 'Sichtweite', value: (window.casoraNum ? window.casoraNum(a.visibility, 0, 1) : String(a.visibility).replace('.', ',')) + ' ' + (a.visibility_unit || 'km') });

  const css = '<style>ha-card.disabled{pointer-events:auto!important;}'
    + '.hw{font-family:' + T.font + ';color:' + T.ink + ';text-align:left;}'
    + '.hw-l{font-size:var(--casora-h15-fs,15px);font-weight:var(--casora-h15-fw,600);letter-spacing:var(--casora-h15-ls,-0.01em);text-transform:var(--casora-h15-tt,none);color:var(--casora-h15-c, inherit);margin:22px 4px 8px;}.hw-plate .hw-l.hw-in{margin:0 0 10px;padding:0 6px;}'
    + '.hw-plate{background:var(--casora-popup-row-fill, rgba(255,255,255,0.10));border-radius:var(--casora-popup-row-radius, 20px);padding:14px 10px;}'
    + '.hw-hilo{text-align:center;font-size:15px;color:' + T.ink2 + ';margin-top:-12px;min-height:19px;font-variant-numeric:tabular-nums;}'
    + '.hw-src{overflow-x:auto;overflow-y:hidden;-webkit-overflow-scrolling:touch;overscroll-behavior-x:contain;scrollbar-width:none;}'
    + '.hw-src::-webkit-scrollbar{display:none;}'
    + ((UI.soft && UI.soft()) ? '.hw-src{-webkit-mask-image:linear-gradient(90deg,#000 calc(100% - 64px),transparent);mask-image:linear-gradient(90deg,#000 calc(100% - 64px),transparent);}' : '')
    + '.hw-trk{display:flex;gap:4px;width:max-content;}'
    + '.hw-h{width:58px;flex:none;display:flex;flex-direction:column;align-items:center;gap:6px;position:relative;}'
    + '.hw-src.rain{padding:6px 0 10px;}'
    + '.hw-hi{width:28px;height:28px;display:grid;place-items:center;}'
    + '.hw-ht{font-size:13px;color:' + T.ink2 + ';white-space:nowrap;}.hw-hv{font-size:17px;font-weight:500;font-variant-numeric:tabular-nums;}.hw-hr{position:absolute;top:100%;left:0;right:0;text-align:center;font-size:var(--casora-weather-precip-fs, 11px);color:var(--casora-weather-precip, #64D2FF);line-height:var(--casora-weather-precip-fs, 12px);margin-top:0;white-space:nowrap;}'
    + '.hw-days{display:flex;flex-direction:column;}'
    + '.hw-d{display:grid;grid-template-columns:52px 32px 58px 38px minmax(50px,1fr) 38px;align-items:center;column-gap:8px;padding:10px 10px;}'
    + '.hw-di{display:grid;place-items:center;}'
    + '.hw-d + .hw-d{border-top:1px solid ' + T.div + ';}'
    + '.hw-dn{font-size:var(--casora-fs16,16px);font-weight:500;}'
    + '.hw-dr{font-size:12px;color:var(--casora-weather-precip, #64D2FF);text-align:left;white-space:nowrap;}'
    + '.hw-dl{text-align:right;font-size:var(--casora-fs16,16px);color:' + T.ink2 + ';font-variant-numeric:tabular-nums;}'
    + '.hw-dh{text-align:left;font-size:var(--casora-fs16,16px);font-variant-numeric:tabular-nums;}'
    + '.hw-bar{position:relative;height:5px;border-radius:999px;background:' + T.fill2 + ';}'
    + '.hw-bar > div{position:absolute;top:0;bottom:0;border-radius:999px;background:linear-gradient(90deg,#64D2FF,#FFD60A,#FF9F0A);}'
    + '.hw-wait{font-size:13px;color:' + T.ink3 + ';padding:6px 8px;}'
    + '.hw-cols{display:block;}'
    + '@media (min-width: 761px){.hw-cols{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:20px;align-items:start;}.hw-cols .hw-l{margin-top:22px;}}'
    + '</style>';
  /* Verlauf der Außentemperatur (Außensensor, 48 h) als Diagramm-Karte unter dem Kopf (24.09.2026). */
  const _od = (dc) => (window.casoraDevice && window.casoraDevice.outdoor(hass, dc)) || '';
  const OUT_T = _od('temperature');
  let chartH = '';
  if (states[OUT_T] && typeof window._hpChartCfg === 'function') {
    window._hpChartCfg(OUT_T, 'Außentemperatur', '48h', '#FF9F0A', 150);
    if (window._hpSmooth) window._hpSmooth(OUT_T);
    /* Umschalter Temperatur / Luftfeuchtigkeit / Luftdruck (24.09.): Pillen mit data-hp-metric, _hpPlantShow tauscht die Kurve. */
    const MET = [[OUT_T, 'Temperatur'], [_od('humidity'), 'Luftfeuchtigkeit', 'Luftfeuchtigkeit außen', '#64D2FF'],
      [_od(['atmospheric_pressure', 'pressure']), 'Luftdruck', 'Luftdruck', '#BF5AF2']].filter((m) => states[m[0]]);
    MET.forEach((m) => { if (m[2]) { window._hpChartCfg(m[0], m[2], '48h', m[3], 150); if (window._hpSmooth) window._hpSmooth(m[0]); } });
    /* Weich (Fix-Runde 1, B-12/B-13): Umschalter als Standard-Segment über volle Breite, eine Zeile auch am Handy. */
    const _sfW = !!(UI.soft && UI.soft());
    const pills = MET.length > 1 ? (_sfW ? '<style>.hw-mh{flex-wrap:wrap!important;}.hw-mh>.hw-mps{flex:1 0 100%;display:grid!important;grid-template-columns:repeat(' + MET.length + ',minmax(0,1fr));gap:8px!important;padding:0!important;margin:2px 0 4px;}'
        + '.hw-mp{min-height:44px;display:flex;align-items:center;justify-content:center;padding:0 8px!important;border-radius:var(--casora-soft-seg-radius,18px)!important;font-size:13px!important;font-weight:600!important;'
        + 'white-space:nowrap;overflow:hidden;text-overflow:ellipsis;background:var(--casora-soft-control-fill,rgba(140,115,90,0.10))!important;color:var(--casora-soft-sub,var(--secondary-text-color))!important;}'
        + '.hw-mp.hp-sel{background:var(--casora-soft-seg-on,#FFFDF9)!important;color:var(--casora-soft-seg-on-ink,inherit)!important;box-shadow:var(--casora-soft-seg-on-shadow,none);}'
        + '@media (max-width:480px){.hw-mp{font-size:12.5px!important;padding:0 4px!important;}}</style>' : '') + '<style>.hw-mp{font-size:13px;font-weight:500;padding:6px 12px;border-radius:999px;cursor:pointer;user-select:none;-webkit-user-select:none;'
        + 'background:var(--casora-popup-seg-fill, rgba(255,255,255,0.16));color:' + T.ink + ';transition:background-color .16s ease,color .16s ease;}'
        + '.hw-mp.hp-sel{background:' + T.ink + ';color:var(--casora-popup-ui-on-ink, #000);}</style>'
      + '<div class="hw-mps" style="display:flex;gap:6px;flex-wrap:wrap;padding:0 6px 4px;" ontouchstart="window._hpPlantTap&&window._hpPlantTap(event,\'s\')" ontouchend="window._hpPlantTap&&window._hpPlantTap(event,\'t\')" onclick="window._hpPlantTap&&window._hpPlantTap(event,\'c\')">'
      + MET.map((m, i) => '<div class="hw-mp' + (i === 0 ? ' hp-sel' : '') + '" data-hp-metric="' + m[0] + '">' + m[1] + '</div>').join('') + '</div>' : '';
    /* K2 (Weich-Audit): in Weich stehen alle Etiketten über der Fläche, wie in den übrigen Popups. */
    const _hwOut = !!(UI.soft && UI.soft());
    const _mh = '<div class="hw-mh" style="display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;' + (_hwOut ? 'margin:22px 4px 8px;' : '') + '">'
      + '<div class="hp-ct hw-l' + (_hwOut ? '" style="margin:0;' : ' hw-in') + '">' + (window._hpChartTitle ? window._hpChartTitle(OUT_T) : 'Außentemperatur') + '</div>' + pills + '</div>';
    chartH = (_hwOut ? _mh + '<div class="hw-plate" style="padding:8px 10px 6px;">' : '<div class="hw-plate" style="margin-top:18px;padding:14px 10px 6px;">' + _mh)
      + '<div class="hp-chart-slot" style="min-height:150px;margin:6px 0 0;"></div></div>';
    if (typeof window._hpChartInit === 'function') window._hpChartInit(OUT_T);
  }
  const body = css + '<div class="hw">'
    /* Weich (Fix-Runde 1, B-01): eine Statuszeile – Temperatur · Wetter · H/T · Ort. */
    + ((UI.soft && UI.soft() && UI.line)
      ? UI.line(r0(curT) + '°', [c0[0]], { slotClass: 'hw-slot-hilo-' + key, slotText: hiLo || '', after: [a.station_name || null] })
      : UI.hero({ label: a.station_name || null, value: r0(curT) + '°', sub: c0[0], center: true })
        + '<div class="hw-hilo hw-slot-hilo-' + key + '">' + (hiLo || '') + '</div>')
    + chartH
    + ((UI.soft && UI.soft()) ? '<div class="hw-l">Nächste Stunden</div><div class="hw-plate">' : '<div class="hw-plate" style="margin-top:18px;"><div class="hw-l hw-in">Nächste Stunden</div>') + '<div class="hw-slot-hourly-' + key + '">'
    + (hourly(window._hwFc[key + '_hourly']) || '<div class="hw-wait">Lade Vorhersage …</div>') + '</div></div>'
    + '<div class="hw-cols"><div>'
    + ((UI.soft && UI.soft()) ? '<div class="hw-l">7 Tage</div><div class="hw-plate">' : '<div class="hw-plate" style="margin-top:18px;"><div class="hw-l hw-in">7 Tage</div>') + '<div class="hw-slot-daily-' + key + '">'
    + (daily(window._hwFc[key + '_daily']) || '<div class="hw-wait">Lade Vorhersage …</div>') + '</div></div></div>'
    + '<div>' + (rows.length ? '<div style="margin-top:18px;">' + UI.group(rows, 'Details', null, { labelInside: true }) + '</div>' : '') + '</div></div>'
    + (a.attribution ? '<div style="font-size:11px;color:' + T.ink3 + ';margin:12px 4px 0;">' + esc(a.attribution.replace('Data provided by ', 'Daten: ')) + '</div>' : '')
    + '</div>';

  return { type: 'vertical-stack', cards: [{
    type: 'custom:button-card',
    card_mod: { style:
      '\n:host { --ha-card-backdrop-filter: none !important; --ha-card-background: transparent !important; --card-background-color: transparent !important; --ha-card-box-shadow: none !important; --ha-card-border-width: 0px !important; }'
      + '\nha-card::before, ha-card::after, #card::before, #card::after, #container::before, #container::after { display: none !important; }'
      + '\nha-card { will-change: auto !important; }'
      + '\n@media (max-width: 600px) { ha-card { padding-left: 14px !important; padding-right: 14px !important; } }' },
    tap_action: { action: 'none' }, hold_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    styles: {
      card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: 'var(--casora-soft-card-top, 6px) 26px 22px 26px' }],
      grid: [{ 'grid-template-areas': '"body"' }, { 'grid-template-columns': '1fr' }],
      custom_fields: { body: [{ 'justify-self': 'stretch' }, { 'min-width': '0' }] },
    },
    custom_fields: { body: body },
  }] };
]]]

popup_styles.styles:
/* Eine Popup-Familie (01.10.2026): dieselbe Sheet-Fläche wie die Bedien-Popups –
   Fläche, Blur, Schatten und Abdunklung aus dem Standard, Höhe folgt dem Inhalt,
   Schließen-Kreuz mit demselben Abstand zur Sheet-Kante. */
.header { padding-top: var(--casora-popup-header-gap, 10px); }
--casora-popup-header-gap: 14px;
--casora-popup-gutter-wide: 34px;
--casora-popup-gutter-phone: 22px;

/* No chart here, so nothing to wait for: the widgets arrive as
   soon as they are built. Read by each widget for itself, never by
   a wrapper - an animated opacity on an ancestor flattens the frost
   inside it. */
--casora-popup-plate-enter:
  casora-plate-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
@media (prefers-reduced-motion: reduce) {
  --casora-popup-plate-enter: none;
}

--casora-popup-hero-label-size: 15px;
--casora-popup-row-radius: 26px;
/* Frosted, not opaque. The pane's blur used to sit under these, and
   .content still nulls --ha-card-backdrop-filter for every card in
   the popup, so the frost has to be asked for here. The fills drop
   to let it read. */
/* The theme lifts every ha-card with filter: brightness(1.01) on
   hover. A filter on an ancestor makes every descendant's
   backdrop-filter inert, so hovering the empty space around a
   widget - the wrapper card - knocked the frost out of both of
   them. Killed popup-wide; the plate re-declares its own shadow. */
--casora-card-hover-filter: none;
--casora-hover-filter: none;
--casora-card-hover-shadow: none;

--casora-popup-row-pad-x: 26px;
--casora-popup-row-pad-y: 15px;
--casora-popup-plate-backdrop: blur(24px) saturate(180%);
--casora-popup-chart-fill: var(--casora-sheet-chart-fill, rgba(10, 12, 16, 0.68));
--casora-popup-row-fill: var(--casora-sheet-row-fill, rgba(12, 14, 19, 0.62));
/* Lifted, not slabbed: one wide soft pass carries the height, one
   short contact pass keeps the edge from dissolving into the room. */
--casora-popup-plate-shadow: var(--casora-sheet-plate-shadow,
  0 18px 40px -22px rgba(0, 0, 0, 0.50),
  0 2px 8px -5px rgba(0, 0, 0, 0.28));

/* visionOS puts nothing bare on the room: the only chrome outside a
   window is its close control, and that control is itself a glass
   object. The title was printed twice - here and in the widget
   eight pixels below - so it goes, clipped rather than removed so a
   screen reader still gets it. */

/* The chrome arrives with the first plate instead of being there
   on frame one while everything under it fades in. */
--casora-popup-chrome-enter:
  casora-popup-chrome-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
.content { animation: none; }
/* The title lives in the bar now, centered and level with the
   close control, so it is no longer hidden. */
.header-title { font-size: 20px; font-weight: 600; letter-spacing: -0.01em; }
/* 48px is left alone: the base sizes it so the glyph's ink lands on
   the same left margin as the widgets below. */
.header-close {
  border-radius: 50%;
  background: var(--casora-popup-row-fill, rgba(255, 255, 255, 0.10));
  backdrop-filter: var(--casora-popup-plate-backdrop, none);
  -webkit-backdrop-filter: var(--casora-popup-plate-backdrop, none);
  box-shadow: var(--casora-popup-plate-shadow, none);
}

ha-adaptive-dialog, ha-dialog, wa-drawer {
  --ha-card-backdrop-filter: none;
  --ha-card-background: transparent;
  --card-background-color: transparent;
  --ha-card-box-shadow: none;
  --ha-card-border-width: 0px;
}
/* Anzeige-Popup: Pflanzen/Energie-Stil ohne Pane (23.09.2026). */
--popup-min-width: min(900px, 92vw);
--popup-max-width: min(900px, 92vw);

/* Popup-Standard (24.09.2026): Info-Popup - Abschnittsüberschriften in der Karte. */
--casora-lbl-in: block;
--casora-lbl-out: none;

casora_weather_warning.extra_styles:
/* Dreieck optisch mittig: Bild und Weich-Maske (::before) gemeinsam anheben – sonst stand die Maske 2 px darunter wie ein Schatten. */
#img-cell img,
#img-cell::before {
  transform: translateY(-2px) !important;
}

casora_weather_warning.name:
[[[
  const ids = (variables.sensors && variables.sensors.length > 0) ? variables.sensors : [entity?.entity_id];
  const order = ['Extrem', 'Severe', 'Moderate', 'Minor'];
  const active = ids
    .map(id => states[id])
    .filter(s => s && s.state === 'on')
    .sort((a, b) => order.indexOf(a.attributes?.severity) - order.indexOf(b.attributes?.severity));

  const isMobile = window.matchMedia('(max-width: 767px), (max-height: 600px)').matches;

  if (!active.length) return "NINA";

  const text = variables.levels[active[0].attributes?.severity]?.text;
  if (!text) return "NINA";

  return isMobile ? text : "NINA - " + text;
]]]

card.--casora-icon-color-current:
[[[
  const ids = (variables.sensors && variables.sensors.length > 0) ? variables.sensors : [entity?.entity_id];
  const sev = s => s === 'Extrem' ? 4 : s === 'Severe' ? 3 : s === 'Moderate' ? 2 : s === 'Minor' ? 1 : 0;
  const max = ids
    .map(id => states[id])
    .filter(s => s?.state === 'on')
    .reduce((m, s) => Math.max(m, sev(s.attributes?.severity)), 0);
  if (max >= 4) return 'var(--casora-color-purple, #9333ea)';
  if (max === 3) return 'var(--casora-color-red, #FF4245)';
  if (max === 2) return 'var(--casora-color-orange, #FF9230)';
  return 'var(--casora-color-yellow, #FFCC00)';
]]]

