casora_weather_warning.state_display:
[[[
  const fit = (t) => window.casoraStateFit?.(t) ?? t;
  const ids = (variables.sensors && variables.sensors.length > 0) ? variables.sensors : [entity?.entity_id];
  const order = ['Extrem', 'Severe', 'Moderate', 'Minor'];
  const active = ids
    .map(id => states[id])
    .filter(s => s && s.state === 'on')
    .sort((a, b) => order.indexOf(a.attributes?.severity) - order.indexOf(b.attributes?.severity));
  // Weich-Popup: ohne Warnung ruhiger Sand-Ring statt Warn-Orange (casora-core ringFor).
  this._casoraRingQuiet = !active.length;
  if (!active.length) return fit("Keine Warnung");
  const headline = active[0].attributes?.headline || "";
  const match = headline.match(/vor\s+(.+?)(?:\s+mit\s|\s+und\s|$)/i);
  const raw = match ? match[1] : headline.split(' - ')[0].replace(/\s*\d{4}$/, '');
  const label = raw.toLowerCase().split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
  return `<span style="color: var(--casora-entity-state-active-color); text-transform: none;">${fit(label)}</span>`;
]]]

variables.levels:
[[[
  return {
    Minor:    { text: 'Hinweis'         },
    Moderate: { text: 'Warnung'         },
    Severe:   { text: 'Schwere Warnung' },
    Extreme:  { text: 'Notfall'         }
  };
]]]
